ll n, a[N], ans;
bool vis[N];

int main()
{
	scanf("%lld",&n);
	for(ll i=1;i<=n;i++) {
		scanf("%lld",&a[i]);
		ans += a[i];
	}
	for(ll i=n;i>=1;i--) {
		ll C = 0;
		for(ll j=1;j*i<=n;j++) {
			if(!vis[i*j]) C += a[i*j];
		}
		if(C >= 0) continue;
		for(ll j=1;j*i<=n;j++) {
			vis[i*j] = true;
		}
		ans -= C;
	}
	printf("%lld\n",ans);
}

