struct FlowEdge {
    Int to;
    Int cap;
    Int rev;
    FlowEdge(Int t, Int c, Int r) : to(t), cap(c), rev(r) {}
};

void flow_add_edge(vector<vector<FlowEdge>>& g, Int from, Int to, Int cap) {
    g[from].emplace_back(to, cap, SIZE(g[to]));
    g[to].emplace_back(from, 0, SIZE(g[from])-1);
}

Int flow_dinic(vector<vector<FlowEdge>>& g, Int s, Int t) {
    Int n = SIZE(g);

    vector<Int> ds(n);
    auto bfs = [&]() {
        queue<Int> que;
        ALL(fill, ds, -1);
        que.emplace(s);
        ds[s] = 0;

        while(!que.empty()) {
            Int v = POP(que);
            for(const auto& e : g[v]) {
                if(ds[e.to] >= 0) continue;
                if(e.cap == 0) continue;
                que.emplace(e.to);
                ds[e.to] = ds[v] + 1;
            }
        }
    };

    vector<Int> idxs(n);
    auto dfs = FIX([&](auto&& self, Int v, Int flmax) -> Int {
        if(v == t) return flmax;

        for(Int& i = idxs[v]; i < SIZE(g[v]); ++i) {
            auto& e = g[v][i];
            if(ds[v] >= ds[e.to]) continue;
            if(e.cap == 0) continue;
            Int fl = self(e.to, MIN(e.cap, flmax));
            if(fl > 0) {
                auto& e_rev = g[e.to][e.rev];
                e.cap     -= fl;
                e_rev.cap += fl;
                return fl;
            }
        }
        return 0;
    });

    Int res = 0;
    for(;;) {
        bfs();
        if(ds[t] < 0) break;

        ALL(fill, idxs, 0);
        for(;;) {
            Int fl = dfs(s, INF);
            if(fl == 0) break;
            res += fl;
        }
    }

    return res;
}

void solve() {
    Int N = RD();
    auto A = RD_VEC(N);

    // 2択のうち大きい方の利益
    auto f_base = [](Int a) { return MAX(0,a); };
    Int base_sum = 0;
    for(Int a : A)
        base_sum += f_base(a);

    // 石に対応する頂点は [1,N]
    Int S = 0;
    Int T = N+1;
    vector<vector<FlowEdge>> G(N+2);
    FOR(v, 1, N+1) {
        Int a = A[v-1];
        Int base = f_base(a);
        flow_add_edge(G, S, v, base);    // 割る
        flow_add_edge(G, v, T, base-a);  // 割らない
    }
    // 制約: v を割ったら k*v も割らねばならない
    FOR(v, 1, N+1) {
        for(Int k = 1; k*v <= N; ++k) {
            flow_add_edge(G, k*v, v, INF);
        }
    }

    Int cut = flow_dinic(G, S, T);

    Int ans = base_sum - cut;

    PRINTLN(ans);
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

