struct max_flow{
    public:
    struct edge {int to;ll cap;int rev;};
    int V;
    vector<vector<edge>> G;
    vector<int> level,iter;

    void init(int v){
        V = v; G.resize(v);
    }

    void add_edge(int from, int to, ll cap){
        int a=G[to].size(),b=G[from].size()-1;
        G[from].push_back((edge){to,cap,a});
        G[to].push_back((edge){from,0,b});
    }

    void bfs(int s){
        level.assign(V,-1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(!que.empty()){
            int v = que.front();
            que.pop();
            rep(i,G[v].size()){
                edge &e = G[v][i];
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    ll dfs(int v, int t, ll f){
        if(v == t) return f;
        for(int &i = iter[v]; i < G[v].size(); i++){
            edge &e = G[v][i];
            if(e.cap > 0 && level[v] < level[e.to]){
                int d = dfs(e.to,t,min(f,e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    ll run(int s, int t){
        int flow = 0;
        while(1){
            bfs(s);
            if(level[t] < 0) return flow;
            iter.assign(V,0);
            ll tmp;
            while((tmp = dfs(s,t,INF)) > 0){
                flow += tmp;
            }
        }
    }
