int a[N], n, s, t, dis[N], tot = 1, head[N];
LL ans;
struct edge { int to, nxt; LL rem; } e[N * N];
void link(int x, int y, LL z) {
	e[++tot] = (edge) { y, head[x], z }, head[x] = tot;
	e[++tot] = (edge) { x, head[y], 0 }, head[y] = tot;
}
bool bfs() {
	for (int i = s; i <= t; ++i) dis[i] = 0;
	std::queue<int> q; q.push(s), dis[s] = 1;
	while (q.size()) {
		int tmp = q.front(); q.pop();
		for (int i = head[tmp]; i; i = e[i].nxt)
			if (!dis[e[i].to] && e[i].rem)
				dis[e[i].to] = dis[tmp] + 1, q.push(e[i].to);
	}
	return dis[t] > 0;
}
LL dinic(int x, LL low) {
	if (x == t) return low;
	LL t, ans = 0;
	for (int i = head[x]; i; i = e[i].nxt)
		if (e[i].rem && dis[e[i].to] == dis[x] + 1 && (t = dinic(e[i].to, std::min(low, e[i].rem)))) {
			low -= t, ans += t, e[i].rem -= t, e[i ^ 1].rem += t;
			if (!low) break;
		}
	return ans;
}

