struct Dinic{
    struct edge{ll to;ll cap;ull rev;};
    ll n;
    vector<vector<edge>>g;
    vector<ll>rank,visit;
    Dinic(ll size):n(size),g(size){}
    void add(ll from,ll to,ll cap){
        g[from].push_back({to,cap,g[to].size()});
        g[to].push_back({from,0,g[from].size()-1});
    }
    ll bfs(ll from,ll to){
        rank.assign(n,LINF);
        queue<ll>q;
        rank[from]=0;
        q.push(from);
        while(q.size()){
            ll at=q.front();
            if(at==to)return rank[to];
            q.pop();
            each(i,g[at])if(i.cap)if(chmin(rank[i.to],rank[at]+1))q.push(i.to);
        }
        return rank[to];
    }
    ll dfs(ll from,ll to,ll mn){
        if(from==to)return mn;
        each(i,g[from])if(rank[from]+1==rank[i.to]&&i.cap){
            ll a=dfs(i.to,to,min(mn,i.cap));
            if(a){
                i.cap-=a;
                g[i.to][i.rev].cap+=a;
                return a;
            }
        }
        return 0;
    }
    ll flow(ll from,ll to){
        ll ans=0;
        while(bfs(from,to)!=LINF){
            visit.assign(n,0);
            ll a=dfs(from,to,LINF);
            while(a){
                ans+=a;
                a=dfs(from,to,LINF);
            }
        }
        return ans;
    }
};
