void solve()
{
	for(int i = 1; i <= n; i++) if(i * 2 > n && a[i] < 0) a[i] = 0;

	int64_t answer = 0;
	for(int mask = 0; mask < (1 << (int)(imp_list.size())); mask++)
	{
		for(int i = 1; i <= n; i++) b[i] = a[i];
		for(int j = 0; j < (int)imp_list.size(); j++)
			if((mask >> j) & 1)
				for(int p = imp_list[j]; p <= n; p += imp_list[j])
					b[p] = 0;

		int64_t c_ans = 0;
		for(int i = n; i >= 1; i--)
		{
			int64_t sum = 0;
			for(int j = i; j <= n; j += i)
				sum += b[j];

			c_ans += b[i];
			if(sum < 0)
			{
				c_ans -= sum;
				for(int j = i; j <= n; j++)
					b[j] = 0;
			}

			chkmax(answer, c_ans);
		}
	}

	cout << answer << endl;
}

