inline double _random() { return rand() * 1.0 / RAND_MAX; }

inline int solve()
{
    for( int i = 1; i <= n; i ++ )
        tmp[i] = a[i];

    for( int i = n; i >= 1; i -- )
    {
        int now = 0;
        for( int j = i; j <= n; j += i )
            now -= tmp[j];

        if( now >= 0 || exp( now * 1.0 / i ) >= _random() )
            for( int j = i; j <= n; j += i ) tmp[j] = 0;
    }

    int ret = 0;
    for( int i = 1; i <= n; i ++ )
        ret += tmp[i];
    return ret;
}

