void bfs(int s,int cnt){
    int nxt;
    queue<int> q;
    q.push(s);
    dep[s]=iter[s]=0;
    went[s]=cnt;
    while(!q.empty()){
        nxt=q.front();
        q.pop();
        for(edge i:flow[nxt])if(i.cap>0&&went[i.to]!=cnt){
            dep[i.to]=dep[nxt]+1;
            went[i.to]=cnt;
            iter[i.to]=0;
            q.push(i.to);
        }
    }
    return ;
}
long long int dfs(int u,int t,long long int nf){
    if(u==t)return nf;
    long long int temp;
    for(int &i=iter[u];i<flow[u].size();i++)if(flow[u][i].cap>0&&dep[flow[u][i].to]==dep[u]+1){
        temp=dfs(flow[u][i].to,t,min(nf,flow[u][i].cap));
        if(temp>0){
            flow[flow[u][i].to][flow[u][i].re].cap+=temp;
            flow[u][i].cap-=temp;
            return temp;
        }
    }
    return 0;
}
