            ans += a;
            dinic.add_edge(0, i + 1, a);
        } else {
            dinic.add_edge(i + 1, n + 1, -a);
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = i * 2; j <= n; j += i) {
            dinic.add_edge(j, i, INF);
        }
    }

    ans -= dinic.max_flow(0, n + 1);
    cout << ans << "\n";
    return 0;
}

