const int INFTY = 987654321;
//
template <typename T>
class Edge {
public:
    Edge(int input_to, T input_cap, int input_rev) :
        to(input_to), cap(input_cap), rev(input_rev), init_cap(input_cap) {
    }

    int to;       // 行先
    T   cap;      // 容量
    int rev;      // 逆辺
    T   init_cap; // 初期容量（デバッグ用）
};

// 最大流 Dinic O(EV^2)だけど、実際もっとはやい。
template <typename T>
class Dinic {
	static const T DINIC_INF = (sizeof(T) > 4) ? LLONG_MAX : INT_MAX;

	int maxv;
	vector<vector<Edge<T>>> G; // グラフの隣接リスト
	vector<int> level;     // sからの距離
	vector<int> iter;      // どこまで調べ終わったか

public:
	Dinic(int input_maxv) : maxv(input_maxv) {
		G.resize(input_maxv);
		level.resize(input_maxv);
		iter.resize(input_maxv);
	}

	void add_edge_both(int from, int to, T cap) {
		const int rev_from  = G[from].size();
		const int rev_to    = G[to].size();
		G[from].push_back(Edge<T>(to, cap, rev_to));
		G[to].push_back(Edge<T>(from, cap, rev_from));
	}

	void add_edge(int from, int to, T cap) {
		const int rev_from  = G[from].size();
		const int rev_to    = G[to].size();
		G[from].push_back(Edge<T>(to, cap, rev_to));
		G[to].push_back(Edge<T>(from, (T)0, rev_from));
	}

	// sからtへの最大流を求める
	T max_flow(int s, int t) {
		T flow = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) break;
			fill(ALL(iter), 0);
			T f;
			while ((f = dfs(s, t, DINIC_INF)) > 0) {
				flow += f;
			}
		}
		return flow;
	}

	//  ノードsから辿れる範囲を求める（これ以上流せないところcap=0は、リンクがなくなる）
	// （流し終わったあとsourceからたどれる範囲が、最小カット時のs側。たどれない範囲がt側。その境界がカットするところ。）
	vector<bool> get_nodes_in_group(int s) {
		vector<bool> ret(maxv);

		queue<int> q;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			ret[v] = true;

            rep(i, G[v].size()) {
				Edge<T> &e = G[v][i];
				if (e.cap > 0 && !ret[e.to]) {
					q.push(e.to);
				}
			}
		}
		return ret;
	}

	void disp() {
        rep(v, maxv) {
			fprintf(stderr, "%d:", v);
            rep(i, G[v].size()) {
				if (G[v][i].init_cap > 0) {
					fprintf(stderr, "->%d(%d),", G[v][i].to, G[v][i].init_cap);
				}
			}
			fprintf(stderr, "\n");
		}
	}

private:
	// sからの最短距離をBFSで計算する
	void bfs(int s) {
		fill(ALL(level), -1);
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
            rep(i, G[v].size()) {
				Edge<T> &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	// 増加パスをDFSで探す
	int dfs(int v, int t, T f) {
		if (v == t) return f;
		for (int &i=iter[v]; i<G[v].size(); i++) {
			Edge<T>& e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				T d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

};

