ll solve(int N, vi& a) {
	const int S = N+1;
	const int T = S+1;

    Dinic<ll>* dinic = new Dinic<ll>(T+1);
    ll answer = 0;
    rep1(i,N) {
        int a_i = a[i-1];
        if (a_i <= 0) {
            dinic->add_edge(S, i, -a_i);
        } else {
            answer += a_i;
            dinic->add_edge(i, T, a_i);
        }
        for (int k=i; k<=N; k+=i) {
            dinic->add_edge(i, k, INFTY);
        }
    }
    answer -= dinic->max_flow(S, T);

    delete dinic;

    return answer;
}

