struct max_flow{
    struct edge{int to; i64 cap,rev;};
    vector<vector<edge>> graph;
    vector<bool> done;
    max_flow(int size):graph(size),done(size){}
    void add_edge(int from,int to,i64 cap){
        graph[from].push_back(edge{to,cap,(int)graph[to].size()});
        graph[to].push_back(edge{from,0,(int)graph[from].size()-1});
    }
    i64 dfs(int v,int t,i64 f){
        if(v==t) return f;
        done[v]=true;
        for(auto &e:graph[v]){
            if(done[e.to] or e.cap<=0) continue;
            int d=dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;
                graph[e.to][e.rev].cap+=d;
                return d;
            }
        }
        return 0;
    }
    i64 calc_max_flow(int s,int t){
        i64 flow=0;
        while(true){
            fill(done.begin(),done.end(),false);
            i64 f=dfs(s,t,inf);
            if(f==0) return flow;
            flow+=f;
        }
    }
};

void solve(){
    int N;
    cin >> N;

    vector<i64> a(N);
    rep(i,0,N) cin >> a[i];

    int s=N,t=N+1;
    max_flow mf(N+2);
    i64 ideal=0;
    rep(i,0,N){
        if(a[i]>0) ideal+=a[i];
        if(a[i]>=0) mf.add_edge(s,i,a[i]);
        else mf.add_edge(i,t,-a[i]);
        rep(j,i+1,N) if((j+1)%(i+1)==0) mf.add_edge(j,i,inf64/10000);
    }

    cout << ideal-mf.calc_max_flow(s,t) << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

