const ll linf=1e15;
const int inf=1e9+10;
const int N=2e2+10;
const int M=2e4+10;


int n,a[105];
struct flow{
    vector <int> e[N];
    int v[N][2];
    int n,st,en,m;

    int t[N],q[N];
    ll f[N];
    ll flow[M][2],cap[M];

    void build(int _n,int _st,int _en){
        n=_n,st=_st,en=_en;
        m=0;
        for(int i=1;i<=n;i++) e[i].clear();
    }
    void add_edge(int x,int y,ll wei){
        ++m;
        v[m][0]=x;v[m][1]=y;
        e[x].push_back(m);
        e[y].push_back(m);
        flow[m][0]=0;
        flow[m][1]=cap[m]=wei;
    }

    bool BFS(){
        memset(t,0,sizeof(t));
        int top=1,bot=1;

        t[st]=-1;
        f[st]=linf;
        q[1]=st;

        while (top<=bot){
            int x=q[top++];
            for(auto i:e[x]){
                int dir=x==v[i][1];
                int y=v[i][dir^1];
                if (flow[i][dir]==cap[i]) continue;
                if (t[y]) continue;
                t[y]=i;
                q[++bot]=y;
                f[y]=min(f[x],cap[i]-flow[i][dir]);
            }
        }
        return t[en];
    }
    ll inc_flow(){
        int cur=en;
        while (cur!=st){
            int idx=t[cur];
            int dir=(cur!=v[idx][1]);
            flow[idx][dir]+=f[en];
            flow[idx][dir^1]-=f[en];
            cur=v[idx][dir];
        }
        return f[en];
    }
    ll answer(){
        ll ans=0;
        while (BFS()) ans+=inc_flow();
        return ans;
    }
}mflow;

int main(){
    cin>>n;
    for(int i=1;i<=n;i++) cin>>a[i];
    mflow.build(n,n+1,n+2);


    ll ans=0;
    for(int i=1;i<=n;i++) ans+=a[i];
    for(int i=1;i<=n;i++) {
        if (a[i]<0) {
            mflow.add_edge(n+1,i,-a[i]);
            ans+=-a[i];
        }else mflow.add_edge(i,n+2,a[i]);
    }
    for(int i=1;i<=n;i++)
        for(int j=i+i;j<=n;j+=i) mflow.add_edge(i,j,linf);
    cout<<ans-mflow.answer();
}

