template<class T, class U = size_t>
class Dinic {
	struct E { U to, rev_edge_index; T c; };
	U n;
	vector<vector<E>> g;
public:
	explicit Dinic(U n) : n(n), g(n) {}
	void add_undirected_edge(U from, U to, T c) { add_edge(from, to, c, c); }
	void add_edge(U from, U to, T c, T c2 = 0) {
		if (from != to) {
			g[from].push_back({ to,   g[to].size(),     c });
			g[to].push_back({ from, g[from].size() - 1, c2 });
		}
	}

	T max_flow(U in, U out) {
		vector<U> d(n);
		auto bfs = [&]() {
			d.assign(n, 0);
			d[in] = 1;
			queue<U> q; q.push(in);
			while (!q.empty()) {
				U v = q.front(); q.pop();
				for (E e : g[v]) {
					if (e.c > 0 && !d[e.to]) {
						d[e.to] = d[v] + 1;
						q.push(e.to);
					}
				}
			}
			return d[out] > 0;
		};

		vector<U> ptr(n); // 各頂点について何処まで探索したかを保持
		function<T(U, T)> dfs = [&](U v, T lim) {
			if (in == v || !lim) return lim;
			T sum = 0;
			for (U &i = ptr[v]; i < g[v].size(); ++i) {
				E &e = g[v][i], &re = g[e.to][e.rev_edge_index];
				if (d[e.to] >= d[v] || re.c <= 0) continue;
				T f = dfs(e.to, min(lim - sum, re.c));
				if (f <= 0) continue;
				re.c -= f;
				e.c += f;
				sum += f;
				if (sum == lim) break;
			}
			return sum;
		};

		T ans = 0;
		while (bfs()) {
			ptr.assign(n, 0);
			ans += dfs(out, numeric_limits<T>::max() / 8);
		}
		return ans;
	}
};

