inline void dfs(int x,int sum,int g){
	if (g+sum<=ans) return;
	if (x==n+1) {ans=sum;return;}
	if (de[x]) {dfs(x+1,sum,g);return;}
//	if (x+x>n) {dfs(x+1,sum+c[x],g-c[x]);return;}
