namespace {

const int MAXN = 100 + 9;
long long a[MAXN], sum[MAXN], b[MAXN];
int n, pos[MAXN];

inline bool cmp(const int i, const int j) { return sum[i] < sum[j]; }

const int TIMES = 100;
const double INIT_T = 100000;
const double DROP = 0.99;
const double EPS = 0.1;

inline void solve() {
    srand(495);
    std::cin >> n;
    register long long allSum = 0;
    for (register int i = 1; i <= n; i++) std::cin >> a[i], allSum += a[i];
    register long long ans = allSum;
    for (register int i = 1; i <= TIMES; i++) {
        register long long now = allSum;
        memcpy(b, a, sizeof(a));
        for (register double T = INIT_T; T > EPS; T *= DROP) {
            register int p = rand() % n + 1;
            register long long tmp = 0;
            for (register int j = 1; j <= n; j++)
                if (j % p) tmp += b[j];
            ans = std::max(ans, tmp);
            register long long delta = now - tmp;
            if (delta <= 0 || exp(delta / T) * RAND_MAX >= rand()) {
                now = tmp;
                for (register int j = p; j <= n; j += p) b[j] = 0;
            }
        }
        memset(sum, 0, sizeof(sum));
        for (register int i = 1; i <= n; i++)
            for (register int j = i; j <= n; j += i) sum[i] += b[j];
        for (register int i = 1; i <= n; i++) pos[i] = i;
        std::sort(pos + 1, pos + n + 1, cmp);
        for (; sum[pos[1]] < 0;) {
            for (register int i = pos[1]; i <= n; i += pos[1]) b[i] = 0;
            memset(sum, 0, sizeof(long long) * (n + 1));
            for (register int i = 1; i <= n; i++)
                for (register int j = i; j <= n; j += i) sum[i] += b[j];
            for (register int i = 1; i <= n; i++) pos[i] = i;
            std::sort(pos + 1, pos + n + 1, cmp);
        }
        now = std::max(now, std::accumulate(b + 1, b + n + 1, 0ll));
        ans = std::max(ans, now);
    }
    std::cout << ans;
}
}  // namespace

int main() {
    // freopen("sample/1.in", "r", stdin);
    solve();
    return 0;
}

