					}
					long long int ad = 0;
					for (auto el : gr[j]) {
						if ((dv[el] & val2) == 0LL) {
							if (el >= 50) {
								ad += max(0LL, cost[el]);
							}
							else {
								ad += cost[el];
							}
						}
					}
					www = max(www, ad);
					if (www == ad) {
						id = k;
					}
				}
				if (id & 1) {
					val |= (1LL << (long long int)(o1));
				}
				if ((id >> 1) & 1) {
					val |= (1LL << (long long int)(o2));
				}
				for (auto el : gr[j]) {
					if ((dv[el] & val) == 0LL) {
						if (el >= 50) {

						}
						else {
							ans += cost[el];
						}
					}
				}
				continue;
			}
			if (pos[j]==false) {
				if (val&dv[j])continue;
				long long int nex = j * 2;
				long long int U = cost[j];
				if ((val&dv[nex])==0LL) {
					U += max(0LL, cost[nex]);
				}
				if (U >= 0) {
					ans += cost[j];
				}
				else {
					val |= (1LL << (long long int)(j));
				}
				continue;
			}
		}
		for (int j = 51; j <= 100; j++) {
			if (val&dv[j]) {
				continue;
			}
			ans += max(0LL, cost[j]);
		}
		C = max(C, ans);

		return;
	}
