long long arr[105],n,sum,cap[105][105],maxflow,pre[105];

queue <pair<long long, long long> > q;
vector<long long> adj[105];
const long long inf = 1e18;
long long bfs(){
	while(!q.empty())q.pop();
	pre[0]=-2;
	q.push({0ll,inf});
	while(!q.empty()){
		long long cur  = q.front().fi;
		long long flow = q.front().se;
		q.pop();
		for(auto v: adj[cur]){
			// cout<<v<<' '<<cur<<' '<<cap[cur][v]<<endl;
			if(pre[v]==-1&&cap[cur][v]>0){
				pre[v]=cur;
				long long newflow = min(flow,cap[cur][v]);
				if(v==n+1)return newflow;
				q.push({v,newflow});
			}
		}
	}
	return 0;
}
int main(){
	cin>>n;
	for(long long i =1;i<=n;i++){
		cin>>arr[i];

		if(arr[i]>=0){
			adj[i].pb(n+1);
			adj[n+1].pb(i);
			cap[i][n+1]+=arr[i];
			sum+=arr[i];
		}
		if(arr[i]<0){
			adj[i].pb(0);
			adj[0].pb(i);
			cap[0][i]-=arr[i];
		}
		for(int j =2*i;j<=n;j+=i){
			adj[i].pb(j);
			adj[j].pb(i);
			cap[i][j]= inf;
		}
	}
	while(1){
		memset(pre,-1,sizeof(pre));
		long long add =bfs();
		if(add==0)break;
		maxflow+=add;
		long long cur = n+1;
		while(cur!=0){
			long long prev = pre[cur];
			cap[prev][cur]-=add;
			cap[cur][prev]+=add;
			cur=prev;
		}
	}
	// cout<<maxflow<<endl;
	cout<<sum-maxflow<<endl;

}

