bool ok(int x, const vi &v){
	for(int i : v) if(x % i == 0) return 0;
	return 1;
}
int ind[101];
int n, a[100];
ll rec(int c, vi &v){
	if(c > n) return 0;
	if(!ok(c, v)) return rec(c + 1, v);

	if(!ind[c]){
		ll res = rec(c + 1, v) + a[c - 1];
		v.pb(c);
		res = max(res, rec(c + 1, v));
		v.pop_back();
		return res;
	}
	if(ind[c] != c) return rec(c + 1, v);
	ll mx = -1e18;
	vi mul;
	for(int i = c; i <= n; i += c) if(ok(i, v)) mul.pb(i);
	rep(i, 1 << mul.size()){
		vi u, d;
		ll sum = 0;
		bool skip = 0;

		rep(j, mul.size()) if(i & 1 << j) u.pb(mul[j]); else d.pb(mul[j]);
		rep(j, u.size()) rep(k, d.size()) if(u[j] % d[k] == 0) { skip = 1; break; }
		if(skip) continue;
		for(int j : u) sum += a[j - 1];
		mx = max(mx, sum);
	}
	return mx + rec(c + 1, v);
}
