	}

	Maxflow::init();
	for(long long i=1;i<=n;i++)
		for(long long j=i*2;j<=n;j+=i)
			Maxflow::add_edge(j, i, Maxflow::inf);
	Maxflow::n = n+2;
	Maxflow::source = 0;
	Maxflow::sink = n+1;
	for(long long i=1;i<=n;i++) {
