    ll sum = 0;
    for (int i = 1; i <= N; i++) {
        if (a[i] >= 0) {
            sum += a[i];
            inst.add_edge(T, i, 0);
            inst.add_edge(i, T, a[i]);
        } else {
            inst.add_edge(S, i, -a[i]);
            inst.add_edge(i, T, 0);
        }
    }

    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            if (j % i == 0 && a[i] < 0) {
                inst.add_edge(i, j, 100000000);
            }
        }
    }

    ll f = inst.max_flow(S, T);
    cout << sum - f << endl;

    return 0;
}

