	if (u==t) return f;
	for (int &i=iter[u],v;i;i=e[i].nxt){
		if (e[i].cap>0&&level[v=e[i].v]>level[u]){
			int d=dfs(v,t,min(f,e[i].cap));
			if (d>0){e[i].cap-=d; e[i^1].cap+=d; return d;}
