using namespace std;

ll calcval(vector<ll> &a, vector<bool> smash) {
	ll ret = 0;
	for (int i = 0; i < a.size(); i++) if (!smash[i]) ret += a[i];
	return ret;
}

ll ans(vector<ll> &a, vector<bool> smash) {
	ll ret = calcval(a, smash);
	for (int i = 1; i <= a.size(); i++) {
		bool contflag = true;
		for (int j = 1; i * j <= a.size(); j++) {
			if (!smash[i * j - 1]) contflag = false;
		}
		if (contflag) continue;
		vector<bool> smashcopy(a.size());
		for (int j = 0; j < a.size(); j++) {
			if ((j + 1) % i == 0) smashcopy[j] = true;
			else smashcopy[j] = smash[j];
		}
		if (calcval(a, smash) < calcval(a, smashcopy)) ret = max(ret, ans(a, smashcopy));
	}
	return ret;
}

