int main(){
  int N;
  cin >> N;
  vector<int> a(N);
  for (int i = 0; i < N; i++){
    cin >> a[i];
  }
  int V = N + 2;
  vector<map<int, long long>> E(V);
  long long ans = 0;
  for (int i = 0; i < N; i++){
    if (a[i] > 0){
      ans += a[i];
      E[N][i] = a[i];
      E[i][N + 1] = 0;
    } else {
      E[N][i] = 0;
      E[i][N + 1] = abs(a[i]);
    }
  }
  for (int i = 1; i <= N; i++){
    for (int j = i * 2; j <= N; j += i){
      E[j - 1][i - 1] = INF;
    }
  }
  while (1){
    vector<long long> flow(V, INF);
    vector<int> prev(V, -1);
    prev[N] = N;
    queue<int> Q;
    Q.push(N);
    while (!Q.empty()){
      int v = Q.front();
      Q.pop();
      for (auto edge : E[v]){
        int w = edge.first;
        long long c = edge.second;
        if (prev[w] == -1){
          prev[w] = v;
          flow[w] = min(flow[v], c);
          Q.push(w);
        }
      }
