int N;
ll A[110];
int mem[110] = {0};

ll unit(int n)
{
    ll res = 0;
    if(3 * n > N)
    {
        for(int i = n; i <= N; i++)
        {
            if((i % 2 == 0 && i / 2 >= n) || mem[i])continue;
            if(i * 2 > N)res += max(0LL,A[i]);
            else
            {
                if(mem[i * 2])res += max(0LL,A[i]);
                else res += max(0LL,max(A[i],A[i] + A[i * 2]));
            }
        }
        return res;
    }
    if(mem[n])return unit(n + 1);
    res = A[n] + unit(n + 1);
    for(int i = n * 2; i <= N; i += n)mem[i]++;
    res = max(res,unit(n + 1));
    for(int i = n * 2; i <= N; i += n)mem[i]--;
    return res;
}

