  V<lint> a(n + 1); for (int i = 1; i < n + 1; i++) cin >> a[i];
  VV< edge<lint> > g(n + 2);
  lint res = 0;
  for (int i = 1; i < n + 1; i++) {
    if (a[i] < 0) {
      add_edge(i, n + 1, -a[i], g);
    } else {
      add_edge(0, i, a[i], g);
      res += a[i];
    }
    for (int j = 2 * i; j < n + 1; j += i) {
      add_edge(j, i, inf, g);
    }
  }
  cout << res - dinic<lint>(0, n + 1, g) << '\n';
}

