void Solver::exec(){
	for (int i = n; i > 0; i--)
	{
		ll sum1 = 0;
		ll sum2 = 0;
		for (int j = 1; j <= n; ++j)
		{
			if(check[j] == true) sum1 += a[j]; // わらない
			if(check[j] == true && j % i != 0) sum2 += a[j]; // わる
		}
		if(sum1 < sum2) {
			for (int j = 1; j <= n; ++j)
			{
				if(j % i == 0) check[j] = false;
			}
		}
	}
	ll ans = 0;
	for (int i = 0; i <= n; ++i)
	{
		if(check[i] == true) ans += a[i];
	}
