struct Edge {
    int v, rev;
    ll f, cap;
};

struct Flow {
    vector<vector<Edge> > g;
    vector<int> dist, pos;
    int n, s, t;

    void print() {
        fto(u, 0, n-1) {
            debug(u);
            for(Edge e: g[u]) {
                printf("%d %d %lld %lld\n", e.v, e.rev, e.f, e.cap);
            }
        }
    }

    void addEdge(int u, int v, ll cap) {
        Edge A = {v, sz(g[u]), 0, cap};
        Edge B = {u, sz(g[v]), 0, 0};
        g[u].pb(A);
        g[v].pb(B);
    }

    bool bfs() {
        dist.assign(n, -1);
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for(Edge e: g[u]) {
                if (e.f == e.cap) continue;
                int v = e.v;
                if (dist[v] == -1) {
                    dist[v] = dist[u]+1;
                    q.push(v);
                }
            }
        }
        return (dist[t] != -1);
    }

    ll dfs(int u, ll f) {
        if (u == t)
            return f;
        for(int &i = pos[u]; i < sz(g[u]); ++i) {
            Edge &e = g[u][i];
            if (e.cap == e.f) continue;
            int v = e.v;
//            printf("%d %d\n", u, v);
            if (dist[v] == dist[u]+1) {
                ll df = dfs(v, min(f, e.cap-e.f));
                if (df > 0) {
                    e.f += df;
                    g[v][e.rev].f -= df;
                    return df;
                }
            }
        }
        return -1;
    }

    ll maxFlow(int _s, int _t) {
        s = _s; t = _t;
        ll res = 0;
        while (bfs()) {
//            fto(u, 0, n-1) printf("%d ", dist[u]);
//            puts("");
            pos.assign(n, 0);
            ll x = dfs(s, oo);
            if (x != -1) res += x;
            else break;
        }
        return res;
    }

    Flow(int n): n(n) {
        g.assign(n, vector<Edge>());
    }
};

