#define int long long
using namespace std;

int INF = 1e+12;
int n;
int a[101];

int getScore(bool crash[]) {
	bool tmp[101];
	int i;

	for (i = 1; i <= n; i++) tmp[i] = crash[i];

	for (i = n / 3 + 1; 2 * i <= n; i++) {
		if (crash[i]) { continue; }
		int x = -(a[i] + a[2 * i]);
		int y = -a[2 * i];
		if (0 >= max(x, y)) {}
		else if (x > y) { crash[i] = crash[2 * i] = true; }
		else { crash[2 * i] = true; }
	}
	for (; i <= n; i++) {
		if (!crash[i] && 0 < -a[i]) { crash[i] = true; }
	}

	int score = 0;
	for (i = 1; i <= n; i++) score += a[i];
	for (i = 1; i <= n; i++) if (crash[i]) score -= a[i];
	for (i = 1; i <= n; i++) crash[i] = tmp[i];
	return score;
}

int dfs(int x, bool crash[]) {
	if (x > n / 3) {
		return getScore(crash);
	}

	if (crash[x]) {
		return dfs(x + 1, crash);
	}

	int res1 = dfs(x + 1, crash);

	int i;
	bool back[101];
	for (i = 1; i <= n; i++) back[i] = crash[i];
	for (i = x; i <= n; i += x) crash[i] = true;
	int res2 = dfs(x + 1, crash);
	for (i = 1; i <= n; i++) crash[i] = back[i];

	return max(res1, res2);
}

