int main(){
  const int n = getInt();
  vector<int> a(n);
  REP(i,n) a[i] = getInt();
  ll ans = accumulate(a.begin(), a.end(), 0ll);

  vector<int> r(n, 1);
  for(int i = n; i >= 1; i--){
    ll s = 0;
    REP(j,n) if(r[j] && (j + 1) % i == 0) s += a[j];
    if(s <= 0){
      ans -= s;
      REP(j,n) if((j + 1) % i == 0) r[j] = 0;
    }
  }

  printf("%lld\n", ans);

  return 0;
}

