ll dfs(int x,vector<int> &vec){
    if(x==n+1) return 0;
    bool isDiv=false;
    for(int i=0;i<vec.size();i++){
        isDiv|=(x%vec[i]==0);
    }
    if(isDiv) return dfs(x+1,vec);
    if(a[x]<0){
        if(x>50){
            return dfs(x+1,vec);
        }
        if(x>33){
            vec.push_back(x);
            ll res=dfs(x+1,vec)+max(0LL,a[x]+a[2*x]);
            vec.pop_back();
            return res;
        }
        vec.push_back(x);
        ll res2=dfs(x+1,vec);
        vec.pop_back();
        ll res1=dfs(x+1,vec)+a[x];
        return max(res1,res2);
    }
    else{
        ll res1=dfs(x+1,vec)+a[x];
        return res1;
    }
}

