ll calc_sum(const V<ll> &alist, ll n, const ll idxs[], ll idxs_size)
{
    ll ret = 0LL;

    srep (i, 1, n+1) {
        rep (j, idxs_size) {
            if (i % idxs[j]) continue;
            ret += alist[i];
            break;
        }
    }

    return ret;
}

