inline bool bfs()
{
	int he=1,ti=0,now,tmp;
	memcpy(cur,head,sizeof(cur));
	memset(dep,-1,sizeof(dep));
	q[++ti]=S;dep[S]=1;
	while(he<=ti)
	{
		tmp=q[he++];
		for(now=head[tmp];now;now=nxt[now])
		{
			if(dep[to[now]]==-1&&val[now])
			{
				dep[to[now]]=dep[tmp]+1;
				q[++ti]=to[now];
			}
		}
	}
	return dep[T]!=-1;
}
ll dfs(int x,ll f)
{
	if(x==T)	return f;
	ll res=0;
	for(int &now=cur[x];now;now=nxt[now])
	{
		if(dep[to[now]]==dep[x]+1&&val[now])
		{
			ll tmp=dfs(to[now],min(f,val[now]));
			if(tmp)
			{
				val[now]-=tmp;
				val[now^1]+=tmp;
				res+=tmp;
				f-=tmp;
				if(f==0)	return res;
			}
		}
	}
	dep[x]=-1;
	return res;
}
