		}
		else{
			capacity[i][n+1] = tmp;
            capacity[n+1][i] = 0;
            adj[n+1].push_back(i);
            adj[i].push_back(n+1);
			ans += tmp;
		}
		for(int j = 1;j < i; j++){
			if(i%j == 0){
				capacity[i][j] = INF;
                capacity[j][i] = 0;
                adj[j].push_back(i);
                adj[i].push_back(j);
			}
		}
	}

