		}
		if(sum>=0)continue;
		else {
			que.push(pii(sum,i));
		}
	}
	for(int i=0;i<que.size();i++){
		pii p=que.top(); que.pop();
		ll sum1=0;
		for(int j=1;j<=n;j++){
			if(j>=p.second && j%p.second==0){
				sum1+=a[j-1];
			}
		}
		if(sum1>=0)continue;
		else{
			for(int j=1;j<=n;j++){
				if(j>=p.second && j%p.second==0){
					a[j-1]=0;
				}
			}
		}
	}
	ll value=0;
	REP(i,n){
		value+=a[i];
	}
	cout<<value<<endl;
	return 0;
}

