void insert(int u,int v,int w)
{
	e[++cnt]=(edge){v,last[u],w,0};
	last[u]=cnt;
}
int bfs()
{
	queue<int> q;
	for(int i=1;i<=n+2;i++) dis[i]=INF;
	dis[S]=0;q.push(S);
	while(q.size())
	{
		int x=q.front();q.pop();
		for(int i=last[x];i;i=e[i].nxt)
		if(e[i].cap>e[i].flow&&dis[e[i].to]==INF)
		{
			dis[e[i].to]=dis[x]+1;
			q.push(e[i].to);
		}
	}
	return dis[T]!=INF;
}
ll dfs(int x,ll low)
{
	if(x==T||low==0) return low;
	ll ret=0,st;
	for(int i=cur[x];i;i=e[i].nxt)
	{
		cur[x]=i;
		if(dis[e[i].to]==dis[x]+1&&(st=dfs(e[i].to,min(low,e[i].cap-e[i].flow)))>0)
		{
			ret+=st,low-=st;
			e[i].flow+=st,e[i^1].flow-=st;
			if(!low) break;
		}
	}
	return ret;
}
ll dinic()
{
	ll ret=0;
	while(bfs())
	{
		for(int i=1;i<=n+2;i++) cur[i]=last[i];
		ret+=dfs(S,INF);
	}
	return ret;
}
