//最小费用最大流，求最大费用只需要取相反数，结果取相反数即可。
//点的总数为N，点的编号0~N-1
const int MAXN=10000;
const int MAXM=100000;
const int INF=0x7fffffff;
namespace MCMF
{
	struct Edge
	{
		int to,next,cap,flow,cost;
	}edge[MAXM];
	int head[MAXN],tol;
	int pre[MAXN];
	long long dis[MAXN];
	bool vis[MAXN];
	int N;//节点总个数，节点编号从0~N-1
	void init(int n)
	{
		N=n;
		tol=0;
		memset(head,-1,sizeof(head));
	}
	void addedge(int u,int v,int cap,int cost)
	{
		edge[tol].to=v;edge[tol].cap=cap;edge[tol].cost=cost;edge[tol].flow=0;edge[tol].next=head[u];
		head[u]=tol++;
		edge[tol].to=u;edge[tol].cap=0;edge[tol].cost=-cost;edge[tol].flow=0;edge[tol].next=head[v];
		head[v]=tol++;
	}
	bool spfa(int s,int t)
	{
		queue<int>q;
		for(int i=0;i<N;i++)
		{
			dis[i]=INF;
			vis[i]=false;
			pre[i]=-1;
		}
		dis[s]=0;
		vis[s]=true;
		q.push(s);
		while(!q.empty())
		{
			int u=q.front();
			q.pop();
			vis[u]=false;
			for(int i=head[u];i!=-1;i=edge[i].next)
			{
				int v=edge[i].to;
				if(edge[i].cap>edge[i].flow&&dis[v]>dis[u]+edge[i].cost)
				{
					dis[v]=dis[u]+edge[i].cost;
					pre[v]=i;
					if(!vis[v])
					{
						vis[v]=true;
						q.push(v);
					}
				}
			}
		}
		//for(int i=1;i<N;i++) cout<<pre[i]<<endl;
		//cout<<pre[t]<<endl;
		if(pre[t]==-1)
			return false;
		else
			return true;
	}
	//返回的是最大流，cost存的是最小费用
	int minCostMaxflow(int s,int t,long long &cost)
	{
		int flow=0;
		cost=0;
		while(spfa(s,t))
		{

			int Min=INF;
			for(int i=pre[t];i!=-1;i=pre[edge[i^1].to])
			{
				if(Min>edge[i].cap-edge[i].flow)
					Min=edge[i].cap-edge[i].flow;
                //cout<<i<<endl;
			}
			//cout<<"1"<<endl;
			for(int i=pre[t];i!=-1;i=pre[edge[i^1].to])
			{
				edge[i].flow+=Min;
				edge[i^1].flow-=Min;
				if(edge[i].flow==Min)
				   cost+=edge[i].cost;
			}
			flow+=Min;
		}
		return flow;
	}
}

