typedef LL FTYPE;
struct edge{
    FTYPE flow;
    int to,rev;
};
typedef vector<edge> E;
typedef vector<E> Graph;
#define pb push_back
void addedge(Graph&g,int from,int to,FTYPE f){
    int x=g[from].size();
    int y=g[to].size();
    g[from].pb(edge{f,to,y});
    g[to].pb(edge{(FTYPE)0,from,x});
}

vector<int> bfs(Graph& G,int s){
    int N = G.size();
    queue<int> que;
    vector<int> dist(N,-1);
    dist[s] = 0;
    que.push(s);
    for(;!que.empty();que.pop()){
        auto v=que.front();
        for(auto& e : G[v])
            if(e.flow>0&&dist[e.to]==-1){
                dist[e.to] = dist[v] + 1;
                que.push(e.to);
        }
    }
    return dist;
}

FTYPE maxflow(Graph& G,int s,int t){
    FTYPE res=0;
    int N = G.size();
    while(true){
        auto dist = bfs(G,s);
        if(dist[t] < 0)break;
        vector<unsigned> iter(N,0);
        std::function<FTYPE(int,FTYPE)> dfs=[&](int v,FTYPE f){
            if(v==s)return f;
            for(auto &i = iter[v]; i < G[v].size(); i++){
                edge &e = G[v][i];
                edge &re = G[e.to][e.rev];
                if(re.flow>0 && dist[v] >dist[e.to]){
                    FTYPE d=dfs(e.to,min(f,re.flow));
                    if(d>0){e.flow+=d;re.flow-=d;return d;}
                }
            }
            return (FTYPE)0;
        };
        FTYPE f;
        while((f=dfs(t,114514))> 0)res+=f;
    }
    return res;
}

