	if (a[x] < 0) {
		int b[101] = {0};
		for (int i = 1; i <= n; i++) {
			b[i] = a[i];
		}
		for (int i = x; i <= n; i += x) {
			a[i] = 0;
		}
		dfs(x + 1);
		for (int i = 1; i <= n; i++) {
			a[i] = b[i];
		}
	}
	dfs(x + 1);
}
