struct FordFulkerson {
  struct edge { ll to, cap, rev, idx; bool isrev; };
  vector<vector<edge>> adj;
  vector<ll> used;
  ll timestamp;
  FordFulkerson(ll n) : timestamp(0) { adj.resize(n); used.resize(n,-1); }
  void add_edge(ll from, ll to, ll cap, ll idx = -1) {
    adj[from].push_back({to, cap, (ll)adj[to].size(), idx, false});
    adj[to].push_back({from, 0, (ll)adj[from].size()-1, idx, true});
  }
  ll dfs(ll now, ll to, ll flow) {
    if (now==to) return flow;
    used[now] = timestamp;
    for (auto &x: adj[now]) {
      if (x.cap>0 && used[x.to]!=timestamp) {
        ll d = dfs(x.to, to, min(flow, x.cap));
        if (d>0) {
          x.cap -= d;
          adj[x.to][x.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }
  ll max_flow(ll from, ll to) {
    ll result = 0;
    for (ll f; (f=dfs(from,to,LLINF))>0; timestamp++) result += f;
    return result;
  }
  void output() {
    rep(i,adj.size()) {
      for (auto &x: adj[i]) {
        if (!x.isrev) {
          edge rev = adj[x.to][x.rev];
          cout << x.idx << ":" << i << "->" << x.to << " " << rev.cap << "/" << x.cap+rev.cap << endl;
        }
      }
    }
  }
};

