  ll a[N]; rep(i,N) cin >> a[i];
  ll sum = 0, mi = 0; rep(i,N) { sum += a[i]; mi = min(mi,a[i]); }
  sum -= mi*N;

  FordFulkerson ff(N+2);
  rep(i,N) ff.add_edge(0,i+1,a[i]-mi);
