#include <bits/stdc++.h>
using namespace std;

const int64_t INF = 1e18;

struct Dinic{
    struct edge {
        int64_t to, cap, rev;
        edge(int64_t to, int64_t cap, int64_t rev):to(to), cap(cap), rev(rev){}
    };

    int N, S, T;
    int64_t flow = 0;
    vector<int> level, iter;
    vector<vector<edge>> G;

    Dinic(int N, int S, int T):N(N), S(S), T(T){
        flow = 0;
        level.resize(N);
        iter.resize(N);
        G.resize(N);
    }

    void add_edge(int from, int to, int64_t cap){
        G[from].emplace_back(to, cap, G[to].size());
        G[to].emplace_back(from, 0, G[from].size()-1);
    }

    void bfs(int s){
        fill(level.begin(), level.end(), -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(que.size()){
            int v = que.front(); que.pop();
            for(auto& e : G[v]){
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    int64_t dfs(int v, int t, int64_t f){
        if(v == t) return f;
        for(int& i=iter[v]; i<G[v].size(); i++){
            auto& e = G[v][i];
            if(e.cap > 0 && level[v] < level[e.to]){
                int64_t d = dfs(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int64_t max_flow(){
        while(true){
            bfs(S);
            if(level[T] < 0) return flow;
            fill(iter.begin(), iter.end(), 0);
            while(true){
                int64_t f = dfs(S, T, INF);
                if(f == 0) break;
                flow += f;
            }
        }
    }
};

int main(){
    int N, A[101];
    cin >> N;
    for(int i=1; i<=N; i++) cin >> A[i];

    int S = 101, T = 102;
    Dinic solver(T+1, S, T);

    int64_t pre_gain = 0;

    for(int i=1; i<=N; i++){
        if(A[i] >= 0){
            pre_gain += A[i];
            solver.add_edge(S, i, 0);
            solver.add_edge(i, T, A[i]);
        }else{
            solver.add_edge(S, i, -A[i]);
            solver.add_edge(i, T, 0);
        }
    }

    for(int i=1; i<=N; i++) for(int k=2; i*k<=N; k++){
        solver.add_edge(i, k*i, INF);
    }

    int64_t ans = pre_gain - solver.max_flow();
    cout << ans << endl;
}

