}E[CE];
int hd[CP],ecnt=1;
void add(int x,int y,LL z){
	E[++ecnt].init(x,y,hd[x],z,0);
	hd[x] = ecnt;
	E[++ecnt].init(y,x,hd[y],0,0);
	hd[y] = ecnt;
}

