void copy(int *a,int *b,int pos,int sz){
	for(int i=pos;i<pos+sz;i++) b[i] = a[i];
}

//dinic
int dep[CP];
bool build(int s,int t){ //构造分层图 
	memset(dep,0,sizeof(dep));
	dep[s] = 1;

	queue<int> Q;
	Q.push(s);

	while(!Q.empty()){
		int u = Q.front();
		Q.pop(); 

		for(int k=hd[u]; k; k=E[k].nxt){
			int v = E[k].to;
			if(!dep[v] && E[k].cap-E[k].flow>0){
				dep[v] = dep[u]+1;
				Q.push(v);
			}
		}
	}

	return dep[t];
}
int cur[CP]; //当前弧优化 
LL augment(int u,int t,LL rst){ //多路增广 
	if(u == t) return rst;

	LL used = 0;
	for(int k=cur[u]; k; k=E[k].nxt){
		//cur[u] = k;
		fs &e = E[k];

		if(dep[e.to] == dep[u]+1){
			LL a = augment(e.to,t, min(rst-used,e.cap-e.flow));
			if(a){
				used += a;
				E[k].flow += a;
				E[k^1].flow -= a;
				if(used == rst) return rst;
			}
		}
	}

	return used;
}
LL mf(int s,int t){
	LL _mf = 0;
	while(build(s,t)){
		//copy(hd,cur,1,n+2);
        memcpy(cur, hd, sizeof(int)*(n + 4));
		_mf += augment(s,t,INF);
	}
	return _mf;
}

