template<ll MOD> struct mll_{
	ll val;
	mll_(ll v = 0): val(v % MOD){ if (val < 0) val += MOD; }
	mll_ operator - () const { return -val; }
	mll_ operator + (const mll_ &b) const { return val + b.val; }
	mll_ operator - (const mll_ &b) const { return val - b.val; }
	mll_ operator * (const mll_ &b) const { return val * b.val; }
	mll_ operator / (const mll_ &b) const { return mll_(*this) /= b; }
	mll_ operator + (ll b) const { return *this + mll_(b); }
	mll_ operator - (ll b) const { return *this - mll_(b); }
	mll_ operator * (ll b) const { return *this * mll_(b); }
	friend mll_ operator + (ll a, const mll_ &b) { return b + a; }
	friend mll_ operator - (ll a, const mll_ &b) { return -b + a; }
	friend mll_ operator * (ll a, const mll_ &b) { return b * a; }
	friend mll_ operator / (ll a, const mll_ &b) { return mll_(a)/b; }
	mll_ &operator += (const mll_ &b) { val=(val+b.val)%MOD; return *this; }
	mll_ &operator -= (const mll_ &b) { val=(val+MOD-b.val)%MOD; return *this; }
	mll_ &operator *= (const mll_ &b) { val=(val*b.val)%MOD; return *this; }
	mll_ &operator /= (const mll_ &b) {
		ll c=b.val, d=MOD, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	mll_ &operator += (ll b) { return *this += mll_(b); }
	mll_ &operator -= (ll b) { return *this -= mll_(b); }
	mll_ &operator *= (ll b) { return *this *= mll_(b); }
	mll_ &operator /= (ll b) { return *this /= mll_(b); }
	bool operator == (const mll_ &b) { return val == b.val; }
	bool operator != (const mll_ &b) { return val != b.val; }
	bool operator == (ll b) { return *this == mll_(b); }
	bool operator != (ll b) { return *this != mll_(b); }
	friend bool operator == (ll a, const mll_ &b) { return mll_(a) == b.val; }
	friend bool operator != (ll a, const mll_ &b) { return mll_(a) != b.val; }
	friend ostream &operator << (ostream &os, const mll_ &a) { return os << a.val; }
	friend istream &operator >> (istream &is, mll_ &a) { return is >> a.val; }
	static mll_ Combination(ll a, ll b){
		chmin(b, a-b);
		if (b<0) return mll_(0);
		mll_ c = 1;
		REP(i, b) c *= a-i;
		REP(i, b) c /= i+1;
		return c;
	}
};
using mll = mll_<1000000007LL>; //1000000007LL;// 998244353LL;
using vmll = std::vector<mll>;
using vvmll = std::vector<vmll>;
using vvvmll = std::vector<vvmll>;
using vvvvmll = std::vector<vvvmll>;
using vvvvvmll = std::vector<vvvvmll>;

class DinicMethod{
public:
	struct Edge{ ll to, cap, rev; };
	vector<vector<Edge>> G;
private:
	vll level;
	vll iter;
public:
	DinicMethod(ll nodeNum): G(nodeNum){}

	void Link(ll v, ll u, ll cap, ll rcap = 0){//v→uに重みcapで張る、逆辺も張る
		this->G[v].push_back({u,  cap, (ll)this->G[u].size()});
		this->G[u].push_back({v, rcap, (ll)this->G[v].size()-1});
	}

	ll MaxFlow(ll s, ll t){//s→tの最大流を求める
		ll f, flow = 0;
		while (true){
			this->BfsLevelRenew(s);
			if (this->level[t] < 0) return flow;
			iter.assign(this->G.size(), 0);
			while ((f = this->DfsFindPath(s, t, INF)) > 0) { flow += f; }
		}
	}

private:
	void BfsLevelRenew(ll s) {
		this->level.assign(this->G.size(), -1);
		this->level[s] = 0;
		queue<ll> que;
		que.push(s);
		while (!que.empty()){
			ll from = que.front(); que.pop();
			EACH(e, this->G[from]){
				if (e.cap > 0 && this->level[e.to] < 0){
					this->level[e.to] = this->level[from] + 1;
					que.push(e.to);
				}
			}
		}
	}

	ll DfsFindPath(ll v, ll t, ll f){
		if (v == t) return f;

		for (ll &i = iter[v]; i < (ll)this->G[v].size(); i++){
			Edge &e = this->G[v][i];
			if (e.cap > 0  &&  this->level[v] < this->level[e.to]){
				ll d = this->DfsFindPath(e.to, t, min(f, e.cap));
				if (d > 0){
					e.cap -= d;
					this->G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};


void solve()
{
	ll n;  cin >> n;
	vector<ll> a = cinv<ll>(n);

	DinicMethod din(n+2);
	ll s=n;
	ll t=n+1;

	rep(i, 0, n-1){
		if (a[i]>0){
			din.Link(s, i, a[i]);
			din.Link(i, t, 0);
		}
		if (a[i]<0){
			din.Link(s, i, 0);
			din.Link(i, t, -a[i]);
		}
	}
	rep(x, 1, n){
		rep(k, 2, n){
			if (x*k>n)break;

			din.Link(x*k-1, x-1, INF);
		}
	}

	ll val=din.MaxFlow(s, t);
	ll sum=0;
	rep(i, 0, n-1){
		if (a[i]>0)sum+=a[i];
	}
	ll ans=sum-val;
	cout << ans << '\n';
}

int main(){
#if 1
	solve();
#else
	ll t;  cin >> t;
	rep(i, 0, t-1){
		solve();
	}
#endif
	return 0;
}

