struct edge {
	int to;
	ll cap;
	unsigned rev;
};

int N, a, Rank[102],iter[102];
ll res;
vector<edge>vec[102];

void bfs() {
	memset(Rank, -1, sizeof Rank);
	Rank[0] = 0;
	queue<int>q;
	q.push(0);
	while (!q.empty()) {
		int t = q.front();
		q.pop();
		for (auto i : vec[t]) {
			if (i.cap && Rank[i.to] == -1) {
				Rank[i.to] = Rank[t] + 1;
				q.push(i.to);
			}
		}
	}
}

ll dfs(int x, ll s) {
	if (x == N + 1)return s;
	for (; iter[x] < vec[x].size(); ++iter[x]) {
		if (vec[x][iter[x]].cap&&Rank[vec[x][iter[x]].to] == Rank[x] + 1) {
			ll l = dfs(vec[x][iter[x]].to, min(s, vec[x][iter[x]].cap));
			if (l) {
				vec[x][iter[x]].cap -= l;
				vec[vec[x][iter[x]].to][vec[x][iter[x]].rev].cap += l;
				return l;
			}
		}
	}
	return 0;
}

ll MaxFlow() {
	ll flow = 0;
	while (true) {
		bfs();
		if (Rank[N + 1] == -1) {
			return flow;
		}
		memset(iter, 0, sizeof iter);
		ll f;
		while ((f = dfs(0, 0xE869120E869120))) {
			flow += f;
		}
	}
}


void addedge(int from, int to, ll cap) {
	vec[from].push_back({ to,cap,vec[to].size() });
	vec[to].push_back({ from,0,vec[from].size() - 1 });
}

