	cin >> N;
	for (int i = 1; i <= N; ++i) {
		cin >> a;
		if (a > 0) {
			addedge(i, N + 1, a);
			res += a;
		}
		else {
			addedge(0, i, -a);
		}
		for (int j = i + i; j <= N; j += i) {
			addedge(i, j, 0xE869120E869120);
		}
	}
	cout << res - MaxFlow() << endl;
	return 0;
}

