LL N;

LL ans = 0LL;


/* 最大流 Dinic Ｏ(EV^2)よりかなりはやい */
struct DINIC {
#define  MAX_V 305
	const LL INF = 1LL<<60LL;
	struct edge {
		int to; LL cap, rev;
		edge() {}
		edge(int to, LL cap, LL rev) :to(to), cap(cap), rev(rev) {}
	};

	vector<edge> G[MAX_V];
	LL level[MAX_V], iter[MAX_V];

	void add_edge(int from, int to, LL cap) {
		G[from].push_back(edge(to, cap, G[to].size()));
		G[to].push_back(edge(from, 0, G[from].size() - 1));
	}

	void bfs(int s) {
		memset(level, -1, sizeof(level));
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while (!q.empty()) {
			int v = q.front(); q.pop();
			FOR(i, 0, (int)G[v].size()) {
				edge &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	int dfs(int v, int t, LL f) {
		if (v == t) return f;
		for (LL &i = iter[v]; i < (int)G[v].size(); ++i) {
			edge &e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				LL d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	LL max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) return flow;
			memset(iter, 0, sizeof(iter));
			LL f;
			while ((f = dfs(s, t, INF)) > 0)
				flow += f;
		}
	}

#undef  MAX_V 
};


int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	scanf("%lld", &N);
	VL a(N);
	LL sum = 0;
	FOR(i, 0, N) {
		scanf("%lld", &a[i]);
		if(a[i]>0)sum += a[i];
	}
	DINIC F;
	int s = 0;
	int t = N + 4;
	FOR(i, 0, N) {
		if (a[i] < 0)
			F.add_edge(s, i + 1, -a[i]);
		else F.add_edge(i+1, t, a[i]);
	}
	FOR(i, 1, N + 1) {
		FOR(j, i+1, N + 1) {
			if (j%i == 0) {
				F.add_edge(i, j, LINF);
			}
		}
	}

	ans = sum-F.max_flow(s,t);



	printf("%lld\n", ans);

	return 0;
}

#include <stdio.h>
