using namespace std;
const int N=1e2+10;
const long long int INF=1e16+10;
const int MAX_V=800;
struct edge
{
    long long int to,cap;
	int rev;//终点、容量、反向边
};
vector<edge>G[MAX_V];//图的邻接表表示
int level[MAX_V];//顶点到源点的距离标号
int iter[MAX_V];//当前弧，在其之前的边都已经没有用了
void add_edge(int from,int to,long long int cap)//向图中增加一条从from到to的容量为cap的边
{
    G[from].push_back((edge){to,cap,(int)G[to].size()});
     G[to].push_back((edge){from,0,(int)G[from].size()-1});
}
void bfs(int s)//通过BFS计算从源点出发的距离标号
{
    memset(level,-1,sizeof(level));
    queue<int>que;
    level[s]=0;
    que.push(s);
    while(!que.empty())
    {
        int v=que.front();
        que.pop();
        for(int i=0; i<G[v].size(); ++i)
        {
            edge &e=G[v][i];
            if(e.cap>0&&level[e.to]<0)
            {
                level[e.to]=level[v]+1;
                que.push(e.to);
            }
        }
    }
}
long long int dfs(int v,int t,long long int f)//DFS寻找增广路
{
    if(v==t) return f;
    for(int &i=iter[v]; i<G[v].size(); ++i)
    {
        edge &e=G[v][i];
        if(e.cap>0&&level[v]<level[e.to])
        {
            long long int d=dfs(e.to,t,min(f,e.cap));
            if(d>0)
            {
                e.cap-=d;
                G[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}
long long int Dinic(int s,int t)//求解s到t的最大流
{
    long long int maxflow=0;
    while(1)
    {
        bfs(s);
        if(level[t]<0) return maxflow;
        memset(iter,0,sizeof(iter));
        int f;
        while((f=dfs(s,t,INF))>0)
            maxflow+=f;
    }
}
int main(){
	int n,s=N-1,t=N-2;
	long long int temp,tot=0;
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%lld",&temp);
		if(temp>0)add_edge(i,t,temp);
		else add_edge(s,i,-temp);
		for(int j=i<<1;j<=n;j+=i)add_edge(i,j,INF);
		if(temp>0)tot+=temp;
	}
	printf("%lld\n",tot-Dinic(s,t));
}

