struct edge{int to;ll cap;int rev;};
struct Dinic{
    int n;
    vector<int> lev,itr;
    vector<vector<edge>> G;
    Dinic(int n):n(n){
        itr.resize(n);
        lev.resize(n);
        G.resize(n);
    }
    void add_edge(int from,int to,ll cap){
        G[from].push_back((edge){to,cap,(int)G[to].size()});
        G[to].push_back((edge){from,0LL,(int)G[from].size()-1});
    }

    void bfs(int s){
        lev.assign(n,-1);
        queue<int> q;
        lev[s]=0;
        q.push(s);
        while(!q.empty()){
            int v=q.front();q.pop();
            for(int i=0;i<G[v].size();i++){
                edge &e=G[v][i];
                if(e.cap>0&&lev[e.to]<0){
                    lev[e.to]=lev[v]+1;
                    q.push(e.to);
                }
            }
        }
    }
    ll dfs(int v,int t,ll f){
        if(v==t)return f;
        for(int &i=itr[v];i<G[v].size();i++){
            edge &e=G[v][i];
            if(e.cap>0&&lev[v]<lev[e.to]){
                ll d=dfs(e.to,t,min(f,e.cap));
                if(d>0){
                    e.cap-=d;
                    G[e.to][e.rev].cap+=d;
                    return d;
                }
            }
        }
        return 0;
    }
    ll max_flow(int s,int t){
        ll flow=0;
        for(;;){
            bfs(s);
            if(lev[t]<0)return flow;
            itr.assign(n,0);
            ll f;
            while((f=dfs(s,t,LINF))>0){
                flow+=f;
            }
        }
    }
};
int main(){
    int n;cin>>n;
    vector<ll> a(n+10);
    for(int i=1;i<=n;i++)cin>>a[i];
    Dinic d(n+2);
    int s=0,t=n+1;
    ll ans=0;
    for(int i=1;i<=n;i++){
        ans+=max(a[i],0LL);
        if(a[i]>=0){
            d.add_edge(s,i,a[i]);
            d.add_edge(i,t,0);
        }else{
            d.add_edge(s,i,0);
            d.add_edge(i,t,-a[i]);
        }
        for(int j=i+1;j<=n;j++){
            if(j%i==0){
                if(a[j]>=0){
                    d.add_edge(j,i,a[j]);
                }else{
                    d.add_edge(j,i,0);
                }
            }
        }
    }
    cout<<ans-d.max_flow(s,t)<<endl;
}

