{
    ios_base::sync_with_stdio(false); cin.tie(NULL);
    cin >> n;
    ll sum = 0;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        sum += a[i];
        a[i] *= -1;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j += i) {
            adj[i].push_back(j);
            //adj[j].push_back(i);
        }
    }
    FF graph = FF();
    graph.getflow();
    graph.findReachable(graph.source);
    ll r = 0;
    for (int i = 1; i <= n; i++) {
        if (graph.seen[i]) {
            r += a[i];
            //cout << i << ' ' << a[i] << '\n';
        }
    }
