		add_edge(g, i, snk, geta);
	}
	REP(i, n)
	{
		REP(j, n)
		{
			int k = (i + 1) * (j + 2);
			if (k <= n) add_edge(g, i, k - 1, INF);
			else break;
		}
	}
	ll f = ford_fulkerson(g, src, snk);
	cout << -(f - geta * n) << endl;
	return 0;
}

