X->Yに容量Zの辺を貼る

「Xが赤 or 青だとZ円罰金」
赤だと罰金:X->Tに容量Zの辺
青だと罰金:S->Xに容量Zの辺
*/

int main(){
    int n;
    cin >>n;
    vector<ll> a(n);
    rep(i,n) cin >>a[i];

    // S:割らない, T:割る
    int S = n, T = n+1;

    ll ss = 0;
    rep(i,n){
        if(a[i]>0){
            ss += a[i];
            add_edge(S,i,a[i]);
        }
        else{
            add_edge(i,T,-a[i]);
        }

        int I=i+1;
        rep(j,i){
            int J=j+1;
            if(I%J == 0) add_edge(i,j,F_INF);
        }
    }

    cout << ss - max_flow(S,T) << endl;
    return 0;
}

