void addFlowEdge(Graph &g,int src,int dst,Weight cap){
	while(g.size()<max(src,dst)+1)g.push_back(Edges());
	g[src].push_back(Edge(src,dst,cap,g[dst].size()));
	g[dst].push_back(Edge(dst,src,0,g[src].size()-1));
}
