const int N = 104;
struct edge{
	int from, to; ll c,f;	
};

vector<edge> e;
vector<int> g[N];

void adde(int from, int to, ll w){
	edge f = {from, to, w, 0};
	edge b = {from, to, 0, 0};
	g[from].pb((int) e.size());
	e.pb(f);
	g[to].pb((int) e.size());
	e.pb(b);
}

int q[N], d[N], s,t;

bool bfs(){
	int qh = 0,qt = 0;// [,)
	memset(d,-1, sizeof(d));
	q[qt++] = s;
	d[s] = 0;
	while(qh < qt && d[t] == -1){
		int cur = q[qh++];
		for(int a:g[cur]){
			edge ce = e[a]; // what edge
			if(d[ce.to] == -1 && ce.c > ce.f){
				q[qt++] = ce.to;
				d[ce.to] = d[ce.from] + 1;
			}
		}
	}
	return d[t] != -1; // path still exists
}

int ptr[N];

ll dfs(int cur, ll flow){
	if(flow == 0)return 0;	
	if(cur == t)return flow;  
	for(int &i = ptr[cur]; i < g[cur].size(); ++i){ // for all children
		int id = g[cur][i]; // what edge are we looking at
		if(d[cur] + 1 != d[e[id].to])continue;
		ll pushed = dfs(e[id].to, min(flow, e[id].c - e[id].f)); // how much is actually pushed?
		if(pushed){ // we could maybe reuse this edge
			e[id].f += pushed;
			e[id^1].f -= pushed;
			return pushed;
		}
	}
	return 0;
}

ll dinic(){
	ll ans = 0;
	while(true){
		if(!bfs())break; // no more level graphs
		memset(ptr,0,sizeof(ptr));
		while(ll pushed = dfs(s,INF))ans += pushed;
	}
	return ans;
}

