	fu(i,1,n){
		cin >> a[i];
		if(a[i] > 0){
			best += a[i];	
			adde(i, n + 1, a[i]);
		}
		else{
			adde(0, i, -a[i]);
		}
	}
	fu(i,1,n){
		for(int j = 2*i;j <= n; j += i){
			adde(i,j, INF);
		}
	}
	best -= dinic();
	cout << best << '\n';
}

