            c[i]-=temp;c[i^1]+=temp;f-=temp;rst+=temp;
            if (!f) return rst;
        }
        if (--gap[h[x]]==0) h[s]=n+1;
        ++gap[++h[x]];cur[x]=fi[x];
        return rst;
    } 
    inline int maxflow(int _n,int _s,int _t){
        n=_n;s=_s;t=_t;
        memcpy(cur,fi,sizeof fi);gap[0]=n;
        int mf=0;
        while (h[s]<=n) mf+=dfs(s,1e9);
        return mf;
    }
}
