int main(){
	int mobius[101];
	for(int i = 2;i <= 100;i ++){
		int n=i;
		mobius[i]=1;
		for(int j = 2;j*j <= n;j ++){
			if(n%j==0){
				n/=j;
				if(n%j==0){
					mobius[i]=0;
					break;
				}
				mobius[i]=-mobius[i];
			}
		}
	}
	int n;
	scanf("%d", &n);
	vector <long long> dp(n);
	vector <int> a(n);
	for(int&i:a)
		scanf("%d", &i);
	for(int i = n;i --;){
		dp[i]=a[i];
		for(int j = 2;(i+1)*j <= n;j ++)
			dp[i]+=mobius[j]*dp[(i+1)*j-1];
		if(dp[i]<a[i])
			dp[i]=a[i];
		if(dp[i]<0)
			dp[i]=0;
	}
	printf("%lld\n", dp[0]);
}

