        if (sum < 0){
            for (int x = i; x <= n; x += i) a[x] = 0;
        }
    }

    ll ans = 0;
    REP(mask,1<<22){
        VI c(n+1);
        REP(i,22){
            if (((mask >> i) & 1) == 0) continue;
            int d = i + 1;
            for (int x = d; x <= n; x += d) c[x] = 1;
        }
        ll tmp = 0;
        REP(i,n) if (!c[i]) tmp += a[i];
