const int V = 300002;

struct E { int t; LL c; int r; };
vector<E> g[V];
bool used[V];
const LL INF = 1e12;

void add(int f, int t, LL c) {
	int gt = g[t].size();
	int gf = g[f].size();
	g[f].PB({ t, c, gt });
	g[t].PB({ f, 0, gf });
}

LL dfs(int v, int t, LL f) {
	if(v == t) { return f; }

	used[v] = true;
	inc(i, g[v].size()) {
		E & e = g[v][i];
		if(! used[e.t] && e.c > 0) {
			LL d = dfs(e.t, t, min(f, e.c));
			if(d > 0) {
				e.c -= d;
				g[e.t][e.r].c += d;
				return d;
			}
		}
	}

	return 0;
}

LL flow(int S, int T) {
	LL ans = 0;
	while(true) {
		inc(i, V) { used[i] = false; }
		LL f = dfs(S, T, INF);
		ans += f;
		if(f == 0) { break; }
	}
	return ans;
}

