inline void go()
{
	int id = 0;
	for(int i = 2; i <= n; ++i)
	{
		cost[i] = 0;
		fo(j, n)
			if(j % i == 0 && !bad[j])
				cost[i] -= a[j];
		if(cost[i] > cost[id])
			id = i;
	}
	if(id == 0)
		return;
	fo(i, n)
		if(i % id == 0)
			bad[i] = 1;
	go();      
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n;
	fo(i, n)
		cin >> a[i];
	fo(i, n)
		if(i > n / 2 && a[i] < 0)
			bad[i] = 1;
	go();
	fo(i,n)
		if(!bad[i])
			ans += a[i];
	cout << max(ans, 0ll);
	return 0;
}

