template <typename T>
class ford_fulkerson {
  public:
    struct edge {
      explicit edge(size_t t, T c, size_t r) : to(t), cap(c), rev(r) {}
      size_t to; T cap; size_t rev;
    };

    explicit ford_fulkerson(size_t v): G(v), used(v) {}
    ~ford_fulkerson() = default;

    void add_edge(size_t from, size_t to, T cap) {
      G[from].emplace_back(to, cap, G[to].size());
      G[to].emplace_back(from, 0, G[from].size() - 1);
    }
    T dfs(size_t v, size_t t, T f) {
      if (v == t) return f;
      used[v] = true;
      for (auto &&e : G[v]) {
        if (used[e.to] || e.cap <= 0) continue;
        T d = dfs(e.to, t, std::min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          reverse(e).cap += d;
          return d;
        }
      }
      return 0;
    }
    T max_flow(size_t s, size_t t) {
      T flow = 0;
      while (true) {
        std::fill(used.begin(), used.end(), 0);
        T f = dfs(s, t, infty<lli>);
        if (f == 0) return flow;
        flow += f;
      }
    }

  private:
    std::vector<std::vector<edge>> G;
    std::vector<bool> used;
    edge &reverse(edge const &e) {
      return G[e.to][e.rev];
    }
};

template <typename T, template <class> class Solver>
class project_selection {
  public:
    explicit project_selection(size_t n): solver(n+2), offset(0) {}
    ~project_selection() = default;

    void add_red_benefit(size_t i, T benefit) {
      if (benefit > 0) {
        offset += benefit;
        solver.add_edge(red, i+2, benefit);
      } else {
        solver.add_edge(i+2, blue, -benefit);
      }
    }
    void add_red_penalty(size_t i, T penalty) {
      add_red_benefit(i, -penalty);
    }
    void add_split_penalty(size_t r, size_t b, T penalty) {
      solver.add_edge(r+2, b+2, penalty);
    }
    T max_benefit() {
      return offset - solver.max_flow(red, blue);
    }
  private:
    Solver<T> solver;
    int offset;
    static constexpr size_t red = 0;
    static constexpr size_t blue = 1;
};

using namespace std;

void solve(int n, vector<lli> const &as) {
  project_selection<lli, ford_fulkerson> proj(n+100);
  FOR(i, 1, n) {
    proj.add_red_benefit(i, as[i]);
    for (int j = 2 * i; j <= n; j += i) {
      proj.add_split_penalty(j, i, infty<lli>);
    }
  }
  cout << proj.max_benefit() << endl;
}

int main() {
  // cout << fixed << setprecision(10);

