template<typename T>
struct Max_Flow{
    struct edge{
        int to; T cap; int rev;
        edge(int to, T cap, int rev) : to(to), cap(cap), rev(rev) {}
    };

    vector<vector<edge>> es;
    vector<int> d, pos;
    const T INF_T;

    Max_Flow(int n) : INF_T(numeric_limits<T>::max()){
        es.resize(n), d.resize(n), pos.resize(n);
    }

    void add_edge(int from, int to, T cap, bool directed = true){
        es[from].eb(to, cap, sz(es[to]));
        es[to].eb(from, directed? 0 : cap, sz(es[from])-1);
    }

    bool bfs(int s, int t){
        fill(all(d), -1);
        queue<int> que;
        d[s] = 0, que.push(s);
        while(!que.empty()){
            int i = que.front(); que.pop();
            for(auto &e: es[i]){
                if(e.cap > 0 && d[e.to] == -1){
                    d[e.to] = d[i]+1;
                    que.push(e.to);
                }
            }
        }
        return d[t] != -1;
    }

    T dfs(int now, int t, T flow){
        if(now == t) return flow;
        for(int &i = pos[now]; i < sz(es[now]); i++){
            edge &e = es[now][i];
            if(e.cap > 0 && d[e.to] > d[now]){
                T f = dfs(e.to, t, min(flow, e.cap));
                if(f > 0){
                    e.cap -= f;
                    es[e.to][e.rev].cap += f;
                    return f;
                }
            }
        }
        return 0;
    }

    T max_flow(int s, int t){
        T flow = 0;
        while(bfs(s, t)){
            fill(all(pos), 0);
            T f = 0;
            while((f = dfs(s, t, INF_T)) > 0) flow += f;
        }
        return flow;
    }
};

int main(){
    int N;
    cin >> N;
    Max_Flow<ll> G(N+2);
    int s = 0, t = N+1;
    ll sum = 0;
    rep2(i, 1, N){
        ll a; cin >> a;
        if(a >= 0) G.add_edge(i, t, a), sum += a;
        else G.add_edge(s, i, -a);
        for(int j = 2; i*j <= N; j++) G.add_edge(i, i*j, INF);
    }
    cout << sum-G.max_flow(s, t) << endl;
}

