		level[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int v = q.front();
			q.pop();
			for (auto &e : G[v]) {
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	ll dfs(int v, int t, ll f) {
		if (v == t) return f;
		for (int &i = iter[v]; i < (int)G[v].size(); i++) {
			Edge &e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	ll max_flow(int s, int t) {
		ll flow = 0;
		while (1) {
			bfs(s);
			if (level[t] < 0) return flow;
			memset(iter, 0, sizeof(iter));
			ll f;
			while ((f = dfs(s, t, INF_F)) > 0) {
				flow += f;
			}
		}
	}

};

void solve(void){
	LESEN;
	ll N;
	cin >> N;
	vector <ll> as(N);
	rep(N ,i) cin >> as[i];
	Dinic dinic;
	ll sum = 0LL;
	Rep(1, N, i) {
		if (as[i-1] >= 0LL) {
			dinic.add_edge(0, i, as[i-1]);
			sum += as[i-1];
		}
		else {
			dinic.add_edge(i, N+1, -as[i-1]);
		}
		ll j = 2;
		while (j * i <= N) {
			dinic.add_edge(i*j, i, INF_F);
			j++;
		}
	}
	cout << sum - dinic.max_flow(0, N+1) << endl;
}

int main(void){
	solve();
