const int N = 105;
const int K = 11;

int n;
ll a[N];
ll big[N];
int used[N];
bool isp[N];

void run() {
	cin >> n;
	rep(i, 1, n + 1) {
		cin >> a[i];
		big[i] = i;
		rep(j, 2, K + 1) {
			while (big[i] % j == 0) big[i] /= j;
		}
	}

	rep(i, 2, N) {
		if (isp[i]) continue;
		for (int j = i + i; j < N; j += i) isp[j] = 1;
	}

	ll ans = 0;
	rep(mask, 0, 1 << K) {
		memset(used, 0, sizeof used);
		rep(bit, 0, K) {
			if (mask & (1 << bit)) {
				int step = bit + 1;
				for (int i = step; i <= n; i += step) {
					used[i] = 1;
				}
			}
		}
		ll cur = 0;
		rep(i, 1, n + 1) {
			if (!used[i]) {
				if (big[i] == 1) cur += a[i];
			}
		}

		rep(p, K + 1, n + 1) {
			if (isp[p]) {
				continue;
			}

			ll opt = 0;
			ll mx = 1;
			while ((mx + 1) * p <= n) {
				mx++;
			}

			rep(cool, 0, 1 << mx) {
				rep(bit, 0, mx) {
					if (cool & (1 << bit)) {
						int w = (bit + 1) * p;
						for (int i = w; i <= n; i += w) {
							used[i]++;
						}
					}
				}
				ll wtf = 0;
				for (int i = p; i <= n; i += p) {
					assert(big[i] == p);
					if (!used[i]) wtf += a[i];
				}
				maxi(opt, wtf);
				rep(bit, 0, mx) {
					if (cool & (1 << bit)) {
						int w = (bit + 1) * p;
						for (int i = w; i <= n; i += w) {
							used[i]--;
						}
					}
				}
			}

			cur += opt;
		}

		maxi(ans, cur);
	}

	cout << ans << "\n";
}

