struct dinic{
  struct edgef{
    int to; ll cap; int rev;
    edgef(int to=0,ll cap=0,int rev=0):to(to),cap(cap),rev(rev){}
  };
  static constexpr ll INF = numeric_limits<ll>::max()/2;
  vector<vector<edgef>> nw;
  vector<int> level,itr;

  dinic(size_t sz):nw(sz),level(sz),itr(sz){}

  inline void add_edge(int src, int dst, ll cap)noexcept{
    nw[src].emplace_back(dst,cap,nw[dst].size());
    nw[dst].emplace_back(src,0,nw[src].size()-1);
  }
  bool bfs(int s, int t)noexcept{
    fill(level.begin(),level.end(),-1);
    level[s] = 0;
    queue<int> q;
    q.emplace(s);

    while(!q.empty()){
      auto cur = q.front(); q.pop();
      for(auto e:nw[cur]){
        if(level[e.to]!=-1 || e.cap==0) continue;
        q.emplace(e.to);
        level[e.to] = level[cur]+1;
      }
    }
    return level[t] != -1;
  }
  inline ll rdfs(int now, int s, ll f=INF)noexcept{
    if(now == s) return f;
    ll res = 0;
    for(int& i=itr[now];i<(int)nw[now].size();++i){
      auto &e = nw[now][i];
      auto &r = nw[e.to][e.rev];
      if(r.cap > 0 && level[now] > level[e.to]){
        ll d = rdfs(e.to,s,min(f,r.cap));
        if(d>0){
          r.cap -= d;
          e.cap += d;
          res += d;
          f -= d;
        }
      }
    }
    return res;
  }
  //  rdfs is faster than dfs.
  ll solve(int s, int t)noexcept{
    ll res = 0, flow=-1;
    while(bfs(s,t)){
      flow = -1;
      fill(itr.begin(),itr.end(),0);
      flow = rdfs(t,s);
      res += flow;
    }
    return res;
  }
};
