void go(int i, int n, ll sum){
	if(i*2>n){
		for(int j=i;j<=n;++j) if(!u[j] && a[j]<0) sum-=a[j];
		ans = max(ans, sum);
		return ;
	}

	if(i*3>n){
		if(u[i*2]){
			if(!u[i] && a[i]<0) sum-=a[i];
			go(i+1,n,sum);
			return; 
		}else{
			if(a[i]>=0){
				go(i+1, n, sum);
				return ;
			}else{
				///188..980
				if(a[i*2]<0){
					sum-=a[i]+a[i*2];
					u[i*2] = 1;
					go(i+1, n, sum);
					u[i*2] = 0;
					return ;
				}else{
					if(a[i]+a[i*2]<0) sum-=a[i]+a[i*2], u[i*2] = 1;
					go(i+1, n, sum);
					u[i*2] = 0;
					return ;
				}
			}
		}
	}

	go(i+1, n, sum);

	if(!u[i]){
		for(int j=i;j<=n;j+=i){
			if(!u[j]) sum-=a[j];
			++u[j];
		}
		go(i+1, n, sum);
		for(int j=i;j<=n;j+=i) --u[j];
	}
}


