const LL MAXN=105,INF=1e18;
LL bneck,adj[MAXN][MAXN],source,sink,ans,n,a[MAXN];
bool visited[MAXN],sudah;

void dfs(LL node,LL bottleneck){
	if(node==sink){
		ans-=bottleneck;
		sudah=true;
		bneck=bottleneck;
		return;
	}
	if(!visited[node]){
		visited[node]=true;
		for(LL i=1;i<=n+2;i++){
			if(adj[node][i]>0){
				dfs(i,min(adj[node][i],bottleneck));
				if(sudah){
					adj[node][i]-=bneck;
					adj[i][node]+=bneck;
					return;
				}
			}
		}
	}
}

