using namespace std; 
typedef long long ll; 
int lst[10005], to[100005], pre[100005], rev[100005], tot; 
int dep[10005], fst[10005], que[10005]; 
ll cap[100005]; 
inline void add_edge(int u, int v, ll _cap)
{
	to[tot] = v; 
	pre[tot] = lst[u]; 
	cap[tot] = _cap; 
	rev[tot] = tot + 1; 
	lst[u] = tot++; 
	to[tot] = u; 
	pre[tot] = lst[v]; 
	cap[tot] = 0; 
	rev[tot] = tot - 1; 
	lst[v] = tot++; 
}
inline bool bfs(int s, int t)
{
	int he = 0, ta = 1; 
	que[0] = s; 
	memset(dep, -1, sizeof(dep)); 
	dep[s] = 0; 
	while (he < ta)
	{
		int u = que[he++]; 
		for (int i = lst[u]; ~i; i = pre[i])
		{
			if (cap[i] && dep[to[i]] == -1)
			{
				dep[to[i]] = dep[u] + 1; 
				que[ta++] = to[i]; 
			}
		}
	}
	return dep[t] != -1; 
}
ll dfs(int u, int t, ll mx)
{
	if (u == t)
		return mx; 
	ll ans = 0; 
	for (int i = fst[u]; ~i; i = pre[i])
	{
		if (cap[i] && dep[to[i]] == dep[u] + 1)
		{
			ll res = dfs(to[i], t, min(mx - ans, cap[i])); 
			cap[i] -= res; 
			cap[rev[i]] += res; 
			if (cap[i])
				fst[u] = i; 
			ans += res; 
			if (ans == mx)
				return ans;
		}
	}
	if (!ans)
		dep[u] = -1; 
	return ans; 
}
inline ll dinic(int s, int t)
{
	ll ans = 0; 
	while (bfs(s, t))
	{
		memcpy(fst, lst, sizeof(lst)); 
		ans += dfs(s, t, 1e18); 
	}
	return ans; 
}
