ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN = 100;
const int MAXGN = MAXN + 2;
const int MAXGM = MAXN + MAXN*MAXN;


typedef struct G {
	int n, m;
	int ghead[MAXGN], gto[2 * MAXGM], gnxt[2 * MAXGM]; ll gcap[2 * MAXGM];

	void init(int _n) { n = _n; m = 0; REP(i, n) ghead[i] = -1; }
	void addedge(int a,int b,ll cap) { 
		gnxt[m] = ghead[a], ghead[a] = m, gto[m] = b, gcap[m] = cap, ++m;
		gnxt[m] = ghead[b], ghead[b] = m, gto[m] = a, gcap[m] = 0, ++m;
	}

	ll flow[MAXGN]; int back[MAXGN]; int q[MAXGN], qhead, qtail;
	void upd(int to, ll f, int b) { assert(flow[to] == 0 && f > 0); flow[to] = f; back[to] = b; q[qhead++] = to; }
	ll maxflow(int s, int t) {
		ll ret = 0;
		while (true) {
			REP(i, n) flow[i] = 0, back[i] = -2; qhead = qtail = 0;
			upd(s, LLONG_MAX, -1);
			while (qtail < qhead) {
				int at = q[qtail++];
				for (int x = ghead[at]; x != -1; x = gnxt[x]) {
					int to = gto[x]; if (gcap[x] == 0 || flow[to] > 0) continue;
					upd(to, min(flow[at], gcap[x]), x ^ 1);
				}
			}
			if (flow[t] == 0) return ret;
			ret += flow[t];
			for (int x = t; x != s; x = gto[back[x]]) {
				gcap[back[x]] += flow[t];
				gcap[back[x] ^ 1] -= flow[t];
			}
		}
	}
} G;

int n;
int a[MAXN+1];
G g;


void run() {
	scanf("%d", &n); FORE(i, 1, n) scanf("%d", &a[i]);
	int s = 0, t = n + 1; ll sum = 0; g.init(n + 2);
	FORE(i, 1, n) if (a[i] >= 0) g.addedge(i, t, a[i]), sum += a[i]; else g.addedge(s, i, -a[i]);
	FORE(i, 1, n) if (a[i] < 0) for (int j = i + i; j <= n; j += i) if (a[j] >= 0) g.addedge(i, j, LLONG_MAX);
	ll ret = sum - g.maxflow(s, t);
	printf("%lld\n", ret);
}

int main() {
	run();
	return 0;
}

