#define int long long

constexpr auto INF = LLONG_MAX / 10000;

using namespace std;

class network {
  private:
    struct edge;
    int size;
    vector<vector<edge>> graph;
    struct edge {
      int to, capacity, flow, rev;
      vector<vector<edge>>& graph;
      edge& reverse() {
        return graph[to][rev];
      }
      void add_flow(int df) {
        assert(df > 0);
        flow += df;
        assert(flow <= capacity);
        reverse().flow -= df;
      }
    };

  public:
    network(int n): size(n), graph(n) {}

    void add_edge(int from, int to, int cap) {
      graph[from].push_back({to, cap, 0, static_cast<long long>(graph[to].size()), graph});
      graph[to].push_back({from, cap, cap, static_cast<long long>(graph[from].size() - 1), graph});
    }

    int max_flow(int source, int sink) {
      int flow = 0;
      queue<int> que;
      while (true) {
        que.push(source);
        vector<edge*> path(size, nullptr);
        while (!que.empty()) {
          int v = que.front();
          if (v == sink) break;
          que.pop();
          for (auto& e : graph[v]) {
            if (e.to == source || path[e.to] != nullptr || e.flow == e.capacity)
              continue;
            que.push(e.to);
            path[e.to] = &e;
          }
        }
        if (path[sink] == nullptr)
          break;
        int inc = INF;
        for (auto e = path[sink]; e != nullptr; e = path[e->reverse().to])
          inc = min(inc, e->capacity);
        for (auto e = path[sink]; e != nullptr; e = path[e->reverse().to])
          e->add_flow(inc);
        assert(inc < INF);
        flow += inc;
      }
      return flow;
    }
};

signed main() {
  int n;
  cin >> n;
  vector<int> a(n);
  int reward = 0;
  network graph(n + 2);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    if (a[i] < 0) {
      graph.add_edge(0, i + 1, -a[i]);
    }
    else {
      reward += a[i];
      graph.add_edge(i + 1, n + 1, a[i]);
    }
  }
  for (int i = 1; i <= n; i++)
    for (int j = 2 * i; j <= n; j += i)
      graph.add_edge(i, j, INF);
  cout << (reward - graph.max_flow(0, n + 1)) << endl;
}

