	cin >> n;
	int sum = 0;
	for (int i = 0; i < n; i++) {
		cin >> a[i + 1];
		sum += a[i + 1];
		a[i + 1] *= -1;
	}
	saiki(1);
	cout << sum + MAX << endl;
}

