int n,cnt,a[N];
int bgn[N],nxt[M],to[M],E=1;
LL c[M],ans;
inline void ADD(int u,int v,LL w){nxt[++E]=bgn[u],bgn[u]=E,to[E]=v,c[E]=w;}
inline void add_edge(int u,int v,LL w){ADD(u,v,w),ADD(v,u,0);}
struct Netflow
{
	int cur[N],dis[N],S,T,n;
	inline void init(int s,int t,int cnt){S=s,T=t,n=cnt;}
	inline bool bfs()
	{
		memset(dis,0,n*sizeof(int));
		dis[S]=1;
		queue<int>q;
		q.push(S);
		while(!q.empty())
		{
			int u=q.front();q.pop();
			for(int v,i=bgn[u];i;i=nxt[i])
				if(c[i]&&!dis[v=to[i]])
					dis[v]=dis[u]+1,q.push(v);
		}
		return dis[T]!=0;
	}
	inline LL dfs(int u,LL flow)
	{
		if(u==T)return flow;
		LL ret=flow;
		for(int v,&i=cur[u];i;i=nxt[i])
			if(c[i]&&dis[v=to[i]]==dis[u]+1)
			{
				LL f=dfs(v,min(ret,c[i]));
				c[i]-=f,c[i^1]+=f,ret-=f;
				if(!ret)return flow;
			}
		return flow-ret;
	}
	inline LL Maxflow()
	{
		LL ans=0;
		while(bfs())
		{
			memcpy(cur,bgn,n*sizeof(int));
			ans+=dfs(S,inf);
			cerr<<ans<<endl;
		}
		return ans;
	}
}Dinic;
int main()
{
	int s,t;
	file();
	read(n);
	For(i,1,n)read(a[i]);
	cnt=n;s=++cnt;t=++cnt;
	Dinic.init(s,t,++cnt);
	For(i,1,n)
	{
		if(a[i]>0)add_edge(i,t,a[i]),ans+=a[i];
		else add_edge(s,i,-a[i]);
		For(j,1,n/i)add_edge(i,i*j,inf);
	}
	printf("%lld\n",ans-Dinic.Maxflow());
	return 0;
}

