struct max_flow {
	struct edge { int to, cap, rev; };
	int V;
	vector<vector<edge>> G;
	vector<int> itr, level;

	max_flow(int V) : V(V) { G.assign(V, vector<edge>()); }

	void add_edge(int from, int to, int cap) {
		G[from].push_back({ to, cap, (int)G[to].size() });
		G[to].push_back({ from, 0, (int)G[from].size() - 1 });
	}

	void bfs(int s) {
		level.assign(V, -1);
		queue<int> q;
		level[s] = 0; q.push(s);
		while (!q.empty()) {
			int v = q.front(); q.pop();
			for (auto &e : G[v]) {
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	int dfs(int v, int t, int f) {
		if (v == t) return f;
		for (int& i = itr[v]; i < (int)G[v].size(); ++i) {
			edge& e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	int run(int s, int t) {
		int ret = 0, f;
		while (bfs(s), level[t] >= 0) {
			itr.assign(V, 0);
			while ((f = dfs(s, t, LLONG_MAX)) > 0) ret += f;
		}
		return ret;
	}
};
signed main() {
	int n;
	cin >> n;
	ll sum = 0;
	vector<int> num(n);
	max_flow flow(n + 2);
	REP(i, n) {
		scanf("%lld", &num[i]);
		if(num[i] < 0)
			flow.add_edge(i + 1, n + 1, 0), flow.add_edge(0, i + 1, -num[i]);
		else 
			flow.add_edge(i + 1, n + 1, num[i]), flow.add_edge(0, i + 1, 0), sum = sum + num[i];
	}

	rep(i,1, n + 1) {
		for (int j = i * 2; n >= j; j += i) {
			flow.add_edge(i, j, LLONG_MAX/2000);
		}
	}

	cout << sum - flow.run(0, n + 1) << endl;


	return 0;
}

