ll ans = 0;
vi vec = {21, 27, 29, 31, 33, 34, 35, 36, 37, 38, 39, 40, 41, 43, 44, 45, 46, 47, 49, 50};

void solve() {
	ll res = 0;
	for (int i = 1; i <= n; i++) {
		f[i] = used[i];
		if (!f[i]) {
			res += a[i];
		}
	}
	for (int i : vec) {
		ll cur = 0;
		for (int j = i; j <= n; j += i) {
			if (!f[j]) {
				res += a[j];
			}
		}
		if (cur < 0) {
			for (int j = i; j <= n; j += i) {
				f[j] = 1;
			}
			res -= cur;
		}
	}
	ans = max(ans, res);
}

void rec(int last) {
	for (int i = last + 1; i <= min(n, 50); i++) {
		if (!good[i] && !used[i]) {
			vi tmp(n / i);
			int cur = 0;
			for (int j = i; j <= n; j += i) {
				tmp[cur++] = used[j];
				used[j] = 1;
			}
			rec(i);
			cur = 0;
			for (int j = i; j <= n; j += i) {
				used[j] = tmp[cur++];
			}
		}
	}
	solve();
}

