lint Power(lint A,lint B,lint C){
	if(!B) return 1LL;
	lint tmp=Power(A,B>>1,C);
	return tmp*tmp%C*(B&1?A:1)%C;
}

int T;

int N,Source,Sink;
int Cost[101],Pre[101];
vector<int> Adj[101];
lint X,Flow,Maxflow;
lint Cap[101][101];

lint Augment(int Pos,lint Bottleneck){
    if(Pos==Source) return Bottleneck;
    if(Pre[Pos]!=-1){
        lint Flow=Augment(Pre[Pos],min(Bottleneck,Cap[Pre[Pos]][Pos]));
        Cap[Pre[Pos]][Pos]-=Flow;
        Cap[Pos][Pre[Pos]]+=Flow;
        return Flow;
    }
    return 0;
}

void DFS(int U){
    if(U==Sink) return;
    for(auto V:Adj[U]){
        if(Pre[V]==-1&&Cap[U][V]>0){
            Pre[V]=U;
            DFS(V);
        }
        if(Pre[Sink]!=-1) return;
    }
}

