const long long INFLL = 1e18;
using namespace std;

const ll INF = 1000LL * 1000 * 1000LL * 1000 * 1000 * 1000;
const ll MAXN = 100;

ll a[MAXN + 1];

struct rib {
    ll b, u, c, f;
    size_t back;
};

void add_rib (vector < vector<rib> > & g, ll a, ll b, ll u, ll c) {
    rib r1 = { b, u, c, 0, g[b].size() };
    rib r2 = { a, 0, -c, 0, g[a].size() };
    g[a].push_back (r1);
    g[b].push_back (r2);
}

int main() {
    //ios_base::sync_with_stdio(false);
    //cin.tie(0);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout

    ll n, m, k = 100;
    cin >> n;
    vector < vector<rib> > g (n + 2);
    ll sum = 0;
    for (ll i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        sum += a[i];
        add_rib(g, 0, i, 1, a[i]);
    }
    for (ll i = 1; i <= n; i++) {
        if (2 * i <= n)
            add_rib(g, i, 2 * i, 1, a[2 * i]);
        else
            add_rib(g, i, n + 1, 1, 0);
    }
    ll s = 0, t = n + 1;
    n += 2;

    ll ans = -1e18;
    ans = max(ans, sum);
    ll flow = 0,  cost = 0;
    while (flow < k) {
        vector<ll> id (n, 0);
        vector<ll> d (n, INF);
        vector<ll> q (n);
        vector<ll> p (n);
        vector<size_t> p_rib (n);
        ll qh=0, qt=0;
        q[qt++] = s;
        d[s] = 0;
        while (qh != qt) {
            ll v = q[qh++];
            id[v] = 2;
            if (qh == n)  qh = 0;
            for (size_t i=0; i<g[v].size(); ++i) {
                rib & r = g[v][i];
                if (r.f < r.u && d[v] + r.c < d[r.b]) {
                    d[r.b] = d[v] + r.c;
                    if (id[r.b] == 0) {
                        q[qt++] = r.b;
                        if (qt == n)  qt = 0;
                    }
                    else if (id[r.b] == 2) {
                        if (--qh == -1)  qh = n-1;
                        q[qh] = r.b;
                    }
                    id[r.b] = 1;
                    p[r.b] = v;
                    p_rib[r.b] = i;
                }
            }
        }
        if (d[t] == INF)  break;
        ll addflow = min(1LL, k - flow);
        for (ll v=t; v!=s; v=p[v]) {
            ll pv = p[v];  size_t pr = p_rib[v];
            addflow = min (addflow, g[pv][pr].u - g[pv][pr].f);
        }
        for (ll v=t; v!=s; v=p[v]) {
            ll pv = p[v];  size_t pr = p_rib[v],  r = g[pv][pr].back;
            g[pv][pr].f += addflow;
            g[v][r].f -= addflow;
            cost += g[pv][pr].c * addflow;
        }
        flow += addflow;
        ans = max(ans, sum - cost);
        //cout << flow << " " << cost << "\n";
    }

    cout << ans << "\n";
    return 0;
}

