ll solve(int n, vi a)
{
	bool f = true;
	while (f)
	{
		f = false;
		for (int x = n; x >= 1; x--)
		{
			ll sum = 0;
			FOR(i, 1, n + 1)
			{
				if (i % x == 0) sum += a[i];
			}
			if (sum < 0)
			{
				FOR(i, 1, n + 1)
				{
					if (i % x == 0) a[i] = 0;
				}
				f = true;
				goto next;
			}

			for (int y = x + 1; y <= n; y++)
			{
				if (x * y > n) break;

				sum = 0;
				FOR(i, 1, n + 1)
				{
					if (i % x == 0 || i % y == 0) sum += a[i];
				}
				if (sum < 0)
				{
					FOR(i, 1, n + 1)
					{
						if (i % x == 0 || i % y == 0) a[i] = 0;
					}
					f = true;				
					goto next;
				}
			}

			for (int y = x + 1; y <= n; y++)
			{
				for (int z = y + 1; z <= n; z++)
				{
					sum = 0;
					if (x * y * z > n) break;

					FOR(i, 1, n + 1)
					{
						if (i % x == 0 || i % y == 0 || i % z == 0) sum += a[i];
					}
					if (sum < 0)
					{
						FOR(i, 1, n + 1)
						{
							if (i % x == 0 || i % y == 0 || i % z == 0) a[i] = 0;
						}
						f = true;
						goto next;
					}
				}
			}
		}
	next:;
	}

	ll ans = 0;
	REP(i, n + 1) ans += a[i];
	return ans;
}

