void solve(int n, vector<lli> const &as) {
  ford_fulkerson<lli> ff(n+200);
  int destroy = 150, protect = 151;
  lli offset = 0;
  FOR(i, 1, n) {
    if (as[i] > 0) {
      offset += as[i];
