const int oo = 1e9 + 1;
const int maxn = 1e3 + 1;
int n,S,T,a[maxn],res,cf[maxn],cnt,b[maxn],num[maxn];
vector <pii> e[maxn];

void Enter()
{
    cin >> n;
    for (int i=1;i<=n;++i)
        cin >> a[i];
}

void Connect(int u, int v, int w)
{
    e[u].push_back(pii(++cnt,v));
    cf[cnt] = w;
    e[v].push_back(pii(++cnt,u));
}

void Init()
{
    S = 0;
    T = n + 1;
    for (int i=1;i<=n;++i) {
        if (a[i] < 0) {
            Connect(S,i,-a[i]);
            //res += a[i];
        }
        else {
            Connect(i,T,a[i]);
            res += a[i];
        }
        if (a[i] < 0)
            for (int j=i+i;j<=n;j+=i)
                Connect(i,j,+oo);
    }
}

bool Can(int S, int T)
{
    queue <int> qu;
    fill(b,b+n+1+1,+oo);
    b[S] = 0;
    qu.push(S);
    while (!qu.empty()) {
        int u = qu.front();
        qu.pop();
        if (u == T)
            return 1;
        for (pii p : e[u]) {
            int i = p.i;
            int v = p.v;
            if (cf[i] > 0 && b[v] == +oo) {
                b[v] = b[u] + 1;
                qu.push(v);
            }
        }
    }
    return 0;
}

int Find(int u, int mn)
{
    if (u == T)
        return mn;
    num[u] = cnt;
    for (pii p : e[u]) {
        int i = p.i;
        int v = p.v;
        if (num[v] != cnt && cf[i] > 0 && b[v] == b[u] + 1)
            if (int x = Find(v,min(mn,cf[i]))) {
                cf[i] -= x;
                cf[i^1] += x;
                return x;
            }
    }
    return 0;
}

void Solve()
{
    //cout << res << '\n';
    while (Can(S,T))
        while (int x = (++cnt,Find(S,+oo)))
            res -= x;//, cout << "   " << x << '\n';
    cout << res;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    //OpenFile();

    Enter();
    Init();
    Solve();
}

