typedef long long ll;
const int N = 110;

ll a[N], ans, tot;
int p[N], vis[N], n;

void check()
{
    ll tans = 0;
    FOR(i, 1, n) vis[i] = 1;
    FOR(i, 1, tot) for(int j = p[i]; j <= n; j += p[i]) vis[j] = 0;
    FOR(i, 1, n) if (vis[i]) tans += a[i];
    ans = max(ans, tans);
}

void dfs(int x)
{
    if (x > n) {check(); return;}
    FOR(i, 1, tot) if (x % p[i] == 0) {dfs(x + 1); return;}
    int tt = 1;
    for(int i = 2 * x; i <= n; i += x)
    {
        bool fl = 1;
        FOR(j, 1, tot) if (i % p[j] == 0) {fl = 0; break;}
        if (fl) ++tt;
    }
    if (tt == 1)
    {
        if (a[x] >= 0) dfs(x + 1);
        else
        {
            p[++tot] = x;
            dfs(x + 1); --tot;
        }
    }
    else
    {
        dfs(x + 1);
        p[++tot] = x;
        dfs(x + 1); --tot;
    }
}

