const int MAXN=100;
const int batas=17;
LL n,arr[MAXN+5],sum,tambahmaks=0;
bool aktif[MAXN+5],kelipatan[MAXN+5];
void reactivate(){
	for(int i=0;i<n;i++)
		aktif[i]=true;
}
void bukanlipatan(){
	for(int i=0;i<n;i++)
		kelipatan[i]=false;
}
void matikan(int state){
	for(int i=0;i<batas;i++)
	{
		if(state&(1<<i))
		{
			for(int j=i;j<n;j+=(i+1))
			{
				if(!aktif[j])
					break;
				aktif[j]=false;
			}
		}
	}
}
void BF(){
	LL temp;
	for(int state=0;state<(1<<n);state++)
	{
		reactivate();
		matikan(state);
		temp=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif[i])
				temp+=-arr[i];
		}
		tambahmaks=max(temp,tambahmaks);
	}
}
int bestmodel(vector <int> &daftar){
	int ret=0;
	int calonret;
	//sum all
	calonret=0;
	for(auto isi:daftar)
		calonret+=-isi;
	ret=max(ret,calonret);

	//sum ganjil
	calonret=0;
	for(int i=2;i<daftar.size();i+=2)
	{
		calonret=-daftar[i];
		ret=max(ret,calonret);
	}

	//sum genap
	calonret=0;
	for(int i=1;i<daftar.size();i+=2)
		calonret+=-daftar[i];
	ret=max(ret,calonret);
	return ret;
}
void solve(){
	LL temp;
	vector <int> daftar;
	for(int state=0;state<(1<<batas);state++)
	{
		reactivate();
		matikan(state);
		temp=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif[i])
				temp+=-arr[i];
		}
		bukanlipatan();
		for(int i=batas;i<n;i++)
		{
			if(!aktif[i])
			{
				assert(kelipatan[i]==false);
				continue;
			}
			if(kelipatan[i])
				continue;
			int now=i;
			daftar.clear();
			while(now<n)
			{
				if(aktif[now])
				{
					kelipatan[now]=true;
					daftar.pb(arr[now]);
				}
				else
					daftar.pb(0);
				now+=i+1;
			}
			temp+=bestmodel(daftar);
		}
		tambahmaks=max(temp,tambahmaks);
	}
}
int main()
{
	scan(n);
	sum=0;
	for(int i=0;i<n;i++)
	{
		scan(arr[i]);
		sum+=arr[i];
	}
	if(n<=batas)			//Brute Force
	{
		BF();
	}
	else
	{
		solve();
	}
	//cout<<"sumnya "<<sum<<" tambahnya "<<tambahmaks<<endl;
	sum+=tambahmaks;
	cout<<sum<<endl;
}

