struct Stat {

        ll vallist[103];
        bool selected[103];
        ll next;
        ll sum;
        ll size;

        Stat (const V<ll> &alist) {
                memset(vallist, 0, sizeof(ll) * size);
                memset(selected, 0, sizeof(bool) * size);
                next = 2LL;
                sum = 0LL;
                rep (i, alist.size()) {
                        vallist[i] = alist[i];
                        sum += alist[i];
                }
                size = alist.size();
        }

        Stat (const Stat &s) {
                memcpy(vallist, s.vallist, sizeof(ll) * s.size);
                memcpy(selected, s.selected, sizeof(bool) * s.size);
                next = s.next;
                sum = s.sum;
                size = s.size;
        }

        void break_jewels(void) {
                rep (i, 103) {
                        int ii = i*next;
                        if (ii >= size) break;
                        sum -= vallist[ii];
                        vallist[ii] = 0LL;
                }
                selected[next] = true;
                next++;
        }

        void preservse_jewels(void) {
                next++;
        }
};

int _main()
{
        ll n;
        llin(n);

        V<ll> alist;
        alist.pb(0);
        llina(alist, n);

        for (int i = n / 2 + 1; i <= n; ++i) {
                if (alist[i] < 0LL) alist[i] = 0LL;
        }

        queue<Stat*> q;
        Stat *s = new Stat(alist);
        q.push(s);

        ll ans = 0LL;

        while (!(q.empty())) {
                Stat *s = q.front(); q.pop();
                ans = max(ans, s->sum);

                if (s->next >= n+1) {
                        delete s;
                        break;
                }

                bool pass = false;
                for (int i = 2; i < s->next; ++i) {
                        if (s->selected[i] && (s->next % i == 0)) {
                                pass = true;
                                break;
                        }
                }

                if (!pass) {
                        Stat *ss = new Stat(*s);
                        ss->break_jewels();
                        q.push(ss);
                }

                s->preservse_jewels();
                q.push(s);
        }

        cout << ans;

        return 0;
}

