long long Go(const vector<int>& a, int n, long long used, int ind) {
	if ((ind + 1) * 3 > n) {
		long long res = 0;
		for (int i = ind; i < n; ++i) {
			if ((used >> i) & 1) {
				continue;
			}

			if ((i & 1) && ((i - 1) >> 1) >= ind) {
				continue;
			}

			if (2 * i + 1 < n) {
				if ((used >> (2 * i + 1)) & 1) {
					res += max(a[i], 0);
				} else {
					res += max(a[i] + a[2 * i + 1], max(a[i], 0));
				}
			} else {
				res += max(a[i], 0);
			}
		}
		return res;
	}

	if ((used >> ind) & 1) {
		return Go(a, n, used, ind + 1);
	}

	long long new_used = used;
	for (int x = ind + 1; x <= n; x += (ind + 1)) {
		new_used |= (1LL << (x - 1));
	}

	return max(a[ind] + Go(a, n, used, ind + 1), Go(a, n, new_used, ind + 1));
}

