ll augment(ll pos, ll minEdge) {
	if (pos == s) return minEdge;

	if (p[pos] != -1) {
		ll f = augment(p[pos], min(minEdge, cap[p[pos]][pos]));

		cap[p[pos]][pos] -= f;
		cap[pos][p[pos]] += f;

		return f;
	}

	return 0;
}

void bfs(ll skrg) {
	if (skrg == t) return;
	for (ll i = 0;i < jalan[skrg].size(); i++) {
		ll ttg = jalan[skrg][i];
		if (p[ttg] == -1 && cap[skrg][ttg] > 0) {
			p[ttg] = skrg;
			bfs(ttg);
		}

		if (p[t] != -1) return;
	}
}


