// DP要る？？
//
// mask[1, i)の割りかたが決まっているが、
// それ以降が未確定である時の最大得点
ll dfs(ll i, bitset<S> mask) {
//    cout << i << " " << mask << endl;
    if (i == min(n+1, thres)) {
        ll ret = 0;
        repi(j, 1, i) if (!mask[j]) {
            ret += a[j-1];
        }
        repi(j, thres, n+1) if (!mask[j]) {
            ll tmp = 0; 
            chmax(tmp, a[j-1]);
            if (2*(j-1)<n) {
                mask[2*j] = 1;
                chmax(tmp, a[j-1]+a[2*(j-1)]*(!mask[2*j]));
            }
            mask[j] = 1;
            ret += tmp;
        }
        return ret;
    }
    ll ret = 0;
    chmax(ret, dfs(i+1, mask));
    if (!mask[i]) {
        for (ll j = i; j < S; j += i) {
            mask[j] = 1;
        }
        chmax(ret, dfs(i+1, mask));
    }
    return ret;
}

