    void init(int v){
        V = v; G.resize(v);
    }

    void add_edge(int from, int to, ll cap){
        int a=G[to].size(),b=G[from].size()-1;
        G[from].push_back((edge){to,cap,a});
        G[to].push_back((edge){from,0,b});
    }

