        rep(i,1<<n){
            ll b[n+1];
            rep(j,n+1)b[j] = a[j];
            int i_ = i;
            srep(j,1,n+1){
                if(i_%2==1){
                    srep(k,1,11){
                        if(k*j>n)break;
                        b[k*j] = 0;
                    }
                }
                i_ /= 2;
            }
            ll tmp = 0;
            srep(j,1,n+1)tmp += b[j];
            ans = max(ans,tmp);
        }
    }else{
        rep(i,1<<11){
            ll b[n+1];
            rep(j,n+1)b[j] = a[j];
            int i_ = i;
            srep(j,1,11){
                if(i_%2==1){
                    srep(k,1,101){
                        if(k*j>n)break;
                        b[k*j] = 0;
                    }
                }
                i_ /= 2;
            }
            ll tmp = 0;
            for(int j=n;j>=11;j--){
                int j_ = j;
                srep(k,2,11){
                    while(j_%k==0){
                        j_/=k;
                    }
                }
                if(j_==1)continue;
                ll sum = 0;
                srep(k,1,10){
                    if(j*k>n)break;
                    sum += b[j*k];
                }
                if(sum<0){
                    srep(k,1,10){
                        if(j*k>n)break;
                        b[j*k] = 0;
                    }
                }
            }
            srep(j,1,n+1){
                tmp += b[j];
            }
            ans = max(ans,tmp);
        }
    }

    cout << ans << endl;
    return 0;
}

