void get(ll y)
{
	bi x = y;
	for (int i = 1; i <= 33; i++)if (x[i])for (int j = i; j <= 100; j += i)x[j] = 1;
	ll ans = 0;
	for (int i = 1; i <= 33; i++)if (!x[i])ans += d[i];
