struct dinic{
  struct edge { int to, cap, rev; };
  int V;
  vector<vector<edge>> G;
  vector<int> itr, level;

  dinic(int V) : V(V) { G.assign(V,vector<edge>()); }

  void add_edge(int from, int to, int cap) {
    G[from].push_back((edge) {to, cap, (int) G[to].size()});
    G[to].push_back((edge) {from, 0, (int) G[from].size()-1});
  }

  void bfs(int s) {
    level.assign(V,-1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for(auto &e: G[v]) if (e.cap > 0 and level[e.to] < 0) {
        level[e.to] = level[v] + 1;
        q.push(e.to);
      }
    }
  }

  int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int& i = itr[v]; i < (int) G[v].size(); ++i) {
      edge& e = G[v][i];
      if (e.cap > 0 and level[v] < level[e.to]) {
        int d = dfs(e.to, t, min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  int run(int s, int t) {
    int ret = 0, f;
    while (bfs(s), level[t] >= 0) {
      itr.assign(V,0);
      while ((f = dfs(s, t, linf)) > 0) ret += f;
    }
    return ret;
  }
};

int n, a;

main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n;
  dinic d(n+2);
  ll ans = 0;
  FOR(i, 1, n+1){
    cin >> a;
    if(a > 0){
      ans += a;
      d.add_edge(i, n+1, a);
    }
    if(a < 0){
      d.add_edge(0, i, -a);
    }
    for(int j = i*2; j <= n; j += i) d.add_edge(i, j, 1e14);
  }
  cout << ans - d.run(0, n+1) << endl;
  return 0;
}

