    Dinic dinic(n + 2);
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        if (a > 0) sum += a;
        if (a < 0) {
            dinic.add_edge(n, i, -a);
        } else {
            dinic.add_edge(i, n + 1, a);
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 2; i * j <= n; j++) {
            dinic.add_edge(i - 1, i * j - 1, 1e18);
        }
    }
