#include <bits/stdc++.h>
#define source 200
#define sink 201
#define pii pair<long long, long long>
using namespace std;

const long long INF = 2e16;

int N;
long long A[205];
vector<int> adj[205];
long long cap[205][205];
int par[205];

void edge(int u, int v, long long c) {
  adj[u].push_back(v);
  adj[v].push_back(u);
//  cout << u << " -> " << v << " " << c << "\n";
  cap[u][v] = c;
}

long long BFS() {
  memset(par, -1, sizeof(par));
  queue<pii> q;
  q.emplace(source, INF);
  while(!q.empty()) {
    int u = q.front().first;
    long long flow = q.front().second;
//    cout << u << " " << flow << "\n";
    q.pop();

    for(int v : adj[u]) {
      if(par[v] == -1 && cap[u][v] > 0) {
        par[v] = u;
        long long new_flow = min(flow, cap[u][v]);
        if(v == sink) return new_flow;
        q.emplace(v, new_flow);
      }
    }
  }
//  cout << "NO\n" << "\n";
  return 0;
}

long long macflow() {
  long long flow = 0, new_flow;
  while(1) {
    new_flow = BFS();
    if(new_flow == 0) break;
    flow += new_flow;
    int u = sink;
    while(u != source) {
      cap[par[u]][u] -= new_flow;
      cap[u][par[u]] += new_flow;
      u = par[u];
    }
  }
//  cout << flow << "\n";
  return flow;
}

int32_t main() {
  ios_base::sync_with_stdio(0);
  cin >> N;
  long long sum = 0;
  for(int i = 1; i <= N; i++) {
    cin >> A[i];
    if(A[i] < 0) {
      edge(source, i, -A[i]);
    }else {
      edge(i, sink, A[i]);
      sum += A[i];
    }
    for(int j = i * 2; j <= N; j += i) {
      edge(i, j, INF);
    }
  }
  long long ans = macflow();
//  cout << ans << "\n";
  cout << sum - ans << "\n";
  cin >> N;
}

