          if( ((s_new>>j) & 1) && k%p[j] == 0 ) {
            c |= 2;
          }
        }
        if( c==2 ) nx -= a[k-1];
      }
      dp[i][s_|s] = max(dp[i][s_|s], nx);
    }
  }

  for(int s=0; s<(1<<p.size()); s++){
    ans = max(ans, dp[n][s]);
  }

