typedef long long ll;

int N;
ll A[110];
ll dp[110][100010] = {0};
bool mem[110] = {0};
int p[110] = {0};
int cnt = 0;
vector<int> V;

ll unit(int n,int bit)
{
    if(n == N)return 0;
    if(dp[n][bit] != -1)return dp[n][bit];
    ll res = -100;
    if(mem[n] || n > N / 2)
    {
        for(int i = 0; i < V.size() - 1; i++)
        {
            if(n % V[i] == 0 && bit & (1 << i))return unit(n + 1,bit) + A[n];
        }
        return unit(n + 1,bit);
    }
    else
    {
        int pnt = p[n];
        res = unit(n + 1,bit | (1 << pnt));
        res = max(res,unit(n + 1,bit) + A[n]);
        return res;
    }
    return 0;
}

