#include <bits/stdc++.h>

namespace {

struct Node {
    int v, f, index;

    Node(int v, int f, int index) : v(v), f(f), index(index) {}
};

const int MAXN = 100 + 9;
const int INF = 0x3f3f3f3f;

std::vector<Node> edge[MAXN];

inline void addEdge(const int u, const int v, const int f) {
    edge[u].push_back(Node(v, f, edge[v].size()));
    edge[v].push_back(Node(u, 0, edge[u].size() - 1));
}

int h[MAXN], gap[MAXN];

inline int sap(int v, int flow, int s, int t, int n) {
    if (v == t) return flow;
    register int rec = 0;
    static int iter[MAXN];
    for (register int &i = iter[v]; i < edge[v].size(); i++) {
        register Node *p = &edge[v][i];
        if (h[v] == h[p->v] + 1) {
            register int ret = sap(p->v, std::min(flow - rec, p->f), s, t, n);
            p->f -= ret, edge[p->v][p->index].f += ret;
            if ((rec += ret) == flow || h[s] >= n) return iter[v] = 0, rec;
        }
    }
    if (--gap[h[v]] == 0) h[s] = n;
    gap[++h[v]]++, iter[v] = 0;
    return rec;
}

inline int sap(int s, int t, int n) {
    register int ret = 0;
    for (gap[0] = n; h[s] < n;) ret += sap(s, INF, s, t, n);
    return ret;
}

inline void solve() {
    register int n;
    std::cin >> n;
    const int S = 0, T = n + 1;
    register long long sum = 0;
    for (register int i = 1, a; i <= n; i++) {
        std::cin >> a;
        if (a <= 0)
            addEdge(S, i, -a);
        else
            addEdge(i, T, a), sum += a;
    }
    for (register int i = 1; i <= n; i++)
        for (register int j = i + i; j <= n; j += i) addEdge(i, j, INF);
    std::cout << sum - sap(S, T, T + 1);
}
}  // namespace

int main() {
    // freopen("sample/1.in", "r", stdin);
    solve();
    return 0;
}

