	int S = 0, T = n+1;
	for(int i = 1; i < n+1; ++i) {
		if(v[i] <= 0) addEdge(S, i, adj, E, -v[i]);
		else addEdge(i, T, adj, E, v[i]);
		for(int j = 2; i*j < n+1; ++j) {
			addEdge(i, i*j, adj, E, INF);
		}
	}
	cout << ans - maxflow(S,T,adj,E) << endl;
}

