int smash[105];

long long bf(int n) {
  if(n > N) return 0;
  if(smash[n]) {
    return bf(n + 1);
  }else {
    long long now = A[n] + bf(n + 1);
    for(int i = n + n; i <= N; i += n) {
      smash[i]++;
    }
    now = max(now, bf(n + 1));
    for(int i = n + n; i <= N; i += n) {
      smash[i]--;
    }
    return now;
  }
}

