	bool ok = true;
	for (int i = n; i <= N; i += n) {
		if (A[i] > 0) ok = false;
	}
	if (ok) {
		for (int i = n; i <= N; i += n) {
			A[i] = 0;
		}
	}
	return ok;
}

LL waru(int n) {
	LL sum = 0;
	for (int i = n; i <= N; i += n) {
		sum += A[i];
	}
	if (sum <= 0) {
		for (int i = n; i <= N; i += n) {
			A[i] = 0;
		}
		return sum;
	}
	return 0;
}

