/* 使い切り */
class FlowSolver {
	static const CapacityType INF_CAPACITY;
	static const int CANNOT_REACH;
private:
	GraphWithReverse graph_m;

	CapacityType Ford_fulkerson_sub_rec(int from, int sink, CapacityType curr_max_flow, bool* used_p);
	CapacityType Ford_fulkerson_sub(int source, int sink, bool* used_p);

	void Calc_dist(int start, int* dist_p);
	CapacityType Dinic_sub_rec(int from, int sink, CapacityType curr_max_flow, int* done_index_p, int* dist_p);
	CapacityType Dinic_sub(int source, int sink, int* done_index_p, int* dist_p);
public:
	FlowSolver(const GraphAsList& graph_arg);

	/* source, sink は頂点番号 */

	/* O(E * Maxflow) */
	CapacityType Ford_fulkerson(int source, int sink);
	/* O(E * V ** 2) */
	CapacityType Dinic(int source, int sink);
