template<typename T>
struct FordFulkerson {
    struct edge {
        int to, rev;
        T cap;
        bool isRev;
    };
    int n;
    T ZERO, INF;
    std::vector<std::vector<edge>> G;
    std::vector<int> used;
    int timestamp;
    FordFulkerson(int n, T INF = std::numeric_limits<T>::max(), T ZERO = T())
        : n(n), INF(INF), ZERO(ZERO), G(n), used(n) {}
    void addEdge(int from, int to, T cap) {
        G[from].push_back({to, (int) G[to].size(), cap, false});
        G[to].push_back({from, (int) G[from].size() - 1, ZERO, true});
    }
    T dfs(int v, int t, T f) {
        if (v == t) { return f; }
        used[v] = timestamp;
        for (int i = 0; i < G[v].size(); i++) {
            edge &e = G[v][i];
            if (used[e.to] != timestamp && e.cap > ZERO) {
                T d = dfs(e.to, t, std::min(f, e.cap));
                if (d > ZERO) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return ZERO;
    }
    T calcMaxFlow(int s, int t, T lim) {
        T ret = ZERO;
        fill(used.begin(), used.end(), 0);
        timestamp = 0;
        while (true) {
            timestamp++;
            T f = dfs(s, t, lim);
            if (f == ZERO) { return ret; }
            ret += f;
            lim -= f;
        }
    }
    T calcMaxFlow(int s, int t) { return calcMaxFlow(s, t, INF); }
    std::map<std::pair<int, int>, T> getMaxFlow() {
        std::map<std::pair<int, int>, T> ret;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < G[i].size(); j++) {
                edge &e = G[i][j];
                if (e.isRev) { ret[{e.to, i}] = e.cap; }
            }
        }
        return ret;
    }
    std::map<std::pair<int, int>, T> getMinCut(int s) {
        std::map<std::pair<int, int>, T> ret;
        std::vector<int> visited(n);
        std::queue<int> que;
        que.push(s);
        while (!que.empty()) {
            int v = que.front();
            que.pop();
            if (visited[v]) { continue; }
            visited[v] = true;
            for (int i = 0; i < G[v].size(); i++) {
                edge &e = G[v][i];
                if (e.cap > ZERO) { que.push(e.to); }
            }
        }
        for (int i = 0; i < n; i++) {
            if (visited[i]) { continue; }
            for (int j = 0; j < G[i].size(); j++) {
                edge &e = G[i][j];
                if (e.isRev && visited[e.to]) { ret[{e.to, i}] = e.cap; }
            }
        }
        return ret;
    }
};

