    rep(i, n) {
        if(a[i] >= 0) {
            offset += a[i];
            g.addedge(s, i, 0);
            g.addedge(i, t, a[i]);
        } else {
            g.addedge(s, i, -a[i]);
            g.addedge(i, t, 0);
        }
