typedef long long ll;

const int V=205;
const ll INF=1e13;

struct Edge{
	int to,rev;
	ll cap;
	Edge(){}
	Edge(int to,ll cap,int rev){
		this->to=to;
		this->cap=cap;
		this->rev=rev;
	}
};
vector<Edge>G[V];
int iter[V],level[V];

void add_edge(int u,int v,ll w){
	G[u].push_back(Edge(v,w,(int)G[v].size()));
	G[v].push_back(Edge(u,0,(int)G[u].size()-1));
}

queue<int>que;
void bfs(int s){
	mem(level,-1);
	level[s]=0;
	que.push(s);
	while(!que.empty()){
		int v=que.front();
		que.pop();
		for(int i=0;i<(int)G[v].size();i++){
			Edge& e=G[v][i];
			if(level[e.to]<0 && e.cap>0) level[e.to]=level[v]+1,que.push(e.to);
		}
	}
}

ll dfs(int s,int t,ll f){
	if(s==t) return f;

	for(int& i=iter[s];i<(int)G[s].size();i++){
		Edge& e=G[s][i];
		if(level[s]<level[e.to] && e.cap>0){
			ll d=dfs(e.to,t,min(f,e.cap));
			if(d>0){
				e.cap-=d,G[e.to][e.rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}

ll max_flow(int s,int t){
	ll flow=0;
	while(1){
		bfs(s);
		if(level[t]<0) return flow;
		mem(iter,0);
		while(1){
			ll f=dfs(s,t,INF);
			if(f==0LL) break;
			flow+=f;
		}
	}
}

void solve(){
	int n;
	cin>>n;
	int s=0,t=n+1;
	ll ans=0;
	for(int i=1;i<=n;i++){
		ll x;
		cin>>x;
		if(x<0) add_edge(s,i,-x);
		else add_edge(i,t,x),ans+=x;
		for(int j=2*i;j<=n;j+=i) add_edge(i,j,INF);
	}
	cout<<ans-max_flow(s,t)<<endl;
}

int main(){
    //freopen("in.txt","r",stdin);
    //freopen("out.txt","w",stdout);

	solve();
    return 0;
}

