}

int maxflow(){
	for(int u=0;u<=n+1;u++)
		for(int v=0;v<=n+1;v++)
			radj[u][v]=adj[u][v];

	int max_flow=0;
	int u,v;
	while(bfs()){
		int path_flow= INT_MAX;
		for(v=n+1;v!=0; v=parent[v]){
			u=parent[v];
