template< typename flow_t >
struct FordFulkerson{
  struct edge {
    int to;
    flow_t cap;
    int rev;
  };

  vector<vector<edge>> graph;
  vector<int> used;
  const flow_t INF;

  FordFulkerson(int V):graph(V),used(V),INF(numeric_limits<flow_t>::max()) {}

  void add_edge(int from,int to,flow_t cap){
    graph[from].push_back((edge){to,cap,(int)graph[to].size()});
    graph[to].push_back((edge){from,0,(int)graph[from].size()-1});
  }

  flow_t dfs(int now,int t,flow_t f){
    if(now==t) return f;
    used[now]=true;
    for(int i=0;i<graph[now].size();i++){
      edge &e=graph[now][i];
      if(!used[e.to]&&e.cap>0){
        flow_t d=dfs(e.to,t,min(f,e.cap));
        if(d>0){
          e.cap-=d;
          graph[e.to][e.rev].cap+=d;
          return d;
        }
      }
    }
    return 0;
  }

  flow_t max_flow(int s,int t){
    flow_t flow=0;
    for(;;){
      for(int i=0;i<graph.size();i++) used[i]=0;

      flow_t f=dfs(s,t,INF);
      if(f>0) flow+=f;
      else return flow;
    }
  }
};


int N;
vector<ll> A;

const ll INF=1e18;

int main(){
  cin>>N;
  A.resize(N);
  rep(i,N) cin>>A[i];

  int s=0,t=N+1;
  FordFulkerson<ll> mff(N+2);
  ll ans=0;
  for(int i=0;i<N;i++){
      if(A[i]>0){
          ans+=A[i];
          mff.add_edge(s,i+1,A[i]);
          mff.add_edge(i+1,t,0);
      }else{
          mff.add_edge(s,i+1,0);
          mff.add_edge(i+1,t,abs(A[i]));
      }
  }

  for(int i=0;i<N;i++){
      for(int j=0;j<N;j++){
          if(i==j) continue;
          if((j+1)%(i+1)==0) mff.add_edge(j+1,i+1,INF);
      }
  }

  ans-=mff.max_flow(s,t);
  cout<<ans<<endl;



  return 0;
}

