lint Power(lint A,lint B,lint C){
	if(!B) return 1LL;
	lint tmp=Power(A,B>>1,C);
	return tmp*tmp%C*(B&1?A:1)%C;
}

lint N,Source,Sink;
lint X,Flow,Maxflow;
lint Cost[105],Pre[105];
lint Cap[105][105];
vector<lint> Adj[105];

lint BFS(){
    memset(Pre,-1,sizeof(Pre));
    Pre[Source]=-2;
    queue<pair<lint,lint>> Q;
    Q.push({Source,INF});
    while(!Q.empty()){
        lint Cur=Q.front().first;
        lint Flow=Q.front().second;
        Q.pop();
        for(lint Next:Adj[Cur]){
            if(Pre[Next]==-1&&Cap[Cur][Next]>0){
                Pre[Next]=Cur;
                lint New_Flow=min(Flow,Cap[Cur][Next]);
                if(Next==Sink) return New_Flow;
                Q.push({Next,New_Flow});
            }
        }
    }
    return 0;
}

int main(){
//	ios_base::sync_with_stdio(0);
//	cin.tie(0); cout.tie(0);
    cin>>N;
    for(int i=1;i<=N;++i){
        cin>>Cost[i];
        if(Cost[i]>0){
            X+=Cost[i];
            Adj[i].push_back(N+1);
            Cap[i][N+1]=Cost[i];
        } else {
            Adj[0].push_back(i);
            Cap[0][i]=-Cost[i];
            for(int j=2*i;j<=N;j+=i){
                Adj[i].push_back(j);
                Cap[i][j]=INF;
            }
        }
    }
    Source=0;
    Sink=N+1;
    lint New_Flow;
    while(New_Flow=BFS()){
        Maxflow+=New_Flow;
        lint Cur=Sink;
        while(Cur!=Source){
            lint Prev=Pre[Cur];
            Cap[Prev][Cur]-=New_Flow;
            Cap[Cur][Prev]+=New_Flow;
            Cur=Prev;
        }
    }
    cout<<X-Maxflow<<endl;
	return 0;
}

