using ll = long long;

ll solve(vector<ll> a){
	const int n = a.size() - 1;
	ll answer = accumulate(a.begin(), a.end(), 0ll);
	for(int i = n; i > 0; --i){
		vector<ll> b = a;
		for(int j = i; j <= n; j += i){ b[j] = 0; }
		bool modified = true;
		while(modified){
			modified = false;
			for(int j = n; j > i; --j){
				ll acc = 0;
				for(int k = j; k <= n; k += j){ acc += b[k]; }
				if(acc < 0){
					for(int k = j; k <= n; k += j){ b[k] = 0; }
					modified = true;
				}
			}
		}
		const ll sum = accumulate(b.begin(), b.end(), 0ll);
		if(sum > answer){
			answer = sum;
			a = move(b);
		}
	}
	return answer;
}

