using namespace std;

const int nmax = 110;
const int inf = 0x3f3f3f3f;

int n, a[nmax];
long long sum = 0;

int source, sink;
vector<int> g[nmax];
int cap[nmax][nmax];
int flow[nmax][nmax];
int father[nmax];
int used[nmax];

bool bfs() {
  queue<int> q;
  for (int i = 1; i <= n + 2; i++) father[i] = -1;
  q.push(source);
  father[source] = 0;

  while (!q.empty()) {
    int node = q.front();
    q.pop();

    if (node == sink) {
      break;
    }

    for (int y : g[node]) {
      if (father[y] != -1) continue;
      if (flow[node][y] < cap[node][y]) {
        father[y] = node;
        q.push(y);
      }
    }
  }

  return father[sink] != -1;
}

long long augment() {
  int added = inf;
  for (int i = sink; i != source; i = father[i]) {
    added = min(added, cap[father[i]][i] - flow[father[i]][i]);
  }
  if (added == inf) return 0;
  for (int i = sink; i != source; i = father[i]) {
    flow[father[i]][i] += added;
    flow[i][father[i]] -= added;
  }
  return added;
}

long long maxflow() {
  long long ans = 0;
  while (bfs()) {
    for (int vec : g[sink]) {
      if (father[vec] != -1 && flow[vec][sink] < cap[vec][sink]) {
        father[sink] = vec;
        ans += augment();
      }
    }
  }
  return ans;
}

int main() {
  cin >> n;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
    if (a[i] > 0)
      sum += a[i];
  }

  source = n + 1;
  sink = n + 2;
  for (int i = 1; i <= n; i++) {
    for (int j = i + i; j <= n; j += i) {
      g[i].push_back(j);
      g[j].push_back(i);
      cap[i][j] = inf;
    }
  }
  for (int i = 1; i <= n; i++) {
    if (a[i] < 0) {
      g[source].push_back(i);
      g[i].push_back(source);
      cap[source][i] = -a[i];
    }
    if (a[i] > 0) {
      g[sink].push_back(i);
      g[i].push_back(sink);
      cap[i][sink] = a[i];
    }
  }

  cout << sum - maxflow() << '\n';

  return 0;
}

