using ll = int64_t;
ll N;
vector<ll> a;

ll solve(ll i, vector<ll> erases) {
    if (i == N + 1) {
        auto b = a;
        for (ll e : erases) {
            for (ll j = e; j <= N; j += e) {
                b[j] = 0;
            }
        }
        return accumulate(b.begin(), b.end(), (ll)0);
    }

    ll result = LLONG_MIN;

    //erasesの中にすでにiの約数が入っていれば既に叩き割られている
    for (ll e : erases) {
        if (i % e == 0) {
            return solve(i + 1, erases);
        }
    }

    //叩き割らない場合
    result = max(result, solve(i + 1, erases));

    //叩き割る場合
    erases.push_back(i);
    result = max(result, solve(i + 1, erases));

    return result;
}

