// 割ってない状態を S , 割った状態を T として
// S-Tグラフを構築し最小カットを求める

ll N;

// 辺を表す構造体(行先、容量、G[i]における逆辺のインデックス)
struct edge {ll to, cap, rev; };

vector<edge> G[MAX_V];  // グラフの隣接リスト表現 (index: ノード番号)
bool used[MAX_V];       // DFS で既に調べたかのグラフ

// from から to へ向かう容量 cap の辺をグラフに追加する
void add_edge(ll from, ll to, ll cap) {
    G[from].push_back((edge){to, cap, static_cast<ll>(G[to].size())});
    G[to].push_back((edge){from, 0, static_cast<ll>(G[from].size() - 1)});
}

// 増加パスを DFS で探す
ll dfs(ll v, ll t, ll f) {
    if (v == t) { return f; }
    used[v] = true;
    for(ll i = 0; i < G[v].size(); ++i) {
        edge &e = G[v][i];  // v から延びるエッジ i
        if(!used[e.to] && e.cap > 0) {
            ll d = dfs(e.to, t, min(f, e.cap));
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

// s から t への最大流を求める
ll max_flow(ll s, ll t) {
    ll flow = 0;
    for(;;) {
        memset(used, 0, sizeof(used));
        ll f = dfs(s, t, INF);
        if(f == 0) { return flow; }
        flow += f;
    }
}

