                ll src = found[i];
                ll dst = found[i+1];
                flowcount = min(flowcount, capacities[src][dst]);
            }
            assert(flowcount > 0LL);

            rep (i, (ll)found.size()-1LL) {
                ll src = found[i];
                ll dst = found[i+1];
                capacities[src][dst] -= flowcount;
                capacities[dst][src] += flowcount;
            }
            ret += flowcount;

        }

        return ret;
    }
};







void _main()
{
    ll n; llin(n);
    V<ll> alist; alist.pb(0LL); llina(alist, n);

    MaxFlow mf(n);

    srep (i, 1, n+1) {
        ll j = i * 2;
        while (j <= n) {
            mf.add_link(i, j, 1e18);
            j += i;
        }
    }

    srep (i, 1, n+1) {
        if (alist[i] <= 0LL) mf.add_link(0, i, -alist[i]);
        else mf.add_link(i, n+1, alist[i]);
    }

    ll mincut = mf.solve();

    ll total = 0LL;
    for (auto a : alist) if (a > 0LL) total += a;

    cout << total - mincut << endl;
}

