// Max flow
// !! Be care of double and INF !!
struct Maxflow {
  typedef ll TT;
  int n;
  vi to, next, head, dist, it;
  vector<TT> lim;
  Maxflow(){}
  Maxflow(int n):n(n),head(n,-1),it(n){}
  void add(int a, int b, TT c=1) {
    next.pb(head[a]); head[a] = sz(to); to.pb(b); lim.pb(c);
    next.pb(head[b]); head[b] = sz(to); to.pb(a); lim.pb(0); 
  }
  void bfs(int sv) {
    dist = vi(n,INF);
    queue<int> q;
    dist[sv] = 0; q.push(sv);
    while (!q.empty()){
      int v = q.front(); q.pop();
      for (int i = head[v]; i != -1; i = next[i]) {
        if (lim[i] && dist[to[i]] == INF) { // double !!
          dist[to[i]] = dist[v]+1; q.push(to[i]);
        }
      }
    }
  }
  TT dfs(int v, int tv, TT nf=LINF) { // INF !!
    if (v == tv) return nf;
    for (; it[v] != -1; it[v] = next[it[v]]) {
      int u = to[it[v]]; TT f;
      if (!lim[it[v]] || dist[v] >= dist[u]) continue; // double !!
      if (f = dfs(u, tv, min(nf, lim[it[v]])), f) { // double !!
        lim[it[v]] -= f;
        lim[it[v]^1] += f;
        return f;
      }
    }
    return 0;
  }
  TT solve(int sv, int tv) {
    TT flow = 0, f;
    while (1) {
      bfs(sv);
      if (dist[tv] == INF) return flow;
      rep(i,n) it[i] = head[i];
      while (f = dfs(sv,tv), f) flow += f;
    }
  }
};
//



int main() {
  int n;
  scanf("%d",&n);
  vi a(n+1);
  rrep(i,n) cin>>a[i];
  int sv = 0, tv = n+1;
  Maxflow g(tv+1);
  rrep(i,n)rrep(j,n) {
    if (i < j && j%i == 0) {
      g.add(j,i,LINF);
    }
  }
  ll ans = 0;
  rrep(i,n) {
    if (a[i] > 0) {
      ans += a[i];
      g.add(sv,i,a[i]);
    } else {
      g.add(i,tv,-a[i]);
    }
  }
  ans -= g.solve(sv,tv);
  cout<<ans<<endl;
  return 0;
}

