template<class T> bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T> bool chmin(T &a, const T &b) { if (a>b) { a=b; return 1; } return 0; }

template<class A, size_t N, class T> void Fill(A (&a)[N], const T &v){ fill( (T*)a, (T*)(a+N), v ); }

const ll INF = 0x3fffffff;


ll N, a[105];
ll solve(vector<ll> &v, int n){
	ll ret = 0;
	for(; n < N; n++){
		bool f = false;
		for(auto t: v) if(n % t == 0){ f = true; break; }
		if(f) continue;
		if(n * 6 <= N){
			chmin(ret, solve(v, n+1));
			auto nx = v;
			nx.push_back(n);
			chmin(ret, solve(nx, n+1));
		}else{
			auto dval = [&](int n, int m){
				for(auto t: v){
					if(t > m) break;
					if(t == m) return 0ll;
					if(m == 4 && t == 2) return 0ll;
				}
				if(n*m > N) return 0ll;
				return a[n*m];
			};
			ll d1 = a[n];
			ll d2 = dval(n,2);
			ll d3 = dval(n,3);
			ll d4 = dval(n,4);
			ll d5 = dval(n,5);
			ll sum = d1 + d2 + d3 + d4 + d5;
			if(sum > d2 + d4) continue;
			if(sum > d3) continue;
			if(sum > d4) continue;
			if(sum > d5) continue;
			if(sum >= 0) continue;
			ret += sum;
			v.push_back(n);
		}
	}
	return ret;
}

