ll MOD = 1000000007;

const int MAX_N = 100;

int N;
ll a[MAX_N + 1];

// ford-fulkerson O(FE) F:Flow
// maximum flow problem
// 1. init G[V] by add_edge
// 2. max_flow(s, t) return the max flow

const int MAX_V = MAX_N + 2;

struct edge{int to;ll cap; int rev;};

vector<edge> G[MAX_V];
bool used[MAX_V];

void add_edge(int from, int to, ll cap){
  G[from].push_back((edge){to, cap, int(G[to].size())});
  G[to].push_back((edge){from, 0, int(G[from].size() -1)});
}

int dfs(int v, int t, ll f){
  if(v == t) return f;
  used[v] = true;
  for (int i = 0; i < G[v].size(); i++){
    edge &e = G[v][i];
    if(!used[e.to] && e.cap > 0){
      int d = dfs(e.to, t, min(f, e.cap));
      if (d > 0){
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}

int max_flow(int s, int t){
  int flow = 0;
  for(;;){
    memset(used, 0, sizeof(used));
    int f = dfs(s, t, INFi);
    if(f == 0) return flow;
    flow += f;
  }
}

int main(){
  cin >> N;

  for (int i = 1; i <= N; i++) {
    cin >> a[i];
  }

  ll ans = 0;

  int s = 0, t = N + 1;
  for(int i = 1; i <= N; i++) {
    if(a[i] < 0) {
      add_edge(s, i, -a[i]);
    } else {
      ans += a[i];
      add_edge(i, t, a[i]);
    }
    for(int j = 2; i * j <= N; j++) {
      add_edge(i, i * j, INFll);
    }
  }

  ans -= max_flow(s, t);

  cout << ans << endl;


  return 0;
}

