void solve(int n, vector<long long> a) {
    for (int i = n/2; i < n; i++) {
        if (a[i] < 0) {
            a[i] = 0;
        }
    }
    int x = n/2 -1;
    while (x >= 0) {
        if (a[x] == 0) {
            x--;
            continue;
        }
        int y = x+1;
        long long tot = 0;
        while(y <= n) {
            tot += a[y-1];
            y += x+1;
        }
        if (tot <= 0) {
            y = x+1;
            while(y <= n) {
                a[y-1] = 0;
                y += x+1;
            }
            x = n/2 -1;
            continue;
        }
        x--;
    }
    long long ret = accumulate(a.begin(), a.end(), 0);
    std::cout << ret << std::endl;
}

int main() {
