};

int main(void)
{

	int jwerry_num = 0;
	std::cin >> jwerry_num;
	std::vector<Jwerry> jwerries(jwerry_num);

	for(auto& j : jwerries){
		std::cin >> j.value;
		j.is_broken = false;
	}

	int broken = 0;

	for(int d=2; d<=jwerry_num; d++){
		int sum = 0;

		for(int i=1; i<=jwerry_num; i++){
			if(i % d == 0 && !jwerries[i-1].is_broken) sum += jwerries[i-1].value;
		}

		if(sum < 0){
			for(int i=1; i<=jwerry_num; i++){
				if(i % d == 0 && !jwerries[i-1].is_broken){
				   	jwerries[i-1].is_broken = true;
					broken++;
				}
			}
		}
