using namespace std;

typedef long long LL;
const int maxn=200;
const LL inf=LL(1e10);

struct LINK
{
	int id, next;
	LL flow;
};

int n;
int now;
int h[maxn], a[maxn], nx[maxn];
int level[maxn];
int q[maxn];
LL maxflow;
LL posisum, total;
LINK t[maxn*maxn*2];

void read()
{
	scanf("%d", &n);
	for (int i=1; i<=n; ++i)
		scanf("%d", &a[i]);
}
void join(int u, int v, LL fl)
{
	t[now].id=v; t[now].next=h[u]; t[now].flow=fl; h[u]=now++;
	t[now].id=u; t[now].next=h[v]; t[now].flow=0; h[v]=now++;
}
void build()
{
	for (int i=0; i<=n+1; ++i) h[i]=-1;
	for (int i=1; i<=n; ++i)
	{
		total+=a[i];
		if (a[i]<0)
		{
			posisum+=-a[i];
			join(0, i, -a[i]);
		}
		else join(i, n+1, a[i]);

		for (int j=i*2; j<=n; j+=i)
			join(i, j, inf);
	}
}
bool build_level()
{
	int head=1, tail=1;
	q[1]=0;
	for (int i=0; i<=n+1; ++i) level[i]=-1;
	while (head<=tail)
	{
		int cur=q[(head++)%(n+1)];
		for (int i=h[cur]; i>-1; i=t[i].next)
			if (t[i].flow && level[t[i].id]==-1)
			{
				level[t[i].id]=level[cur]+1;
				q[(++tail)%(n+1)]=t[i].id;
				if (t[i].id==n+1) return true;
			}
	}
	return false;
}
LL dinic(int cur, LL rest)
{
	if (cur==n+1) return rest;
	LL delta=0;
	for (int i=nx[cur]; i>-1; i=nx[cur]=t[i].next)
		if (t[i].flow && level[cur]+1==level[t[i].id])
		{
			LL tmp=dinic(t[i].id, min(rest, t[i].flow));
			rest-=tmp;
			delta+=tmp;
			t[i].flow-=tmp;
			t[i^1].flow+=tmp;
			if (rest==0) break;
		}
	return delta;
}
void solve()
{
	build();
	while (build_level())
	{
		for (int i=0; i<=n+1; ++i) nx[i]=h[i];
		maxflow+=dinic(0, inf*n);
	}
	printf("%lld\n", total+(posisum-maxflow));
}
int main()
{
	read();
	solve();
	return 0;
}

