    for (int i = 0; i < n; ++i) {
        if (a[i] > 0) {
            mf.add_edge(i, sink, a[i]);
        } else if (a[i] < 0) {
            mf.add_edge(source, i, -a[i]);
        }
        for (int j = i + 1; j < n; ++j) {
            if ((j + 1) % (i + 1) == 0) {
                mf.add_edge(i, j, 1LL << 55);
