const int inf=1e9+9;
class DINIC
{
public:

    queue <int> Q; // queue for bfs
    int n, source, sink; // number of vertices, source, sink
    vector < int > cur, dis;  // current neghbour for dfs, distance from bfs
    vector < vector <int> > cap;  // max capacity
    vector < vector <int> > nei; // neighbours

    bool bfs ()
    {
        dis = vector <int> (n+1, -1);
        dis[source] = 0;
        Q.push(source);
        while (!Q.empty())
        {
            int u = Q.front();
            Q.pop();
            for (int v : nei[u])
                if (!~dis[v] && cap[u][v])
                {
                    dis[v]=dis[u]+1;
                    Q.push(v);
                }
        }
        return ~dis[sink];
    }

    int dfs (int u, int mincap)
    {
        if (!mincap || u==sink)
            return mincap;
        int res=0;
        for (int i=cur[u]; i<nei[u].size(); i++)
        {
            if (!mincap)
                break;
            else
                cur[u]=i;
            int v = nei[u][i];
            if (dis[v]==dis[u]+1)
            {
                int f = dfs (v, min(mincap, cap[u][v]));
                mincap-=f;
                res+=f;
                cap[u][v]-=f;
                cap[v][u]+=f;
            }
        }
        return res;
    }

public:

    DINIC (int n, int source, int sink) : n(n), source(source), sink(sink), cap(n+1,vector<int>(n+1,0)), nei(n+1) {}

    int flow ()
    {
        int res = 0;
        while (bfs())
        {
            cur = vector<int> (n+1, 0);
            res += dfs(source,inf);
        }
        return res;
    }

    void addEdge (int fr, int to, int cap1, int cap2 = 0)
    {
        //printf (">> %d %d %d %d\n",fr,to,cap1,cap2);
        nei[fr].push_back(to);
        nei[to].push_back(fr);
        cap[fr][to]+=cap1;
        cap[to][fr]+=cap2;
    }
};
