const int MAXN=100;
const int batas=17;
LL n,sum,tambahmaks=0;
vector <int> arr;
bool aktif[MAXN+5],kelipatan[MAXN+5],aktif2[MAXN+5];
void bukanlipatan(){
	for(int i=0;i<n;i++)
		kelipatan[i]=false;
}
void matikan(int state,int ukuran,bool aktif[MAXN+5]){
	for(int i=0;i<ukuran;i++)
	{
		if(state&(1<<i))
		{
			for(int j=i;j<n;j+=(i+1))
			{
				if(!aktif[j])
					break;
				aktif[j]=false;
			}
		}
	}
}
LL BF(vector <int> &daftar){
	LL calonret,ret=0;
	for(int state=0;state<(1<<daftar.size());state++)
	{
		for(int i=0;i<daftar.size();i++)
			aktif[i]=true;
		matikan(state,daftar.size(),aktif);
		calonret=0;
		for(int i=0;i<daftar.size();i++)
		{
			if(!aktif[i])
				calonret+=-daftar[i];
		}
		ret=max(calonret,ret);
	}
	return ret;
}
LL solve(){
	LL calonret,ret=0;
	vector <int> daftar;
	for(int state=0;state<(1<<batas);state++)
	{
		memset(aktif2,true,sizeof(aktif2));
		matikan(state,batas,aktif2);
		calonret=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif2[i])
				calonret+=-arr[i];
		}
		memset(kelipatan,false,sizeof(kelipatan));
		for(int i=batas;i<n;i++)
		{
			if(kelipatan[i])
				continue;
			int now=i;
			daftar.clear();
			while(now<n)
			{
				if(aktif[now])
				{
					kelipatan[now]=true;
					daftar.pb(arr[now]);
				}
				else
					daftar.pb(0);
				now+=i+1;
			}
			calonret+=BF(daftar);
		}
		ret=max(calonret,ret);
	}
	return ret;
}
int main()
{
	scan(n);
	sum=0;
	arr.resize(n);
	for(int i=0;i<n;i++)
	{
		scan(arr[i]);
		sum+=arr[i];
	}
	if(n<=batas)			//Brute Force
	{
		tambahmaks=BF(arr);
	}
	else
	{
		tambahmaks=solve();
	}
	//cout<<"sumnya "<<sum<<" tambahnya "<<tambahmaks<<endl;
	sum+=tambahmaks;
	cout<<sum<<endl;
}

