    ll a[n+1] = {};
    srep(i,1,n+1){
        cin >> a[i];
        if(0 < a[i]){
            ans += a[i];
            add_edge(s_, i, 0);
            add_edge(i, t_, a[i]);
        }else{
            add_edge(s_, i, -a[i]);
            add_edge(i, t_, 0);
        }
    }

    srep(i,1,n+1){
        srep(j,i+1,n+1){
            if(j % i == 0){
                add_edge(i, j, LINF);
            }
        }
    }


    ll cut = max_flow(s_, t_);
    ans -= cut;


    cout << ans << endl;
    return 0;
}

