	struct Edge{
		int u, v, c, f;
		Edge() {}
		Edge( int u, int v, int c, int f ) :
			u(u), v(v), c(c), f(f) {}
	} edge[MAXM<<1];
	int n, ecnt, head[MAXN], nxt[MAXM<<1];
	inline void init(){
		ecnt = 0;
		memset( head, -1, sizeof head );
	}
	inline void adde( int u, int v, int c ){
		edge[ecnt] = Edge( u, v, c, 0 );
		nxt[ecnt] = head[u]; head[u] = ecnt++;
		edge[ecnt] = Edge( v, u, 0, 0 );
		nxt[ecnt] = head[v]; head[v] = ecnt++;
	}
	int dis[MAXN], cur[MAXN];
	queue<int> bfsq;
	inline bool bfs(){
		for( int i = 0; i <= n; ++i ) dis[i] = 0;
		dis[s] = 1; bfsq.push(s);
		while( !bfsq.empty() ){
			int u = bfsq.front(); bfsq.pop();
			for( int i = head[u]; ~i; i = nxt[i] ){
				Edge &e = edge[i];
				if( e.c > e.f && !dis[e.v] ){
					dis[e.v] = dis[u] + 1;
					bfsq.push(e.v);
				}
			}
		}
		return dis[t];
	}
	ll dfs( int u, ll res ){
		if( u == t || !res ) return res;
		ll flow = 0;
		for( int &i = cur[u]; ~i; i = nxt[i] ){
			Edge &e = edge[i];
			if( e.c > e.f && dis[e.v] == dis[u] + 1 ){
				ll f = dfs( e.v, min( res, (ll)e.c-e.f ) );
				flow += f; res -= f;
				e.f += (int)f; edge[i^1].f -= (int)f;
				if( !res ) break;
			}
		}
		return flow;
	}
	inline ll mincut(){
		ll flow = 0;
		while( bfs() ){
			for( int i = 0; i <= n; ++i ) cur[i] = head[i];
			flow += dfs( s, LINF );
		}
		return flow;
	}
}

