int Bfs(){
	memset(d,0,sizeof d);
	d[S] = 1;queue<int>q;
	q.push(S);
	while(q.size()){
		int x = q.front();q.pop();
		for(int i = head[x],y; y = E[i].to,i; i = E[i].last){
			if(E[i].res && !d[y])d[y] = d[x] + 1,q.push(y);
		}
	}
	return d[T];
}
LL Dfs(int x,LL flow){
	if(x == T || !flow)return flow;
	LL tmp = flow;
	for(int& i = H[x],y; y = E[i].to,i; i = E[i].last){
		if(d[y] == d[x] + 1){
			LL a = Dfs(y,min(flow,E[i].res));
			E[i].res -= a;E[i ^ 1].res += a;
			flow -= a;
			if(!flow)break;
		}
	}
	return tmp - flow;
}
