using namespace std;
constexpr long long INF = 1LL << 62;

// Dinic O(|E||V|^2)
struct Edge { int dst; long long cap; int rev; };
using Edges = vector<Edge>;
using Graph = vector<Edges>;

struct Dinic {
    int n, s, t;
    vector<int> level, iter;
    Graph g;

    Dinic(int n) : g(n), n(n) {}
    void add_edge(int src, int dst, long long cap) {
        g[src].push_back((Edge){ dst, cap, (int)g[dst].size()  });
        g[dst].push_back((Edge){ src, 0  , (int)g[src].size()-1});
    }

    void bfs(int s) {
        level.assign(n, -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(!que.empty()){
            int v = que.front(); que.pop();
            for(Edge e : g[v]) {
                if(e.cap > 0 && level[e.dst] < 0){
                    level[e.dst] = level[v] + 1;
                    que.push(e.dst);
                }
            }
        }
    }

    long long dfs(int v,int t,long long f){
        if(v==t) return f;
        for(int &i = iter[v]; i < (int)g[v].size(); ++i){
            Edge &e = g[v][i];
            if(e.cap > 0 && level[v] < level[e.dst]){
                long long d = dfs(e.dst, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    g[e.dst][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    long long max_flow(int s,int t) {
        long long flow = 0;
        while(true){
            bfs(s);
            if(level[t] < 0) return flow;
            iter.assign(n,0);
            long long f = 0;
            while((f = dfs(s, t, INF)) > 0){
                flow += f;
            }
        }
    }
};

int main() {
    cin.tie(0); ios_base::sync_with_stdio(false);
    int n; cin >> n;
    int a[100];
    long long sum = 0;
    for(int i=0; i < n; ++i) {
        cin >> a[i];
        if(a[i] > 0) sum += a[i];
    }

    Dinic dn(n + 2);
    int S = n, T = n + 1;
    // S : break, T : not break
    // classify each a[i] into two classes, and minimize losses
    for(int i=0; i < n; ++i) {
        if(a[i] <= 0) dn.add_edge(S, i, -a[i]); // when classify this i to T(not break), lose a[i]
        else dn.add_edge(i, T, a[i]);
    }
    // penalty of classifying (j = 2*i,3*i,...) to same class is INF
    for(int i=0; i < n; ++i) {
        for(int j=0; j < n; ++j) {
            if((j+1)%(i+1)==0) {
                dn.add_edge(i, j, INF);
            }
        }
    }

    cout << sum - dn.max_flow(S, T) << '\n';
    return 0;
}

