using namespace std;

bitset <100> maskdiv[100], full, invmaskdiv[100];
int n;
vector <int> a;
long long ans=0ll;
void bruteForcePrune(long long potential, long long curr=0ll, bitset <100> currmask=full, int pos=1){
	if(potential<=ans)
		return;
	if(pos==n){
		ans=curr;
		return;
	}
	if(!currmask[pos]){
		return bruteForcePrune(potential, curr, currmask, pos+1);
	}
	if(a[pos]>=0){
		return bruteForcePrune(potential, curr+a[pos], currmask, pos+1);
	}
	bruteForcePrune(potential+a[pos], curr+a[pos], currmask, pos+1);
	bitset <100> toDelete=currmask&maskdiv[pos];
	for(int i = pos+1;i < n;i ++){
		if(toDelete[i]){
			if(a[i]>0){
				potential-=a[i];
			}
		}
	}
	return bruteForcePrune(potential, curr, currmask&invmaskdiv[pos], pos+1);
}
int main(){
	full.set();
	for(int i = 0;i < 100;i ++){
		for(int j = i+1;j <= 100;j += i+1){
			maskdiv[i][j-1]=true;
		}
		invmaskdiv[i]=~maskdiv[i];
	}
	scanf("%d", &n);
	a.resize(n);
	long long fullPotential=0ll;
	for(int&i:a){
		scanf("%d", &i);
	}
	for(int i = 1;i < n;i ++){
		fullPotential+=max(a[i], 0);
	}
	bruteForcePrune(fullPotential);
	printf("%lld\n", max(ans+a[0], 0ll));
}

