struct EDGES{
    ll u,v,cap,flow,nextedge;
};
class MAXIMUM_FLOW{
    public :
    EDGES edge[MAXE];
    ll n , m , level[MAXN],Prev[MAXN],last[MAXN];
    queue<ll>Q;
    void init(ll N){
        n = N;
        m = -1;
        for(ll j=0;j<=n;j++) last[j] = -1;
    }
    void addedge(ll a,ll b,ll c){
        edge[++m].u=a , edge[m].v=b , edge[m].cap=c , edge[m].flow=0 , edge[m].nextedge=last[a] , last[a]=m;
        edge[++m].u=b , edge[m].v=a , edge[m].cap=0 , edge[m].flow=0 , edge[m].nextedge=last[b] , last[b]=m;
    }
    bool level_graph(ll src,ll snk){
        for(ll j=0;j<=n;j++) level[j]=-1;
        ll node,nxt;
        level[src]=1;
        Q.push(src);
        while(!Q.empty()){
            node=Q.front(); Q.pop();
            for(ll j=last[node];j!=-1;j=edge[j].nextedge){
                nxt=edge[j].v;
                if(level[nxt]==-1 && edge[j].flow<edge[j].cap){
                    level[nxt]=level[node]+1;
                    Q.push(nxt);
                }
            }
        }
        return (level[snk]!=-1);
    }
    ll dfs(ll node,ll snk,ll flow){
        ll nxt,curflow;
        if(node==snk) return flow;
        for(ll &j=Prev[node];j!=-1;j=edge[j].nextedge){
            nxt=edge[j].v;
            if(level[nxt]==level[node]+1 && edge[j].flow<edge[j].cap){
                curflow=dfs(nxt,snk,min(flow,edge[j].cap-edge[j].flow));
                if(curflow==0) continue;
                edge[j].flow+=curflow;
                edge[j^1].flow-=curflow;
                return curflow;
            }
        }
        return 0;
    }
    ll MAX_FLOW(ll src,ll snk){
        ll flow,ans=0;
        while(level_graph(src,snk)){
            for(ll j=0;j<=n;j++)
                Prev[j]=last[j];
            while(flow=dfs(src,snk,(1<<31)-1)) ans+=flow;
        }
        return ans;
    }
