class Dinic{
public:

  struct edge{
    Int to,cap,rev;
    edge(){};
    edge(Int to,Int cap,Int rev):to(to),cap(cap),rev(rev){};
  };

  Int V;
  vector<vector<edge> > G; //グラフの隣接リスト表現
  vector<Int> level;       //sからの距離
  vector<Int> iter;        //どこまで調べ終わったか
  Int INF;

  Dinic():V(-1){};
  Dinic(Int V,Int INF=1e9):V(V),G(V),level(V),iter(V),INF(INF){}

  //fromからtoへ向かう容量capの辺をグラフに追加。
  void add_edge(Int from,Int to,Int cap){
    assert(from < V && to < V);
    G[from].push_back(edge(to,cap,G[to].size()));
    G[to].push_back(edge(from,0,G[from].size()-1));
  }

  //sからの最短距離をBFSで計算する
  void bfs(Int s){
    level.clear(); level.resize(V,-1);
    queue<Int> que;
    level[s] = 0;
    que.push(s);
    while(!que.empty()){
      Int v = que.front(); que.pop();
      for(edge &e : G[v])
        if(e.cap > 0 && level[e.to] < 0){
          level[e.to] = level[v] + 1;
          que.push(e.to);
        }
    }
  }

  //増加パスをDFSで探す。
  Int dfs(Int v,Int t,Int f){
    if(v==t) return f;
    for(Int &i= iter[v]; i<(Int)G[v].size(); i++){
      edge &e = G[v][i];
      if(e.cap > 0 && level[v] < level[e.to]){
        Int d = dfs(e.to, t, min(f, e.cap));
        if(d > 0){
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  //sからtへの最大流を求める
  Int max_flow(Int s,Int t){
    assert(V >= 0);
    Int flow=0;
    for(;;){
      bfs(s);
      if(level[t] < 0) return flow;
      iter.clear();iter.resize(V,0);
      Int f;
      while((f=dfs(s ,t ,INF)) > 0 ) flow += f;
    }
  }
};


