  for(Int i=1;i<=n;i++)
    for(Int j=2;i*j <= n; j++) {
      D.add_edge(i*j, i , INF);
    }

  for(Int i=1;i<=n;i++){
    if(A[i-1] < 0) continue;
    D.add_edge(S, i, abs(A[i-1]));
  }

  for(Int i=1;i<=n;i++){
    if(A[i-1] > 0) continue;
    D.add_edge(i, T, abs(A[i-1]));
  }

  Int sum = 0;
  for(Int i=0;i<n;i++) if(A[i] > 0) sum += A[i];
  Int ans = sum - D.max_flow(S, T);
  cout<<ans<<endl;
  return 0;
}

