using ll = long long;

constexpr ll inf{ numeric_limits<ll>::max() / 101 };

struct FordFulkerson {
    using T = tuple<ll, ll, ll>; // to, cap, rev
    vector<vector<T>> G;
    vector<bool> used;
    FordFulkerson(ll N) :G(N), used(N) {}
    ll dfs(ll v, ll t, ll f) {
        if(v == t) return f;
        used[v] = true;
        for(auto& e : G[v]) {
            ll to, cap, rev; tie(to, cap, rev) = e;
            if(used[to] || cap <= 0) continue;
            ll res{ dfs(to, t, min(f, cap)) };
            if(res <= 0) continue;
            get<1>(e) -= res;
            get<1>(G[to][rev]) += res;
            return res;
        }
        return 0;
    }
    void add_edge(ll from, ll to, ll cap) {
        G[from].emplace_back(to, cap, G[to].size());
        G[to].emplace_back(from, 0, G[from].size() - 1);
    }
    ll max_flow(ll s, ll t) {
        ll res{}, flow{ 1 };
        for(;flow; res += flow) {
            fill(used.begin(), used.end(), false);
            flow = dfs(s, t, inf);
        }
        return res;
    }
};

ll N, a[101], ans;
int main() {
    cin >> N;
    FordFulkerson ff(N + 2);
    for(int i{ 1 }; i <= N; ++i) cin >> a[i];
    for(int i{ 1 }; i <= N; ++i) {
        if(a[i] > 0) ans += a[i], ff.add_edge(i, N + 1, a[i]);
        else ff.add_edge(0, i, -a[i]);
        for(int j{ i * 2 }; j <= N; j += i)
            ff.add_edge(i, j, inf);
    }
    cout << ans - ff.max_flow(0, N + 1) << endl;
}

