    V<ll> A(N + 1);
    for(ll i = 0; i < N; i++) {
        ll e;
        cin >> e;
        A[i + 1] = e;
        sum += e;
    }

    ll ans = sum;
    ll init_n = min<ll>(10, N);
    for(ll S = 0; S < (1ll << init_n); S++) {
        V<bool> used(N + 1, false);
        V<bool> calced(N + 1, false);
        BS bs(S);
        ll calc = sum;
        for(ll j = 0; j < init_n; j++) {
            if(!bs.test(j)) continue;
            for(ll k = 1; (j + 1) * k <= N; k++) {
                ll idx = (j + 1) * k;
                if(used[idx]) continue;
                calc -= A[idx];
                used[idx] = true;
            }
        }
        for(ll a = init_n + 1; a <= N; a++) {
            if(calced[a]) continue;
            V<ll> jlis;
            for(ll j = 1; a * j <= N; j++) {
                calced[a * j] = true;
                jlis.push_back(a * j);
            }
            ll min_minus = 0;
            for(ll SS = 0; SS < (1ll << jlis.size()); SS++) {
                BS bss(SS);
                ll tmp = 0;
                V<bool> ucopy = used;
                for(ll j = 0; j < jlis.size(); j++) {
                    if(!bss.test(j)) continue;
                    ll idx = jlis[j];
                    if(ucopy[idx]) continue;
                    ucopy[idx] = true;
                    tmp += A[idx];
                }
                chmin(min_minus, tmp);
            }
            calc -= min_minus;
        }
        chmax(ans, calc);
    }
    cout << ans << endl;
    return 0;
}

