template<typename T> struct PSP {
    MaxFlow<T> mf;
    vector<T> p;
    vector<tuple<int, int, T>> xyz;
    int NV;
    PSP() {}
    PSP(int _NV) { init(_NV); }
    void init(int _NV) { NV = _NV; p.resize(N); }
    void setp(int i, T v) { p[i] = v; }
    void setxyz(int x, int y, T z) { xyz.push_back(make_tuple(x, y, z)); }
    T solve() {
        mf.init(N + 2);
        int s = N, t = N + 1;

        T res = 0;
        rep(i, 0, N) {
            if (p[i] < 0) mf.add_edge(s, i, -p[i]);
            else {
                res += p[i];
                mf.add_edge(i, t, p[i]);
            }
        }
        fore(t, xyz) {
            int x, y; T z;
            tie(x, y, z) = t;
            mf.add_edge(x, y, z);
        }

        res -= mf.maxflow(s, t);
        return res;
    }
};






