		nxt[m] = head[u], head[u] = m++;
		edge[m] = Edge(v, u, 0, 0);
		nxt[m] = head[v], head[v] = m++;
	}

	int dis[MAXN], cur[MAXN];
	queue<int> q;

	bool bfs() {
		for( int i = 0; i < n; ++i )
			dis[i] = INF;
		dis[s] = 0, q.push(s);
		while( !q.empty() ) {
			int u = q.front(); q.pop();
			for( int i = head[u]; ~i; i = nxt[i] ) {
				Edge &e = edge[i];
				if( e.c > e.f && dis[e.v] == INF ) {
					dis[e.v] = dis[u] + 1;
					q.push(e.v);
				}
			}
		}
		return dis[t] != INF;
	}
	ll dfs( int u, ll res ) {
		if( u == t || !res ) return res;
		ll flow = 0;
		for( int &i = cur[u]; ~i; i = nxt[i] ) {
			Edge &e = edge[i];
			if( e.c > e.f && dis[u] + 1 == dis[e.v] ) {
				ll f = dfs(e.v, min<ll>(e.c-e.f, res));
				flow += f, res -= f;
				e.f += int(f), edge[i^1].f -= int(f);
				if( !res ) break;
			}
		}
		return flow;
	}
	ll solve( int _s, int _t ) {
		s = _s, t = _t;
		ll flow = 0;
		while( bfs() ) {
			for( int i = 0; i < n; ++i )
				cur[i] = head[i];
			flow += dfs(s, INF);
		}
		return flow;
	}
}

