	int cap,to,rev;
}node;
vector<node> v1[105];
queue<int> q1;
const int S=102,T=103;
const int INF=1<<30;
int lev[105];

void bfs(){
	int a,b,c;
	int i,j;
	node na;
	memset(lev,-1,sizeof(lev));
	lev[S]=0;
	q1.push(S);
	while(!q1.empty()){
		a=q1.front(),q1.pop();
		for(i=0;i<v1[a].size();i++){
			na=v1[a][i];
			if(lev[na.to]==-1 && na.cap>0){
				lev[na.to]=lev[a]+1;
				q1.push(na.to);
			}
		}
	}
}

int dfs(int s,int t,int f){
	if(s==t)return f;
	for(int i=0;i<v1[s].size();i++){
		if(v1[s][i].cap>0 && lev[s]<lev[v1[s][i].to]){
			int d=dfs(v1[s][i].to,t,min(f,v1[s][i].cap));
			if(d>0){
				v1[s][i].cap-=d;
				v1[v1[s][i].to][v1[s][i].rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}

void add_edge(int a,int b,int n){
	node na;
	na.cap=n,na.to=b,na.rev=v1[b].size();
	v1[a].push_back(na);
	na.cap=0,na.to=a,na.rev=v1[a].size()-1;
	v1[b].push_back(na);
}

