int const N = 141;

int n;
int a[N];
ll ans;
int w[N];
ll sp, sn;

ll getcost(int p){
	ll res = 0;
	int x = p;
	while(p <= n){
		if(!w[p]) res += a[p];
		p += x;
	}
	return res;
}

void rem(int p){
	int x = p;
	while(p <= n){
		w[p] += 1;
		p += x;
	}
}

void upd(int p){
	int x = p;
	while(p <= n){
		w[p] -= 1;
		if(w[p] == 0){
			sp += max(0, a[p]);
			sn += min(0, a[p]);
		}
		p += x;
	}
}

void mark(int p){
	int x = p;
	while(p <= n){
		w[p] += 1;
		if(w[p] == 1){
			sp -= max(0, a[p]);
			sn -= min(0, a[p]);
		}
		p += x;
	}
}

void rec(int p){
	cerr << p << " " << ans << endl;
	if(p == n+1) return;
	if(w[p]){
		rec(p+1);
	}else{
		if(sp <= ans) return;
		mark(p);
		ans = max(ans, sp + sn);
		if(sp >= ans){
			rec(p+1);
		}
		upd(p);
		if(sp >= ans){
			rec(p+1);
		}
	}
}

void solve(){
	ans = 0;
	bool f = true;
	while(true){
		int p = -1;
		fdi(n+1, 1){
			if(w[i]) continue;
			if(getcost(i) < 0){
				p = i;
				break;
			}
		}
		if(p == -1) break;
		rem(p);
	}
	fi(1, n+1){
		if(!w[i]) ans += a[i];
	}
	fi(1, n+1){
		w[i] = 0;
	}
	fi(1, n+1){
		sp += max(0, a[i]);
		sn += min(0, a[i]);
	}
	rec(1);
}

