#define fin stdin
#define fout stdout

#define ll long long

#define INF 1000000000000000000LL

#define MAXN 102

int a[MAXN];
ll c[MAXN][MAXN], f[MAXN][MAXN];
std::vector < int > g[MAXN];
int from[MAXN], n, q[MAXN];
bool viz[MAXN];

inline void add(int x, int y, ll z) {
    c[x][y] = z;
    g[x].push_back(y);
    g[y].push_back(x);
}

bool bfs() {
    memset(viz, 0, sizeof viz);
    viz[0] = 1;
    int st = 0, dr = 1;
    q[0] = 0;
    while (st < dr && viz[n + 1] == 0) {
        int x = q[st++];
        for (auto &y : g[x]) {
            if (viz[y] == 0 && c[x][y] - f[x][y] > 0) {
                viz[y] = 1;
                from[y] = x;
                q[dr++] = y;
            }
        }
    }
    return viz[n + 1];
}

int main() {
    fscanf(fin, "%d", &n);

    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        fscanf(fin, "%d", &a[i]);
        if (a[i] < 0)
            add(0, i, -a[i]);
        else if (a[i])
            add(i, n + 1, a[i]), ans += a[i];
    }

    for (int i = 1; i <= n; i++)
        if (a[i] < 0)
            for (int j = 2 * i; j <= n; j += i)
                add(i, j, INF);

    while (bfs()) {
        for (auto &y : g[n + 1]) {
            if (viz[y] && c[y][n + 1] - f[y][n + 1] > 0) {
                from[n + 1] = y;
                int x = n + 1;
                ll best = INF;
                while (x) {
                    best = std::min(best, c[from[x]][x] - f[from[x]][x]);
                    x = from[x];
                }
                x = n + 1;
                while (x) {
                    f[from[x]][x] += best;
                    f[x][from[x]] -= best;
                    x = from[x];
                }
                ans -= best;
            }
        }
    }

    fprintf(fout, "%lld\n", ans);

    fclose(fin);
    fclose(fout);
    return 0;
}

