const int MAX=500;
const int INF=0x3f3f3f3f;
int level[MAX];  //记录节点层次 
struct dinic{
	long long c;  //容量 
	long long f;  //流量 
}edge[MAX][MAX];
vector<int> E[MAX];

void addedge(int u,int v,long long c){
	E[u].push_back(v);
	E[v].push_back(u);
	edge[u][v].c=c;
}

bool dinic_bfs(int S,int T){    //构造层次网络 
	int i;
	int u,v;  //起、终点 
	queue<int> Q;

	memset(level,0,sizeof(level));
	Q.push(S);
	level[S]=1;
	while(!Q.empty()){
		u=Q.front();
		Q.pop();
		for(i=0;i<E[u].size();i++){
			v=E[u][i];
			if(!level[v]&&edge[u][v].c>edge[u][v].f){  //有残余流量 
				level[v]=level[u]+1;
				Q.push(v);
			}
		}
	}
	return level[T]!=0;
}

long long dinic_dfs(int u,int T,long long cpa){  //沿增广路增广 
	long long tmp=cpa,t;
	int i,v;

	if(u==T)
	    return cpa;
	for(i=0;i<E[u].size()&&tmp;i++){
		v=E[u][i];
		if(level[u]+1==level[v]){
			if(edge[u][v].c>edge[u][v].f){
				t=dinic_dfs(v,T,min(tmp,(long long)(edge[u][v].c-edge[u][v].f))); 
				edge[u][v].f+=t;
				edge[v][u].f-=t;
				tmp-=t;
			}
		}
	}
	return cpa-tmp;
} 

long long dinic(int S,int T){
	long long maxflow=0,flow=0;

	while(dinic_bfs(S,T)){   //汇点不在网络中则结束 
		while(flow=dinic_dfs(S,T,INF))  //多路增广 
		    maxflow+=flow;
	}
	return maxflow;
}

int n;
long long a,tot;

int main(){
	int i,j;
	int s=0,t=200;

	scanf("%d",&n);
	for(i=1;i<=n;i++){
		scanf("%lld",&a);
		for(j=2;j*i<=n;j++)
		    addedge(i,i*j,INF);
		if(a<=0) addedge(s,i,-a);
		else addedge(i,t,a),tot+=a;
	}
	long long mf=dinic(s,t);
	printf("%lld\n",tot-mf);

	return 0;
}

