ll dfs(int v, int t, ll cmin) {
	if (v == t) return cmin;
	used[v] = 1;
	for (auto &e : E[v]) {
		if (!used[e.to] && e.f < e.c) {
			ll df = dfs(e.to, t, min(cmin, e.c - e.f));
			if (df) {
				e.f += df;
				E[e.to][e.back].f -= df;
				return df;
			}
		}
	}
	return 0;
}

ll findflow(int s, int t) {
	ll flow = 0;
	while (1) {
		fill(used, used + N, 0);
		ll df = dfs(s, t, 1e18);
		if (!df) break;
		flow += df;
	}
	return flow;
}

