namespace S1 {
   struct Edge {
      Int s, d, f, c, rev;
   };
   struct Graph {
      Int n;
      std::vector<std::vector<Edge>> es;
      Graph(Int n_) : n(n_+1), es(n) {}
      void addEdge(Int s, Int d, Int c) {
         Int i = es[s].size();
         Int k = es[d].size();
         es[s].push_back({s, d, 0, c, k});
         es[d].push_back({d, s, 0, 0, i});
      }
   };
   static Int solve(Graph& graph, Int s, Int t) {
      Int res = 0;
      for(;;) {
         std::queue<Int> q; q.push(s);
         Edge dummy = {-1,-1,-1,-1,-1};
         std::vector<Edge*> prev(graph.n, &dummy);
         while( not q.empty() ) {
            Int v = q.front(); q.pop();
            for(Edge& e : graph.es[v]) {
               if( prev[e.d]->s == -1 and e.c - e.f > 0 ) {
                  q.push(e.d);
                  prev[e.d] = &e;
               }
            }
         }
         if( prev[t]->s == -1 ) break;
         Int f = (1LL << 53);
         {
            Int v = t;
            while( v != s ) {
               f = std::min(f, prev[v]->c - prev[v]->f);
               v = prev[v]->s;
            }
         }
         {
            Int v = t;
            while( v != s ) {
               prev[v]->f += f;
               graph.es[prev[v]->d][prev[v]->rev].f -= f;
               v = prev[v]->s;
            }
         }
         res += f;
         dumpl(f);
         if( f == 0 ) break;
      }
      return res;
   }
