      S1::Graph graph(120);
      Int s = 110, t = 111;
      for(Int i = 1; i <= n; ++i) {
         if( xs[i-1] <= 0 ) graph.addEdge(s, i, -xs[i-1]);
         if( xs[i-1] > 0 ) graph.addEdge(i, t, xs[i-1]);
         for(Int k = 2*i; k <= n; k+=i) {
            graph.addEdge(i, k, (1LL << 40));
         }
      }
      Int res = 0;
      for(Int x : xs) if( x > 0 ) res += x;
      res -= S1::solve(graph, s, t);
      printf("%ld\n", res);
   }
};

