class edge {
public:
	int s, e;
	ll f;
	edge() {
		*this = edge(0, 0, 0);
	}
	edge(int s, int e, ll f) : s(s), e(e), f(f) {}
};
vector <edge> Ve;
vector <int> fconn[100050];
void epush(int s, int e, ll f) {
	fconn[s].push_back(Ve.size());
	fconn[e].push_back(Ve.size() + 1);
	Ve.emplace_back(s, e, f);
	Ve.emplace_back(e, s, 0);
}
ll dchk[100050];
ll DFS(int n, int snk, ll C, ll F) {
	if (n == snk) return F;
	dchk[n] = C;
	for (auto it : fconn[n]) {
		edge& ed = Ve[it];
		if (ed.f == 0 || dchk[ed.e] == C) continue;
		ll t;
		if (t = DFS(ed.e, snk, C, min(F, ed.f))) {
			ed.f -= t;
			Ve[it ^ 1].f += t;
			return t;
		}
	}
	return 0;
}
void init(int snk) {
	int i;
	for (i = 0; i <= snk; i++) {
		fconn[i].clear();
		dchk[i] = false;
	}
	Ve.clear();
}

int main() {
	int N, i, j;
	scanf("%d", &N);

	int src = 0, snk = 2 * N + 1;
	for (i = 1; i <= N; i++) {
		ll t;
		scanf("%lld", &t);

		ll t1 = (ll)INF * 101 - t;
		ll t2 = (ll)INF * 101;
		epush(src, i, t1);
		epush(i + N, snk, t2);
		epush(i, i + N, LL_INF);
	}
	for (i = 1; i <= N; i++) for (j = i; j <= N; j += i) epush(i, j + N, LL_INF);

	ll f = 0, t;
	while (t = DFS(src, snk, f + 1, LL_INF)) f += t;
	return !printf("%lld\n", -(f - 101ll * N * INF));
}

