using namespace std;

#define repeat(i, x) for (int64_t i = 0; (i) < (int64_t)(x); (i)++)

const int64_t inf = (1LL << 40);

struct Network {
    using Flow = int64_t;
    using Cost = int;

    struct Arc {
        int to;
        Flow cap;
        Cost cost;
        int rev;

        Arc() {}
        Arc(int to, Flow cap, Cost cost, int rev) :
            to(to), cap(cap), cost(cost), rev(rev) {}
    };

    int n;
    vector<vector<Arc>> graph;

    Network(int n = 0) : n(n), graph(n) {}

    void addArc(int from, int to, Flow cap) {
        graph[from].emplace_back(to, cap, 0, graph[to].size());
        graph[to].emplace_back(from, 0, 0, graph[from].size() - 1);
    }

    Flow findMaximumFlow(int s, int t) {
        vector<pair<int, int>> hist(n, {-1, -1});
        Flow sumFlow = 0, flow;

        while (flow = findBlockingFlow(hist, s, t), flow > 0) {
            int u = t;
            while (hist[u].first >= 0) {
                Arc& arc = graph[hist[u].first][hist[u].second];

                arc.cap -= flow;
                graph[arc.to][arc.rev].cap += flow;
                u = hist[u].first;
            }
            sumFlow += flow;
        }
        return sumFlow;
    }

    Flow findMinimumCut(int s, int t) {
        return findMaximumFlow(s, t);
    }

private:
    Flow findBlockingFlow(vector<pair<int, int>>& hist, int s, int t) {
        vector<int> dist(n, -1);
        vector<Flow> limit(n, inf);
        fill(hist.begin(), hist.end(), make_pair(-1, -1));

        queue<int> que;
        dist[s] = 0;
        que.push(s);

        bool flag = false;

        while (!que.empty() and !flag) {
            int u = que.front(); que.pop();

            for (int i = 0; i < graph[u].size(); i++) {
                const Arc& arc = graph[u][i];

                if (dist[arc.to] < 0 and arc.cap > 0) {
                    dist[arc.to] = dist[u] + 1;
                    hist[arc.to] = {u, i};
                    limit[arc.to] = min(limit[u], arc.cap);
                    que.push(arc.to);

                    if (arc.to == t) {
                        flag = true;
                        break;
                    }
                }
            }
        }
        return flag ? limit[t] : 0;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<int64_t> a(n);

    repeat (i, n) {
        cin >> a[i];
    }

    // 2n個の頂点+s+t
    Network network(n + 3);
    int s = n + 1,  // 破壊されない
        t = n + 2;  // 破壊される

    int64_t ans = 0;
    for (int u = 1; u <= n; u++) {
        if (a[u - 1] > 0) {
            ans += a[u - 1];
            network.addArc(u, t, a[u - 1]);
        } else {
            network.addArc(s, u, -a[u - 1]);
        }

        for (int v = 2 * u; v <= n; v += u) {
            network.addArc(u, v, inf);
        }
    }

    ans -= network.findMinimumCut(s, t);

    cout << ans << endl;

    return 0;
}

