void Add(int x,int y,int z){
	vi[++tot]=y;wi[tot]=z;nex[tot]=fr[x];fr[x]=tot;
	vi[++tot]=x;wi[tot]=0;nex[tot]=fr[y];fr[y]=tot;
}
