#define ll long long
#define pii pair<int, int>
#define fst first
#define snd second
using namespace std;

struct FlowGraph
{
	const ll FMX = 1e15;
	int N, M, s, t;
	vector<vector<pii>> adj;
	vector<pii> edge;
	vector<ll> cap, flow;
	vector<int> ptr, level;
	queue<int> q;

	void init(int n, int ss, int tt)
	{
		adj.clear(); edge.clear();
		cap.clear(); flow.clear();
		ptr.clear(); level.clear();
		M = 0;
		adj.assign(n, vector<pii>());
		N = n; s = ss; t = tt;
	}

	void newEdge(int u, int v, ll c)
	{
		if (c < 0) {swap(u, v); c = -c;}
		if (c == 0) {return;}
		adj[u].push_back({v, M});
		adj[v].push_back({u, M + 1});
		edge.push_back({u, v});
		edge.push_back({v, u});
		cap.push_back(c);
		cap.push_back(c);
		flow.push_back(0);
		flow.push_back(c);
		M += 2;
	}

	bool bfs()
	{
		level.assign(N, -1);
		level[s] = 0;
		q.push(s);
		while (q.size())
		{
			int u = q.front(); q.pop();
			for (auto v : adj[u])
			{
				if (cap[v.snd] == flow[v.snd]) continue;
				if (level[v.fst] == -1)
				{
					level[v.fst] = level[u] + 1;
					q.push(v.fst);
				}
			}
		}
		return (level[t] != -1);
	}

	ll dfs(int u, ll f)
	{
		if (f == 0) {return 0;}
		if (u == t) {return f;}
		for (; ptr[u] < adj[u].size(); ptr[u]++)
		{
			int v = adj[u][ptr[u]].fst;
			int id = adj[u][ptr[u]].snd;
			if (level[v] == level[u] + 1)
			{
				ll ret = dfs(v, min(f, cap[id] - flow[id]));
				if (ret == 0) continue;
				flow[id] += ret;
				flow[id ^ 1] -= ret;
				return ret;
			}
		}
		return 0;
	}

	ll findFlow()
	{
		ll ret = 0;

		while (bfs()) 
		{
			ll tp;
			ptr.assign(N, 0);

			while (tp = dfs(s, FMX)) 
			{
				ret += tp;
			}
		}
		return ret;
	}
};

int n, ar[101] = {};
FlowGraph g;
long long res = 0;

int main()
{
	cin >> n;
	g.init(n + 2, 0, n + 1);
	for (int i = 1; i <= n; i++) 
	{
		cin >> ar[i];
		if (ar[i] >= 0) res += ar[i];
		if (ar[i] < 0) g.newEdge(0, i, -ar[i]);
		else g.newEdge(i, n + 1, ar[i]);
	}
	for (int i = 1; i <= n; i++)
	{
		if (ar[i] < 0)
		{
			for (int j = 2 * i; j <= n; j += i) if (ar[j] >= 0) g.newEdge(i, j, g.FMX);
		}
	}
	cout << res - g.findFlow() << "\n";
	return 0;
}

