vb cracked;
vl sum;

struct UnionFind {
  vector<int> data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    sum[x] += sum[y];
    return true;
  }

  int find(int k) {
    if (data[k] < 0) return k;
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return -data[find(k)];
  }
};

bool smash(int n, vi &arr) {
  bool b = true;

  while (b) {
    b = false;

    rrep1eq(i,n) {
      if (cracked[i]) continue;

      ll tmp = 0;

      for (int j=i; j<=n; j+=i) {
        if (arr[j] > 0) tmp += arr[j];
      }
      if (tmp > -arr[i]) continue;

      for (int j=i; j<=n; j+=i) {
        arr[j] = 0;
        cracked[j] = true;
      }
      b = true;
    }
  }

  UnionFind tree(n+1);

  rrep1eq(i,n) {
    if (cracked[i]) continue;

    sum[i] = arr[i];

    for (int j=i*2; j<=n; j+=i) {
      if (arr[j] != 0) tree.unite(j,i);
    }

    int idx = tree.find(i);
    if (sum[idx] <= 0) {
      for (int j=i; j<=n; j+=i) {
        arr[j] = 0;
        cracked[j] = true;
      }
      return true;
    }
  }

  return false;
}

void solve() {
  int n; cin >> n;
  vi arr(n+1);
  rep1eq(i,n) cin >> arr[i];

  cracked.assign(n+1, false);
  sum.assign(n+1, 0);

  while (smash(n, arr));

  cout << accumulate(ALL(arr), 0LL) << endl;
}


