#define MAX_V 1000

long long int INF = 10000000000000000LL;

using namespace std;

struct edge{
	long long int to, cap, rev; // 行き先、容量、逆辺
};

vector<edge> G[MAX_V] = {};
bool used[MAX_V];

// from から to へ向かう容量 cap の辺を張る
void add_edge(long long int from, long long int to, long long int cap){
	G[from].push_back((edge){to, cap, G[to].size()});
	G[to].push_back((edge){from, 0, G[from].size() - 1}); // 有向辺
	// G[to].push_back((edge){from, cap, G[from].size() - 1}); // 無向辺
}

// 増加パスを dfs で探す
long long int dfs(int v, int t, long long int f){
	if(v == t){
		return f;
	}
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		edge &e = G[v][i];
		if(!used[e.to] && e.cap > 0){
			long long int d = dfs(e.to, t, min(f, e.cap));
			if(d > 0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

// s から t への最大流を求める
long long int max_flow(int s, int t){
	long long int flow = 0;
	while(true){
		fill(used, used + MAX_V, 0);
		long long int f = dfs(s, t, INF);
		if(f == 0){
			return flow;
		}
		flow += f;
	}
}

int main(){

	int N;
	cin >> N;

	long long int sum = 0;

	for(int i = 1; i <= N; i++){
		long long int a;
		cin >> a;
		if(a > 0){
			add_edge(i, N + 1, a);
			sum += a;
		}else{
			add_edge(0, i, -a);
		}
	}

	for(int i = 1; i <= N; i++){
		for(int j = 2; j <= N; j++){
			if(i * j > N){
				break;
			}
			add_edge(i, i * j, INF);
		}
	}

	cout << sum - max_flow(0, N + 1) << endl;

	return 0;
}

