        if (a < 0) {
            flow.add_edge(S, i + 1, -a);
        } else {
            flow.add_edge(i + 1, T, a);
            ans += 1LL * a;
        }
    }
    for (int i = 1; i <= N; i++) {
        for (int j = i * 2; j <= N; j += i) {
            flow.add_edge(i, j, INF);
        }
    }
    ans -= flow.max_flow(S, T);
    cout << ans << endl;


    return 0;
}

