void add_edge(int f, int t, ll c){
	G[f].push_back(edge{t, c, (int)G[t].size()});
	G[t].push_back(edge{f, 0, (int)G[f].size()-1});
}
bool bfs(int s, int t){
	fill(lev, lev+n+2, -1);
	lev[s] = 0;
	queue<int> qu;
	qu.push(s);
	while(!qu.empty()){
		int v = qu.front(); qu.pop();
		for(edge& e: G[v]) if(e.c && lev[e.t] == -1){
			lev[e.t] = lev[v] + 1;
			qu.push(e.t);
		}
	}
	return lev[t] != -1;
}
ll dfs(int v, int t, ll f){
	if(v == t) return f;
	ll ret = 0;
	for(edge& e: G[v]){
		if(lev[v] < lev[e.t] && e.c){
			ll d = dfs(e.t, t, min(f - ret, e.c));
			if(d){
				e.c -= d; G[e.t][e.r].c += d;
				ret += d;
			}
		}
		if(f == ret) break;
	}
	return ret;
}
ll dinic(int s, int t){
	ll ret = 0;
	while(bfs(s,t)) ret += dfs(s, t, INF);
	return ret;
}

