    Dinic<ll> F(N+2);
    int s = N;
    int t = N+1;

    ll geta = 0;

    REP(i, N){
    	if(a[i]>0){
    		F.add_edge(i, t, a[i]);
    		geta += -a[i];
    	}else{
    		F.add_edge(s, i, -a[i]);
    	}
    }

    const ll INF = (1ll<<60);
    for(int x=1;x<=N;x++){
    	for(int y=2*x;y<=N;y+=x){
    		F.add_edge(x-1, y-1, INF);
    	}
    }

    ll res = F.max_flow(s, t);

    cout << -(res + geta) << endl;
    return 0;
}

#include <stdio.h>
