#include<bits/stdc++.h>
using namespace std;
using Int = long long;

struct Dinic{
  static const Int INF=1LL<<55LL;

  struct edge {
    Int to,cap,rev;
    edge(){}
    edge(Int to,Int cap,Int rev):to(to),cap(cap),rev(rev){}
  };

  Int n;
  vector<vector<edge> > G;
  vector<map<Int,int> > M;
  vector<Int> level,iter;

  Dinic(){}
  Dinic(Int sz):n(sz),G(n),M(n),level(n),iter(n){}

  void add_edge(Int from,Int to,Int cap){
    M[from][to]=G[from].size();
    M[to][from]=G[to].size();
    G[from].push_back(edge(to,cap,G[to].size()));
    // undirected
    //G[to].push_back(edge(from,cap,G[from].size()-1));
    // directed
    G[to].push_back(edge(from,0,G[from].size()-1));
  }

  void bfs(Int s){
    fill(level.begin(),level.end(),-1);
    queue<Int> que;
    level[s]=0;
    que.push(s);
    while(!que.empty()){
      Int v=que.front();que.pop();
      for(Int i=0;i<(Int)G[v].size();i++){
	edge &e = G[v][i];
	if(e.cap>0&&level[e.to]<0){
	  level[e.to]=level[v]+1;
	  que.push(e.to);
	}
      }
    }
  }

  Int dfs(Int v,Int t,Int f){
    if(v==t) return f;
    for(Int &i=iter[v];i<(Int)G[v].size();i++){
      edge &e=G[v][i];
      if(e.cap>0&&level[v]<level[e.to]){
	Int d = dfs(e.to,t,min(f,e.cap));
	if(d>0){
	  e.cap-=d;
	  G[e.to][e.rev].cap+=d;
	  return d;
	}
      }
    }
    return 0;
  }

  Int flow(Int s,Int t,Int lim){
    Int fl=0;
    for(;;){
      bfs(s);
      if(level[t]<0||lim==0) return fl;
      fill(iter.begin(),iter.end(),0);
      Int f;
      while((f=dfs(s,t,lim))>0){
	fl+=f;
	lim-=f;
      }
    }
  }

  Int flow(Int s,Int t){
    return flow(s,t,INF);
  }

  //cap==1 only
  bool back_edge(Int s,Int t,Int from, Int to){
    for(Int i=0;i<(Int)G[from].size();i++) {
      edge& e=G[from][i];
      if(e.to==to) {
	if(e.cap==0&&flow(from,to,1)==0) {
	  flow(from,s,1);
	  flow(t,to,1);
	  return 1;
	}
      }
    }
    return 0;
  }
};

signed main(){
  Int n;
  cin>>n;
  vector<Int> a(n+1);
  for(Int i=1;i<=n;i++) cin>>a[i];
  Dinic G(n+2);
  Int s=0,t=n+1;
  Int sum=0;
  for(Int i=1;i<=n;i++){
    if(a[i]>0) sum+=a[i];
    if(a[i]<0) G.add_edge(s,i,-a[i]);
    if(a[i]>0) G.add_edge(i,t,a[i]);
    for(Int j=i+i;j<=n;j+=i)
      G.add_edge(i,j,Dinic::INF);
  }
  cout<<sum-G.flow(s,t)<<endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MAXN =105;
const ll INF = 1e18;

ll n,sum, cap[MAXN][MAXN],p[MAXN];
vector<ll> adj[MAXN];
queue<pair<ll,ll>> q;

ll bfs(int s, int t){
    while(!q.empty())q.pop();

    p[0] = -2;
    q.push({0ll,INF});
    while(!q.empty()){
        ll cur = q.front().first;
        ll flow = q.front().second;
        q.pop();
        for (auto next : adj[cur]){
            if (p[next] == -1 && cap[cur][next] > 0){
                p[next] = cur;
                ll newflow = min(flow,cap[cur][next]);
                if(next == t)
                    return newflow;
                q.push({next,newflow});
            }
        }
    }
    return 0;
}

ll maxflow(int s, int t){
    ll ans = 0;

    while(1){
        memset(p,-1,sizeof(p));
        ll newflow = bfs(s,t);
		if(!newflow)break;
        ans += newflow;

		long long cur = t;
		while(cur != s){
			long long prev = p[cur];
			cap[prev][cur] -= newflow;
			cap[cur][prev] += newflow;
			cur = prev;
		}
	}
    return ans;
}

int main(){
    cin>>n;
    ll tmp;
	for(ll i =1;i<=n;i++){
        cin >> tmp;

		if(tmp>=0){
			adj[i].push_back(n+1);
			adj[n+1].push_back(i);
			cap[i][n+1]+=tmp;
			sum+=tmp;
		}
		if(tmp<0){
			adj[i].push_back(0);
			adj[0].push_back(i);
			cap[0][i]-=tmp;
		}
		for(int j = 2*i; j <= n;j += i){
			adj[i].push_back(j);
			adj[j].push_back(i);
			cap[i][j]= INF;
		}
	}

    cout << sum - maxflow(0,n+1) << "\n";
}

