constexpr int inf = 1.01e9;
constexpr i64 inf64 = 4.01e18;
constexpr double eps = 1e-9;

struct max_flow {
    struct edge {
        int to;
        i64 cap, rev;
    };
    vector<vector<edge>> graph;
    vector<bool> done;
    max_flow(int size) : graph(size), done(size) {}
    void add_edge(int from, int to, i64 cap) {
        graph[from].push_back(edge{to, cap, (int)graph[to].size()});
        graph[to].push_back(edge{from, 0, (int)graph[from].size() - 1});
    }
    i64 dfs(int v, int t, i64 f) {
        if (v == t) return f;
        done[v] = true;
        for (auto &e : graph[v]) {
            if (done[e.to] or e.cap <= 0) continue;
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }
    i64 calc_max_flow(int s, int t) {
        i64 flow = 0;
        while (true) {
            fill(done.begin(), done.end(), false);
            i64 f = dfs(s, t, inf);
            if (f == 0) return flow;
            flow += f;
        }
    }
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;

    i64 N;
    cin >> N;

    vector<i64> a(N);
    rep(i,0,N){
        cin >> a[i];
    }

    max_flow mf(N+2);
    const i64 s=N,t=N+1;

    i64 maxi=0;
    rep(i,0,N){
        if(a[i]>=0){
            mf.add_edge(s,i,a[i]);
            mf.add_edge(i,t,0);
            maxi+=a[i];
        }else{
            mf.add_edge(i,t,-a[i]);
            mf.add_edge(s,i,0);
        }
    }

    rep(i,0,N){
        rep(j,i+1,N){
            i64 i2=i+1,j2=j+1;
            if(j2%i2==0) mf.add_edge(j,i,inf64);
        }
    }

    cout << maxi-mf.calc_max_flow(s,t) << endl;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

