+ Bの倍数
+ Cの倍数
- lcm(A,B)の倍数
- lcm(A,C)の倍数
- lcm(B,C)の倍数
+ lcm(A,B,C)の倍数
*/

ll naive(VI w) {
	ll N = w.size();
	ll ans = -(1LL<<60);
	REP(bits, 1<<N) {
		VI z(w);
		REP(i, N) if(bits>>i&1) {
			for(int j=i+1;j<=N;j+=i+1) {
				z[j-1] = 0;
			}
		}
		ll lans = accumulate(ALL(z), 0LL);
		ans = max(ans, lans);
	}
	return ans;
}

class Dinic {
public:
	struct Edge {
		int to;
		ll cap;
		int rev;
	};
	int N;
	vector<vector<Edge>> g, orig;
	vector<int> level, iter;
	Dinic(int N) : N(N) {
		g = vector<vector<Edge>>(N);
		level = vector<int>(N);
		iter = vector<int>(N);
	}
	void add_edge(int from, int to, ll cap) {
		g[from].push_back(Edge{to, cap, (int)g[to].size()});
		g[to].push_back(Edge{from, 0, (int)g[from].size()-1});
	}
	void bfs(int s) {
		level.assign(N, -1);
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int v = q.front(); q.pop();
			for(int i=0;i<g[v].size(); i++) {
				Edge& e = g[v][i];
				if(e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}
	int dfs(int v, int t, ll f) {
		if(v==t) return f;
		for(int& i=iter[v]; i<g[v].size(); i++) {
			Edge& e = g[v][i];
			if(e.cap > 0 && level[v] < level[e.to]) {
				ll d = dfs(e.to, t, min(f, e.cap));
				if(d > 0) {
					e.cap -= d;
					g[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
	int max_flow(int s, int t) {
		orig = g;
		int flow = 0;
		ll INF = 1LL<<60;
		for(;;) {
			bfs(s);
			if(level[t] < 0) {
				REP(i, N) {
					REP(j, g[i].size()) {
						orig[i][j].cap = max(0LL, orig[i][j].cap - g[i][j].cap);
					}
				}
				return flow;
			}
			iter.assign(N, 0);
			int f;
			while((f=dfs(s, t, INF)) > 0) flow += f;
		}
		return -1;
	}
};
ostream& operator<<(ostream& os, const Dinic::Edge& e) {
	os<<"(Edge) to "<<e.to<<" cap "<<e.cap<<" rev "<<e.rev<<endl;
	return os;
}

ll f(VI w) {
	ll N = w.size();

	ll S=N, T=N+1;
	Dinic d(N+2);
	ll ans = 0;
	// S : とる  T : すてる
	REP(i, N) {
		if(w[i]>0) {
//			d.add_edge(S, i, 0);
			d.add_edge(i, T, w[i]);
		} else {
			d.add_edge(S, i, -w[i]);
//			d.add_edge(i, T, 0);
		}
		for(int j=(i+1)*2;j<=N;j+=i+1) {
			// i:S, j-1:SはOK
			// i:S, j-1:TはOK
			// i:T, j-1:SはNG
			// i:T, j-1:TはOK
			d.add_edge(i, j-1, 1<<30);
//			d.add_edge(j-1, i, 1<<30);
		}
		if(w[i]>0) ans += w[i];
	}
//	DD(d.g);
	ans -= d.max_flow(S, T);
	return ans;
}


