bool is_prime(int n){
	for(int i=2;i*i<=n;i++){
		if(n%i==0){
			return false;
		}
	}
	return true;
}

ll dp[1<<25],val[25];

void solve(){
	vi prime;
	for(int i=2;i<=100;i++){
		if(is_prime(i)){
			prime.pb(i);
		}
	} 
	int n;
	cin>>n;
	vi a(n);
	cin>>a;
	ll ans=0;
	for(int i=0;i<25;i++){
		for(int j=1;j<=n;j++){
			if(j%prime[i]==0){
				val[i]+=a[j-1];
			}
		}
	}
	dp[0]=accumulate(all(a),0ll);
	for(int i=1;i<(1<<(prime.size()));i++){
		ll sum=0;
		for(int j=0;j<25;j++){
			if(i&(1<<j)){
				sum=dp[i^(1<<j)]-val[j];
				break;
			}
		}
		dp[i]=sum;
		ans=max(ans,sum);
	}
	cout<<ans;
}

