const int MAX_N=120;

struct edge{
	ll to,cap,rev;
};

vector<edge> G[MAX_N];
vector<int> check(MAX_N,0);

ll dfs(int v,int t, int f){
	if(v==t){return f;}
	check[v]=1;
	for(int i=0;i<G[v].size();i++){
		edge &e = G[v][i];
		if(check[e.to]==0 && e.cap > 0){
			ll ff =dfs(e.to,t,min((ll)f,e.cap));
			if(ff>0){
				e.cap -= ff;
				G[e.to][e.rev].cap += ff;
				return ff;
			}
		}
	}
	return 0;
}

void print_graph(int V){
	REP(i, V){
		cout << "from: " << i << endl;
		REP(j, G[i].size()){
			edge e = G[i][j];
			printf("to: %d, cap: %d, rev: %d\n", e.to, e.cap, e.rev);
		}
		cout << endl;
	}
}

ll maxflow(int s,int t){
	ll flow = 0;
	while(1){
		fill(check.begin(),check.end(),0);
		int f = dfs(s,t,INT_MAX);
		if(f==0){return flow;}
		flow += f;
	}
}

