    REP(i, N) cin >> a[i];

    int s=0, t=N+1;
    REP(i, N){
    	if(a[i]>=0){
    		edge e = {t, a[i], (int)G[t].size()};
    		G[i+1].push_back(e);
    		edge f = {i+1, 0, (int)G[i+1].size()-1};
    		G[t].push_back(f);
    	}else{
    		edge e = {i+1, -a[i], (int)G[i+1].size()};
    		G[s].push_back(e);
    		edge f = {s, 0, (int)G[s].size()-1};
