		for(int i=1; i<=n; ++i) if(!chk[i]) c+=a[i];
		ans = max(ans, c);
		return;
	}
	if(x == 34){
		ll c = 0;
		for(int i=1; i<=n; ++i) if(!chk[i]) c+=a[i];
		for(int i=34; i*2<=n; ++i){
			if(chk[i]) continue;
			if(chk[i*2]){
				c = max(c, c - a[i]);
			} else {
				c = max(c, c - a[i*2]);
				c = max(c, c - a[i] - a[i*2]);
			}
		}
		for(int i=69; i<=n; i+=2){
			if(!chk[i]) c=max(c, c-a[i]);
		}
		ans = max(ans, c);
		return;
	}
	dfs(x+1);
	if(!chk[x]){
		for(int i=x; i<=n; i+=x) chk[i]++;
		dfs(x+1);
		for(int i=x; i<=n; i+=x) chk[i]--;
	}
}

