struct Edge {
  int u, v;
  LL cap, flow;
  Edge() {}
  Edge(int u_, int v_, LL cap_): u(u_), v(v_), cap(cap_), flow(0) {}
};

struct Dinic {
  int N;
  vector<Edge> E;
  vector<vector<int>> g;
  vector<int> d, pt;

  Dinic(int N_): N(N_), E(0), g(N_), d(N_), pt(N_) {}

  // u, v are 0-based
  void AddEdge(int u, int v, LL cap) {
    if (u != v) {
      E.emplace_back(u, v, cap);
      g[u].emplace_back(E.size() - 1);
      E.emplace_back(v, u, 0);
      g[v].emplace_back(E.size() - 1);
    }
  }

  bool BFS(int S, int T) {
    queue<int> q({S});
    fill(d.begin(), d.end(), N + 1);
    d[S] = 0;
    while(!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int k: g[u]) {
        Edge &e = E[k];
        if (e.flow < e.cap && d[e.v] > d[e.u] + 1) {
          d[e.v] = d[e.u] + 1;
          q.emplace(e.v);
        }
      }
    }
    return d[T] != N + 1;
  }

  LL DFS(int u, int T, LL flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = pt[u]; i < (int)g[u].size(); ++i) {
      Edge &e = E[g[u][i]];
      Edge &oe = E[g[u][i]^1];
      if (d[e.v] == d[e.u] + 1) {
        LL amt = e.cap - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        if (LL pushed = DFS(e.v, T, amt)) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  // S, T are 0-based
  LL MaxFlow(int S, int T) {
    LL total = 0;
    while (BFS(S, T)) {
      fill(pt.begin(), pt.end(), 0);
      while (LL flow = DFS(S, T))
        total += flow;
    }
    return total;
  }
};

int main() {
    int n; cin >> n;
    Dinic dinic(n+2);
    int DISCARD = 0;
    int KEEP = n+1;
    LL best_case = 0;
    FOR(i, 1, n+1) {
        int a; cin >> a;
        if(a > 0) {
            best_case += a;
            dinic.AddEdge(i, KEEP, a);
        } else {
            dinic.AddEdge(DISCARD, i, -a);
        }
        for(int j = i; j <= n; j += i) {
            dinic.AddEdge(i, j, LINF);
        }
    }
    cout << best_case - dinic.MaxFlow(DISCARD, KEEP) << '\n';
}

