#define ll long long
using namespace std;
const int N = 2e3 + 5;
const ll inf = 1e15;
int a[N];
ll ans;
vector<int> Eid[N];
int n, m, cnt, S, T, in[N], out[N], cur[N], d[N];
struct Edge {
	ll c;
	int v;
} E[N];
void AddEdge(int x, int y, ll c) {
	E[cnt].v = y, E[cnt].c = c;
	Eid[x].push_back(cnt++);
	E[cnt].v = x, E[cnt].c = 0;
	Eid[y].push_back(cnt++);
}
bool BFS() {
	static int Q[N];
	int x, ql, qr;
	for (int i = 0; i <= T; i++) d[i] = -1;
	Q[ql = qr = 0] = S; d[S] = 0;
	while (ql <= qr) {
		x = Q[ql++];
		for (int i = 0; i < Eid[x].size(); i++) {
			const Edge &e = E[Eid[x][i]];
			if (e.c && d[e.v] == -1) {
				Q[++qr] = e.v;
				d[e.v] = d[x] + 1;
				if (e.v == T) return 1;
			}
		}
	}
	return 0;
}
ll Aug(int x, ll a) {
	if (x == T) return a;
	ll aug = 0, delta;
	for (int &i = cur[x]; i < Eid[x].size(); i++) {
		Edge &e = E[Eid[x][i]];
		if (e.c && d[e.v] == d[x] + 1) {
			delta = Aug(e.v, min(a, (ll)e.c));
			if (delta) {
				e.c -= delta;
				E[Eid[x][i] ^ 1].c += delta;
				aug += delta;
				if (!(a -= delta)) break;
			}
		}
	}
	if (!aug) d[x] = -1;
	return aug;
}
ll MaxFlow() {
	ll flow = 0;
	while(BFS()) {
		for (int i = 0; i <= T; i++) cur[i] = 0;
		flow += Aug(S, inf);	
	}
	return flow;
}
int main() {
	cin >> n;
	S = 0; T = n + 1;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		if (a[i] > 0) {
			ans += a[i];
			AddEdge(i, T, a[i]);
		} else {
			AddEdge(S, i, -a[i]);
		}
	}
	for (int i = 1; i <= n; i++) {
		if (a[i] < 0) {
			for (int j = i + 1; j <= n; j++) {
				if (j % i == 0 && a[j] > 0) {
					AddEdge(i, j, inf);
				}
			}
		}
	}
//	cout << ans << endl;
	cout << max(0ll, ans - MaxFlow()) << endl;
}

