	Dinic dinic(n+1);

	rep(i, 2, n+1) {
		dinic.add_edge(0, i, ma);
		dinic.add_edge(i, 1, -(A[i-1]-ma));
		int x = i * 2;
		while (x <= n) {
			dinic.add_edge(x, i, inf);
			x += i;
		}
	}

	ll res = dinic.max_flow(0, 1);
	ll ans = ma * (n-1) - res + a0;

	out(res, ans, sum);

	return max({ans, sum, 0LL});
}

void Main() {
	cout << solve() << endl;
}

