using Edge = pair<ll, ll>;
struct Graph
{
	ll vertex_count;
	vector<Edge> edges;
	Graph() : vertex_count(0), edges(0) {}
};

ll edmonds_karp(const Graph& graph, const vector<ll>& capacities, ll s, ll t)
{
	using Capacity =ll;
	using Vertex = ll;
	struct _Edge
	{
		Vertex from, to;
		Capacity capacity;
		_Edge* reverse_edge;
		_Edge() : from(-1LL), to(-1LL), capacity(0LL), reverse_edge(nullptr) {}
		_Edge(ll from, ll to, ll capacity, _Edge* reverse_edge) :
			from(from), to(to), capacity(capacity), reverse_edge(reverse_edge) {}
	};
	//using _Edge = tuple<Vertex, Vertex, Capacity, _Edge*>;

	if (graph.edges.size() != capacities.size())
	{
		throw runtime_error("グラフの辺の要素数とコストの要素数は一致している必要があります。");
	}

	// 辺の隣接リストを作成
	vector<vector<_Edge>> edges(graph.vertex_count);
	for (ll i = 0; i < graph.edges.size(); ++i)
	{
		Vertex from, to;
		tie(from, to) = graph.edges[i];
		Capacity capacity = capacities[i];

		edges[from].emplace_back(from, to, capacity, nullptr);
		edges[to].emplace_back(to, from, 0, nullptr);
		edges[from].back().reverse_edge = &edges[to].back();
		edges[to].back().reverse_edge = &edges[from].back();
	}

	ll max_flow = 0LL;
	while (true)
	{
		// BFS
		queue<Vertex> queue;
		vector<_Edge*> prev_vertices(graph.vertex_count, nullptr);

		queue.emplace(s);
		while (prev_vertices[t] == nullptr && !queue.empty())
		{
			Vertex v = queue.front();
			queue.pop();
			for (auto& edge : edges[v])
			{
				if (edge.capacity == 0 || prev_vertices[edge.to] != nullptr) continue;
				prev_vertices[edge.to] = &edge;
				queue.emplace(edge.to);
			}
		}

		// 最小パスがなければループを抜ける
		if (prev_vertices[t] == nullptr) break;

		// 最小パスを見つける
		stack<_Edge*> path;
		Capacity min_capacity = 1LL << 60;
		path.emplace(prev_vertices[t]);
		while (path.top()->from != s)
		{
			min_capacity = min(min_capacity, path.top()->capacity);
			path.emplace(prev_vertices[path.top()->from]);
		}
		min_capacity = min(min_capacity, path.top()->capacity);

		// Capacity を更新
		while (!path.empty())
		{
			auto& edge = *path.top();
			path.pop();
			edge.capacity -= min_capacity;
			edge.reverse_edge->capacity += min_capacity;
		}

		max_flow += min_capacity;
	}

	return max_flow;
}

ll edmonds_karp(const Graph& graph, const vector<ll>& capacities)
{
	return edmonds_karp(graph, capacities, 0LL, graph.vertex_count - 1LL);
}

