vector<Node> X[1009]; bool used[1009];

void add_edge(int u, int v, int w) {
	X[u].push_back(Node{ v, w, (long long)X[v].size() });
	X[v].push_back(Node{ u, 0, (long long)X[u].size() - 1 });
}

int dfs(int pos, int to, long long f) {
	if (f == 0) return 0;
	if (pos == to) return f;
	used[pos] = true;

	for (int i = 0; i < X[pos].size(); i++) {
		if (used[X[pos][i].to] == true) continue;
		int G = dfs(X[pos][i].to, to, min(f, X[pos][i].cost));

		if (G != 0) {
			X[pos][i].cost -= G;
			X[X[pos][i].to][X[pos][i].rev].cost += G;
			return G;
		}
	}
	return 0;
}

