typedef long long lint;
typedef unsigned long long ulint;

const int n = 100, cutoff = 33;
int values[n];
lint min_squash;

void solve(int i, lint squash, ulint alive0, ulint alive64) {
  if (i == cutoff + 1) {
    static int alives[n];
    int nalive = 0;
    while (alive0 != 0) {
      int alive = __builtin_ctzll(alive0);
      alives[nalive++] = alive;
      alive0 ^= 1ULL<<alive;
    }
    while (alive64 != 0) {
      int alive = __builtin_ctzll(alive64) + 64;
      alives[nalive++] = alive;
      alive64 ^= 1ULL<<(alive - 64);
    }

    int k = nalive;
    for (int j = nalive - 1; j >= 0; --j) {
      if (values[alives[j]] <= cutoff)
        break;
      while (k - 1 >= j && values[alives[k - 1]] >= 2 * values[alives[j]])
        --k;
      if (k < nalive && values[alives[k]] == 2 * values[alives[j]]) {
        if (values[alives[k]] < 0)
          squash -= values[alives[k]];

        squash +=
          min({0, values[alives[k]], values[alives[j]] + values[alives[k]]});
      } else {
        if (values[alives[j]] < 0)
          squash += values[alives[j]];
      }
    }
    min_squash = min(min_squash, squash);
  } else {
    solve(i + 1, squash, alive0, alive64);

    bool is_alive;
    if (i < 64) is_alive = (alive0 & (1ULL<<i)) != 0;
    else is_alive = (alive64 & (1ULL<<(i - 64))) != 0;

    if (is_alive) {
      lint new_squash = squash;
      ulint new_alive0 = alive0, new_alive64 = alive64;
      int m;
      for (m = i; m < 64; m += i) {
        if (alive0 & (1ULL<<m)) {
          new_squash += values[m];
          new_alive0 ^= 1ULL<<m;
        }
      }
      for (; m <= n; m += i) {
        if (alive64 & (1ULL<<(m - 64))) {
          new_squash += values[m];
          new_alive64 ^= 1ULL<<(m - 64);
        }
      }
      solve(i + 1, new_squash, new_alive0, new_alive64);
    }
  }
}

int main() {
