const int N = 105;

struct edge {
	int to;
	LL cap;
	int rev;
	edge(int _to, LL _cap, int _rev) : to(_to), cap(_cap), rev(_rev) {};
};

int par[N], pare[N];
LL possibleflow[N];
using node = vector<edge>;
using graph = vector<node>;

LL aug(graph &g, int s, int t, int f) {
	memset(par, -1, sizeof(par));
	par[s] = s;
	possibleflow[s] = 1e18;
	deque<int> q;
	q.push_back(s);
	while (!q.empty()) {
		auto i = q.front();
		q.pop_front();
		for (auto &e : g[i]) {
			if (e.cap > 0 && par[e.to] == -1) {
				par[e.to] = i;
				pare[e.to] = e.rev;
				possibleflow[e.to] = min(possibleflow[i], e.cap);
				if (e.to == t) {
					auto df = possibleflow[t];
					while (par[t] != t) {
						g[t][pare[t]].cap += df;
						g[par[t]][g[t][pare[t]].rev].cap -= df;
						t = par[t];
					}
					return df;
				}
				q.push_back(e.to);
			}
		}
	}
	return 0;
}

int maximum_flow(graph &g, int s, int t) {
	LL df;
	LL flow = 0;
	do {
		df = aug(g, s, t, 1e18);
		flow += df;
	} while (df != 0);
	return flow;
}

void addedge(graph &g, int from, int to, LL cap) {
	g[from].PB(edge(to, cap, g[to].size()));
	g[to].PB(edge(from, 0, g[from].size() - 1));
}

int main() {
	int n;
	scanf("%d", &n);
	LL sp = 0;
	graph g(n + 2);
	FOR(i, 1, n+1) {
		int a;
		scanf("%d", &a);
		if (a < 0)addedge(g, 0, i, -a);
		else {
			addedge(g, i, n + 1, a);
			sp += a;
		}
		for (int j = 2*i; j <= n; j += i) {
			addedge(g, i, j, 1e18);
		}
	}
	printf("%lld\n", sp - maximum_flow(g, 0, n + 1));
	return 0;
}

