ll sum, ans;
void recurse(int p)
{
	//printf("%d\n", sum);
	ans = max(ans, sum);
	if (p > n/2) return;
	if (p > n/3)
	{
		int x2 = p*2;
		if (x2 % 3 == 0 && x2/3 > n/4)
		{
			recurse(p+1);
		}
		else
		{
		//	printf("hi\n");
			int v = 0;
			if (!removed[p]) v -= val[p];
			if (!removed[x2]) v-=val[x2];
			if (v > 0) sum+=v;
		//	if (sum == 6) printf(" %d\n", v);
			recurse(p+1);
			if (v > 0) sum-=v;
		}
		return;
	}
	if (p > n/4)
	{
		//printf("%d\n", p);
		int x2 = p*2;
		int x3 = p*3;
		int op1 = 0;
		if (!removed[p]) op1-=val[p];
		if (!removed[x2]) op1-=val[x2];
		if (!removed[x3]) op1-=val[x3];
		int op2 = 0;
		int op3 = op1;
		if (x3 % 2 == 0 && x3/2 > n/3)
		{
			if (!removed[x3/2]) { op2 -= val[x3/2]; op3-= val[x3/2]; }
			if (!removed[x3]) op2 -= val[x3];
		}
		removed[p]++;
		sum+=max(max(op1, op3), max(op2, 0));
		recurse(p+1);
		sum-=max(max(op1, op3), max(op2, 0));
		removed[p]--;
		return;
	}
	recurse(p+1);
	if (removed[p]) return;
	for (int i = p; i <= n; i+=p)
	{
		if (!removed[i])
		{
			sum-=val[i];
		}
		removed[i]++;
	}
	recurse(p+1);
	for (int i = p; i <= n; i+=p)
	{
		removed[i]--;
		if (!removed[i])
		{
			sum+=val[i];
		}
	}
}
