void bkt(int pos, long long S) {
    if (pos > n / 3) {
        vector<int> v;

        for (int i = pos; i <= n; ++i) {
            if (cnt[i] > 0)
                continue;
            if (2 * i <= n) {
                if (a[i] >= 0 || (!cnt[2 * i] && a[i] + a[2 * i] > 0))
                    S += a[i];
                else {
                    ++cnt[2 * i];
                    v.push_back(2 * i);
                }
            }
            else if (a[i] > 0)
                S += a[i];
        }
        while (!v.empty()) {
            --cnt[v.back()];
            v.pop_back();
        }

        sol = max(sol, S);
        return;
    }

    bkt(pos + 1, ((cnt[pos] == 0) ? (S + a[pos]) : S));
    if (cnt[pos] == 0) {
        for (int i = pos + pos; i <= n; i += pos)
            ++cnt[i];
        bkt(pos + 1, S);
        for (int i = pos + pos; i <= n; i += pos)
            --cnt[i];
    }
}

