	rep(i,n){
		if(v[i]>0)ans+=v[i];
		if(v[i]>0){
			mf.add_edge(n,i,0);
			mf.add_edge(i,n+1,v[i]);
		}
		if(v[i]<=0){
			mf.add_edge(n,i,-v[i]);
			mf.add_edge(i,n+1,0);
		}
	}
	rep(i,n){
		for(lint j=2;j*(i+1)-1<n;j++){
			mf.add_edge(i,j*(i+1)-1,INF);
		}
	}
	cout<<ans-mf.run(n,n+1);
}

