	for(int i = 1; i <= N; ++i) {
		for(int j = i * 2; j <= N; j += i) 
		add_(j, i, inf);
	}
	ll ans = 0;
	for(int i = 1; i <= N; ++i) {
		if(val[i] > 0) ans += val[i], add_(S, i, val[i]);
		else add_(i, T, -val[i]);
	}
	//cout << ans << endl;
	while(BFS()) ans -= dfs(S, inf);
	printf("%lld\n", ans);
	return 0;
}

