        if (ai[i] > 0)
            ans += ai[i];
    }
    start_pos = (n << 1) | 1, end_pos = start_pos + 1;
    for (int i = 1; i <= n; i++)
        if (ai[i] < 0)
            addtube(start_pos, i, -ai[i]);
        else
            addtube(i, end_pos, ai[i]);
    for (int i = 1; i <= n; i++)
        for (int j = (i << 1); j <= n; j += i)
            addtube(i, j, INF);
    printf("%lld\n", ans - dinic());
    return 0;
}

