vector<int> adj[N];

void bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	queue<int> q;
	q.push(source);
	while(!q.empty()) {
		int u = q.front(); q.pop();
		if(u == sink) return;
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v] > 0) {
				par[v] = u;
				q.push(v);
			}
		}
	}
}

ll augment(int u, ll bottleneck) {
	if(u == source) return bottleneck;
	if(par[u] != -1) {
		ll flow = augment(par[u], min(bottleneck, cap[par[u]][u]));
		cap[par[u]][u] -= flow;
		cap[u][par[u]] += flow;
		return flow;
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while(1) {
		bfs(source, sink);
		newFlow = augment(sink, INF);
		if(newFlow == 0) break;
		flow += newFlow;
	}
	return flow;
}

