	for (ll i = 1; i <= n; i++) { scanf("%lld", &val[i]); sum+=val[i]; 
		if (i > n/2 && val[i] < 0) { sum-=val[i]; removed[i] = 1; }
	}
	recurse(1);
	printf("%lld\n", ans);
}

