// [N/2+1,N] smash all negatives
// [N/3+1,N/2]  x and 2*x

bool CanBlockSmashId2(int id1, int id2, int N) {
    // smash id1


    ll summ = 0;
    set<int> tmp;
    for(int j=id1;j<=N;j+=id1) {
        if (!smashed[j]) {
            summ += A[j];
            tmp.insert(j);
        }
    }

    if (summ >= 0)
        return false;


    ll summ2 = 0;
    for(int j=id2;j<=N;j+=id2) {
        if (!smashed[j] && tmp.find(j)!=tmp.end())
            summ2 += A[j];
    }

    if (summ2 > 0)
        return true;
    else
        return false;


}

bool CanSmashId(int id,int N) {

    ll summ1 = 0;
    for(int j=id;j<=N;j+=id) {
        if (!smashed[j]) {
            summ1 += A[j];
        }
    }

    if (summ1 > 0)
        return false;


    for(int id1=1;id1<=id-1;id1++) {
        if (CanBlockSmashId2(id1,id,N))
            return false;
    }
    return true;
}



ll Solve(int N) {
    for(int i=1;i<=N;i++)
        smashed[i]=false;


    for(int i=N;i>=1;i--) {
        if (CanSmashId(i,N)) {
            for(int j=i;j<=N;j+=i) {
                smashed[j]=true;
            }

        }
    }


    ll ans = 0;
    for(int i=1;i<=N;i++)
        if (!smashed[i])
            ans += A[i];

    return ans;

}

