      while(levelsz--){v=Q.front();Q.pop() ;
	for(auto &e:ad[v]) if(!Dlevel[E[e].b]&&E[e].f<E[e].c){
	    Dlevel[E[e].b]=Dlevel[v]+1;
	    Q.push(E[e].b);}}}
    return Dlevel[t]>0;}//by default edges are undirected
