	for (int i = 0; i < n; i++) 
  {
    if(a[i] < 0) X.add_flowEdge(n, i, -a[i]);
    else
    {
      X.add_flowEdge(i, n+1, a[i]);
      answer += a[i];
    }
	}

  for(int i = 1; i <= n; i++)
  {
    int x = i*2;
    while(x <= n)
    {
      X.add_flowEdge(i-1, x-1, (1LL<<60));
      x += i;
    }
  }

	cout << (answer - X.max_flow(n, n+1)) << endl;//開始頂点から終了頂点までの最大流を求める
	return 0;
}

