int solve(vector < int > v){
    int sz = v.size();
    int res = 2e13;
    for (int i = 0; i < (1 << sz); i++){
        vector < int > z;
        int r = 0;
        for (int j = 0; j < v.size(); j++) if (i & (1 << j)) z.pb(v[j]);
        for (auto j: v){
            int t = 0;
            for (auto l: z){
                if (j % l == 0){
                    t = 1;
                    break;
                }
            }
            r += t * a[j];
        }
        res = min(res, r);
    }
    res = -res;
    for (auto j: v) res += a[v[j]];
    return res;
}
