using namespace std;

static int64_t mask[101];
int64_t back(const vector<int>& A, int64_t current_mask, int position) {
    if (position  + position + 1 >= int(A.size())) {
        int64_t answer = 0;
        for (int i = position; i < int(A.size()); ++i)
            if ((current_mask & mask[i + 1]) == 0)
                answer += max(A[i], 0);
        return answer;
    }

    int64_t best_value = numeric_limits<int64_t>::min();
    int now = A[position];
    if ((current_mask & mask[position + 1]) == 0) {
        int unmarked = 0;
        for (int i = position; i < int(A.size()); i += position + 1)
            if ((current_mask & mask[i + 1]) == 0)
                ++unmarked;
        if (unmarked > 1)
            best_value = max(best_value, back(A, current_mask | (1LL << (position + 1)), position + 1));
        else
            now = max(now, 0);
    } else
        now = 0;
    return max(best_value, now + back(A, current_mask, position + 1));
}

