    for (int i = 1; i <= N; ++i)
        for (int j = 1; j <= i; ++j)
            if (i % j == 0)
                mask[i] |= (1LL << j);

    vector<int> V(N);
    for (int i = 0; i < N; ++i) {
        cin >> V[i];
    }

    cout << back(V, 0, 0) << "\n";
}

