int n;
int rec(int a,int num){
    int cnum = num;
    if (a > n){
        maxv = max(maxv,num);
        return 0;
    }
    if (vis[a]){
        rec(a + 1,num);
        return 0;
    }
    if (a > n / 2){
        if (seq[a] < 0) cnum -= seq[a];
        rec(a + 1,cnum);
        return 0;
    }
    if (a > n / 3){
        if (vis[a * 2]){
            if (seq[a] < 0) cnum -= seq[a];
            rec(a + 1,cnum);
            return 0;
        }
        if (seq[a] + seq[2 * a] < min(0ll,seq[2 * a])){
            cnum -= seq[a] + seq[2 * a];
            vis[2 * a] = 1;
            rec(a + 1, cnum);
            vis[2 * a] = 0;
            return 0;
        }else {
            rec(a + 1,num);
            return 0;
        }
    }
    rec(a + 1,num);

    for (int j = a;j <= n;j+= a){
        if (vis[j] == 0) cnum -= seq[j];
        vis[j] += 1;
    }
    rec(a + 1,cnum);

    for (int j = a;j <= n;j+= a){
        vis[j] -= 1;
    }
}
