}
int spfa(){
	for (int i=1;i<=T;++i) f[i]=-1;
	f[S]=1; d[1]=S; int l=1,r=2;
	while (l<r){
		for (int i=g[d[l]];i;i=nex[i])
		if (c[i]&&f[b[i]]==-1){
			f[b[i]]=f[d[l]]+1;
			d[r++]=b[i];
		}
		++l;
	}
	return f[T]!=-1;
}
LL flow(int x,LL F){
	if (x==T) return F;
	LL use=0,w;
	for (int i=g[x];i;i=nex[i])
	if (c[i]&&f[b[i]]==f[x]+1){
		w=flow(b[i],min(F-use,c[i]));
		c[i]-=w; c[i^1]+=w; use+=w;
		if (use==F) return F;
	}
	if (!use) f[x]=-1;
	return use;
}
