inline void Add_Edge(int From,int To,int Value){Edge[++tot]=(edge){To,head[From],Value},head[From]=tot;return;}
inline void Insert_Edge(int From,int To,int Value){Add_Edge(From,To,Value);Add_Edge(To,From,0);return;}

inline bool Bfs(int S,int T){
    register int i,x;
    for(i=1;i<=N;i++) Deep[i]=0;
    queue<int> q;
    q.push(S);
    Deep[S]=1;
    while(q.size()){
        x=q.front(),q.pop();
        for(i=head[x];i;i=Next(i)){
            if(Value(i) && !Deep[To(i)]){
                q.push(To(i));
                Deep[To(i)]=Deep[x]+1;
                if(To(i)==T) return true;
            }
        }
    }
    return false;
}

int Dfs(int now,int Now){
    if(now==T) return Now;
    int Rest=Now,Reduce;
    for(int i=head[now];i && Rest;i=Next(i)){
        if(Value(i) && Deep[To(i)]==Deep[now]+1){
            Reduce=Dfs(To(i),min(Rest,Value(i)));
            if(!Reduce) Deep[To(i)]=0;
            Value(i)-=Reduce;
            Value(i^1)+=Reduce;
            Rest-=Reduce;
        }
    }
    return Now-Rest;
}

