void Fastio()
{
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
}

struct Edge{
	int u, v;
	long long cap, flow = 0;
	Edge(int u, int v, long long cap) : u(u), v(v), cap(cap) {};
};

int n;
int s, t;
long long sum = 0;
long long a[105];
vector <Edge> E;
vector <int> Adj[105];

void AddEdge(int u, int v, long long c)
{
	Adj[u].eb(E.size());
	E.eb(u, v, c);
	Adj[v].eb(E.size());
	E.eb(v, u, 0);
}

int Level[105];

long long DFS(int node, long long flow)
{
	if(node == t or flow == 0)
	{
		return flow;
	}
	for(auto x : Adj[node])
	{
		if(Level[E[x].v] != Level[node] + 1 or E[x].cap == E[x].flow)
		{
			continue;
		}
		int temp = DFS(E[x].v, min(E[x].cap - E[x].flow, flow));
		if(temp > 0)
		{
			E[x].flow += temp;
			E[x ^ 1].flow -= temp;
			return temp;
		}
	}
	return 0;
}

signed main()
{
	Fastio();
	cin >> n;
	s = 0, t = n + 1;
	for(int i = 1; i <= n; i++)
	{
		cin >> a[i];
		if(a[i] <= 0)
		{
			AddEdge(s, i, -a[i]);
		}
		else
		{
			sum += a[i];
			AddEdge(i, t, a[i]);
		}
	}
	for(int i = 1; i <= n; i++)
	{
		for(int j = 2 * i; j <= n; j = j + i)
		{
			AddEdge(i, j, INF);
		}
	}
	while(true)
	{
		for(int i = 0; i <= n + 1; i++)
		{
			Level[i] = -1;
		}
		Level[s] = 0;
		queue <int> BFS;
		BFS.push(s);
		while(BFS.empty() == false)
		{
			int node = BFS.front();
			BFS.pop();
			for(auto x : Adj[node])
			{
				if(E[x].cap > E[x].flow and Level[E[x].v] == -1)
				{
					Level[E[x].v] = Level[node] + 1;
					BFS.push(E[x].v);
				}
			}
		}
		if(Level[t] == -1)
		{
			break;
		}
		long long f;
		while(f = DFS(0, INF))
		{
			sum -= f;
		}
	}
	cout << sum;
}

