struct UnionFind {
  vector<int> data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    sum[x] += sum[y];
    return true;
  }

  int find(int k) {
    if (data[k] < 0) return k;
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return -data[find(k)];
  }
};

bool smash(int n, vi &arr) {
  UnionFind tree(n+1);

  rrep1eq(i,n) {
    if (cracked[i]) continue;

    sum[i] = arr[i];

    for (int j=i*2; j<=n; j+=i) {
      if (arr[j] != 0) tree.unite(j,i);
    }

    int idx = tree.find(i);
    if (sum[idx] <= 0) {
      for (int j=i; j<=n; j+=i) {
        arr[j] = 0;
        cracked[j] = true;
      }
      return true;
    }
  }

  return false;
}

