lint Power(lint A,lint B,lint C){
	if(!B) return 1LL;
	lint tmp=Power(A,B>>1,C);
	return tmp*tmp%C*(B&1?A:1)%C;
}

lint N,Source,Sink,X;
lint Cost[105],Par[105];
lint Cap[105][105],Adj[105][105];
bool Vis[105];

bool BFS(){
    lint U,V;
    memset(Vis,0,sizeof(Vis));
    queue<int> Q;
    Q.push(Source);
    Vis[Source]=1;
    Par[Source]=-1;
    while(!Q.empty()){
        U=Q.front();
        Q.pop();
        for(V=0;V<=N+1;++V){
            if(Vis[V]==0&&Cap[U][V]>0){
                Q.push(V);
                Par[V]=U;
                Vis[V]=1;
            }
        }
    }
    return Vis[Sink];
}

lint Maxflow(){
    lint U,V;
    for(int i=0;i<=N+1;++i)
        for(int j=0;j<=N+1;++j)
            Cap[i][j]=Adj[i][j];
    lint Max_Flow=0;
    while(BFS()){
        lint Path_Flow=INF;
        V=Sink;
        while(V!=Source){
            U=Par[V];
            Path_Flow=min(Path_Flow,Cap[U][V]);
            V=Par[V];
        }
        V=Sink;
        while(V!=Source){
            U=Par[V];
            Cap[U][V]-=Path_Flow;
            Cap[V][U]+=Path_Flow;
            V=Par[V];
        }
        Max_Flow+=Path_Flow;
    }
    return Max_Flow;
}

