struct edge { int to; long long cap; edge *rev; };

vector<vector<edge*> > adj(102);

void add_edge(int i, int j, long long cap) {
    edge *e = new edge{j, cap, NULL};
    edge *r = new edge{i, 0, e};
    e->rev = r;
    adj[i].push_back(e);
    adj[j].push_back(r);
}

int maxflow(int n) {
    // 0 = src, n = sink
    long long ans = 0;
    vector<bool> used(n+1, false);
    function<long long(int, long long)> dfs = [&](int i, long long f) {
        if (i == n) return f;
        used[i] = true;
        for (edge *e : adj[i]) {
            if (e->cap <= 0 || used[e->to]) continue;
            long long f1 = dfs(e->to, min(f, e->cap));
            if (f1 > 0) {
                e->cap -= f1;
                e->rev->cap += f1;
                return f1;
            }
        }
        return 0LL;
    };
    while (long long f = dfs(0, 1LL<<60)) {
        ans += f;
        fill(used.begin(), used.end(), false);
    }
    return ans;
}

int main(int argc, char** argv) {
    int n; cin >> n;
    int a[n+1]; for (int i = 1; i <= n; i++) cin >> a[i];
    constexpr long long INF = 1LL << 60;
    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i] == 0) continue;
        if (a[i] < 0) add_edge(0, i, -a[i]);
        else if (a[i] > 0) ans += a[i], add_edge(i, n+1, a[i]);
        for (int m = 2 * i; m <= n; m += i) add_edge(i, m, INF);
    }
    cout << ans - maxflow(n+1) << endl;
}

