#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll N = 105, INF = 1e9;
int n, source, sink;
ll a[N], par[N];
ll cap[N][N];
vector<int> adj[N];

ll bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	queue<pair<int, ll>> q;
	q.push({source, INF});
	while(!q.empty()) {
		ll u = q.front().first, flow = q.front().second;
		if(u == sink) return flow;
		q.pop();
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v] > 0) {
				par[v] = u;
				ll newFlow = min(flow, cap[u][v]);
				q.push({v, newFlow});
			}
		}
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while(1) {
		newFlow = bfs(source, sink);
		if(newFlow == 0) break;
		flow += newFlow;
		int u = sink;
		while(u != source) {
			int v = par[u];
			cap[v][u] -= newFlow;
			cap[u][v] += newFlow;
			u = v;
		}
	}
	return flow;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n;
	source = n+1; sink = n+2;
	ll ideal = 0;
	for(int i = 1; i <= n; i++)
		cin >> a[i], ideal += (a[i]>0)?a[i]:0;
	memset(cap, 0, sizeof cap);
	for(int i = 1; i <= n; i++) {
		if(a[i] < 0) adj[source].push_back(i), cap[source][i] = -a[i];
		else adj[i].push_back(sink), cap[i][sink] = a[i];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 2*i; j <= n; j+=i)
			adj[i].push_back(j), cap[i][j] = INF;
	}
	ll mf = maxflow(source, sink);
	ll ans = ideal - mf;
	cout << ans << '\n';
	return 0;
}

