bool vis[N];
int d[N], cur[N];

int n, s, t;
ll a[N];
ll sum = 0;

void addedge(int from, int to, ll cap)
{
	edges.PB((edge){from, to, cap, 0});
	edges.PB((edge){to, from, 0, 0});
	int m = edges.size();
	G[from].PB(m - 2);
	G[to].PB(m - 1);
}

bool bfs()
{
	memset(vis, 0, sizeof(vis));
	queue<int> q;
	q.push(s);
	d[s] = 0;
	vis[s] = 1;
	while(!q.empty())
	{
		int x = q.front(); q.pop();
		for(int i = 0; i < G[x].size(); i++)
		{
			edge& e = edges[G[x][i]];
			if (!vis[e.to] && e.cap > e.flow)
			{
				vis[e.to] = 1;
				d[e.to] = d[x] + 1;
				q.push(e.to);
			}
		}
	}
	return vis[t];
}

ll dfs(int x, ll a)
{
	if (x == t || a == 0) return a;
	ll flow = 0, f;
	for(int& i = cur[x]; i < G[x].size(); i++)
	{
		edge& e = edges[G[x][i]];
		if (d[x] + 1 == d[e.to] && (f = dfs(e.to, min(a, e.cap - e.flow))) > 0)
		{
			e.flow += f;
			edges[G[x][i] ^ 1].flow -= f;
			flow += f;
			a -= f;
			if (a == 0) break;
		}
	}
	return flow;
}

ll dinic()
{
	ll flow = 0;
	while(bfs())
	{
		memset(cur, 0, sizeof(cur));
		flow += dfs(s, INF);
	}
	return flow;
}

int main()
{
	scanf("%d", &n);
	rep(i, 1, n) scanf("%lld", &a[i]), sum += a[i];
	rep(i, 1, n) a[i] = -a[i];
	ll sum2 = 0;
	for(int i = 1; i <= n; i++)
	{
		if (a[i] > 0) addedge(0, i, a[i]), sum2 += a[i];
		else addedge(i, n + 1, -a[i]);
		for(int k = 2; i * k <= n; k++)
			addedge(i, i * k, INF);
	}
	t = n + 1; s = 0;
	ll ans = sum2 - dinic();

	printf("%lld\n", sum + ans);
	return 0;
}

