const int MAXN=100;
const int batas=20;
LL n,arr[MAXN+5],sum,tambahmaks=0;
bool aktif[MAXN+5],kelipatan[MAXN+5];
void reactivate(){
	for(int i=0;i<n;i++)
		aktif[i]=true;
}
void bukanlipatan(){
	for(int i=0;i<n;i++)
		kelipatan[i]=false;
}
void matikan(int state){
	for(int i=0;i<batas;i++)
	{
		if(state&(1<<i))
		{
			for(int j=i;j<n;j+=(i+1))
			{
				if(!aktif[j])
					break;
				aktif[j]=false;
			}
		}
	}
}
void BF(){
	LL temp;
	for(int state=0;state<(1<<n);state++)
	{
		reactivate();
		matikan(state);
		temp=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif[i])
				temp+=-arr[i];
		}
		tambahmaks=max(temp,tambahmaks);
	}
}
int bestmodel(vector <int> &daftar){
	assert(daftar.size()<=5);
	int ret=0;
	int calonret;
	//sum all
	calonret=0;
	for(auto isi:daftar)
		calonret+=-isi;
	ret=max(ret,calonret);

	//sum solois
	calonret=0;
	for(int i=2;i<daftar.size();i++)
	{
		calonret=-daftar[i];
		ret=max(ret,calonret);
	}

	//sum genap
	calonret=0;
	for(int i=1;i<daftar.size();i+=2)
		calonret+=-daftar[i];
	ret=max(ret,calonret);
	return ret;
}
void solve(){
	LL temp;
	vector <int> daftar;
	for(int state=0;state<(1<<batas);state++)
	{
		reactivate();
		matikan(state);
		temp=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif[i])
				temp+=-arr[i];
		}
		bukanlipatan();
		for(int i=batas;i<n;i++)
		{
			if(kelipatan[i])
				continue;
			int now=i;
			daftar.clear();
			while(now<n)
			{
				if(aktif[now])
				{
					kelipatan[now]=true;
					daftar.pb(arr[now]);
				}
				else
					daftar.pb(0);
				now+=i+1;
			}
			temp+=bestmodel(daftar);
		}
		tambahmaks=max(temp,tambahmaks);
	}
}
int main()
{
	scan(n);
	sum=0;
	for(int i=0;i<n;i++)
	{
		scan(arr[i]);
		sum+=arr[i];
	}
	if(n<=batas)			//Brute Force
	{
		BF();
	}
	else
	{
		solve();
	}
	//cout<<"sumnya "<<sum<<" tambahnya "<<tambahmaks<<endl;
	sum+=tambahmaks;
	cout<<sum<<endl;
}

#include <stdio.h>
#include <algorithm>
#include <vector>
using namespace std;

struct MaxFlowDinic {
	typedef long long cap_t;

	struct Edge
	{
		int next;
		int inv; /* inverse edge index */
		cap_t res; /* residual */
		cap_t save; /* save whatever you want. TODO: just remove if you don't need */
	};

	int n;
	vector<vector<Edge>> graph;

	vector<int> q, l, start;

	void init(int _n) {
		n = _n;
		graph.resize(n);
		for(int i = 0; i < n; i++) graph[i].clear();
	}
	void addNodes(int count) {
		n += count;
		graph.resize(n);
	}

	void addEdgeSave(int s, int e, cap_t cap, cap_t save) {
		Edge forward = { e, (int)graph[e].size() + (s == e ? 1 : 0), cap, save};
		Edge reverse = { s, (int)graph[s].size(), 0, -1};
		graph[s].push_back(forward);
		graph[e].push_back(reverse);
	}

	void addEdge(int s, int e, cap_t cap, cap_t caprev = 0) {
		Edge forward = { e, (int)graph[e].size() + (s == e ? 1 : 0), cap, -1};
		Edge reverse = { s, (int)graph[s].size(), caprev, -1};
		graph[s].push_back(forward);
		graph[e].push_back(reverse);
	}

	bool assignLevel(int source, int sink) {
		int t = 0;
		l.assign(n, 0);
		l[source] = 1;
		q[t++] = source;
		for(int h = 0; h < t && !l[sink]; h++) {
			int cur = q[h];
			for (const auto &edge : graph[cur]) {
				int next = edge.next;
				if (l[next]) continue;
				if (edge.res > 0) {
					l[next] = l[cur] + 1;
					q[t++] = next;
				}
			}
		}
		return l[sink] != 0;
	}

	cap_t blockFlow(int cur, int sink, cap_t currentFlow) {
		if (cur == sink) return currentFlow;
		for (auto &i = start[cur]; i < (int)graph[cur].size(); i++) {
			int next = graph[cur][i].next;
			if (graph[cur][i].res == 0 || l[next] != l[cur]+1)
				continue;
			if (cap_t res = blockFlow(next, sink, min(graph[cur][i].res, currentFlow))) {
				int inv = graph[cur][i].inv;
				graph[cur][i].res -= res;
				graph[next][inv].res += res;
				return res;
			}
		}
		return 0;
	}

	cap_t solve(int source, int sink)
	{
		if (source == sink) {
			// invalid case
			return -1;
		}
		q.resize(n);
		l.resize(n);
		cap_t ans = 0;
		while (assignLevel(source, sink)) {
			start.assign(n, 0);
			while (cap_t flow = blockFlow(source, sink, numeric_limits<cap_t>::max())) {
				ans += flow;
			}
		}
		return ans;
	}
};

int N;

int main()
{
	long long sum = 0;

	scanf ("%d",&N);
	MaxFlowDinic g; g.init(N+2);
	for (int i=1;i<=N;i++){
		int x; scanf ("%d",&x);
		if (x > 0) g.addEdge(i,N+1,x), sum += x;
		if (x < 0) g.addEdge(0,i,-x);
	}

	for (int i=1;i<=N;i++) for (int j=i*2;j<=N;j+=i) g.addEdge(i,j,1e11);

	printf ("%lld\n",sum-g.solve(0,N+1));

	return 0;
}

