ll n,a[111],u[111];
ll ans=-MAXL;

void dfs(ll k) {
  if(k>=min(n,34LL)) {
    ll sum=0;
    vector<int> v;
    for(int i=1; i<=n; i++) {
      if(u[i]) continue;
      if(i<34) sum+=a[i];
      else if(i*2<=n) {
        if(!u[i*2]&&a[i]+a[i*2]<0) {
          u[i*2]++;
          v.pb(i*2);
        } else if(a[i]>0) sum+=a[i];
      } else {
        if(a[i]>0) sum+=a[i];
      }
    }
    ans=max(ans,sum);
    rep(i,v.size()) u[v[i]]--;
    return;
  }
  dfs(k+1);
  if(u[k]) return;
  for(int i=k; i<=n; i+=k) u[i]++;
  dfs(k+1);
  for(int i=k; i<=n; i+=k) u[i]--;
}

