const int MAX_N = 100;

int N;
ll a[MAX_N + 1];

// Dinic O(EV^2)
// maximum flow problem
// 1. init G[V] by add_edge
// 2. max_flow(s, t) return the max flow

const int MAX_V = MAX_N + 2;

struct edge{int to, cap, rev;};

vector<edge> G[MAX_V];
int level[MAX_V];
int iter[MAX_V];

void add_edge(int from, int to, int cap){
  G[from].push_back((edge){to, cap, int(G[to].size())});
  G[to].push_back((edge){from, 0, int(G[from].size() -1)});
}

void bfs(int s){
  memset(level, -1, sizeof(level));
  queue<int> que;
  level[s] = 0;
  que.push(s);
  while(!que.empty()){
    int v = que.front(); que.pop();
    REP(i,G[v].size()){
      edge &e = G[v][i];
      if (e.cap > 0 && level[e.to] < 0){
        level[e.to] = level[v] + 1;
        que.push(e.to);
      }
    }
  }
}

int dfs(int v, int t, int f){
  if(v == t) return f;
  for (int &i = iter[v]; i < G[v].size(); i++){
    edge &e = G[v][i];
    if(e.cap > 0 && level[v] < level[e.to]){
      int d = dfs(e.to, t, min(f, e.cap));
      if (d > 0){
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}

int max_flow(int s, int t){
  int flow = 0;
  for(;;){
    bfs(s);
    if(level[t] < 0) return flow;
    int f;
    while((f = dfs(s, t, INFi)) > 0){
      flow += f;
    }

  }
}

int main(){
  cin >> N;

  for (int i = 1; i <= N; i++) {
    cin >> a[i];
  }

  ll ans = 0;

  int s = 0, t = N + 1;
  for(int i = 1; i <= N; i++) {
    if(a[i] < 0) {
      add_edge(s, i, -a[i]);
    } else {
      ans += a[i];
      add_edge(i, t, a[i]);
    }
    for(int j = 2; i * j <= N; j++) {
      add_edge(i, i * j, INFi);
    }
  }

  ans -= max_flow(s, t);

  cout << ans << endl;


  return 0;
}

