int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  int N;
  cin >> N;

  vector<int> A(N + 1);
  for (int i = 1; i <= N; i++) {
    cin >> A[i];
  }

  long long ans = 0;
  vector<int> AA = A;

  auto Eval = [&](const vector<int> &order) {
    long long cost = 0;
    A = AA;
    for (auto i : order) {
      if (i == 0) continue;
      long long cur = 0;
      for (int j = i; j <= N; j += i) {
        cur += A[j];
      }
      if (cur < 0) {
        for (int j = i; j <= N; j += i) {
          A[j] = 0;
        }
      }
    }
    for (int i = 1; i <= N; i++) {
      cost += A[i];
    }
    return cost;
  };

  vector<int> order(N + 1);
  iota(begin(order), end(order), 0);
  ans = max(ans, Eval(order));
  reverse(begin(order), end(order));
  ans = max(ans, Eval(order));

  mt19937 rnd(chrono::high_resolution_clock::now().time_since_epoch().count());
  for (int rep = 0; rep < 10000; rep++) {
    shuffle(begin(order), end(order), rnd);
    ans = max(ans, Eval(order));
  }

  cout << ans << "\n";
  return 0;
}

