		ver[cnte]=y;
		cap[cnte]=c;
		next[cnte]=head[x];
		head[x]=cnte;
		cnte++;
		ver[cnte]=x;
		cap[cnte]=0;
		next[cnte]=head[y];
		head[y]=cnte;
	}
	int S,T,clk;
	int vis[maxn];
	int depth[maxn];
	bool bfs(){
		vis[S]=++clk;
		std::queue<int> q;
		q.push(S);
		while (!q.empty()){
			int u=q.front();q.pop();
			cur[u]=head[u];
			for (int i=head[u],v;i;i=next[i])
				if (cap[i]&&vis[v=ver[i]]!=clk){
					vis[v]=clk;
					depth[v]=depth[u]+1;
					q.push(v);
				}
		}
		return vis[T]==clk;
	}
	int dfs(int u,int a){
