const ll MAX_V = 110;

struct edge {
    ll to;
    ll cap;
    ll rev;  // path[to]中でのfromのイテレータ
    edge(ll to_, ll cap_, ll rev_) : to(to_), cap(cap_), rev(rev_){};
};

class Dinic {
public:
    array<V<edge>, MAX_V> path;
    array<ll, MAX_V> level;
    array<ll, MAX_V> iter;

    void add_edge(ll from, ll to, ll cap) {
        // fromからtoへの辺を加える
        path[from].pb(edge(to, cap, SIZE(path[to])));
        path[to].pb(edge(from, 0, SIZE(path[from]) - 1));
    }

    void bfs(ll s) {
        // 頂点sからのcap>0の辺のみを通った最短距離を求める
        // 辿り着けなければ-1

        fill(ALL(level), -1);
        queue<ll> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            ll v = que.front();
            que.pop();

            for (auto e : path[v]) {
                ll sv = e.to, c = e.cap;
                if (c > 0 && level[sv] < 0) {
                    level[sv] = level[v] + 1;
                    que.push(sv);
                }
            }
        }
    }

    ll dfs(ll v, ll g, ll f) {
        if (v == g) return f;

        // iterで事前にどこまで探索したかをセーブ
        for (ll& itr = iter[v]; itr < SIZE(path[v]); itr++) {
            edge e = path[v][itr];

            if (e.cap > 0 && level[v] < level[e.to]) {
                ll df = dfs(e.to, g, min(f, e.cap));
                if (df > 0) {
                    path[v][itr].cap -= df;
                    path[e.to][e.rev].cap += df;
                    return df;
                }
            }
        }
        return 0;
    }

    ll max_flow(ll s, ll g) {
        // sからgへの最大フロー(最小カット)を求める

        ll flow = 0;
        while (true) {
            bfs(s);
            if (level[g] < 0) {
                return flow;
            }
            fill(ALL(iter), 0);
            while (true) {
                ll f = dfs(s, g, INF);
                if (f == 0) break;
                flow += f;
            }
        }
    }
};

