long greedy(const vector<int> &v){
  int n = v.size();
  long ret = 0;
  rep(i,n){
    long tmp = 0;
    for(int j = i; j<n; j+=i+1){
      tmp += v[j];
    }
    ret = max(ret, tmp);
  }
  // dbg(v,ret);
  return ret;
}

