using namespace std;
typedef long long ll;
const ll oo = 1e15;
const int nodeCount = 1e6;
const int edgeCount = 3e6;
struct edge {
	int u, v, next;
	ll cap;
}E[edgeCount];
int n, e, parent[nodeCount], last[nodeCount];
ll cost[nodeCount];
void addEdge(int a, int b, ll cap) {
	E[e].u = a; E[e].v = b; E[e].cap = cap; E[e].next = last[a];
	last[a] = e++;
	E[e].u = b; E[e].v = a; E[e].cap = 0; E[e].next = last[b];
	last[b] = e++;
}
bool getPath(int src, int sink) {
	for (int i = 0; i < n; ++i)
		cost[i] = oo;
	cost[src] = 0;
	queue<int> q;
	q.push(src);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		for (int e = last[u]; e != -1; e = E[e].next)
			if (E[e].cap > 0 && cost[E[e].v] == oo) {
				cost[E[e].v] = cost[E[e].u] + 1;
				parent[E[e].v] = e;
				q.push(E[e].v);
			}
	}
	return cost[sink] != oo;
}
ll calc(int src, int sink) {
	ll flow = 0;
	while (getPath(src, sink)) {
		ll z = oo;
		for (int cur = sink; cur != src; cur = E[parent[cur]].u)
			z = min(z, E[parent[cur]].cap);
		for (int cur = sink; cur != src; cur = E[parent[cur]].u) {
			E[parent[cur]].cap -= z;
			E[parent[cur] ^ 1].cap += z;
		}
		flow += z;
	}
	return flow;
}
int main()
{
	memset(last, -1, sizeof(last));
	int N;
	cin >> N;
	vector<int> v(N);
	ll total = 0;
	ll total2 = 0;
	for (auto &x : v) {
		cin >> x;
		total += x;
		if (x > 0)
			total2 += x;
		//x *= -1;
	}
	n = N;
	int src = n++;
	int sink = n++;
	for (int i = 1; i <= N; ++i) {
		for (int j = 1; j < i; ++j)
			if (i%j == 0)
				addEdge(i - 1, j - 1, oo);
	}
	for (int i = 0; i < v.size(); ++i) {
		if (v[i] < 0)
			addEdge(i, sink, -v[i]);
		else {
			addEdge(src, i, v[i]);
		}
	}
	ll f = calc(src, sink);
	queue<int> q;
	q.push(src);
	vector<bool> vis(n);
	vis[src] = true;
	ll res = 0;
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (u < N)
			res += v[u];
		for(int e=last[u];e!=-1;e=E[e].next)
			if (E[e].cap > 0 && !vis[E[e].v]) {
				vis[E[e].v] = true;
				q.push(E[e].v);
			}
	}
	cout << res << endl;
	//cout << f << endl;
	return 0;
}

