bool finpath(int s,int t) {
    memset(trace,0,sizeof(trace));
    queue<int> que;
    que.push(s);
    while (!que.empty()) {
        int u = que.front(); que.pop();
      //  cout<<u<<endl;
        for (int v=0;v<=n+1;v++)
            if ((g[u][v]==1) && (trace[v]==0) && (f[u][v] < c[u][v])) {
                trace[v] = u;
              //  cout<<v<<" trace: "<<trace[v]<<" ";
                que.push(v);
                if (v==t) return true;
            }
      //  cout<<endl;
    }
    return false;
}

void incFlow(int s,int t) {
    int v = t;
    ll x = oo;
    while (v!=s) {
        int u = trace[v];
        x = min(x,c[u][v] - f[u][v]);
        v = u;
    }
    maxFlow += x;
    v = t;
    while (v!=s) {
        int u = trace[v];
        f[u][v] += x;
        f[v][u] -= x;
        v = u;
    }

}

