		edge &e = G[v][i];
		if(used[e.to] == 0 and e.cap > 0){
			int d = dfs(e.to, t, min(f, e.cap));
			if(d > 0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(int s, int t){
	int flow = 0;
	while(1){
		fill(used, used+MAX, 0);
		int f = dfs(s, t, inf);
		if(f == 0)return flow;
		flow += f;
	}
}

