using ll = long long;



// Build "penalty" graph
// We sum up all positive values, but we then have to compute the penalty of doing so
// If there was a negative value removed, the penalty is either the positive values that we wrongly took
// For example, in the case of [-10, 3, 1], -10 was deleted, but now we have to pay back penalty of 3+1
// Or, if negative value was smaller than positive, we should incur this cost
// For example, [-1, 6, 7], we need to give back our debt of -1, which will be reflected in the penalty graph.

const int maxn = 110;
const ll inf = 1e18;

struct edge {
    ll to, cost, cap, rev;
};

struct min_cost_max_flow {

    int n;
    vector<vector<edge>> g;
    min_cost_max_flow(int n) {
	this->n = n;
	g.resize(n);
    }


    void add_edge(ll from, ll to, ll ecost, ll ecap) {
	assert(from>=0 && from<n);
	assert(to>=0 && to<n);

	edge fwd = { to, ecost, ecap, int(g[to].size()) };
	edge bak = { from, -ecost, 0, int(g[from].size()) };

	g[from].push_back(fwd);
	g[to].push_back(bak);
    }



    void sp(ll source, vector<ll>& dist, vector<pair<ll,ll>>& par) {
	dist.resize(n, inf);
	par.resize(n);
	dist[source] = 0;
	vector<bool> inq(n, false);
	queue<ll> qq;
	qq.push(0);
	while (!qq.empty()) {
	    ll at = qq.front();
	    qq.pop();
	    inq[at] = false;
	    for (int i=0; i<(int)g[at].size(); i++) {
		edge &ed = g[at][i];
		ll to = ed.to;
		if (ed.cap > 0 && dist[to] > dist[at] + ed.cost) {
		    dist[to] = dist[at] + ed.cost;
		    par[to] = {at, i};
		    if (!inq[to]) {
			inq[to] = true;
			qq.push(to);
		    }
		}
	    }
	}
    }

    pair<ll, ll> compute(int source, int sink, ll k=inf) {
	ll mincost = 0;
	ll maxflow = 0;

	while (maxflow < k) {
	    vector<ll> dist;
	    vector<pair<ll,ll>> par;
	    sp(source, dist, par);


	    if (dist[sink] == inf) {
		break;
	    }

	    ll f = k - maxflow;
	    ll at = sink;
	    while (at != source) {
		ll to = par[at].first;
		ll id = par[at].second;
		f = min(f, g[to][id].cap);
		at = to;
	    }

	    at = sink;
	    while (at != source) {
		ll to = par[at].first;
		ll id = par[at].second;
		mincost += f*g[to][id].cost;
		g[to][id].cap -= f;
		ll revid = g[to][id].rev;
		g[at][revid].cap += f;
		at = to;
	    }
	    maxflow += f;
	}

	return make_pair(mincost, maxflow);
    }
};


