inline bool spfa() {
	fill(d, d + N, inf);
	memset(p, -1, sizeof(p));
	memset(used, 0, sizeof(used));
	d[S] = 0;
	q[ql = qr = 0] = S;
	used[S] = true;
	while(ql <= qr) {
		int v = q[ql++];
		used[v] = false;
		for(int ind : g[v]) {
			int to = e[ind].v, cap = e[ind].c, w = e[ind].w;
			if(cap <= 0)
				continue;
			if(d[to] > d[v] + w) {
				d[to] = d[v] + w;
				p[to] = ind;
				if(!used[to]) {
					q[++qr] = to;
					used[to] = true;
				}
			}
		}
	}
	return d[T] != inf;
}

