	for(auto& j : jwerries){
		std::cin >> j.value;
		j.is_broken = false;
	}

	int broken = 0;

	for(int p=0; p<prime_num; p++){
		int sum = 0;

		for(int i=1; i<=jwerry_num; i++){
			if(i % prime[p] == 0 && !jwerries[i-1].is_broken) sum += jwerries[i-1].value;
		}

		if(sum < 0){
			for(int i=1; i<=jwerry_num; i++){
				if(i % prime[p] == 0 && !jwerries[i-1].is_broken){
				   	jwerries[i-1].is_broken = true;
					broken++;
				}
			}
		}
	}

	if(broken == jwerry_num - 1){
		jwerries[0].is_broken = true;
	}

	int obtain = 0;
	for(int i=0; i<jwerry_num; i++){
		obtain += (jwerries[i].is_broken ? 0 : jwerries[i].value);
	}

	std::cout << obtain << std::endl;

	return 0;
}

