template<typename flow_t>
struct Dinic {
    struct edge {
        int to;
        flow_t cap;
        int rev;
        edge(){}
        edge(int to, flow_t cap, int rev) : to(to), cap(cap), rev(rev) {}
    };

    vector<vector<edge>> G;
    vector<int> level,iter;
    Dinic(){}
    Dinic(int N) : G(N),level(N),iter(N) {} 

    int add_edge(int from, int to, flow_t cap) {
        G[from].emplace_back(to, cap, G[to].size());
        G[to].emplace_back(from, 0, G[from].size()-1);
        return G[to].back().rev;
    }

    void bfs(int s) {
        fill(level.begin(),level.end(),-1);
        queue<int> que;
        level[s] = 0;
        que.emplace(s);
        while (!que.empty()) {
            int v = que.front(); que.pop();
            for(int i = 0; i < (int)G[v].size(); i++) {
                edge &e = G[v][i];
                if(e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.emplace(e.to);
                }
            }
        }
    }

    flow_t dfs(int v, int t, flow_t f) {
        if(v == t) return f;
        for (int &i=iter[v]; i < (int)G[v].size(); i++) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                flow_t d = dfs(e.to, t, min(f,e.cap));
                if (d == 0) continue;
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }

    flow_t flow(int s, int t, flow_t lim) {
        flow_t fl = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0 || lim == 0) break;
            fill(iter.begin(),iter.end(),0);

            while (true) {
                flow_t f = dfs(s,t,lim);
                if (f == 0) break;
                fl += f;
                lim -= f;
            }
        }
        return fl;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<ll> A(N+1);
    rep(i,N) cin >> A[i+1];

    Dinic<ll> D(N+2);
    //S(0)(赤)が割られていない,T(N+1)(青)が割られている
    ll ans = 0;
    for (int i = 1; i <= N; i++) {
        if (A[i] > 0) {
            ans += A[i];
            D.add_edge(i,N+1,0);
            D.add_edge(0,i,A[i]);
        } else {
            D.add_edge(0,i,0);
            D.add_edge(i,N+1,-A[i]);
        }
    }

    for (int i = 1; i <= N; i++) {
        for (int j = 2; i*j <= N; j++) {
            D.add_edge(i*j,i,1e18);
        }
    }

    ans -= D.flow(0,N+1,6e18);
    cout << ans << ln;
}

