struct FlowEdge {
    int to, rev;
    long long cap;
    FlowEdge(int to_, long long cap_, int rev_) :to(to_), rev(rev_), cap(cap_) { }
};
/*
O(fE)
最大フロー
*/
class FordFulkerson {
public:
    FordFulkerson() {}

    FordFulkerson(int n) : G(n), used(n) {}

    void add(int from, int to, long long cap) {
        G[from].emplace_back(to, cap, (int)G[to].size());
        G[to].emplace_back(from, 0, (int)G[from].size() - 1);
    }

    long long get(int s, int t) {
        long long f = 1;
        long long res = 0;
        while (f) {
            fill(begin(used), end(used), false);
            f = dfs(s, t, LLONG_MAX);
            res += f;
        }
        return res;
    }
private:

    vector<vector<FlowEdge>> G;
    vector<bool> used;

    long long dfs(int v, int t, long long f) {
        if (v == t) return f;
        used[v] = 1;
        for (auto &e : G[v]) {
            if (!used[e.to] && e.cap > 0) {
                long long d = dfs(e.to, t, min(e.cap, f));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vi a(N);

    FordFulkerson ff(N + 2);
    const int src = N, sink = N + 1;

    ll sm = 0;
    rep(i, N) {
        cin >> a[i];
        if (a[i] >= 0) {
            ff.add(src, i, a[i]);
            sm += a[i];
        } else {
            ff.add(i, sink, -a[i]);
        }
    }

    ll INF = (ll)2e11;
    for (int i = 1; i <= N; ++i) {
        for (int j = 2 * i; j <= N; j+=i) {
            ff.add(j-1, i-1, INF);
        }
    }


    ll ans = sm - ff.get(src, sink);
    cout << ans << endl;
}

