long long int C;

inline void dfs(long long int idx, long long int val) {
	if (idx == 34) {
		long long int ans = 0;
		for (int j = 1; j <= 33; j++) {
			if ((val&dv[j])==0LL) {
				ans += cost[j];
			}
		}
		for (int j = 34; j <= 50; j++) {
				if (val&dv[j])continue;
				int nex = j * 2;
				long long int U = cost[j];
				if ((val&dv[nex])==0LL) {
					U += max(0LL, cost[nex]);
				}
				if (U >= 0) {
					ans += cost[j];
				}
				else {
					val |= (1LL << (long long int)(j));
				}
				continue;
		}
		for (int j = 51; j <= 100; j++) {
			if (val&dv[j]) {
				continue;
			}
			ans += max(0LL, cost[j]);
		}
		C = max(C, ans);

		return;
	}
	bool ng = false;
	if (val&dv[idx]) {
		ng = true;
	}
	if (ng == false) {
		dfs(idx + 1, val);
	}
	dfs(idx + 1, val | (1LL << (long long int)(idx)));
}

