#include<bits/stdc++.h>
using namespace std;
const int N=1<<18,inf=0x3f3f3f3f;
int pv[N],p1[N],st[N],aa[N],d[N],shana,u2,a[N],tot;
long long pf[N];

void side(int u,int v,int f,int invf)
{
	pv[tot]=v;
	pf[tot]=f;
	p1[tot]=st[u];
	st[u]=tot++;
	swap(u,v);
	f=invf;
	pv[tot]=v;
	pf[tot]=f;
	p1[tot]=st[u];
	st[u]=tot++;
}

int sap(int u,int flow)
{
	int rest=flow;
	//printf("%d %d\n",u,flow);
	if(u==shana)return flow;
	for(int &pp=aa[u];~pp;pp=p1[pp])
	{
		int v=pv[pp];
		if(pf[pp] && d[v]==d[u]+1)
		{
			//printf("holy %d %d rest %d\n",u,v,rest);
			int e=sap(v,min(rest,(int)pf[pp]));
			rest-=e;
			pf[pp]-=e;
			pf[pp^1]+=e;
			if(!rest)return flow;
		}
	}
	return flow-rest;
}

long long dinic()
{
	int ans=0;
	for(;;)
	{
		for(int i=0;i<shana;i++)
		{
			aa[i]=st[i];
			d[i]=0;
		}
		static int q[N];
		int din=1;
		d[u2]=1;
		q[0]=u2;
		for(int k=0;k<din && q[din-1]!=shana;k++)
		{
			int u=q[k];
			//printf("%d rain %d\n",k,u);
			for(int pp=st[u];~pp;pp=p1[pp])
			{
				int v=pv[pp];
				//printf("from %d\n",v);
				if(!d[v] && pf[pp])
				{
					d[v]=d[u]+1;
					q[din++]=v;
					if(v==shana)break;
				}
			}
		}
		//printf("above %d\n",shana);
		//puts("justice");
		if(q[din-1]!=shana)return ans;
		ans+=sap(u2,inf);
	}
}

int main()
{
	int n;
	scanf("%d",&n);
	u2=n;
	shana=n+1;
	memset(st,-1,sizeof(st));
	tot=1;
	int ans=0;
	for(int i=0;i<n;i++)
	{
		scanf("%d",a+i);
		if(a[i]>0)
		{
			ans+=a[i];
			side(i,shana,a[i],0);
		}
		else side(u2,i,-a[i],0);
		for(int j=2;i*j+j<=n;j++)
		{
			side(i,i*j+j-1,inf,0);
		}
	}
	printf("%I64d\n",ans-dinic());
	return 0;
}

