using namespace std;
typedef long long ll;
const ll MAX=101;
const ll INF=0x3f3f3f3f;
ll n,pos[MAX],r[MAX],g1[MAX],fin=-INF;
void track(ll x,ll d){
    ll p1=0,p2=0;
    if(x>n){
        fin=max(fin,d);
        return;
    }
    if(r[x]>=0) p1=1,p2=0;
    else if(x<=n/3) p1=1,p2=1;
    else if(x<=n/2){
        if(pos[2*x]||r[x]+r[2*x]<0) p1=0,p2=1;
        else p1=1,p2=0;
    }
    else p1=0,p2=1;
    if(p1) track(x+1,d);
    if(p2){
        for(ll i=x;i<=n;i+=x) {
            if(pos[i]==0) d-=r[i];
            pos[i]++;
        }
        track(x+1,d);
        for(ll i=x;i<=n;i+=x) pos[i]--;
    }
}
int main(){
    ll t=0;
    scanf("%lld",&n);
    for(ll i=1;i<=n;i++) scanf("%lld",&r[i]);
    for(ll i=1;i<=n;i++) t+=r[i];
    track(1,t);
    printf("%lld\n",fin);
}

