  }

  long long ans = 0;
  vector<int> AA = A;

  auto Eval = [&](const vector<int> &order) {
    long long cost = 0;
    A = AA;
    for (auto i : order) {
      if (i == 0) continue;
      long long cur = 0;
      for (int j = i; j <= N; j += i) {
