    }
    return cost;
  };

  vector<int> order(N + 1);
  iota(begin(order), end(order), 0);
  ans = max(ans, Eval(order));
  reverse(begin(order), end(order));
  ans = max(ans, Eval(order));

  cout << ans << "\n";
  return 0;
}

