/*
全ての宝石が自分のもので，そこから割って行くことを考える
「何もしない」→「割る」の順で考えた．
容量0の辺を無闇に作ってはいけない
*/

struct Dinic{
	const long long INF=1e18+9;

	struct edge {
		long long to,cap,rev;
		edge(){}
		edge(long long to,long long cap,long long rev):to(to),cap(cap),rev(rev){}
	};

	long long n;
	vector<vector<edge> > G;
	vector<map<long long,long long> > M;
	vector<long long> level,iter;

	Dinic(){}
	Dinic(long long sz):n(sz),G(n),M(n),level(n),iter(n){}

	void add_edge(long long from,long long to,long long cap){
		M[from][to]=G[from].size();
		M[to][from]=G[to].size();
		G[from].push_back(edge(to,cap,G[to].size()));
		// undirected
		//G[to].push_back(edge(from,cap,G[from].size()-1));
		// directed
		G[to].push_back(edge(from,0,G[from].size()-1));
	}

	void bfs(long long s){
		fill(level.begin(),level.end(),-1);
		queue<long long> que;
		level[s]=0;
		que.push(s);
		while(!que.empty()){
			long long v=que.front();que.pop();
			for(long long i=0;i<(long long)G[v].size();i++){
				edge &e = G[v][i];
				if(e.cap>0&&level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}
	}

	long long dfs(long long v,long long t,long long f){
		if(v==t) return f;
		for(long long &i=iter[v];i<(long long)G[v].size();i++){
			edge &e=G[v][i];
			if(e.cap>0&&level[v]<level[e.to]){
				long long d = dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap-=d;
					G[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}

	long long flow(long long s,long long t,long long lim){
		long long fl=0;
		for(;;){
			bfs(s);
			if(level[t]<0||lim==0) return fl;
			fill(iter.begin(),iter.end(),0);
			long long f;
			while((f=dfs(s,t,lim))>0){
				fl+=f;
				lim-=f;
			}
		}
	}

	long long flow(long long s,long long t){
		return flow(s,t,INF);
	}

	//cap==1 only
	bool back_edge(long long s,long long t,long long from, long long to){
		for(long long i=0;i<(long long)G[from].size();i++) {
			edge& e=G[from][i];
			if(e.to==to) {
				if(e.cap==0&&flow(from,to,1)==0) {
					flow(from,s,1);
					flow(t,to,1);
					return 1;
				}
			}
		}
		return 0;
	}
};

int main(void){
	ll n,sum=0;
	Dinic f(110);
	cin>>n;
	reg(i,1,n){
		ll a;
		cin>>a;
		if(a>0){
			sum+=a;
			f.add_edge(0,i,a);//割る
		}else if(a<0){//容量0の辺を無闇に作ってはいけない
			f.add_edge(i,n+1,-a);//残す
		}
		reg(j,1,n){
			if(i*j>n)break;
			f.add_edge(i*j,i,inf);//自分が割られたら自分の倍数も割る
		}
	}
	cout<<sum-f.flow(0,n+1)<<endl;
	// cout<<sum<<endl;
	return 0;
}

