inline bool bfs(){
	static int q[N];
	clr(st,-1);st[S]=10;
	int h=1,t=1;q[t]=S;
	while(h<=t){
		int x=q[h++];
		for(int i=head[x];i;i=p[i].next){
			int y=p[i].to;
			if(~st[y]||!p[i].cap) continue;
			st[y]=st[x]+1;q[++t]=y;
		}
	}
	return st[T]>0;
}
inline ll dfs(int x,ll f){
	if(x==T) return f;
	ll r=0;
	for(int i=head[x];i;i=p[i].next){
		int y=p[i].to;
		if(st[y]!=st[x]+1||!p[i].cap) continue;
		ll tmp=dfs(y,min(f-r,p[i].cap));
		r+=tmp;p[i].cap-=tmp;p[i^1].cap+=tmp;
		if(r==f) return f;
	}
	if(!r) st[x]=-1;
	return r;
}
inline ll dinic(){
	ll ans=0,t;
	while(bfs())
		while(t=dfs(S,inf)) ans+=t;
	return ans;
}

