        for(int i = head[x]; i; i = e[i].next)
            if (d[e[i].to] > d[x] + 1 && e[i].v)
            {
                d[e[i].to] = d[x] + 1;
                h[++r] = e[i].to;
            }
    }
    return d[t] != t + 10;
}

ll dfs(int x, ll flow)
{
    if (x == t) return flow; ll tt = 0;
    for(int i = f[x]; i && tt < flow; i = e[i].next)
        if (e[i].v && d[e[i].to] == d[x] + 1)
        {
            ll tmp = dfs(e[i].to, min(e[i].v, flow - tt));
            e[i].v -= tmp; e[i ^ 1].v += tmp; tt += tmp;
            if (e[i].v) f[x] = i;
        }
    if (!tt) d[x] = -1;
    return tt;
}

