using namespace std;

struct edge { 
	long long to;
	long long cap;
	long long rev;
};

vector<edge> G[110];
long long level[110];
long long iter[110];
long long INF = 1000000000000000;

void add_edge(long long from, long long to, long long cap) {
	G[from].push_back({ to, cap, (long long)G[to].size() });
	G[to].push_back({ from, 0, (long long)G[from].size() - 1 });
}

void BFS(long long S) {
	memset(level, -1, sizeof(level));
	queue<long long> Q;
	level[S] = 0;
	Q.push(S);
	while (!Q.empty()) {
		long long V = Q.front(); Q.pop();
		for (edge E : G[V]) {
			if (E.cap > 0 && level[E.to] < 0) {
				level[E.to] = level[V] + 1;
				Q.push(E.to);
			}
		}
	}
}

long long DFS(long long V, long long T, long long F) {
	if (V == T) return F;
	for (long long& i = iter[V]; i < G[V].size(); i++) {
		edge& E = G[V][i];
		if (E.cap > 0 && level[V] < level[E.to]) {
			long long D = DFS(E.to, T, min(F, E.cap));
			if (D > 0) {
				E.cap -= D;
				G[E.to][E.rev].cap += D;
				return D;
			}
		}
	}
	return 0;
}

long long max_flow(long long S, long long T) {
	long long flow = 0;
	while (1) {
		BFS(S);
		if (level[T] < 0) return flow;
		memset(iter, 0, sizeof(iter));
		long long F;
		while ((F = DFS(S, T, INF)) > 0) {
			flow += F;
		}
	}
}

