bool Bfs()
{
	memset(d,0,sizeof d);
	d[S]=1;
	static queue<int> Q;
	Q.push(S);
	while(!Q.empty())
	{
		int u=Q.front();
		Q.pop();
		for(int i=fir[u];i;i=nxt[i])
		{
			Edge &e=edges[i];
			if(e.c&&!d[e.v])
			{
				d[e.v]=d[u]+1;
				Q.push(e.v);
			}
		}
	}
	return d[T];
}

int Dfs(int u,int a=INF)
{
