LL isprime(LL N) {
  for (LL p = 2; p * p <= N; ++p) if(N%p == 0) return false;
  return true;
}
int main() {
  LL N;
  scanf("%lld", &N);
  LL td = min(N , 11ll), ans = -1e18;
  for (size_t i = 0; i < N; ++i) scanf("%lld", A + i + 1);
  for (int S = 0; S < (1 << td); ++S) {
    bitset<101> b(0);
    b.flip();
    for (int j = 0; j < td; ++j) {
      if ((S>>j)&1) for (int k = j + 1; k <= N; k += j + 1) b[k] = 0;
    }
    for (int j = td + 1; j <= N; ++j) {
      LL test = 0;
      if (isprime(j)) {
        for (LL k = j; k <= N; k += j) test += A[k] * b[k];
        if (test <= 0) for (LL k = j; k <= N; k += j) b[k] = 0;
      }
    }
    LL cur = 0;
    for (int i = 0; i < N; ++i) cur += A[i + 1] * b[i + 1];
    ans = max(ans,cur);
  }
