/* 使い切り */
class FlowSolver {
	static const CapacityType InfCapacity;
	static const int CannotReach;

private:
	GraphWithReverse graph_m;

	CapacityType fordFulkersonSubRec(int from, int sink, CapacityType curr_max_flow, bool* used_p);
	CapacityType fordFulkersonSub(int source, int sink, bool* used_p);

	void calcDistance(int start, int* dist_p);
	CapacityType dinicSubRec(int from, int sink, CapacityType curr_max_flow, int* done_index_p, int* dist_p);
	CapacityType dinicSub(int source, int sink, int* done_index_p, int* dist_p);

public:
	FlowSolver(const WeightedGraph<CapacityType>& wgraph);

	/* source, sink は頂点番号 */

	/* O(E * Maxflow) */
	CapacityType fordFulkerson(int source, int sink);
	/* O(E * V ** 2) */
	CapacityType dinic(int source, int sink);
