/*---------   FlowSolver   ---------*/
/*----------------------------------*/

const CapacityType FlowSolver::InfCapacity = std::numeric_limits<CapacityType>::max();
const int FlowSolver::CannotReach = -1;

CapacityType FlowSolver::fordFulkersonSubRec(int from, int sink, CapacityType curr_max_flow, bool* used_p) {
	if (from == sink) return curr_max_flow;
	used_p[from] = true;

	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	GraphDataType* data_p = graph_m.data();
	for (auto&& edge : data_p[from]) {
		if (used_p[edge.to_m] || edge.capacity_m <= 0) continue;
		CapacityType flow = fordFulkersonSubRec(edge.to_m, sink, std::min(curr_max_flow, edge.capacity_m), used_p);
		if (flow > 0) {
			edge.capacity_m -= flow;
			data_p[edge.to_m][edge.rev_index_m].capacity_m += flow;
			return flow;
		}
	}
	return 0;
}

CapacityType FlowSolver::fordFulkersonSub(int source, int sink, bool* used_p) {
	const int size = graph_m.size();
	std::fill(used_p, used_p + size, false);
	return fordFulkersonSubRec(source, sink, InfCapacity, used_p);
}

void FlowSolver::calcDistance(int start, int* dist_p) {
	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	const int size = graph_m.size();
	std::fill(dist_p, dist_p + size, CannotReach);
	GraphDataType* data_p = graph_m.data();

	std::queue<int> dist_queue;
	dist_p[start] = 0;
	dist_queue.push(start);
	while (!dist_queue.empty()) {
		int from = dist_queue.front(); dist_queue.pop();
		for (auto&& edge : data_p[from]) {
			if (dist_p[edge.to_m] != CannotReach || edge.capacity_m <= 0) continue;
			dist_p[edge.to_m] = dist_p[from] + 1;
			dist_queue.push(edge.to_m);
		}
	}
}

CapacityType FlowSolver::dinicSubRec(int from, int sink, CapacityType curr_max_flow, int* done_index_p, int* dist_p) {
	if (from == sink) return curr_max_flow;

	typedef std::vector<GraphWithReverse::Edge> GraphDataType;
	GraphDataType* data_p = graph_m.data();
	for (int& i = done_index_p[from]; i < data_p[from].size(); ++i) {		// i は done_index_p[from] の別名
		GraphWithReverse::Edge& edge = data_p[from][i];
		if (dist_p[edge.to_m] <= dist_p[from] || edge.capacity_m <= 0) continue;
		CapacityType flow = dinicSubRec(edge.to_m, sink, std::min(curr_max_flow, edge.capacity_m), done_index_p, dist_p);
		if (flow > 0) {
			edge.capacity_m -= flow;
			data_p[edge.to_m][edge.rev_index_m].capacity_m += flow;
			return flow;
		}
	}
	return 0;
}

CapacityType FlowSolver::dinicSub(int source, int sink, int* done_index_p, int* dist_p) {
	return dinicSubRec(source, sink, InfCapacity, done_index_p, dist_p);
}

FlowSolver::FlowSolver(const WeightedGraph<CapacityType>& wgraph)
	: graph_m(wgraph.getGraph().size()) {
	const auto& graph = wgraph.getGraph();
	const auto& costs = wgraph.getWeights();

	const int size = graph.size();
	for (int from = 0; from < size; ++from) {
		for (auto id : graph.row(from)) {
			const auto& edge = graph.getEdge(id);
			int to = edge.to;
			CapacityType cost = costs[id];
			graph_m.add(from, to, cost, false);
		}
	}
}

CapacityType FlowSolver::fordFulkerson(int source, int sink) {
	const int size = graph_m.size();
	bool* used_p = new bool[size];
	std::fill(used_p, used_p + size, false);

	CapacityType sum_flow = 0;
	while (true) {
		CapacityType curr_flow = fordFulkersonSub(source, sink, used_p);
		if (curr_flow == 0) break;
		sum_flow += curr_flow;
	}

	delete[] used_p;
	return sum_flow;
}

CapacityType FlowSolver::dinic(int source, int sink) {
	const int size = graph_m.size();
	int* done_index_p = new int[size];
	int* dist_p = new int[size];

	CapacityType sum_flow = 0;
	while (true) {
		calcDistance(source, dist_p);
		if (dist_p[sink] == CannotReach) break;
		std::fill(done_index_p, done_index_p + size, 0);
		while (true) {
			CapacityType curr_flow = dinicSub(source, sink, done_index_p, dist_p);
			if (curr_flow == 0) break;
			sum_flow += curr_flow;
		}
	}

	delete[] done_index_p;
	delete[] dist_p;
	return sum_flow;
}
