inline void add(int x,int y,int z) {
	to[++e] = y,nex[e] = beg[x],beg[x] = e,w[e] = z;
	to[++e] = x,nex[e] = beg[y],beg[y] = e,w[e] = 0;
}

inline int Isap(int x,int f) {
	if(x == T || !f) return f;
	int res = f;
	for(int i = beg[x];i;i = nex[i])
		if(w[i] > 0 && dis[x] == dis[to[i]] + 1) {
			int val = Isap(to[i],min(res,w[i]));
			w[i] -= val,w[i ^ 1] += val;
			res -= val;
			if(!res) return f;
		}
	if(!(--gap[dis[x]])) dis[S] = tot;
	++gap[++dis[x]];
	return f - res;
}

