            graph.add_edge(i, goal, -a[i]);
        }
    }
    rep(i, N){
        for(int j = (i + 1) * 2; j <= N; j += i + 1){
            graph.add_edge(j - 1, i, INF);
        }
    }
    res += graph.dinic(start, goal);
    cout<<-res<<endl;
}

