bool dijkstra(ll s,ll t,Graph graph,vector<pair<ll,ll>> &prev)
{
    ll n=graph.size();
    for (ll i=0;i<n;i++) prev[i]=p(-1,-1);
    vector<ll> d(n,INF);
    d[s]=0;prev[s]=p(s,-1);
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> que;
    que.push(p(d[s],s));
    ll v;
    edge e;
    while(!que.empty())
    {
        v=que.top().second;
        que.pop();
        for (ll i=0;i<graph[v].size();i++)
        {
            e=graph[v][i];
            if (e.cap>0)
            {
                if (d[e.to]>d[v]+1)
                {
                    d[e.to]=d[v]+1;
                    prev[e.to]=p(v,i);
                    que.push(p(d[e.to],e.to));
                }
            }
        }
    }
return prev[t].first!=-1;
}

