template <typename T, T INF> class Dinic{
private:
  vector<vector<pair<int,T>>> graph;
  int size, s, t;
  vector<vector<T>> cap;
  vector<int> level;

  bool buildLevel(){
    fill(ALL(level), 0);
    level[s] = 1;
    deque<int> deq = {s};
    while(!deq.empty()){
      int cur = deq.front(); deq.pop_front();
      REP(i,size)
        if(level[i]==0 && cap[cur][i]>0){
          level[i] = level[cur] + 1;
          deq.push_back(i);
        }
    }
    return level[t] != 0;
  }
  void dfs(vector<int> &path, T &flow){
    if(path.empty()) return;
    int cur = path.back();
    if(cur == t){
      T f = INF;
      FOR(i,1,(int)path.size()) f = min(f, cap[path[i-1]][path[i]]);
      FOR(i,1,(int)path.size()){
        cap[path[i-1]][path[i]] -= f;
        cap[path[i]][path[i-1]] += f;
      }
      flow += f;
    }else{
      REP(i,size){
        if(cap[cur][i]>0 && level[i]>level[cur]){
          path.push_back(i);
          dfs(path, flow);
          path.pop_back();
        }
      }
    }
  }
  T augment(){
    T f = 0;
    vector<int> path = {s};
    dfs(path, f);
    return f;
  }
  T loop(){
    T f = 0;
    while(buildLevel()) f += augment();
    return f;
  }

public:
  Dinic(vector<vector<pair<int,T>>> &_graph): graph(_graph), size(graph.size()) {}
  Dinic(int size): graph(size), size(size){}
  Dinic(){}

  void add_edge(int from, int to, const T &cap){
    graph[from].push_back({to, cap});
  }

  T max_flow(int _s, int _t){
    cap = vector<vector<T>>(size, vector<T>(size, 0));
    level = vector<int>(size, 0);

    REP(i,size)
      for(auto &p : graph[i]){
        int j = p.first;
        T d = p.second;
        cap[i][j] += d;
      }

    s = _s;
    t = _t;

    return loop();
  }
};






template <typename T, T INF>
class ProjectSelectionProblem{
  int N;
  Dinic<T, INF> flow;

  int s, t;

  T default_gain;

public:
  ProjectSelectionProblem(int N): N(N), flow(N+2), s(N), t(N+1), default_gain(0){

  }

  void penalty_if_red(int i, T c){
    assert(c >= 0);
    flow.add_edge(i, t, c);
  }

  void gain_if_red(int i, T c){
    assert(c >= 0);
    default_gain += c;
    penalty_if_blue(i, c);
  }

  void penalty_if_blue(int i, T c){
    assert(c >= 0);
    flow.add_edge(s, i, c);
  }

  void gain_if_blue(int i, T c){
    assert(c >= 0);
    default_gain += c;
    penalty_if_red(i, c);
  }

  void penalty_if_red_blue(int i, int j, T c){
    assert(c >= 0);
    flow.add_edge(i, j, c);
  }

  void penalty_if_different(int i, int j, T c){
    assert(c >= 0);
    flow.add_edge(i, j, c);
    flow.add_edge(j, i, c);
  }

  void must_be_red(int i){
    penalty_if_blue(i, INF);
  }

  void mush_be_blue(int i){
    penalty_if_red(i, INF);
  }

  void if_red_then_must_be_red(int i, int j){
    penalty_if_red_blue(i, j, INF);
  }


  T run(){
    return default_gain - flow.max_flow(s, t);
  }
};



const LLI inf = 1LL << 50;


int main(){

  int N;
  while(cin >> N){
    vector<LLI> a(N); cin >> a;

    ProjectSelectionProblem<LLI,inf> psp(N);

    REP(i,N){
      if(a[i] >= 0){
        psp.gain_if_blue(i, a[i]);
      }else{
        psp.penalty_if_blue(i, -a[i]);
      }
    }

    FORE(i,1,N){
      FORE(j,i+1,N){
        if(j % i == 0){
          psp.if_red_then_must_be_red(i-1, j-1);
        }
      }
    }

    auto ans = psp.run();

    cout << ans << endl;
  }

  return 0;
}

