bool dijkstra(int s,int t,Graph graph,vector<pair<int,int>> &prev)
{
    int n=graph.size();
    for (int i=0;i<n;i++) prev[i]=p(-1,-1);
    vector<int> d(n,INF);
    d[s]=0;prev[s]=p(s,-1);
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> que;
    que.push(p(d[s],s));
    int v;
    edge e;
    while(!que.empty())
    {
        v=que.top().second;
        que.pop();
        for (int i=0;i<graph[v].size();i++)
        {
            e=graph[v][i];
            if (e.cap>0)
            {
                if (d[e.to]>d[v]+1)
                {
                    d[e.to]=d[v]+1;
                    prev[e.to]=p(v,i);
                    que.push(p(d[e.to],e.to));
                }
            }
        }
    }
return prev[t].first!=-1;
}

void update(int from,int to,int f, int edge_num, Graph &graph,matrix &flow,matrix cap)
{
    edge &e=graph[from][edge_num];
    edge &e_r=graph[e.to][e.rev];
    if (e.reverse)
    {
        flow[to][from]-=f;
        e_r.cap=cap[to][from]-flow[to][from];
        e.cap=flow[to][from];
    }
    else
    {
        flow[from][to]+=f;
        e.cap=cap[from][to]-flow[from][to];
        e_r.cap=flow[from][to];
    }
return;
}

