  x = (x & 0x55555555) + ((x >> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
  x = (x & 0x0F0F0F0F) + ((x >> 4) & 0x0F0F0F0F);
  x = (x & 0x00FF00FF) + ((x >> 8) & 0x00FF00FF);
  x = (x & 0x0000FFFF) + ((x >> 16) & 0x0000FFFF);
  return x;
}

void buildGraph(int n) {
  for(int i=1; i<=n; i++) {
    for(int j=i+i; j<=n; j+=i) {
      setBit(nodes[i].links, j, 1);
    }
  }
  return;
}

void topoSort(int n, int* status, ll sum) {
  globalMin = min(sum, globalMin);

  if (countOnes(status[0]) +
      countOnes(status[1]) +
      countOnes(status[2]) == n) {

    return ;
  }
  tuple<int,int,int> t = make_tuple(status[0], status[1], status[2]);
  if(dp.find(t) != dp.end()) {
    return;
  }
  dp[t] = sum;

  for(int i=1; i<=n; i++) {
    if(noDependency(status, nodes[i].links) && empty(status, i)) {
      setBit(status, i, 1);
      topoSort(n, status, sum + nodes[i].val);
      setBit(status, i, 0);
    }
  }

  return;
}


