long long int flow(int v, int g, long long int f) {
	if (v == g) {
		return f;
	}
	used[v] = true;
	for (auto i = edge[v].begin(); i != edge[v].end(); ++i) {
		if (!used[(*i).first] && (*i).second > 0) {
			long long int box = flow((*i).first, g, min(f, (*i).second));
			if (box > 0) {
				(*i).second -= box;
				for (auto j = edge[(*i).first].begin(); j != edge[(*i).first].end(); ++j) {
					if ((*j).first == v) {
						(*j).second += box;
					}
				}
				return box;
			}
		}
	}
	return 0;
}

