int N;
lint a[102];
bool deleted[102];

lint rec(int x) {
	if (x == N+1) return 0;

	lint res = rec(x+1) + (deleted[x-1] ? 0 : a[x-1]);

	Vec< int > del;
	for_(i,x,N+1) if (i % x == 0 && !deleted[i-1]) del.push_back(i-1);

	for (int i : del) deleted[i] = true;
	res = max(res, rec(x+1));
	for (int i : del) deleted[i] = false;

	return res;
}

