        for(int i = x; i <= n; i++) if(!d[i]) r += f(i, 1);
        return r;
    }
    int v = t * x;
    if(v > n) return 0LL;
    d[v] = 1;
    if(c[v]) return f(t, x + 1);
    for(int i = v; i <= n; i += v) c[i]++;
    ll r = f(t, x + 1);
    for(int i = v; i <= n; i += v) c[i]--;
    return max(r, f(t, x + 1) + a[v]);
}

int main(){
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) scanf("%d", a + i);
    printf("%lld\n", f(1, 1));
}

