#define LL long long
#define PII pair<int, int>
using namespace std;
const int MAXN = 105;
const int MAXV = 205;
const LL INF = (LL)1e18+5;

struct Dinic {
    struct Edge {
        int to, rev;
        LL cap;
    };

    int V, cur[MAXV], vis[MAXV], lv[MAXV];
    vector<Edge> G[MAXV];

    void init(int _V) {
        V = _V;
        for (int i = 0; i < V; i++) {
            G[i].clear();
        }
    }

    void add_edge(int from, int to, LL cap) {
        int id1 = G[from].size(), id2 = G[to].size();
        G[from].push_back({to, id2, cap});
        G[to].push_back({from, id1, 0});
    }

    bool bfs(int s, int t) {
        // cout << "BFS\n";
        for (int i = 0; i < V; i++) {
            cur[i] = 0;
            lv[i] = -1;
        }

        queue<int> q;
        q.push(s);
        lv[s] = 0;
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (Edge &e : G[v]) {
                if (e.cap > 0 && lv[e.to] == -1) {
                    q.push(e.to);
                    lv[e.to] = lv[v] + 1;
                }
            }
        }

        return lv[t] != -1;
    }

    LL dfs(int v, int t, LL cur_flow) {
        // cout << "DFS " << v << "\n";
        vis[v] = true;
        if (v == t) return cur_flow;
        for (int &i = cur[v]; i < G[v].size(); i++) {
            Edge &e = G[v][i];
            if (vis[e.to] || e.cap <= 0) continue;
            LL f = dfs(e.to, t, min(cur_flow, e.cap));
            if (f > 0) {
                e.cap -= f;
                G[e.to][e.rev].cap += f;
                return f;
            }
        }
        return 0;
    }

    LL max_flow(int s, int t) {
        LL ans = 0;
        while (bfs(s, t)) {
            LL add = 0;
            do {
                for (int i = 0; i < V; i++) {
                    vis[i] = false;
                }
                add = dfs(s, t, INF);
                ans += add;
            }
            while (add != 0);
        }
        return ans;
    }
} algo;

LL a[MAXN];

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    // freopen("in.txt", "r", stdin);
    // freopen("out.txt", "w", stdout);

    int N;
    cin >> N;

    int s = 0, t = N + 1;
    LL ans = 0;
    algo.init(t + 1);
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        if (a[i] < 0) {
            algo.add_edge(i, t, -a[i]);
        }
        else {
            algo.add_edge(s, i, a[i]);
            ans += a[i];
        }
        for (int j = i + i; j <= N; j += i) {
            algo.add_edge(j, i, INF);
        }
    }

    cout << ans - algo.max_flow(s, t) << "\n";
}

