struct dinic{
  struct edgef{
    int to,cap,rev;
    edgef(int to=0,int cap=0,int rev=0):to(to),cap(cap),rev(rev){}
  };
	friend ostream& operator<<(ostream& os, edgef &e){
		return os << e.to << endl;
	}
  static constexpr int INF = numeric_limits<int>::max()/2;
  vector<vector<edgef>> nw;
  vector<int> level,itr;

  dinic(int sz):nw(sz),level(sz),itr(sz){}

  inline void add_edge(int src, int dst, int cap)noexcept{
    nw[src].emplace_back(dst,cap,nw[dst].size());
    nw[dst].emplace_back(src,0,nw[src].size()-1);
  }
  bool bfs(int s, int t)noexcept{
    fill(level.begin(),level.end(),-1);
    level[s] = 0;
    queue<int> q;
    q.emplace(s);

    while(!q.empty()){
      auto cur = q.front(); q.pop();
      for(auto e:nw[cur]){
        if(level[e.to]!=-1 || e.cap==0) continue;
        q.emplace(e.to);
        level[e.to] = level[cur]+1;
      }
    }
    return level[t] != -1;
  }
  inline int rdfs(int now, int s, int f=INF)noexcept{
    if(now == s) return f;
    int res = 0;
    for(int& i=itr[now];i<(int)nw[now].size();++i){
      auto &e = nw[now][i];
      auto &r = nw[e.to][e.rev];
      if(r.cap > 0 && level[now] > level[e.to]){
        int d = rdfs(e.to,s,min(f,r.cap));
        if(d>0){
          r.cap -= d;
          e.cap += d;
          res += d;
          f -= d;
        }
      }
    }
    return res;
  }
  //  rdfs is faster than dfs.
  int solve(int s, int t)noexcept{
    int res = 0, flow=-1;
    while(bfs(s,t)){
      flow = -1;
      fill(itr.begin(),itr.end(),0);
      flow = rdfs(t,s);
      res += flow;
    }
    return res;
  }
};
signed main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  int n;
	cin >> n;
	vi a(n);
	cin >> a;
	dinic f(n+2);
	int sc = n, sink = n+1;
	ll ans = accumulate(ALL(a),0LL);
	for(auto &i:a) i = -i;
	ans += accumulate(ALL(a),0LL,[](ll acc,ll i){return acc + max(0LL,i);});
	REP(i,n){
		if(a[i]>=0) f.add_edge(sc,i,a[i]);
		if(a[i]<0) f.add_edge(i,sink,-a[i]);
	}
	// eprint(f.nw);
	REP(i,n)for(int j=2*i+1;j<n;j+=i+1){
		// if(i==j) continue;
		f.add_edge(i,j,f.INF);
	}
	ans -= f.solve(sc,sink);
	cout << ans << endl;
}

