}

#include <bits/stdc++.h>
using namespace std;
int N; 
long long A[110]; 
long long INF = 1145141919810364; 
struct edge{
	int to; 
	long long cap;
	int rev; 
}; 
vector<edge> E[110]; // 0がS, [1,N]が宝石, N+1がT
int level[110]; 
int iter[110]; 
void add_edge(int from, int to, long long cap){
	E[from].push_back((edge){to, cap, (int) E[to].size()}); 
	E[to].push_back((edge){from, 0, (int) E[from].size()-1}); 
}
void bfs(int s){
	fill(level, level + N+2, -1); 
	queue<int> que; 
	level[s] = 0; 
	que.push(s); 
	while(que.size()){
		int v = que.front(); que.pop(); 
		for(auto i : E[v]){
			edge &e = i; 
			if(e.cap > 0 && level[e.to] < 0){
				level[e.to] = level[v] + 1; 
				que.push(e.to); 
			}
		}
	}
}
long long dfs(int v, int t, long long f){
	if(v == t) return f; 
	for(int &i = iter[v]; i < (int) E[v].size(); i++){
		edge &e = E[v].at(i); 
		if(e.cap > 0 && level[v] < level[e.to]){
			long long d = dfs(e.to, t, min(f, e.cap)); 
			if(d > 0){
				e.cap -= d; 
				E[e.to].at(e.rev).cap += d; 
				return d; 
			}
		}
	}
	return 0; 
}
long long max_flow(int s, int t){
	long long flow = 0; 
	while(1){
		bfs(s); 
		if(level[t] < 0) return flow; 
		fill(iter, iter + N+2, 0); 
		long long f; 
		while((f = dfs(s, t, INF)) > 0){
			flow += f; 
		}
	}
}
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> N;
	long long mx = 0; 
	for(int i = 1; i <= N; i++){
		cin >> A[i];
		if(A[i] > 0) mx += A[i]; 
		if(A[i] >= 0){
			add_edge(0, i, A[i]); 
			add_edge(i, N+1, 0); 
		}else{
			add_edge(0, i, 0); 
			add_edge(i, N+1, -A[i]); 
		}
	}
	for(int i = 1; i <= N; i++){
		for(int j = i+1; j <= N; j++){
			if(j % i) continue; 
			add_edge(j, i, INF); 
		}
	}
	long long ans = max_flow(0, N+1); 
	cout << mx - ans << "\n"; 
}

