void add_edge(Graph &g, int a, int b, Weight w = 1, Flow c = 1) {
    g[a].emplace_back(a, b, w, c);
    g[b].emplace_back(b, a, w, c);
}
void add_arc(Graph &g, int a, int b, Weight w = 1, Flow c = 1) {
    g[a].emplace_back(a, b, w, c);
}

// ディニック法 O(V^2E+V^2) 2部グラフは高速
struct dinic {
    int n, s, t;
    vector<int> level, prog, que;
    vector<vector<Flow>> cap, flow;
    vector<vector<int>> g;
    Flow inf;
    dinic(const Graph &graph)
        : n(graph.size()),
          cap(n, vector<Flow>(n)),
          flow(n, vector<Flow>(n)),
          g(n, vector<int>()),
          inf(numeric_limits<Flow>::max() / 8) {
        for (int i = 0; i < n; i++) {
            for (auto &e : graph[i]) {
                int u = e.src, v = e.dst;
                Flow c = e.cap;
                cap[u][v] += c;
                cap[v][u] += c;
                flow[v][u] += c;
                g[u].push_back(v);
                g[v].push_back(u);
            }
        }
    }
    inline Flow residue(int u, int v) { return cap[u][v] - flow[u][v]; }
    Flow solve(int s_, int t_) {
        this->t = t_, this->s = s_;
        que.resize(n + 1);
        Flow res = 0;
        while (levelize()) {
            prog.assign(n, 0);
            res += augment(s, inf);
        }
        return res;
    }
    bool levelize() {
        int l = 0, r = 0;
        level.assign(n, -1);
        level[s] = 0;
        que[r++] = s;
        while (l != r) {
            int v = que[l++];
            if (v == t) break;
            for (const int &d : g[v])
                if (level[d] == -1 && residue(v, d) != 0) {
                    level[d] = level[v] + 1;
                    que[r++] = d;
                }
        }
        return level[t] != -1;
    }
    Flow augment(int v, Flow lim) {
        Flow res = 0;
        if (v == t) return lim;
        for (int &i = prog[v]; i < (int)g[v].size(); i++) {
            const int &d = g[v][i];
            if (residue(v, d) == 0 || level[v] >= level[d]) continue;
            const Flow aug = augment(d, min(lim, residue(v, d)));
            flow[v][d] += aug;
            flow[d][v] -= aug;
            res += aug;
            lim -= aug;
            if (lim == 0) break;
        }
        return res;
    }
};

int main(void) {
    int n;
    cin >> n;
    lint sum = 0;
    vector<int> a(n + 1);
    repeat_from_to (i, 1, n) {
        cin >> a[i];
        (a[i] > 0 ? sum += a[i] : sum += 0);
    }

    const int s = 0;
    const int t = n + 1;
    Graph g(n + 2);

    // s が残す側，t が割る側
    repeat_from_to (i, 1, n) {
        if (a[i] > 0) {
            add_arc(g, s, i, 1, a[i]);
        }
        else {
            add_arc(g, i, t, 1, -a[i]);
        }
    }

    // 倍数約数関係は両方残すか両方割るか
    const lint INF = numeric_limits<lint>::max() / 100;
    repeat_from_to (i, 1, n) {
        repeat_from_to (j, i + 1, n) {
            if (j % i == 0) {
                add_arc(g, j, i, 1, INF);
            }
        }
    }

    dinic dn(g);
    cout << sum - dn.solve(s, t) << endl;
}

