//  freopen("out.txt", "w", stdout);
  int n;
  cin >> n;
  int a[n + 1];
  ll x = 0;
  int s = 0, t = n + 1;
  Edmond mf(n + 2, true);
  ll res = 0;
  for(int i = 1;i <= n;i++){
    cin >> a[i];
    if(a[i] > 0)
      res += a[i], mf.add_edge(s, i, a[i]);
    else if(a[i] < 0)
      mf.add_edge(i, t, -a[i]);
  }
  for(int i = 1;i <= n;i++)
    for(int j = 2 * i;j <= n;j += i)
      mf.add_edge(j, i, OO);
  cout << res - mf.max_flow(s, t);
}

