void test() {
    LL all = 0;
    bitset<MAXN> take = vis;
    for (int i = 1; i <= N; i++) {
        if (take[i]) {
            all += a[i];
        }
        else if (i > 33) {
            if (i * 2 > N) {
                if (a[i] < 0) {
                    all += a[i];
                }
            }
            else {
                if (take[i * 2]) {
                    if (a[i] < 0) {
                        all += a[i];
                    }
