const int N = 340000;
int K = 25;
int a[N], b[N], used[N], c[N];
main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    //freopen("input.txt", "r", stdin);
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++){
        cin >> a[i];
        a[i] = -a[i];
    }
    ll ans = 0;
    K = (n + 3)/4;
    for (int i = 0; i < K; i++){
        for (int j = i + i + 2; j <= K; j += (i + 1))
            c[i] |= (1 << (j - 1));
    }
    for (int i = 0; i < (1 << K); i++){
        int q = 1;
        for (int j = 0; j < K; j++) if ((i & (1 << j)) && (c[j] & i) != 0){
          	q = 0;
          	break;
        }
        if (!q) continue;
        ll s = 0;
        for (int j = 1; j <= n; j++){
            b[j] = a[j];
            used[j] = 0;
        }
        for (int j = 0; j < K; j++) if (i & (1 << j))
        for (int l = j + 1; l <= n; l += (j + 1)){
            s += b[l];
            b[l] = 0;
        }
        for (int j = K + 1; j <= n; j++){
            if (used[j]) continue;
            int x, y, z, t;
            if (3 * j <= n){
                x = b[j];
                y = b[j + j];
                z = b[j + j + j];
                if (j % 2 == 0){
                    t = b[3 * j /2];
                    s += max({0, y,  z, y + z, x + y + z, x + y + z + t, z + t});
                    used[j] = used[j + j] = used[j + j + j] = used[(j + j + j) / 2] = 1;
                } else
                {
                    s += max({0, y, z, y + z, x + y + z});
                    used[j] = used[j + j] = used[j + j + j] = 1;
                }
            } else
            if (j + j <= n){
                x = b[j];
                y = b[j + j];
                s += max({0, x + y, y});
                used[j] = 1;
                used[j + j] = 1;
            } else{
                x = b[j];
                used[j] = 1;
                s += max(0, x);
            }
        }
        ans = max(ans, s);
    }
    for (int i = 1; i <= n; i++) ans -= a[i];
    cout << ans << endl;
}

