class dinic{
	public :
		void init(int _n){
			n=_n;
			G.resize(n);
			iter.resize(n);
			level.resize(n);
		}

		void add_edge(int from,int to ,ll cap){
			G[from].push_back((edge){to,cap,(int)G[to].size()});
			G[to].push_back((edge){from,0,(int)G[from].size()-1});
		}

		void add_edge_both(int from,int to ,ll cap){
			add_edge(from,to,cap);
			add_edge(to,from,cap);
		}

		int max_flow(int s,int t){
			ll flow=0;
			for(;;){
				bfs(s);
				if(level[t]<0) return flow;
				iter.assign(n,0);
				ll f;
				while((f=dfs(s,t,DINIC_INF))>0){
					flow+=f;
				}
			}
		}
	private:

		int n;
		struct edge{int to; ll cap; int rev;};
		static const ll DINIC_INF = inf;
		vector< vector<edge> > G;
		vll level;
		vi iter;

		void bfs(int s){
			level.assign(n,-1);
			queue<int> que;
			level[s]=0;
			que.push(s);
			while(!que.empty()){
				int v=que.front();que.pop();
				for(int i=0;i< (int)G[v].size(); i++){
					edge &e=G[v][i];
					if(e.cap>0 && level[e.to] <0){
						level[e.to]=level[v]+1;
						que.push(e.to);
					}
				}
			}
		}

		ll dfs(int v,int t,ll f){
			if(v==t) return f;
			for(int &i=iter[v];i<(int)G[v].size();i++){
				edge &e= G[v][i];
				if(e.cap>0 && level[v]<level[e.to]){
					ll d=dfs(e.to,t,min(f,e.cap));
					if(d>0){
						e.cap -=d;
						G[e.to][e.rev].cap+=d;
						return d;
					}
				}
			}
			return 0;
		}	
};

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    ll sum = 0;
    vll a(n); for(auto& e : a) cin >> e, sum += max(e, 0LL);

	dinic d;
	d.init(n + 2);
    int s = 0, t = n + 1;
    rep(i, n){
        ll cur = a[i];
        d.add_edge(s, i+1, max(0LL, -cur));
        d.add_edge(i+1, t, max(0LL, cur));
    }
    rep(i, 1, n+1){
        for(int j = 2 * i; j <= n; j += i){
            d.add_edge(i, j, inf);
        }
    }

	cout << sum - d.max_flow(s,t) << endl;

    return 0;
}

