using P=pair<ll,int>;
ll N,a[101],c[101],ans;
vector<P> v;
int main(){
    cin>>N;
    for(int i{1};i<=N;++i)cin>>a[i];
    for(int i{1};i<=N;++i){
        if(c[i])continue;
        ll res{};
        for(int j{1};i*j<=N;++j)
            res+=a[i*j];
        if(res<0)v.emplace_back(res,i);
    }
    sort(v.begin(),v.end());
    while(v.size()){
        int j{v[0].second};
        ll res{v[0].first};
        if(res<0){
            for(int k{1};j*k<=N;++k)
                c[j*k]=1;
            v.erase(v.begin());
            if(!v.size())continue;
            vector<P> w;
            for(int k{};k<v.size();++k){
                int l{v[k].second};
                ll val{};
                for(int m{1};l*m<=N;++m)
                    if(!c[l*m])val+=a[l*m];
                if(val<0)w.emplace_back(val,l);
            }
            sort(w.begin(),w.end());
            v=w;
        }
    }
    for(int i{1};i<=N;++i)
        if(!c[i])
            ans+=a[i];
    cout<<max(ans,0ll)<<endl;
}

