ll rec(vec a) {
    vector<ll> s(sz(a) + 1, 0);
    for (int i = 1; i <= sz(a); i++) {
        for (int j = 1; j <= i; j++) {
            if (i % j == 0) {
                s[j] += a[i - 1];
            }
        }
    }
    ll mn = LINF;
    for (int i = 1; i <= sz(a); i++) {
        mn = min(mn, s[i]);
    }
    if (mn >= 0) {
        ll ans = 0;
        for (auto it : a) ans += it;
        return ans;
    }
    for (int i = 1; i <= sz(a); i++) {
        if (mn == s[i]) {
            for (int j = i; j <= sz(a); j += i) { 
                a[j - 1] = 0;
            }
            return rec(a);
        }
    }
}

