template<class T> struct flow {
  struct edge {
    int to;
    T cap;
    int rev;
  };

  int n, s, t;
  vector<vector<edge>> g;
  vector<bool> used;

  flow(int n, int s, int t) : n(n), s(s), t(t) {
    g = vector<vector<edge>>(n);
  }

  void add(int from, int to, T cap) {
    g[from].push_back({ to, cap, (int) g[to].size() });
    g[to].push_back({ from, 0, (int) g[from].size() - 1 });
  }

  T dfs(int v, int t, T f) {
    if (v == t) {
      return f;
    }
    used[v] = true;
    for (auto &e : g[v]) {
      if (used[e.to] || e.cap <= 0) {
        continue;
      }
      T d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }

  T max_flow() {
    T flow = 0;
    while (true) {
      used = vector<bool>(n);
      T f = dfs(s, t, numeric_limits<T>::max());
      if (f == 0) {
        break;
      }
      flow += f;
    }
    return flow;
  }
};

int main() {
  ioinit();
  int n;
  cin >> n;
  vi32 a(n);
  rep(i, n) cin >> a[i];
  flow<i64> g(n + 2, 0, n + 1);
  rep(i, n) {
    if (a[i] <= 0) {
      g.add(0, i + 1, -a[i]);
    } else {
      g.add(i + 1, n + 1, a[i]);
    }
  }
  reps(i, n) {
    for (int j = i + i; j <= n; j += i) {
      g.add(i, j, numeric_limits<i64>::max());
    }
  }
  i64 ans = 0;
  rep(i, n) ans += max(0, a[i]);
  ans -= g.max_flow();
  cout << ans << '\n';
  return 0;
}

