struct Edge {
  int src, dst;
  Edge() { src = dst = -1; }
  Edge(int s, int d) : src(s), dst(d) {}
  Edge reverse(void) const { return Edge(dst, src); }
};

bool operator < (const Edge& a, const Edge& b)
{
  if (a.src != b.src) return a.src < b.src;
  return a.dst < b.dst;
}

bool operator == (const Edge& a, const Edge& b)
{
  return a.dst == b.dst && a.src == b.src;
}

ostream& operator << (ostream& os, Edge e)
{
  os << make_pair(e.src, e.dst);
  return os;
}

const int N = 100 + 10;
vector<Edge> g[N];

map<Edge, lli> cap;
map<Edge, lli> flow;

void add_edge(int src, int dst, lli c)
{
  Edge a(src, dst);
  Edge b = a.reverse();
  g[a.src].push_back(a);
  g[b.dst].push_back(b);
  cap[a] += c;
  cap[b] += 0;
  return ;
}

// EdmondsKarp
lli max_flow(int src, int snk)
{
  lli sum = 0;
  Edge path[N];
  while (true) {
    fill(path, path + N, Edge());
    set<int> vis;
    vis.insert(src);
    queue<int> q;
    for (q.push(src); q.size(); q.pop()) {
      each (e, g[q.front()]) {
        if (vis.count(e.dst)) continue;
        if (0 < cap[e]) {
          vis.insert(e.dst);
          q.push(e.dst);
          path[e.dst] = e;
        }
      }
    }
    if (path[snk] == Edge()) {
      break;
    }
    lli mn = 1LL << 60;
    for (Edge e = path[snk]; e.src != e.dst; e = path[e.src]) {
      mn = min(mn, cap[e]);
    }
    for (Edge e = path[snk]; e.src != e.dst; e = path[e.src]) {
      cap[e] -= mn;
      cap[e.reverse()] += mn;
      flow[e] += mn;
      flow[e.reverse()] -= mn;
    }
    sum += mn;
  }

  return sum;
}

lli min_cut(int src, int snk)
{
  return max_flow(src, snk);
}

