        if ((j + 1) % (i + 1) == 0) {
          add_edge(i, j, inf);
        }
      }
    }

    for (int i = 0; i < n; ++i) {
      if (0 < a[i]) {
        add_edge(i, snk, a[i]);
      } else {
        add_edge(src, i, -a[i]);
      }
    }

    lli sum = 0;
    each (i, a) {
      if (0 < i) sum += i;
    }
    cout << sum - min_cut(src, snk) << endl;
  }

  return 0;
}

