main()
{
      cin >> n;

      for(int i = 1; i <= n; i ++)
            cin >> a[i];

      for(int mask = 0; mask < (1 << n); mask ++)
      {
            int res = 0;
            for(int j = 0; j < n; j ++)
            {
                  int i = mask & (1 << j);
                  if(i)
                  {
                        for(int i = j + 1; i <= n; i += (j + 1))
                              u[i] = 1;
                  }
            }

            for(int j = 1; j <= n; j ++)
            {
                  if(!u[j]) res += a[j];
                  u[j] = 0;
            }
            ans = max(ans, res);
      }

      cout << ans << endl;
}

