ll ans=0;
void find(int v,ll sum)
{
	if(v>n/2)
	{
		for(int i=v;i<=n;i++)
			if(!b[i]&&a[i]>0) sum+=a[i];
		ans=max(ans,sum);			
		return ;
	}
	if(!b[v])
	{
		find(v+1,sum+a[v]);
		int p=top;
		for(int i=1;i*v<=n;i++)
			if(!b[i*v]) b[i*v]=1,st[++p]=i*v;
		find(v+1,sum);
		for(;p>=top;p--)
			b[st[p]]=0;	
	}
	else find(v+1,sum);
}
