LL aug(graph &g, int s, int t, LL f) {
	memset(par, -1, sizeof(par));
	par[s] = s;
	possibleflow[s] = 1e18;
	deque<int> q;
	q.push_back(s);
	while (!q.empty()) {
		auto i = q.front();
		q.pop_front();
		for (auto &e : g[i]) {
			if (e.cap > 0 && par[e.to] == -1) {
				par[e.to] = i;
				pare[e.to] = e.rev;
				possibleflow[e.to] = min(possibleflow[i], e.cap);
				if (e.to == t) {
					auto df = possibleflow[t];
					while (par[t] != t) {
						g[t][pare[t]].cap += df;
						g[par[t]][g[t][pare[t]].rev].cap -= df;
						t = par[t];
					}
					return df;
				}
				q.push_back(e.to);
			}
		}
	}
	return 0;
}

