const int inf = (int)1e9 + 7;
const int N = 107;

struct edge  {
    int a, b, c, f;
};

vector < int > gr[N];
vector < edge > e;
int lim, s, t;
ll maxflow, x;
int pt[N], d[N];

void add_edge (int a, int b, int c) {
    edge ed;
    ed.a = a; ed.b = b; ed.c = c; ed.f = 0;
    gr[a].pb(sz(e));
    e.pb(ed);

    ed.a = b; ed.b = a; ed.c = c; ed.f = c;
    gr[b].pb(sz(e));
    e.pb(ed);
}

bool bfs () {
    for (int i = s; i <= t; i++) {
        d[i] = inf;
    }
    d[s] = 0;
    queue < int > q;
    q.push(s);
    while (!q.empty() && d[t] == inf) {
        int v = q.front(); q.pop();
        for (int i = 0; i < sz(gr[v]); i++) {
            int id = gr[v][i];
            int to = e[id].b;
            if (d[to] == inf && e[id].c - e[id].f >= lim) {
                d[to] = d[v] + 1;
                q.push(to);
            }
        }
    }
    while (!q.empty()) q.pop();
    return d[t] != inf;
}

bool dfs (int v, int flow) {
    if (flow == 0) return false;
    if (v == t) return true;
    for (; pt[v] < sz(gr[v]); pt[v]++) {
        int id = gr[v][pt[v]];
        int to = e[id].b;
        if (d[v] + 1 == d[to] && e[id].c - e[id].f >= flow) {
            int pushed = dfs(to, flow);
            if (pushed) {
                e[id].f += flow;
                e[id ^ 1].f -= flow;
                return true;
            }
        }
    }
    return false;
