using namespace std;

struct Graph {
    static constexpr int INF = 1 << 30;
    struct Edge {
        int i, r, f;
    };
    Graph(int n) : v(n), h(n), q(n), e(n) {}
    void add_edge(int i, int j, int f) {
        int r0 = e[j].size();
        int r1 = e[i].size();
        e[i].push_back({ j, r0, max(+f, 0) });
        e[j].push_back({ i, r1, max(-f, 0) });
    }
    void bfs(int i0, int i1) {
        fill(v.begin(), v.end(), -1);
        v[i0] = 0;
        int j0 = 0, j1 = 0;
        q[j1++] = i0;
        while (j0 < j1) {
            int i = q[j0++];
            for (Edge& o : e[i]) {
                if (v[o.i] >= 0 || o.f == 0) continue;

                v[o.i] = v[i] + 1;
                if (o.i == i1) return;
                q[j1++] = o.i;
            }
        }
    }
    int dfs(int i, int i1, int f0) {
        for (; h[i] < e[i].size(); h[i]++) {
            Edge& o = e[i][h[i]];
            if (v[o.i] <= v[i] || o.f == 0) continue;

            int f = min(f0, o.f);
            if (o.i != i1) f = dfs(o.i, i1, f);
            if (f == 0) continue;

            o.f -= f;
            e[o.i][o.r].f += f;
            return f;
        }
        return 0;
    }
    int64_t max_flow(int i0, int i1) { // i0 != i1
        for (int64_t f = 0;;) {
            bfs(i0, i1);
            if (v[i1] < 0) return f;
            fill(h.begin(), h.end(), 0);
            while (1) {
                int t = dfs(i0, i1, INF);
                if (t == 0) break;
                f += t;
            }
        }
    }
    vector<int> v, h, q;
    vector<vector<Edge>> e;
};

int main() {
    int n;
    cin >> n;

    Graph g(n + 2);
    int S = 0, T = n + 1;
    int64_t p = 0;

    for (int i = 1; i <= n; i++) {
        int a;
        cin >> a;

        if (a < 0) {
            g.add_edge(S, i, -a);
        } else if (a > 0) {
            g.add_edge(i, T, a);
            p += a;
        }
        for (int j = i * 2; j <= n; j += i) {
            g.add_edge(i, j, Graph::INF);
        }
    }

    cout << p - g.max_flow(S, T) << endl;

    return 0;
}

