typedef pair< int, set< int > > iP;

int n, a[101];
map< iP, long long > dp;

long long rec(int idx, set< int > v) {

    if(idx > n) return 0;

    if(dp[iP(idx, v)]) return dp[iP(idx, v)];

    long long ret = -INF;
    if(v.find(idx) != v.end()) {
        ret = rec(idx + 1, v);
    } else {
        ret = max(ret, rec(idx + 1, v) + a[idx]);

        set< int > temp(v);
        for(int i = 1; i * idx <= n; i++) {
            temp.insert(i * idx);
        }
        ret = max(ret, rec(idx + 1, temp));
    }

    return dp[iP(idx, v)] = ret;
}

int main() {

    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
    }

    set< int > v;
    cout << rec(1, v) << endl;
}

