int bt6[8] = { 0, 4, 8, 9, 10, 12, 14, 15 };
int n, c, a[109]; long long ret; bool choose[29], chosen[109], slc[109];
inline int val(int pos) {
	return chosen[pos] ? 0 : a[pos];
}
void dfs(int pos, long long sum) {
	if (pos > c) {
		for (int i = 1; i <= n; i++) chosen[i] = false, slc[i] = false;
		for (int i = 1; i <= n; i++) {
			if (choose[i]) {
				for (int j = i; j <= n; j += i) chosen[j] = true;
			}
		}
		// 6m which 2m > c
		long long res = sum;
		for (int i = c + 1; i <= n; i++) {
			if (!chosen[i]) res += a[i];
		}
		for (int i = c / 2 + 1; 6 * i <= n; i++) {
			long long rm = 0;
			for (int j = 0; j < 8; j++) {
				long long cur = 0;
				if (bt6[j] & 1) cur += val(2 * i);
				if (bt6[j] & 2) cur += val(3 * i);
				if (bt6[j] & 4) cur += val(4 * i);
				if (bt6[j] & 8) cur += val(6 * i);
				rm = min(rm, cur);
			}
			res -= rm;
			slc[2 * i] = true;
			slc[3 * i] = true;
			slc[4 * i] = true;
			slc[6 * i] = true;
		}
		// 3m which m > c
		for (int i = c + 1; 3 * i <= n; i++) {
			if (!slc[i]) {
				res -= min({ 0, val(3 * i), val(i) + val(3 * i) });
				slc[i] = true;
				slc[3 * i] = true;
			}
		}
		// 2m which m > c
		for (int i = c + 1; 2 * i <= n; i++) {
			if (!slc[i]) {
				res -= min({ 0, val(2 * i), val(i) + val(2 * i) });
				slc[i] = true;
				slc[2 * i] = true;
			}
		}
		// normal numbers
		for (int i = c + 1; i <= n; i++) {
			if (!slc[i]) res -= min(0, val(i));
		}
		ret = max(ret, res);
		return;
	}
	bool flag = false;
	for (int i = 1; i < pos; i++) {
		if (pos % i == 0 && choose[i]) flag = true;
	}
	dfs(pos + 1, sum + a[pos]);
	if (!flag) {
		choose[pos] = true;
		dfs(pos + 1, sum);
		choose[pos] = false;
	}
}
int main() {
	cin >> n; c = n / 4;
	for (int i = 1; i <= n; i++) cin >> a[i];
	dfs(0, 0);
	cout << ret << endl;
	return 0;
}

