template<typename T>
class MaxFlow {
private:
  struct Edge {
    int v;
    int r;
    T c;
  };

private:
  std::vector<std::vector<Edge>> g;
  std::vector<int> d, it;

public:
  MaxFlow(int n) : g(n), d(n), it(n) {}

  void add(int u, int v, T c) {
    const int i = g[u].size();
    const int j = g[v].size();
    g[u].push_back({ v, j, c });
    g[v].push_back({ u, i, 0 });
  }

  T calc(int s, int t) {
    T sum = 0;
    while (bfs(s, t)) {
      T f;
      while ((f = dfs(s, t, std::numeric_limits<T>::max())) > 0) sum += f;
    }
    return sum;
  }

private:
  bool bfs(int s, int t) {
    std::fill(it.begin(), it.end(), 0);
    std::fill(d.begin(), d.end(), -1);
    d[s] = 0;
    std::queue<int> q;
    q.push(s);
    while (!q.empty()) {
      int v = q.front();
      q.pop();
      for (Edge e : g[v]) {
        if (e.c > 0 && d[e.v] == -1) {
          d[e.v] = d[v] + 1;
          q.push(e.v);
        }
      }
    }
    return d[t] >= 0;
  }

  T dfs(int v, int t, T f) {
    if (v == t) return f;
    while (it[v] < g[v].size()) {
      Edge &e = g[v][it[v]++];
      if (e.c > 0 && d[v] < d[e.v]) {
        T ff = dfs(e.v, t, std::min(f, e.c));
        if (ff > 0) {
          e.c -= ff;
          g[e.v][e.r].c += ff;
          return ff;
        }
      }
    }
    return 0;
  }
};

int main() {
  int n;
  cin >> n;

  vector<int> a(n);
  long long sum = 0;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    sum += a[i];
  }

  MaxFlow<long long> mf(n * 2 + 2);
  int s = n * 2;
  int t = n * 2 + 1;

  const long long inf = 1e12;

  auto add = [&](int i, int j, long long c) {
    mf.add(i, j, -c + inf);
  };

  for (int i = 0; i < n; i++) {
    add(s, i, 0);
    add(i, i + n, a[i]);
    add(i + n, t, -inf);
    for (int j = i + 1; j < n; j++) {
      if ((j + 1) % (i + 1) == 0) {
        add(j, i, -inf);
      }
    }
  }

  cout << -mf.calc(s, t) + inf * n << endl;
}

