	for (int i = lvl; i <= n && 3 * i <= n; i++) if (!tk[i]) {
	//	printf("got %d\n", i);
		for (int j = i; j <= n; j += i) 
			if (tk[j]++ == 0) res -= a[j];
	//	printf("tk %d, res = %lld\n", i, res);
		Solve(i + 1);
		for (int j = i; j <= n; j += i)
			if (--tk[j] == 0) res += a[j];
