template<class T> struct flow {
  struct edge {
    int to;
    T cap;
    int rev;
  };

  int n, s, t;
  vector<vector<edge>> g;
  vector<bool> used;

  flow(int n, int s, int t) : n(n), s(s), t(t) {
    g = vector<vector<edge>>(n);
  }

  void add(int from, int to, T cap) {
    g[from].push_back({ to, cap, (int) g[to].size() });
    g[to].push_back({ from, 0, (int) g[from].size() - 1 });
  }

  T dfs(int v, T f) {
    if (v == t) {
      return f;
    }
    used[v] = true;
    for (auto &e : g[v]) {
      if (used[e.to] || e.cap <= 0) {
        continue;
      }
      T d = dfs(e.to, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }

  T max_flow() {
    T sum = 0;
    while (true) {
      used = vector<bool>(n);
      T f = dfs(s, numeric_limits<T>::max());
      if (f == 0) {
        break;
      }
      sum += f;
    }
    return sum;
  }
};

int main() {
  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  int s = 0, t = n + 1;
  long long sum = 0;
  flow<long long> f(n + 2, s, t);
  for (int i = 0; i < n; i++) {
    if (a[i] < 0) {
      f.add(s, i + 1, -a[i]);
      f.add(i + 1, t, 0);
    } else {
      f.add(i + 1, t, a[i]);
      sum += a[i];
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = i + i; j <= n; j += i) {
      f.add(i, j, numeric_limits<i64>::max());
    }
  }
  cout << sum - f.max_flow() << endl;
  return 0;
}

