	REP(i,n)
	{
		int a;cin >> a;
		if(a > 0){add_edge(i+1,n+1,a);ans += a;}
		else add_edge(0,i+1,-a);
		for(int j = (i+1);j <= n;j += i+1)
		{
			add_edge(i+1,j,INF);
		}
	}

	cout << ans - Dinic(0,n+1) << endl;

	return 0;
}

