int n;
ll arr[110][110] = {};
ll flow[110][110] = {};
ll capacity[110][110] = {};

ll solve() {
	n += 2;

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			capacity[i][j] += arr[i][j];
		}
	}

	const int s = 0;
	const int t = n-1;

	ll total = 0;
	while (1) {
		//cout << total << endl;
		queue<int> Q; Q.push(s);
		vector<int> prev(n, -1); prev[s] = s;
		while (!Q.empty() && prev[t] < 0) {
			int u = Q.front(); Q.pop();
			for (int i = 0; i < n; i++) {
				if (prev[i] < 0 && capacity[u][i] - flow[u][i] > 0) {
					prev[i] = u;
					Q.push(i);
				}
			}
		}
		if (prev[t] < 0) return total;
		ll inc = pow(10, 12);
		for (int j = t; prev[j] != j; j = prev[j]) {
			//cout << j << " ";
			inc = min(inc, capacity[prev[j]][j] - flow[prev[j]][j]);
		}
		//cout << endl << endl;
		for (int j = t; prev[j] != j; j = prev[j]) {
			flow[prev[j]][j] += inc, flow[j][prev[j]] -= inc;
		}
		total += inc;
	}


}


