#include <bits/stdc++.h>
using namespace std;

const int MAXN = 210;

struct node {
	int to, next;
	long long flow;
	int neg;
} edge[MAXN*MAXN];
int head[MAXN], top = 0;
inline void push(int i, int j, long long f)
{
	++top, edge[top] = (node) {j, head[i], f, top+1}, head[i] = top;
	++top, edge[top] = (node) {i, head[j], 0, top-1}, head[j] = top;
}

int vis[MAXN], lev[MAXN], bfstime = 0;
const int S = MAXN-1, T = MAXN-2;
queue<int> que;

bool bfs()
{
	vis[S] = ++bfstime, lev[S] = 0, que.push(S);
	while (!que.empty()) {
		int nd = que.front(); que.pop();
		for (int i = head[nd]; i; i = edge[i].next) {
			int to = edge[i].to;
			if (!edge[i].flow || vis[to] == bfstime) continue;
			vis[to] = bfstime, lev[to] = lev[nd]+1, que.push(to);
		}
	}
	return vis[T] == bfstime;
}

long long dfs(int nd, long long maxf)
{
	// cerr << nd << " " << maxf << endl;
	// cin.get();
	if (!maxf || nd == T) return maxf;
	long long ans = 0, t;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (!edge[i].flow || lev[to] != lev[nd]+1) continue;
		t = dfs(to, min(maxf, edge[i].flow));
		ans += t, maxf -= t, edge[i].flow -= t, edge[edge[i].neg].flow += t;
	}
	// if (!maxf) lev[nd] = -1;
	return ans;
}

long long dinic()
{
	long long ans = 0;
	while (bfs()) {
		ans += dfs(S, 1e15);
		// cerr << vis[T] << " " << ans << endl;
	}
	return ans;
}

int n;
int a[MAXN];

int main()
{
	cin >> n;
	long long ans = 0;
	for (int i = 1; i <= n; i++) { cin >> a[i]; ans += a[i]; }
	for (int i = 1; i <= n; i++) push(S, i, 1e9), push(i, T, 1e9+a[i]);
	for (int i = 1; i <= n; i++)
		for (int j = i+i; j <= n; j += i)
			push(i, j, 1e15);
	// cerr << "HA" << endl;
	long long val = dinic()-(long long)n*1000000000;
	// cerr << val << endl;
