vector<node> g[N+10];
queue<int > q;
int n,m,s,t;
int level[N+10],cur[N+10];
bool bfs() {
	memset(level,0,sizeof(level));
	while(!q.empty()) q.pop();
	q.push(s); level[s]=1;
	while(!q.empty()) {
		int u=q.front(); q.pop();
		//printf("%d\n",u);
		if(u==t) return 1;
		for(int i=0;i<(int)g[u].size();i++) {
			int v=g[u][i].to;
			LL f=g[u][i].flow;
			if(level[v]==0 && f!=0) {
				level[v]=level[u]+1;
				q.push(v);
			}
		}
	}
	return 0;
}
LL dfs(int u,int t,LL maxf) {
	if(u==t) return maxf;
	LL ret=0;
	for(int i=cur[u];i<(int)g[u].size();i++) {
		int v=g[u][i].to;
		LL f=g[u][i].flow;
		if(level[u]+1==level[v] && f) {
			LL Min=min(maxf-ret,f);
			f=dfs(v,t,Min);
			if(f>0) {
				g[u][i].flow-=f;
				g[v][g[u][i].rev].flow+=f;
				ret+=f;
				cur[u]=i;
			}
			if(maxf==ret) return ret;
		}
	}
	return ret;
}
void addedge(int u,int v,LL f) {
	node e; e.to=v; e.flow=f; e.rev=(int)g[v].size();
	g[u].push_back(e);
	e.to=u; e.flow=0; e.rev=(int)g[u].size()-1;
	g[v].push_back(e);
}
