	for(int i=1;i<=n;i++)
		for(int j=i+i;j<=n;j+=i)
			addedge(j,i,inf);
	while(bfs()) {
		memset(cur,0,sizeof(cur));
		ans-=dfs(s,t,inf);
	}
	printf("%lld\n",ans);
	return 0;
}

