inline int Isap(int x,int f) {
	if(x == T || !f) return f;
	int res = f;
	for(int i = beg[x];i;i = nex[i])
		if(w[i] && dis[x] == dis[to[i]] + 1) {
			int val = Isap(to[i],min(res,w[i]));
			w[i] -= val,w[i ^ 1] += val;
			res -= val;
			if(!res) return f;
		}
	if(!(--gap[dis[x]])) dis[S] = tot;
	++gap[++dis[x]];
	return f - res;
}

