const int MAX_N = 110;
ll N;
vector<ll> A;
ll res;
bool flag[MAX_N];
int main() {
  cin >> N;
  A.resize(N);
  for (auto &val : A){
    cin >> val;
    res += val;
  }
  for (int i = N; i >= 1; i--){
    if (flag[i])continue;
    if (A[i - 1] < 0){
      ll sum = 0;
      for (int j = i; j <= N; j++){
        if (j % i == 0 and not flag[j]){
          sum += A[j - 1];
        }
      }
      if (sum <= 0){
        for (int j = i; j <= N; j++){
          if (j % i == 0){
            flag[j] = true;
          }
        }
      }
    }
  }
  ll res1 = 0;
  for (int i = 1; i <= N; i++){
    if (not flag[i]){
      res1 += A[i - 1];
    }
  }
  cout << max(res1, res) << endl;
  return 0;
}

