using namespace std;

void set_score(vector<int> &score, vector<int> &a, vector<bool> &alive){
    int N = score.size();
    for (int pos = 1; pos <= N; pos++){
        int s=0;
        int i = pos;
        while(i <= N){
            if (alive[i-1]){
                s += a[i - 1];
            }
            i+=pos;
        }
        score[pos-1]=s;
    }
}

void set_dead(int pos, vector<bool> &alive){
    int N = alive.size();
    int i = pos;
    while(i <= N){
        alive[i -1]=false;
        i += pos;
    }
}

void show_vec(vector<int> &vec){
    int N = vec.size();
    for (int i=1; i<=N;i++){
        cout<<i<<":"<<vec[i-1]<<endl;
    }
}

int main()
{
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i =0;i<N;i++){
        cin>>a[i];
    }

    vector<bool> alive(N, true);
    vector<int> score(N, 0);
    set_score(score, a, alive);

    while (true) {
        int pos = min_element(score.begin(), score.end()) - score.begin() + 1;
        int minVal = score[pos - 1];
        if (minVal >= 0) {
            break;
        } else {
            set_dead(pos, alive);
            set_score(score, a, alive);
        }
    }

    cout<<score[0]<<endl;
    return 0;
}

