int n, a[M], b1;
bool used[M];
ll ans;

void gen(int b)
{
    if (3 * b > n)
    {
        ll s = 0;
        for (int i = 1; i <= n; i++)
            if (used[i])
                s += a[i];
        for (int x = b1 + 1; x <= n; x++)
            if (used[x] && ((x & 1) || x < 2 * b) && a[x] < 0)
                s -= a[x];
        for (int x = 2 * b; x <= n; x += 2)
        {
            int y = (x / 2);
            if (!used[y] && !used[x])
                continue;
            if (!used[y] && a[x] < 0)
                s -= a[x];
            else if (!used[x] && a[y] < 0)
                s -= a[y];
            else
            {
                if (s < max(s - a[x] - a[y], s - a[x]))
                    s = max(s - a[x] - a[y], s - a[x]);
            }
        }
        ans = max(s, ans);
        return;
    }
    gen(b + 1);
    vector<int> id;
    for (int i = b; i <= n; i += b)
        if (used[i])
            id.push_back(i);
    if (!id.empty())
    {
        for (int i : id)
            used[i] = 0;
        gen(b + 1);
        for (int i : id)
            used[i] = 1;
    }
}

