    Dinic mf(N + 2);
    ll s = N, t = N + 1;
    ll ans = 0;
    REP(i, N) {
        if(a[i] >= 0) {
            mf.add_edge(s, i, a[i]);
            mf.add_edge(i, t, 0);
            ans += a[i];
        } else {
            mf.add_edge(s, i, 0);
            mf.add_edge(i, t, -a[i]);
        }
    }
    REP(i, N) FOR(j, i + 1, N) {
        if((j + 1) % (i + 1) == 0) {
            mf.add_edge(j, i, LINF);
        }
    }
    cout << ans - mf.max_flow(s, t) << "\n";
}

