int solve(vector < int > v){
    //for (auto i: v) cout << i << " ";
    //cout << endl;
    int sz = v.size();
    int res = 2e13;
    for (int i = 0; i < (1 << sz); i++){
        vector < int > z;
        z.clear();
        for (int j = 0; j < sz; j++) if (i &(1 << j)) z.pb(v[j]);
        int r = 0;
        for (auto j: v){
            int t = 0;
            for (auto l: z){
                if (j % l == 0){
                    t = 1;
                    break;
                }
            }
            r += t * a[j];
        }
        res = min(res, r);
    }
    return res;
}
