    vector < int > v[200];
    int ans = 2e13;
    for (int i = 1; i <= n; i++) cin >> a[i];
    int k = min(n, (int)10);
    for (int i = 0; i < (1 << k); i++){
        int r = 0;
        for (int j = 1; j <= n; j++) v[j].clear();
        for (int j = 1; j <= n; j++){
            int t = 0;
            for (int l = 1; l <= k; l++){
                if ((i & (1 << (l - 1))) && j % l == 0){
                    t = 1;
                    break;
                }
            }
            r += t * a[j];
            if (t == 0 && j > k){
                v[j].pb(j);
                for (int l = k + 1; l < j; l++){
                    if (j % l == 0){
                        for (auto q: v[l]) v[j].pb(q);
                        v[l].clear();
                    }
                }
            }
        }
        for (int j = k + 1; j <= n; j++){
            r += solve(v[j]);
        }
        ans = min(ans, r);
    }
    ans = -ans;
    for (int i = 1; i <= n; i++) ans += a[i];
    cout << ans;
}

