		if (sign) {
			//cerr << "a" << endl;
			int M = dels.size();
			if (M == 0)continue;
			int idx = xor128() % M;
			int d = dels[idx];
			//dels.erase(dels.begin() + idx);
			REP(i, N + 1)new_del[i] = false;
			for (auto x : dels) {
				if (x == d)continue;
				if (new_del[x])continue;
				for (int j = x; j <= N; j += x) {
					//if (new_del[j])break;
					new_del[j] = true;
				}
			}
			new_val = 0;
			FOR(i, 1, N + 1) {
				if (!new_del[i])new_val += A[i];
			}
			double prob = exp((new_val - pre_val) / temp);
			if (new_val > pre_val || prob > (xor128() % INF) / (double)INF) {
				del = new_del;
				pre_val = new_val;
				//if (new_val > best_score)ans_del = new_del;
				best_score = max(best_score,new_val);
				dels.erase(dels.begin() + idx);
			}
		}
		//消去するものを1つ増やす
		else {
			//cerr << "b" << endl;
			int cnt = 0;
			FOR(i, 1, N + 1) {
				if (!del[i])cnt++;
			}
			if (cnt == 0)continue;
			int idx = xor128() % cnt;
			int d = 0;
			int c = 0;
			//DEBUG(cnt);

			FOR(i, 1, N + 1) {
				if (!del[i]) {
					if (c == idx) {
						d = i; break;
					}
					c++;
				}
			}
			REP(i, N + 1)new_del[i] = false;
			for (auto x : dels) {
				if (new_del[x])continue;
				for (int j = x; j <= N; j += x) {
					//if (new_del[j])continue;
					new_del[j] = true;
				}
			}
			for (int j = d; j <= N; j += d) {
				new_del[j] = true;
			}
			new_val = 0;
			FOR(i, 1, N + 1) {
				if (!new_del[i])new_val += A[i];
			}
			double prob = exp((new_val - pre_val) / temp);
			if (new_val > pre_val || prob > (xor128() % INF) / (double)INF) {
				del = new_del;
				pre_val = new_val;
				//if (new_val > best_score)ans_del = new_del;
				best_score = max(best_score, new_val);
				//dels.erase(dels.begin() + idx);
				dels.push_back(d);
			}
		}
	}
END:;
	//print_space(ans_del);
	//vector<int>vv;
	//FOR(i, 1, N + 1)if (ans_del[i])vv.push_back(i);
	//print_space(vv);
	return best_score;
}
