struct Dinic {
	struct Hen {
		int to;
		int64_t cap;
		int rev_id;
	};
	int n;
	std::vector<std::vector<Hen> > hen;
	Dinic (int n) : n(n), hen(n) {}
	void add_hen(int a, int b, int64_t c) {
		hen[a].push_back({b, c, (int) hen[b].size()});
		hen[b].push_back({a, 0, (int) hen[a].size() - 1});
	}
	std::vector<int> dist;
	void bfs(int s) {
		dist.assign(n, 1000000000);
		std::queue<int> que;
		que.push(s);
		dist[s] = 0;
		while (que.size()) {
			int i = que.front();
			que.pop();
			for (auto j : hen[i]) if (j.cap > 0 && dist[j.to] > dist[i] + 1) dist[j.to] = dist[i] + 1, que.push(j.to);
		}
	}
	std::vector<int> heads;
	int64_t dfs(int i, int goal, int64_t flow) {
		if (i == goal) return flow;
		for (int &j = heads[i]; j < (int) hen[i].size(); j++) {
			if (hen[i][j].cap <= 0 || dist[hen[i][j].to] <= dist[i]) continue;
			int64_t new_flow = dfs(hen[i][j].to, goal, std::min(flow, hen[i][j].cap));
			if (new_flow > 0) {
				hen[i][j].cap -= new_flow;
				hen[hen[i][j].to][hen[i][j].rev_id].cap += new_flow;
				return new_flow;
			}
		}
		return 0;
	}
	int64_t run(int s, int t) {
		int64_t res = 0;
		while (1) {
			bfs(s);
			if (dist[t] == 1000000000) break;
			heads.assign(n, 0);
			int64_t cur;
			while ((cur = dfs(s, t, 1000000000)) > 0) res += cur;
		}
		return res;
	}
};

int main() {
	int n = ri();
	int a[n + 1];
	for (int i = 1; i <= n; i++) a[i] = ri();
	int64_t base = 0;
	Dinic dinic(n + 2);
	for (int i = 1; i <= n; i++) {
		if (a[i] >= 0) {
			dinic.add_hen(0, i, a[i]);
			dinic.add_hen(i, n + 1, 0);
			base += a[i];
		} else {
			dinic.add_hen(0, i, 0);
			dinic.add_hen(i, n + 1, -a[i]);
		}
		for (int j = i + i; j <= n; j += i) dinic.add_hen(j, i, 1000000000000000000);
	}
	base -= dinic.run(0, n + 1);
	printf("%" PRId64 "\n", base);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
using Int = long long;

template< typename T >
struct Dinic
{
  struct edge
  {
    int to;
    T cap;
    int rev;
  };

  const T INF;
  vector< vector< edge > > graph;
  vector< T > min_cost;
  vector< int > iter;

  Dinic(int n) : INF(numeric_limits< T >::max())
  {
    graph.resize(n);
  }

  void add_edge(int from, int to, T cap)
  {
    graph[from].push_back((edge) {to, cap, (int) graph[to].size()});
    graph[to].push_back((edge) {from, 0, (int) graph[from].size() - 1});
  }

  bool bfs(int s, int t)
  {
    min_cost.assign(graph.size(), -1);
    queue< int > que;
    min_cost[s] = 0;
    que.push(s);
    while(!que.empty()) {
      int p = que.front();
      que.pop();
      for(auto &e : graph[p]) {
        if(e.cap > 0 && min_cost[e.to] == -1) {
          min_cost[e.to] = min_cost[p] + 1;
          que.push(e.to);
        }
      }
    }
    return (min_cost[t] != -1);
  }

  T dfs(int idx, const int t, T flow)
  {
    if(idx == t) return (flow);
    for(int &i = iter[idx]; i < graph[idx].size(); i++) {
      edge &e = graph[idx][i];
      if(e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
        T d = dfs(e.to, t, min(flow, e.cap));
        if(d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return (d);
        }
      }
    }
    return (0);
  }

  T max_flow(int s, int t)
  {
    T flow = 0;
    while(bfs(s, t)) {
      iter.assign(graph.size(), 0);
      T f = 0;
      while((f = dfs(s, t, INF)) > 0) {
        flow += f;
      }
    }
    return (flow);
  }
};

