{
    int N; cin >> N;
    vector<int> A(N); for (auto &a : A) cin >> a;
    int S = N, T = N+1;
    Dinic<Int> dinic(N+2);
    Int sum = 0;
    for (int i = 0; i < N; i++) {
        dinic.add_edge(S, i, (A[i] <= 0 ? -A[i] : 0));
        dinic.add_edge(i, T, (A[i] >= 0 ?  A[i] : 0));
        if (A[i] > 0) sum += A[i];
    }
    const Int INF = 1e12;
    for (int i = 0; i < N; i++) {
        int n = i + 1;
        for (int m = n + n; m <= N; m += n) {
            dinic.add_edge(n-1, m-1, INF);
        }
    }
    cout << sum - dinic.max_flow(S, T) << '\n';
    return 0;
}

