template <typename T>
class Dinic {
    T INF_;
    struct Edge {int to, rev; T cap;};
    vector<vector<Edge>> G;
    vector<int> dist, iter;
    bool bfs(int s, int t) {
        dist.assign(G.size(), -1);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (Edge &e : G[v]) {
                if (dist[e.to] != -1 || e.cap == 0) continue;
                dist[e.to] = dist[v] + 1;
                q.push(e.to);
            }
        }
        return dist[t] != -1;
    }
    T dfs(int now, int t, T min_cap) {
        if (now == t) return min_cap;
        for (int &i = iter[now]; i < G[now].size(); ++i) {
            Edge &e = G[now][i];
            if (e.cap == 0 || dist[e.to] != dist[now] + 1) continue;
            T d = dfs(e.to, t, min(min_cap, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }
public:
    Dinic(int V) : G(V), INF_(numeric_limits<T>::max()) {}
    void AddEdge(int from, int to, T cap) {
        G[from].push_back(Edge{to, (int)G[to].size(), cap});
        G[to].push_back(Edge{from, (int)G[from].size() - 1, 0});
    }
    T MaxFlow(int s, int t) {
        T ans = 0;
        while (bfs(s, t)) {
            iter.assign(G.size(), 0);
            T f = 0;
            while ((f = dfs(s, t, INF_)) > 0) ans += f;
        }
        return ans;
    }
};

