    ll ans = 0;
    rep(i, n) {
        int x = max(a[i], 0);
        G.AddEdge(0, i + 1, x - a[i]);
        G.AddEdge(i + 1, n + 1, x);
        ans += x;
    }
    rep(i, 1, n + 1) for (int j = 2 * i; j <= n; j += i) G.AddEdge(i, j, INF);
    ans -= G.MaxFlow(0, n + 1);
    cout << ans << "\n";
    return 0;
}

