int n;
int removed[110];
ll val[110];
ll sum, ans;
void recurse(int p)
{
	ans = max(ans, sum);
	if (p > n/2) return;
	if (p > n/3)
	{
		int x2 = p*2;
		if (x2 % 3 == 0 && x2/3 > n/2)
		{
			recurse(p+1);
		}
		else
		{
			int v = 0;
			if (!removed[p]) v -= val[p];
			if (!removed[x2]) v-=val[x2];
			if (v > 0) sum+=v;
			recurse(p+1);
			if (v > 0) sum-=v;
		}
		return;
	}
	if (p > n/4)
	{
		int x2 = p*2;
		int x3 = p*3;
		int op1 = 0;
		if (!removed[p]) op1-=val[p];
		if (!removed[x2]) op1-=val[x2];
		if (!removed[x3]) op1-=val[x3];
		int op2 = 0;
		if (x3 % 2 == 0)
		{
			if (!removed[x3/2]) op2 -= val[x3/2];
			if (!removed[x3]) op2 -= val[x3];
		}
		sum+=max(op1, max(op2, 0));
		recurse(p+1);
		sum-=max(op1, max(op2, 0));
		return;
	}
	recurse(p+1);
	if (removed[p]) return;
	for (int i = p; i <= n; i+=p)
	{
		if (!removed[i])
		{
			sum-=val[i];
		}
		removed[i]++;
	}
	recurse(p+1);
	for (int i = p; i <= n; i+=p)
	{
		removed[i]--;
		if (!removed[i])
		{
			sum+=val[i];
		}
	}
}
int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) { scanf("%lld", &val[i]); sum+=val[i]; 
		if (i > n/2 && val[i] < 0) { sum-=val[i]; removed[i] = 1; }
	}
	recurse(1);
	printf("%lld\n", ans);
}

