	out.sync_with_stdio(false);
	in.tie(nullptr);
	out.tie(nullptr);

	in >> N;
	for (int64_t i = 1; i <= N; i++)
	{
		in >> A[i];
	}

	for (int64_t i = N; i >= 1; i--)
	{
		int64_t tmp = 0;
		for (int64_t j = i; j <= N; j+=i)
		{
			tmp += A[j];
		}
		if (tmp < 0) {
			for (int64_t j = i; j <= N; j += i)
			{
				A[j] = 0;
			}
		}
	}

	for (int64_t i = 1; i <= N; ++i)
	{
		for (int64_t j = i; j <= N; j += i)
		{
			diff[i] += A[j];
		}
	}
	int64_t res = std::accumulate(A + 1, A + N + 1, 0_i64);


	auto func = [&](int64_t v) {
		for (int64_t k = 1; k*v <= N; ++k)
		{
			for (int64_t i = 1; i <= k*v; i++)
			{
				if ((k*v)%i == 0) { diff[i] -= A[k*v]; }
			}
			A[k*v] = 0;
		}
	};

	//二つ
	for (int64_t i = N; i >= 1; --i)
	{
		for (int64_t j = i - 1; j >= 1; --j)
		{
			if (lcm(i, j) > N) { continue; }
			if (-diff[i] - diff[j] + diff[lcm(i, j)] > 0) {
				res += -diff[i] - diff[j] + diff[lcm(i, j)];
				func(i); func(j);
			}
		}
	}
	//3つ
	for (int64_t i = N; i >= 1; --i)
	{
		for (int64_t j = i - 1; j >= 1; --j)
			for (int64_t kkk = j - 1; kkk >= 1; --kkk)
		{
			if (lcm(kkk, lcm(i, j)) > N) { continue; }
			if (
				-diff[i] - diff[j] - diff[kkk]
				+ diff[lcm(i, j)] + diff[lcm(j, kkk)] + diff[lcm(kkk, i)]
				- diff[lcm(kkk, lcm(i, j))]> 0
				) {

				res += (-diff[i] - diff[j] - diff[kkk]
					+ diff[lcm(i, j)] + diff[lcm(j, kkk)] + diff[lcm(kkk, i)]
					- diff[lcm(kkk, lcm(i, j))]);

				func(i); func(j); func(kkk);
			}
		}
	}


	out << std::accumulate(A + 1, A + N + 1, 0_i64) << endl;

	return 0;
}
