            dinic.add_edge(0, i, -a);
        }

        ll n = 2;
        while (i * n <= N) {
            dinic.add_edge(i, i * n, INF);
            n++;
        }
    }

    cout << total - dinic.max_flow(0, N + 1) << endl;
    return 0;
}

#include "bits/stdc++.h"

using namespace std;

typedef long long ll;
const ll INF = 1e15;

class max_flow {
	struct edge {
		ll to, cap, rev;
		edge(ll to_, ll cap_, ll rev_) : to(to_), cap(cap_), rev(rev_) {};
	};

	ll V;
	vector<vector<edge>> G;
	vector<int> level;
	vector<int> iter;

	void BFS(int s) {
		fill(level.begin(), level.end(), -1);
		queue<int> que;
		level[s] = 0;
		que.push(s);
		while (!que.empty()) {
			int v = que.front(); que.pop();
			for (size_t i = 0; i < G[v].size(); i++) {
				edge &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					que.push(e.to);
				}
			}
		}
	}
	int DFS(int v, int t, ll f) {
		if (v == t) return f;
		for (int &i = iter[v]; i < (int)G[v].size(); i++) {
			edge &e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				int d = DFS(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
public:
	max_flow(int _V) : V(_V), G(_V), level(_V), iter(_V) {}
	void add(int from, int to, ll cap) {
		G[from].push_back(edge(to, cap, G[to].size()));
		G[to].push_back(edge(from, 0, G[from].size() - 1));
	}
	int dinic(int s, int t) {
		int flow = 0;
		while (true) {
			BFS(s);
			if (level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			int f;
			while ((f = DFS(s, t, INF)) > 0) {
				flow += f;
			}
		}
	}
};

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

    int n;cin>>n;
    vector<ll> a(n+1);
	ll sum=0;
	max_flow mf(n+2);
    for(int i=1;i<=n;i++){
		cin>>a[i];
		if(a[i]<=0){
			mf.add(0,i,-a[i]);
		}
		else{
			sum += a[i];
			mf.add(i,n+1,a[i]);
		}
	}
	for(int i=1;i<=n;i++){
		for(int j=2;i*j<=n;j++){
			mf.add(i,i*j,INF);
		}
	}
	cout<<sum-mf.dinic(0,n+1)<<endl;

}

#include <bits/stdc++.h>
using namespace std;

class Dinic {
 public:
  Dinic() {}
  Dinic(int n) : n(n) {
    adj.resize(n);
  }

  struct Edge {
    int v;
    long long cap, flow = 0;
    Edge() {}
    Edge(int v, long long c) : v(v), cap(c) {}
  };

  int n, s, t;
  vector<Edge> edge;
  vector<vector<int>> adj;

  vector<int> ptr;
  vector<int> level;
  queue<int> q;

  void AddEdge(int u, int v, long long cap) {
    adj[u].emplace_back(edge.size());
    edge.emplace_back(v, cap);
    adj[v].emplace_back(edge.size());
    edge.emplace_back(u, cap);
  }

  bool Bfs() {
    while (!q.empty()) {
      int u = q.front();
      q.pop();
      for (auto id : adj[u]) {
        auto e = edge[id];
        if (e.cap - e.flow == 0) {
          continue;
        }
        if (level[e.v] == -1) {
          level[e.v] = level[u] + 1;
          q.emplace(e.v);
        }
      }
    }
    return level[t] != -1;
  }

  long long Dfs(int u, long long fl) {
    if (fl == 0) {
      return 0;
    }
    if (u == t) {
      return fl;
    }
    for (int &p = ptr[u]; p < (int) adj[u].size(); p++) {
      int id = adj[u][p];
      auto e = edge[id];
      if (e.cap - e.flow == 0 || level[e.v] != level[u] + 1) {
        continue;
      }
      int res = Dfs(e.v, min(fl, e.cap - e.flow));
      if (res == 0) {
        continue;
      }
      edge[id].flow += res;
      edge[id ^ 1].flow -= res;
      return res;
    }
    return 0;
  }

  long long MaxFlow(int s_, int t_) {
    s = s_, t = t_;
    long long res = 0;
    while (true) {
      level.assign(n, -1);
      ptr.assign(n, 0);
      q.emplace(s);
      level[s] = 0;
      if (!Bfs()) {
        break;
      }
      while (long long flow = Dfs(s, 1e15)) {
        res += flow;
      }
    }
    return res;
  }
};

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  int N;
  cin >> N;

  vector<int> S, T; // S is smashed, T is not smashed
  vector<int> A(N + 1);
  long long X = 0; // Ideally, smash all negative As

  for (int i = 1; i <= N; i++) {
    cin >> A[i];
    if (A[i] <= 0) {
      S.emplace_back(i);
    } else {
      X += A[i];
      T.emplace_back(i);
    }
  }

  Dinic MF(N + 3);
  for (auto i : S) {
    for (auto j : T) {
      if (j % i == 0) { // j's position is determined by i's position
        MF.AddEdge(i, j, 1e18);
      }
    }
  }
  for (auto i : S) {
    MF.AddEdge(N + 1, i, -A[i]); // if this edge is "cut", then we get penalty
  }
  for (auto i : T) {
    MF.AddEdge(i, N + 2, A[i]); // if this edge is "cut", then we get penalty
  }

  cout << X - MF.MaxFlow(N + 1, N + 2) << "\n";
  return 0;
}

