void add_edge(int from,int to,int cap){
    G[from].pb((edge){to,cap,(int)G[to].size()});
    G[to].pb((edge){from,0,(int)G[from].size()-1});
}

//増加パスをDFSで探す
int dfs(int v,int t,int f){
    if(v==t)return f;
    used[v]=true;
    REP(i,G[v].size()){
        edge& e=G[v][i];
        if(!used[e.to]&&e.cap>0){
            int d=dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;
                G[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

