long long bf(int n) {
  if(n + n > N) {
    long long ans = 0;
    for(int i = n; i <= N; i++) {
      if(smash[i]) {
        ans += max(A[i], 0);
      }
    }
    return ans;
  }
  if(smash[n]) {
    return bf(n + 1);
  }else {
    long long now = A[n] + bf(n + 1);
    for(int i = n + n; i <= N; i += n) {
      smash[i]++;
    }
    now = max(now, bf(n + 1));
    for(int i = n + n; i <= N; i += n) {
      smash[i]--;
    }
    return now;
  }
}

