    //freopen("output.txt", "w", stdout

    cin >> n;
    s = 0, t = n + 1;
    ll sum = 0;
    for (ll i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        if (a[i] < 0) {
            add_edge(s, i, -a[i]);
        } else {
            sum += a[i];
            add_edge(i, t, a[i]);
        }
        for (int j = i + i; j <= n; j += i) {
            add_edge(i, j, INF * MAXN);
        }
    }
    n += 2;
    cout << max(0LL, sum - dinic()) << "\n";
    return 0;
}

