lint Cap[101][101];

lint Augment(lint Pos,lint Bottleneck){
    if(Pos==Source) return Bottleneck;
    if(Pre[Pos]!=-1){
        lint Flow=Augment(Pre[Pos],min(Bottleneck,Cap[Pre[Pos]][Pos]));
        Cap[Pre[Pos]][Pos]-=Flow;
        Cap[Pos][Pre[Pos]]+=Flow;
        return Flow;
    }
    return 0;
}

void DFS(lint U){
    if(U==Sink) return;
    for(auto V:Adj[U]){
        if(Pre[V]==-1&&Cap[U][V]>0){
            Pre[V]=U;
            DFS(V);
        }
        if(Pre[Sink]!=-1) return;
    }
}

