#define ll long long
const ll INF = 100000000000;

struct Edge
{
    int to, rev;
    ll capacity;

    Edge(int to_, ll capacity_, int rev_)
            : to(to_), capacity(capacity_), rev(rev_){}
};

ll DFS(int current, int target, ll flow,
        std::vector<std::vector<Edge>>& connection,
        std::vector<bool>& seenTable)
{
    if (current == target)
        return flow;

    seenTable[current] = true;
    for (auto& e : connection[current])
    {
        if (!seenTable[e.to] && 0 < e.capacity)
        {
            auto d = DFS(e.to, target, std::min(flow, e.capacity), connection, seenTable);
            if (0 < d)
            {
                // d だけ e に流す
                e.capacity -= d;

                // d だけ 逆編から流れる
                connection[e.to][e.rev].capacity += d;

                return d;
            }
        }
    }

    return 0;
}

ll MaxFlow(int s, int t, std::vector<std::vector<Edge>>& connection)
{
    std::vector<bool> seenTable(connection.size());

    ll flow = 0;
    while (true)
    {
        for (auto i=0; i<seenTable.size(); ++i)
            seenTable[i] = false;

        ll f = DFS(s, t, INF, connection, seenTable);
        if (f == 0)
            return flow;
        else
            flow += f;
    }
}

int main()
{
    int N;
    std::cin >> N;
    std::vector<ll> A(N + 1);
    std::vector<std::vector<Edge>> graph(N + 3);

    ll maxSum = 0;
    for (auto i=1; i<=N; ++i)
    {
        std::cin >> A[i];
        if (0 < A[i])
            maxSum += A[i];
    }

    const int S = N + 1;
    const int T = N + 2;

    auto Connect = [&](int from, int to, ll capacity)
            {
                graph[from].push_back(Edge(to, capacity, graph[to].size()));
                graph[to].push_back(Edge(from, 0, graph[from].size() - 1));
            };

    for (auto i=1; i<=N; ++i)
    {
        if (A[i] < 0)
            Connect(S, i, -A[i]);
        else
            Connect(i, T, A[i]);

        for (auto j=i; j<=N; j += i)
            Connect(i, j, INF);
    }

    auto breakScore = MaxFlow(S, T, graph);
    std::cout << maxSum - breakScore << std::endl;
}

