int findmin(int n){
	long long int ans = INT_MAX;
	int pos = -1;
	for(int i = 0; i<n; i++){
		long long int local = 0;
		for(int j = i; j<n; j+=(i+1)){
			if(!visited[j])	local += arr[j];
		}
		if(local < ans){
			ans = local;
			pos = i;
		}
	}
	if(ans >= 0){
		return -1;
	}
	return pos;
}

