void addedge(int x,int y,long long z)
{
	++E;
	to[E]=y;nex[E]=fir[x];fir[x]=E;wei[E]=z;
	++E;
	to[E]=x;nex[E]=fir[y];fir[y]=E;wei[E]=0;
}
bool bfs()
{
	l[1]=ST;
	for(int i=MINNODE;i<=MAXNODE;i++)
		dis[i]=0;
	dis[ST]=1;
	for(int h=1,t=1;h<=t;h++)
	{
		for(int i=fir[l[h]];i;i=nex[i])
		if(wei[i]>0 && !dis[to[i]])
		{
			dis[to[i]]=dis[l[h]]+1;
			l[++t]=to[i];
		}
	}
	return dis[ED]>0;
}
long long dfs(int now,long long flow)
{
	if(flow<=0) return 0;
	if(now==ED) return flow;
	long long all=0;
	for(int i=fir[now];i && flow;i=nex[i])
	if(wei[i]>0 && dis[to[i]]==dis[now]+1)
	{
		int tem=dfs(to[i],min(flow,wei[i]));
		wei[i]-=tem;wei[i^1]+=tem;
		all+=tem;flow-=tem;
	}
	if(flow)
		dis[now]=0;
	return all;
}
