bool aktif[MAXN+5],aktif2[MAXN+5];
void buatawal(){
	bool kelipatan[MAXN+5];
	memset(kelipatan,false,sizeof(kelipatan));
	for(int i=batas;i<n;i++)
	{
		if(kelipatan[i])
			continue;
		daftarawal.pb(i);
		int now=i;
		while(now<n)
		{
			kelipatan[now]=true;
			now+=i+1;
		}
	}
