void matikan(int state,int ukuranbit,int ukuranaktif,bool aktif[MAXN+5]){
	for(int i=0;i<ukuranbit;i++)
	{
		if(state&(1<<i))
		{
			for(int j=i;j<ukuranaktif;j+=(i+1))
			{
				if(!aktif[j])
					break;
				aktif[j]=false;
			}
		}
	}
}
LL BF(vector <int> &daftar){
	LL calonret,ret=0;
	for(int state=0;state<(1<<daftar.size());state++)
	{
		for(int i=0;i<daftar.size();i++)
			aktif[i]=true;
		matikan(state,daftar.size(),daftar.size(),aktif);
		calonret=0;
		for(int i=0;i<daftar.size();i++)
		{
			if(!aktif[i])
				calonret+=-daftar[i];
		}
		ret=max(calonret,ret);
	}
	return ret;
}
LL solve(){
	LL calonret,ret=0;
	vector <int> daftar;
	for(int state=0;state<(1<<batas);state++)
	{
		memset(aktif2,true,sizeof(aktif2));
		matikan(state,batas,n,aktif2);
		calonret=0;
		for(int i=0;i<n;i++)
		{
			if(!aktif2[i])
				calonret+=-arr[i];
		}

		for(auto isi:daftarawal)
		{
			int now=isi;
			daftar.clear();
			while(now<n)
			{
				daftar.pb((aktif2[now])?arr[now]:0);
				now+=isi+1;
			}
			calonret+=BF(daftar);
		}
		ret=max(calonret,ret);
	}
	return ret;
}
