using namespace std;
typedef long long LL;

const int maxn = 1009, maxm = 10009;
const LL INF = 2e15;
struct edge { int u, v; LL f, c; };
struct ISAP {
	int n, m, s, t, head[maxn], link[maxm];
	int d[maxn], p[maxn], cur[maxn], num[maxn];
	edge e[maxm];
	void init(int _n) {
		n = _n; m = 0;
		memset(head, -1, sizeof head);
		memset(cur, -1, sizeof cur);
	}
	void addEdge(int u, int v, LL w) {
		e[m].u = u; e[m].v = v; e[m].f = 0; e[m].c = w;
		link[m] = head[u]; cur[u] = head[u] = m++;
		e[m].u = v; e[m].v = u; e[m].f = 0; e[m].c = 0;
		link[m] = head[v]; cur[v] = head[v] = m++;
	}
	LL augment() {
		LL mn = INF; int u = t;
		while (u != s) {
			mn = min(mn, e[p[u]].c - e[p[u]].f);
			u = e[p[u]].u;
		}
		u = t;
		while (u != s) {
			e[p[u]].f += mn; e[p[u]^1].f -= mn;
			u = e[p[u]].u;
		}
		return mn;
	}
	LL Maxflow(int _s, int _t) {
		LL res = 0; int u = _s, flag;
		memset(d, 0, sizeof d);
		memset(num, 0, sizeof num);
		s = _s; t = _t; num[0] = n;
		while (d[s] < n) {
			if (u == t) { res += augment(); u = s; }
			flag = 0;
			loop (k, cur[u])
				if (e[k].f < e[k].c && d[u] == d[e[k].v] + 1) {
					p[e[k].v] = cur[u] = k;
					u = e[k].v; flag = 1;
					break;
				}
			if (flag) continue;
			int mn = n;
			loop (k, head[u])
				if (e[k].f < e[k].c)
					mn = min(mn, d[e[k].v] + 1);
			if (--num[d[u]] == 0) return res;
			num[d[u] = mn]++; cur[u] = head[u];
			if (u != s) u = e[p[u]].u;
		}	
		return res;
	}
} G;
