    } else {
      ans += a[i];
      add_edge(i, t, a[i]);
    }
    for(int j = 2; i * j <= N; j++) {
      add_edge(i, i * j, INFi);
    }
  }

  ans -= max_flow(s, t);

  cout << ans << endl;


  return 0;
}

