std::int64_t greedy(int N, std::vector<std::int64_t> vec)
{
	std::vector<std::int64_t> sum(N + 1);
	while (true)
	{
		for (auto& v : sum)
		{
			v = 0;
		}
		for (int i = 1; i <= N; ++i)
		{
			for (int k = i; k <= N; k += i)
			{
				sum[i] += vec[k];
			}
		}
		auto mi = boost::min_element(sum) - sum.begin();
		if (sum[mi] == 0)
		{
			break;
		}
		for (int k = mi; k <= N; k += mi)
		{
			vec[k] = 0;
		}
	}
	return sum[1];
}

