#define INF 1LL<<30

class MaxFlow {
    // 辺を表す構造体（行き先、容量、逆辺）
    struct edge {
        long long to, cap, rev;
    };
    vector<vector<edge>> G;  // グラフの隣接リスト表現
    vector<long long> level;       // sからの距離
    vector<long long> iter;        // どこまで調べ終わったか

    // sからの最短距離をBFSで計算する
    void bfs(long long s) {
        fill(level.begin(), level.end(), -1);
        queue<long long> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            long long v = que.front();
            que.pop();
            for(auto &e : G[v]){
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    // 増加パスをDFSで探す
    long long dfs(long long v, long long t, long long f) {
        if (v == t) return f;
        for (long long &i = iter[v]; i < G[v].size(); i++) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                long long d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

public:
    MaxFlow(long long V) : G(V), level(V), iter(V) {}

    // from から to へ向かう容量 cap の辺をグラフに追加する
    void add_edge(long long from, long long to, long long cap) {
        G[from].push_back((edge){to, cap, static_cast<long long>(G[to].size())});
        G[to].push_back((edge){from, 0, static_cast<long long>(G[from].size()) - 1});
    }
    // s から t への最大流を計算する
    long long max_flow(long long s, long long t) {
        long long flow = 0;
        while (bfs(s), level[t] >= 0) {
            fill(iter.begin(), iter.end(), 0);
            long long f;
            while ((f = dfs(s, t, INF)) > 0) flow += f;
        }
        return flow;
    }
};

