struct edge{
	int u, v, fa; ll cap;
}G[maxN << 1];
void add_(int u, int v, ll val) {
	//if(val == 0) return;
	G[e].u = u; G[e].v = v; G[e].cap = val; G[e].fa = l[u]; l[u] = e++;
	G[e].u = v; G[e].v = u; G[e].cap = 0; G[e].fa = l[v]; l[v] = e++; 
}
bool BFS() {
	for(int i = 0; i <= T; ++i) layer[i] = -1, cur[i] = l[i];
	queue<int> q; q.push(S); layer[S] = 0;
	while(!q.empty()) {
		int u = q.front(); q.pop();
		for(int i = l[u]; i != -1; i = G[i].fa) {
			int v = G[i].v;
			if(layer[v] > -1 || G[i].cap == 0) continue;
			layer[v] = layer[u] + 1;
			q.push(v);
		}
	}
	return layer[T] > -1;
}
int dfs(int u, ll flow) {
	if(u == T) return flow;
	ll ret = 0;
	for(int& i = cur[u]; i != -1; i = G[i].fa) {
		int v = G[i].v;
		if(layer[v] == layer[u] + 1 && G[i].cap > 0) {
			ll tmp = dfs(v, min(flow, G[i].cap));
			ret += tmp; flow -= tmp;
			G[i ^ 1].cap += tmp; G[i].cap -= tmp;
			if(flow == 0) return ret; 	
		}
	}
	return ret;
}
