template<class E> // Edge type
class Graph{
public:
  typedef std::vector<std::vector<E> > G;

private:
  G g;

public:
  Graph(int n) : g(G(n)) {}

  void addEdge(int from, int to, ll cap){
    g[from].push_back(E(cap, to, g[to].size()));
    g[to].push_back(E(0, from, g[from].size() - 1));
  }

  G &getRowGraph(){
    return g;
  }
};

template<class E>
class Dinic{
  typedef typename Graph<E>::G G;
  G &g;
  std::size_t n; // size of graph

  std::vector<int> level;
  std::vector<int> iter;

  // other utilities

  // search length of shortest path from s
  void bfs(int s){
    std::queue<int> que;
    level = std::vector<int>(n, -1);

    level[s] = 0;
    que.push(s);

    while(!que.empty()){
      int v = que.front(); que.pop();
      for(int i = 0; i < (int)g[v].size(); i++){
	E &e = g[v][i];
	if(e.cap > 0 && level[e.to] < 0){
	  level[e.to] = level[v] + 1;
	  que.push(e.to);
	}
      }
    }
  }

  // search path
  ll dfs(int v, int t, ll f){
    if(v == t) return f;
    for(int &i = iter[v]; i < (int)g[v].size(); i++){
      E &e = g[v][i];
      if(e.cap > 0 && level[v] < level[e.to]){
	ll d = dfs(e.to, t, min<ll>(f, e.cap));
	if(d > 0){
	  e.cap -= d;
	  g[e.to][e.rev].cap += d;
	  return d;
	}
      }
    }
    return 0;
  }

public:
  Dinic(Graph<E> &graph) : g(graph.getRowGraph()){
    n = g.size();
  }

  // Max flow of the flow from s to t.
  ll solve(int s, int t){
    ll flow = 0;
    while(true){
      ll f;
      bfs(s);
      if(level[t] < 0) return flow;
      iter  = std::vector<int>(n, 0);
      while((f = dfs(s, t, numeric_limits<ll>::max())) > 0){
	flow += f;
      }
    }
  }
};

template<class E>
ll dinic(Graph<E> &g, int s, int d){
  return Dinic<E>(g).solve(s, d);
}



