const int maxn = 310;
const ll oo = 1e18;

int n,a[maxn],s,t,trace[maxn],g[maxn][maxn];
ll f[maxn][maxn],c[maxn][maxn],maxFlow;
ll ans=0;

void add(int x,int y,ll vl) {
   // cout<<x<<" "<<y<<" "<<vl<<endl;
    f[x][y] = 0; f[y][x] = 0;
    c[x][y] = vl; c[y][x] = 0;
    g[x][y] = 1; g[y][x] = 1;
}

bool finpath(int s,int t) {
    for (int i=0;i<=n+1;i++) trace[i]=-1;
    queue<int> que;
    que.push(s);
    while (!que.empty()) {
        int u = que.front(); que.pop();
      //  cout<<u<<endl;
        for (int v=0;v<=n+1;v++)
            if ((g[u][v]==1) && (trace[v]==-1) && (f[u][v] < c[u][v])) {
                trace[v] = u;
             //   cout<<v<<" trace: "<<trace[v]<<" ";
                que.push(v);
                if (v==t) return true;
            }
       // cout<<endl;
    }
    return false;
}

void incFlow(int s,int t) {
    int v = t;
    ll x = oo;
    while (v!=s) {
        int u = trace[v];
        x = min(x,c[u][v] - f[u][v]);
        v = u;
    }
    maxFlow += x;
    v = t;
    while (v!=s) {
        int u = trace[v];
        f[u][v] += x;
        f[v][u] -= x;
        v = u;
    }

}

