        }
        for (LL i=1;i<=n;i++)
            for (LL j=i+i;j<=n;j+=i)
                add_edge(j,i,INF);
        LL tmp = max_flow(S,T);
        // cout<<"bug "<<ans<<" "<<tmp<<endl;
