using namespace std;
const int INF=(int) 0x3f3f3f3f;
const LL  LINF=(LL) INF<<32|INF;
const int maxn=1e2+20;
struct Dinic{
    struct E{
        int from,to;LL cap,flow;
        E(){}
        E(int _from,int _to,LL _cap,LL _flow):from(_from),to(_to),cap(_cap),flow(_flow) {}
    };
    int n,m,s,t;
    vector<E> edge;
    vector<int> G[maxn];
    bool vis[maxn];
    int d[maxn],cur[maxn];

    void init(int _n,int _s,int _t){
        n=_n; s=_s; t=_t;
        m=0;
        for(int i=0;i<=n;i++) G[i].clear();
        edge.clear();
    }

    void add(int from,int to,LL cap){
        edge.push_back(E(from,to,cap,0));G[from].push_back(m++);
        edge.push_back(E(to,from,0,0));G[to].push_back(m++);
    }

    queue<int> Q;
    bool BFS(){
        for (int i=0;i<=n;i++) vis[i]=false;
        while (!Q.empty())Q.pop();
        Q.push(s);d[s]=0;vis[s]=1;
        while(!Q.empty()){
            int x=Q.front(); Q.pop();
            for(int i=0,siz=G[x].size();i<siz;i++){
                E &e=edge[G[x][i]];
                if(!vis[e.to] && e.cap>e.flow){
                    vis[e.to]=1;
                    d[e.to]=d[x]+1;
                    Q.push(e.to);
                }
            }
        }
        return vis[t];
    }

    LL DFS(int x,LL a){
        if(x==t || a==0) return a;
        LL flow=0, f;
        for(int &i=cur[x],siz=G[x].size();i<siz;i++){
            E &e=edge[G[x][i]];
            if(d[x]+1==d[e.to] && (f = DFS(e.to,min(a,e.cap-e.flow)))>0){
                e.flow+=f;
                edge[G[x][i]^1].flow-=f;
                flow+=f;
                a-=f;
                if(a==0) break;
            }
        }
        return flow;
    }

    LL mf(){
        LL res=0;
        while(BFS()){
            for (int i=0;i<=n;i++) cur[i]=0;
            res+=DFS(s,LINF);
        }
        return res;
    }
}MF;
