	for (int i = 0; i < n + 2; i++) {
		cout << "i:" << i << endl;
		for (int j = 0; j < g[i].size(); j++) {
			edge e = g[i][j];
			cout << "  to:" << e.to << " cap:" << e.cap << endl;
		}
	}
}

