using ll = long long;


const int maxn = 110;
const ll inf = 1e18;

struct edge {
    ll to, cost, cap, rev;
};

struct min_cost_max_flow {

    int n;
    vector<vector<edge>> g;
    min_cost_max_flow(int n) {
	this->n = n;
	g.resize(n);
    }


    void add_edge(ll from, ll to, ll ecost, ll ecap) {
	assert(from>=0 && from<n);
	assert(to>=0 && to<n);

	edge fwd = { to, ecost, ecap, int(g[to].size()) };
	edge bak = { from, -ecost, 0, int(g[from].size()) };

	g[from].push_back(fwd);
	g[to].push_back(bak);
    }



    void sp(ll source, vector<ll>& dist, vector<pair<ll,ll>>& par) {
	dist.resize(n, inf);
	par.resize(n);
	dist[source] = 0;
	vector<bool> inq(n, false);
	queue<ll> qq;
	qq.push(0);
	while (!qq.empty()) {
	    ll at = qq.front();
	    qq.pop();
	    inq[at] = false;
	    for (int i=0; i<(int)g[at].size(); i++) {
		edge &ed = g[at][i];
		ll to = ed.to;
		if (ed.cap > 0 && dist[to] > dist[at] + ed.cost) {
		    dist[to] = dist[at] + ed.cost;
		    par[to] = {at, i};
		    if (!inq[to]) {
			inq[to] = true;
			qq.push(to);
		    }
		}
	    }
	}
    }

    pair<ll, ll> compute(int source, int sink, ll k=inf) {
	ll mincost = 0;
	ll maxflow = 0;

	while (maxflow < k) {
	    vector<ll> dist;
	    vector<pair<ll,ll>> par;
	    sp(source, dist, par);


	    if (dist[sink] == inf) {
		break;
	    }

	    ll f = k - maxflow;
	    ll at = sink;
	    while (at != source) {
		ll to = par[at].first;
		ll id = par[at].second;
		f = min(f, g[to][id].cap);
		at = to;
	    }

	    at = sink;
	    while (at != source) {
		ll to = par[at].first;
		ll id = par[at].second;
		mincost += f*g[to][id].cost;
		g[to][id].cap -= f;
		ll revid = g[to][id].rev;
		g[at][revid].cap += f;
		at = to;
	    }
	    maxflow += f;
	}

	return make_pair(mincost, maxflow);
    }
};


int n;
ll a[maxn];


int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    cin>>n;
    for (int i=1; i<=n; i++) {
	cin>>a[i];
    }
    int S = 0;
    int T = n+1;
    min_cost_max_flow flow(n+2);


    ll psum = 0;

    for (int i=1; i<=n; i++) {
	if (a[i]<=0) {
	    flow.add_edge(S, i, 0, -a[i]);
	} else {
	    psum += a[i];
	    flow.add_edge(i, T, 0, a[i]);
	}

	for (int j=i+i; j<=n; j+=i) {
	    flow.add_edge(i, j, 0, inf);
	}
    }


    pair<ll,ll> res = flow.compute(S, T);
    ll mincut = res.second;

    // watch(psum);
    // watch(mincut);

    out(psum - mincut);
    return 0;
}

