LL bestmodel(vector <int> &daftar){
	assert(daftar.size()<=5);
	LL ret=0;
	LL calonret;
	//sum all
	calonret=0;
	for(auto isi:daftar)
		calonret+=-isi;
	ret=max(ret,calonret);

	//sum genap
	calonret=0;
	for(int i=1;i<daftar.size();i+=2)
		calonret+=-daftar[i];
	//gabung solois
	for(int i=2;i<daftar.size();i+=2)
		calonret+=max(0,-daftar[i]);
	ret=max(ret,calonret);

	//sum solois
	calonret=0;
	for(int i=2;i<daftar.size();i++)
		calonret+=max(0,-daftar[i]);
	ret=max(ret,calonret);

	return ret;
}
void solve(){
	LL temp;
	vector <int> daftar;
