typedef long long ll;

template <class T> struct Dinic {

    struct Edge {
        int to,rev; T cap;
        Edge (int t, int r, T c) : to(t), rev(r), cap(c) {}
    };

    vector < vector< Edge > > G;
    vector < int > level, iter;
    const T INF = numeric_limits < T > ::max();
    Dinic (int n) : G(n), level(n, 0), iter(n, 0) {}

    void add_edge(int from, int to, T cap) {
        G[from].push_back(Edge(to, (int)(G[to].size()), cap));
        G[to].push_back(Edge(from, (int)(G[from].size()) - 1, 0));
    }

    void bfs(int s) {
        fill(level.begin(), level.end(), -1);
        queue < int > que({s});
        level[s] = 0;
        while (!que.empty()) {
            int v = que.front();
            que.pop();
            for (int i = 0; i < G[v].size(); i++) {
                Edge& e = G[v][i];
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    T dfs(int cur, int t, T f) {
        if (cur == t) return f;
        for (int &i = iter[cur]; i < G[cur].size(); i++) {
            Edge& e = G[cur][i];
            if (e.cap > 0 && level[e.to] > level[cur]) {
                T d = dfs(e.to, t, min(f, e.cap));
                if (d == 0) continue;
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }

    T max_flow(int s, int t) {
        T flow = 0, d;
        while (true) {
            bfs(s);
            if(level[t] < 0) break;
            fill(iter.begin(), iter.end(), 0);
            while ((d = dfs(s, t, INF)) > 0) {
                flow += d;
            }
        }
        return flow;
    }

};

int main() {

    ll N; cin >> N;
    vector < ll > a(N + 1);
    REP(i,N) cin >> a[i + 1];

    Dinic < ll > inst(1000);
    const int S = 900;
    const int T = 950;

    ll sum = 0;
    for (int i = 1; i <= N; i++) {
        if (a[i] >= 0) {
            sum += a[i];
            inst.add_edge(T, i, 0);
            inst.add_edge(i, T, a[i]);
        } else {
            inst.add_edge(S, i, -a[i]);
            inst.add_edge(i, T, 0);
        }
    }

    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            if (j % i == 0 && a[i] < 0) {
                inst.add_edge(i, j, 1000000000000);
            }
        }
    }

    ll f = inst.max_flow(S, T);
    cout << sum - f << endl;

    return 0;
}

#include <bits/stdc++.h>
using i64 = long long;

class Dinic {
    using i64 = long long;
    struct Edge {
        int to;
        i64 cap;
        int rev;
        Edge(int t, i64 c, int r) : to(t), cap(c), rev(r) {}
    };

    static constexpr i64 inf = 1000000000000000;
    std::vector<std::deque<Edge>> g;
    std::vector<int> level;
    std::vector<unsigned> iter;
    int size;

    void bfs(int s) {
        for (int i = 0; i < size; i++) level[i] = -1;
        level[s] = 0;

        std::deque<int> q { s };

        while (!q.empty()) {
            auto curr = q.front();
            q.pop_front();
            for (auto & e : g[curr]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[curr] + 1;
                    q.push_back(e.to);
                }
            }
        }
    }

    i64 dfs(int v, int t, i64 f) {
        if (v == t) return f;

        for (unsigned i = 0; i < g[v].size(); i++) {
            iter[v] = i;
            auto &e = g[v][i];

            if (e.cap > 0 && level[v] < level[e.to]) {
                i64 d = dfs(e.to, t, std::min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }

        return 0;
    }

public:
    explicit Dinic(int s) :
        g(s),
        level(s),
        iter(s),
        size(s) {}

    void add_edge(int from, int to, i64 cap) {
        g[from].emplace_back(to, cap, g[to].size());
        g[to].emplace_back(from, 0, g[from].size() - 1);
    }

    i64 calc(int s, int t) {
        i64 flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;

            for (auto &el : iter) el = 0;

            i64 f = dfs(s, t, inf);
            while (f > 0) {
                flow += f;
                f = dfs(s, t, inf);
            }
        }
    }
};

int main() {
    int n;
    std::cin >> n;
    int s = n, t = s + 1;
    const i64 inf = std::numeric_limits<i64>::max() / 200;
    Dinic d(n + 2);
    i64 total = 0;
    for (int i = 1; i <= n; i++) {
        i64 in;
        std::cin >> in;
        if (in >= 0) {
            total += in;
            d.add_edge(i - 1, t, in);
        } else {
            d.add_edge(s, i - 1, -in);
        }

        for (int j = 2; j * i <= n; j++) {
            d.add_edge(i - 1, j * i - 1, inf);
        }
    }

    std::cout << total - d.calc(s, t) << std::endl;

    return 0;
}

