long long maxflow(vector<vector<int>> E_, vector<vector<long long>> F_, int s, int t)
{
    int n = (int)E_.size();

    vector<vector<int>> E(n), R(n);
    vector<vector<long long>> F(n);
    for (int i=0; i<n; i++)
    for (int j=0; j<(int)E_[i].size(); j++)
    {
        int v = E_[i][j];
        R[i].push_back(int(E[v].size()));
        R[v].push_back(int(E[i].size()));
        E[i].push_back(v);
        E[v].push_back(i);
        F[i].push_back(F_[i][j]);
        F[v].push_back(0);
    }
    vector<bool> U(n);
    function<long long (int, long long)> dfs = [&](int p, long long f)
    {
        if (p==t)
            return f;
        U[p] = true;
        for (int i=0; i<(int)E[p].size(); i++)
        if (!U[E[p][i]] && F[p][i]>0)
        {
            long long t = dfs(E[p][i], min(f, F[p][i]));
            if (t>0)
            {
                F[p][i] -= t;
                F[E[p][i]][R[p][i]] += t;
                return t;
            }
        }
        return 0LL;
    };

    long long flow = 0;
    while (true)
    {
        for (int i=0; i<n; i++)
            U[i] = false;
        long long f = dfs(s, 1000000000000000LL);
        if (f==0)
            break;
        flow += f;
    }

    return flow;
}

