		return 0;
	}

	bool bfs(int lim) {
		for (int i = 0; i < n; i++) {
			d[i] = INF;
		}
		d[start] = 0;
		queue<int> q;
		q.push(start);
		while (!q.empty()) {
			int u = q.front();
			q.pop();
			for (auto ind : g[u]) {
				int to = ed[ind].v;
				if (d[to] > d[u] + 1 && ed[ind].flow + lim <= ed[ind].cap) {
					d[to] = d[u] + 1;
					q.push(to);
				}
			}
		}
		return d[end] < INF;
	}

	void init(int n_, int start_, int end_) {
		n = n_;
		start = start_;
		end = end_;
		d.resize(n);
		pnt.resize(n);
		g.resize(n);
	}

	void add_edge(int u, int v, int c) {
		int p = (int)ed.size();
		ed.push_back(Edge(u, v, c, 0));
		ed.push_back(Edge(v, u, 0, 0));
		g[u].push_back(p);
		g[v].push_back(p + 1);
	}

	int solve() {
		int ans = 0;
		for (int i = MAX_LOG; i >= 0; i--) {
			while (bfs(1LL << i)) {
				fill(pnt.begin(), pnt.end(), 0);
				while (true) {
					int nw = dfs(start, INF);
					if (nw > 0) {
						ans += nw;
					} else {
						break;
					}
				}
			}
		}
		return ans;
	}
}


