					kelipatan[now]=true;
					daftar.pb(arr[now]);
				}
				else
					daftar.pb(0);
				now+=i+1;
			}
			temp+=bestmodel(daftar);
		}
		tambahmaks=max(temp,tambahmaks);
	}
}
