int solve(int N, vector<int> a) {
	REP(i, N / 2, N - 1) a[i] = max(0LL, a[i]);

	REP(i, 2, N / 2) {
		int sum = 0;
		for (int j = i; j <= N; j += i) {
			sum += a[j - 1];
		}
		if (sum < 0) {
			for (int j = i; j <= N; j += i) {
				a[j - 1] = 0;
			}
		}
	}

	REP(i, 2, N / 2) {
		REP(j, i + 1, N / 2) {
			if (j % i == 0) continue;
			int sum = 0;
			for (int k = i; k <= N; k += i) {
				sum += a[k - 1];
			}
			for (int k = j; k <= N; k += j) {
				if (k % i == 0) continue;
				sum += a[k - 1];
			}
			if (sum < 0) {
				for (int k = i; k <= N; k += i) {
					a[k - 1] = 0;
				}
				for (int k = j; k <= N; k += j) {
					a[k - 1] = 0;
				}
			}
		}
	}

	REP(i, 2, N / 2) {
		REP(j, i + 1, N / 2) {
			if (j % i == 0) continue;
			REP(k, j + 1, N / 2) {
				if (k % j == 0) continue;
				if (k % i == 0) continue;
				int sum = 0;
				for (int x = i; x <= N; x += i) {
					sum += a[x - 1];
				}
				for (int x = j; x <= N; x += j) {
					if (x % i == 0) continue;
					sum += a[x - 1];
				}
				for (int x = k; x <= N; x += k) {
					if (x % i == 0) continue;
					if (x % j == 0) continue;
					sum += a[x - 1];
				}
				if (sum < 0) {
					for (int x = i; x <= N; x += i) {
						a[x - 1] = 0;
					}
					for (int x = j; x <= N; x += j) {
						a[x - 1] = 0;
					}
					for (int x = k; x <= N; x += k) {
						a[x - 1] = 0;
					}
				}
			}
		}
	}

	int ret = 0;
	rep(i, N) ret += a[i];
	ret = max(0LL, ret);

	return ret;
}

