const int maxnodes = 505;

long long int nodes = maxnodes, src, dest;
long long int dist[maxnodes], q[maxnodes], work[maxnodes];

struct Edge {
  int to, rev;
  long long int f, cap;
};

vector<Edge> g[maxnodes];


//	biderectional edges.
void addEdgeUndirected(int s, int t, long long int cap){
  Edge a = {t, g[t].size(), 0ll, cap};
  Edge b = {s, g[s].size(), 0ll, cap};
  g[s].push_back(a);
  g[t].push_back(b);
}

//	unidirectional edges.
void addEdgeDirected(int s, int t,long long int cap){
  Edge a = {t, g[t].size(), 0ll, cap};
  Edge b = {s, g[s].size(), cap, cap};
  g[s].push_back(a);
  g[t].push_back(b);
}

bool dinic_bfs() {
  //fill(dist, dist + nodes, -1);
  for(int i=0;i<nodes;i++)	dist[i] = -1;
  dist[src] = 0;
  int qt = 0;
  q[qt++] = src;
  for (int qh = 0; qh < qt; qh++) {
    int u = q[qh];
    for (int j = 0; j < (int) g[u].size(); j++) {
      Edge &e = g[u][j];
      int v = e.to;
      if (dist[v] < 0 && e.f < e.cap) {
        dist[v] = dist[u] + 1;
        q[qt++] = v;
      }
    }
  }
  return dist[dest] >= 0;
}

long long dinic_dfs(int u,long long int f) {
  if (u == dest)
    return f;
  for (ll &i = work[u]; i < (int) g[u].size(); i++) {
    Edge &e = g[u][i];
    if (e.cap <= e.f) continue;
    int v = e.to;
    if (dist[v] == dist[u] + 1) {
      int df = dinic_dfs(v, min(f, e.cap - e.f));
      if (df > 0) {
        e.f += df;
        g[v][e.rev].f -= df;
        return df;
      }
    }
  }
  return 0ll;
}

long long maxFlow(int _src, int _dest) {
  src = _src;
  dest = _dest;
  long long int result = 0;
  while (dinic_bfs()) {
    for(int i=0;i<nodes;i++){
    	work[i] = 0;
    }
    //fill(work, work + nodes, 0);
    while (int delta = dinic_dfs(src, INT_MAX))
      result += delta;
  }
  return result;
}

