ll go(int v) {
  if (v * 3 > n) {
    ll res = 0;
    FOR(i, v, n) {
      if (i >= v + v && i % 2 == 0) continue;
      if (i + i > n) {
        if (!cnt[i]) res += max(0, a[i]);
        continue;
      }
      if (!cnt[i]) {
        if (cnt[i + i]) res += max(0, a[i]);
        else res += max(0, max(a[i], a[i] + a[i + i]));
      }
    }
    return res;
  }
  if (cnt[v]) return go(v + 1);
  ll res = a[v] + go(v + 1);
  for (int i = v; i <= n; i += v)cnt[i]++;
  Max(res, go(v + 1));
  for (int i = v; i <= n; i += v)cnt[i]--;
  return res;
}

