template<class T> struct PrimalDual {

    struct Edge {
        int to, rev;
        T cap, cost;
        Edge () {}
        Edge (int _to, T _cap, T _cost, int _rev) :
        to(_to), cap(_cap), cost(_cost), rev(_rev) {}
    };

    const T INF = numeric_limits<T>::max() / 2;
    int N;
    vector< vector< Edge > > G;
    vector< T > h;
    vector< T > dist;
    vector< int > prevv, preve;
    PrimalDual (int n) : N(n), G(n), h(n), dist(n), prevv(n), preve(n) {}

    void add_edge(int from, int to, T cap, T cost) {
        G[from].push_back(Edge(to,cap,cost,(T)G[to].size()));
        G[to].push_back(Edge(from,0,-cost,(T)G[from].size()-1));
    }

    T get_min(int s, int t, T f) {
        T ret = 0;
        fill(h.begin(),h.end(),0);
        while (f > 0) {
            priority_queue< pair<T,int>, vector< pair<T,int> >, greater< pair<T,int> > > que;
            for (int i = 0; i < N; i++) dist[i] = INF;
            dist[s] = 0;
            que.push(make_pair(0,s));
            while (que.size() != 0) {
                pair< T, int > p = que.top();
                que.pop();
                int v = p.second;
                if (dist[v] < p.first) continue;
                for (int i = 0; i < G[v].size(); i++) {
                    Edge &e = G[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push(make_pair(dist[e.to], e.to));
                    }
                }
            }
            if (dist[t] == INF) {
                return -1;
            }
            for (int v = 0; v < N; v++) h[v] += dist[v];
            T d = f;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d,G[prevv[v]][preve[v]].cap);
            }
            f -= d;
            ret += d * h[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = G[prevv[v]][preve[v]];
                e.cap -= d;
                G[v][e.rev].cap += d;
            }
        }
        return ret;
    }

};

struct PrimeNumbers {

    vector<bool> sieve;
    vector<long long> prime;

    PrimeNumbers (int n) : sieve(n+1,true) {
        sieve[0] = sieve[1] = false;
        for (long long i = 2; i < sieve.size(); i++) {
            if (sieve[i]) {
                prime.push_back(i);
                for (long long j = i * i; j < sieve.size(); j += i) {
                    sieve[j] = false;
                }
            }
        }
    }

    bool isPrime(long long n) {
        return sieve[n];
    }

    int size(void) {
        return (int) prime.size();
    }

    long long  operator [] (int n) {
        return  prime[n];
    }

};

