{
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll n;
	cin >> n;

	ll a[n];
	rep(i,n) cin >> a[i];

	ll s = n;
	ll t = n + 1;

	ll sum = 0;
	rep(i,n) sum += max(0LL,a[i]);

	rep(i,n){
		if(a[i] <= 0) add_edge(s,i,abs(a[i]));
		else add_edge(i,t,abs(a[i]));
	}

	rep(i,n){
		for(ll j = 2*(i+1); j <= n; j+=i+1){
			ll b = j-1;
			add_edge(i,b,INF);
		} 
	}

	cout << (sum - max_flow(s,t)) << endl;

}

