		{
			dis[to[i]]=dis[x]+1;
			q[r++]=to[i];
		}
	}
	if(dis[T]==-1)return 0;
	else return 1;
}
inline ll dfs(int x,ll y)
{
	if(x==T || !y){return y;}ll lft=y,t=y;
	Rep(i,x)
	{
		int j=to[i];if(!lft)break;
		if(dis[j]==dis[x]+1 && cap[i])
		{
			ll xjt=dfs(j,min(lft,cap[i]));
			if(xjt){lft-=xjt;cap[i]-=xjt;cap[i^1]+=xjt;}
		}
	}
	return t-lft;
}
