template<class T> struct flow {
  struct edge {
    int to;
    T cap;
    int rev;
  };

  int n;
  vector<vector<edge>> g;
  vector<bool> used;

  flow(int n) : n(n) {
    g = vector<vector<edge>>(n);
  }

  void add(int from, int to, T cap) {
    g[from].push_back({ to, cap, (int) g[to].size() });
    g[to].push_back({ from, 0, (int) g[from].size() - 1 });
  }

  T dfs(int v, int t, T f) {
    if (v == t) {
      return f;
    }
    used[v] = true;
    for (auto &e : g[v]) {
      if (used[e.to] || e.cap <= 0) {
        continue;
      }
      T d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }

  T max_flow(int s, int t) {
    T flow = 0;
    while (true) {
      used = vector<bool>(n);
      T f = dfs(s, t, numeric_limits<T>::max());
      if (f == 0) {
        break;
      }
      flow += f;
    }
    return flow;
  }
};

