        return d;
      }
    }
  }
  return 0;
}

ll Ford_Fulkerson(ll s,ll t){
  ll flow = 0;
  while(1){
    memset(used,0,sizeof(used));
    ll f = dfs(s,t,INF);
    if(f == 0) return flow; //max flow
    flow += f;
  }
}

