ll unit(int n)
{
    if(n == N + 1)return 0;
    if(n * 2 > N)
    {
        ll res = 0;
        for(int i = n; i <= N; i++)if(!mem[i] && A[i] > 0)res += A[i];
        return res;
    }
    if(mem[n] == 1)return unit(n + 1);

    ll res = unit(n + 1) + A[n];
    for(int i = n; i <= N; i += n)mem[i]++;
    res = max(res,unit(n + 1));
    for(int i = n; i <= N; i += n)mem[i]--;
    return res;
