using namespace std;
typedef long long LL;
const LL N = 105,M = 20005;
const LL INF = 0x3f3f3f3f3f3f3f3f;

LL ec = 1,hed[N],cur[N],cap[M],nxt[M],to[M];
void add_edge(LL f,LL t,LL c){
	++ ec; to[ec] = t; nxt[ec] = hed[f]; hed[f] = ec; cap[ec] = c;
	++ ec; to[ec] = f; nxt[ec] = hed[t]; hed[t] = ec; cap[ec] = 0;
}

LL lev[N];
queue <LL> q;
void bfs(LL s){
	memset(lev,0,sizeof(lev));
	while(!q.empty()) q.pop();
	q.push(s); lev[s] = 1; 
	while(!q.empty()){
		LL u = q.front(); q.pop();
		for(LL i = hed[u];i;i = nxt[i]){
			LL v = to[i];
			if(lev[v] || !cap[i]) continue;
			lev[v] = lev[u] + 1;
			q.push(v);
		}
	}
}

LL dfs(LL u,LL t,LL f){
	if(u == t) return f;
	for(LL i = cur[u];i;i = nxt[i]){
		cur[u] = i;
		LL v = to[i];
		if(lev[v] == lev[u] + 1 && cap[i]){
			LL tmp = dfs(v,t,min(cap[i],f));
			if(tmp){
				cap[i] -= tmp;
				cap[i ^ 1] += tmp;
				return tmp;
			}
		}
	}
	return 0;
}

LL mxf = 0;
void dinic(LL s,LL t){
	LL f = 0;
	while(1){
		bfs(s);
		if(!lev[t]) return;
		for(LL i = 1;i <= t;i ++) cur[i] = hed[i];
		while(1){
			f = dfs(s,t,INF);
			mxf += f;
			if(!f) break;
		}	
	}
}

int main(){
	LL n,S,T,a,sum = 0;
	cin >> n; S = n + 1; T = S + 1;
	for(LL i = 1;i <= n;i ++){
		cin >> a; sum += max(0LL,a);
		if(a > 0) add_edge(i,T,a);
		if(a < 0) add_edge(S,i,-a);
	}
	for(LL i = 1;i <= n;i ++){
		for(LL j = i + 1;j <= n;j ++){
			if(j % i == 0) add_edge(i,j,INF);
		}
	}
	dinic(S,T);
	cout << sum - mxf << '\n';
	return 0;
}

