//------------------------------------------head---------------------------------------------------//
int head[N],nxt[N],to[N],e;
ll cap[N];
int S,T;
inline void init(){memset(head,-1,sizeof(head));}
inline void add_edge(int x,int y,ll c)
{
	to[e]=y;nxt[e]=head[x];cap[e]=c;head[x]=e++;
	to[e]=x;nxt[e]=head[y];cap[e]=0;head[y]=e++;
}
int q[N],h,r,dis[N];
int bfs()
{
	h=r=0;q[r++]=S;rep(i,1,T)dis[i]=-1;dis[S]=1;
	while(h!=r)
	{
		int x=q[h++];
		Rep(i,x)if(dis[to[i]]==-1 && cap[i])
		{
			dis[to[i]]=dis[x]+1;
			q[r++]=to[i];
		}
	}
	if(dis[T]==-1)return 0;
	else return 1;
}
inline int dfs(int x,ll y)
{
	if(x==T || !y){return y;}ll lft=y,t=y;
	Rep(i,x)
	{
		int j=to[i];if(!lft)break;
		if(dis[j]==dis[x]+1 && cap[i])
		{
			int xjt=dfs(j,min(lft,cap[i]));
			if(xjt){lft-=xjt;cap[i]-=xjt;cap[i^1]+=xjt;}
		}
	}
	return t-lft;
}
inline ll dinic()
{
	ll ans=0;
	while(bfs())
	{
		ll TT=dfs(S,inf); 
		while(TT){ans+=TT;TT=dfs(S,inf);}
	}return ans;
}
