lli iter[MAX_V];
void add_edge(lli from, lli to, lli cap)
{
    G[from].push_back(edge(to, cap, G[to].size()));
    G[to].push_back(edge(from, 0, G[from].size() - 1));
}
lli gcd(lli a, lli b)
{
    return b > a ? gcd(b, a) : (b == 0 ? a : gcd(b, a % b));
}
void bfs(lli s)
{
    //memset(level, -1, sizeof(level));
    rep(i, MAX_V) level[i] = -1;
    queue<lli> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        lli v = que.front();
        que.pop();
        for (lli i = 0; i < G[v].size(); i++) {
            edge& e = G[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}
lli dfs(lli v, lli t, lli f)
{
    if (v == t)
        return f;
    for (lli& i = iter[v]; i < G[v].size(); i++) {
        edge& e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            lli d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
lli max_flow(lli s, lli t)
{
    lli flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0)
            return flow;
        //memset(iter, 0, sizeof(iter));
        rep(i, MAX_V) iter[i] = 0;
        lli f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}
