long greedy(const vector<long> &v){
  int n = v.size();
  long ret = 0;
  rep(mask, 1<<n){
    vector<bool> use(n+1, true);
    rep(i,n) if((mask>>i)%2==1){
      // i:0-indexed, j:1-indexed
      int j = i+1;
      for(int x=j; x<=n; x+=j){
        use[x] = false;
      }
    }
    long tmp = 0;
    rep(i,n) if(use[i+1]) tmp += v[i];
    ret = max(ret, tmp);
  }
  return ret;
}

