class dinic {
private:
	struct edge {
		int to; long long cap; int rev;
		edge(int t_, long long c_, int r_) :to(t_), cap(c_), rev(r_) {}
	};
	vector<vector<edge> >G; vector<int>level, iter;
	//sourceからBFSをする
	void bfs(int s_) {
		fill(level.begin(), level.end(), -1);
		std::queue<int>que;
		level[s_] = 0;
		que.push(s_);
		while (!que.empty()) {
			int v = que.front(); que.pop();
			for (int i = 0; i < G[v].size(); ++i) {
				edge &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					que.push(e.to);
				}
			}
		}
	}
	//DFSで増加パスを見つけて、流す。
	long long dfs(int v_, int t_, long long f_) {
		if (v_ == t_)return f_;
		for (int &i = iter[v_]; i < G[v_].size(); ++i) {
			edge &e = G[v_][i];
			if (e.cap > 0 && level[v_] < level[e.to]) {
				long long d = dfs(e.to, t_, min(f_, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
public:
	dinic(int vec_) :G(vec_), level(vec_), iter(vec_) {}
	//fromからtoへ容量capの辺を張る
	void add_edge(int from_, int to_, long long cap_) {
		G[from_].push_back(edge(to_, cap_, G[to_].size()));
		G[to_].push_back(edge(from_, 0ll, G[from_].size() - 1));
	}
	//Dinic法で、頂点source→sinkの最大流量を計算する 最悪計算量O(V^2*E)
	long long max_flow(int source_, int sink_) {
		int flow = 0;
		for (;;) {
			bfs(source_);
			if (level[sink_] < 0)return flow;
			fill(iter.begin(), iter.end(), 0);
			for (;;) {
				long long f = dfs(source_, sink_, LLONG_MAX);
				if (f > 0)flow += f;
				else break;
			}
		}
		return flow;
	}
};

const LL INF = 1145148101919893;

int main(void)
{
	int N;
	vector<LL>a;
	cin >> N;
	LL ans = 0;
	for (int i = 0; i < N; ++i) {
		LL aa; cin >> aa; aa = -aa; a.push_back(aa);
		ans += max(0LL, -aa);
	}
	dinic D(N + 2);
	for (int i = 0; i < N; ++i) {
		if (a[i] >= 0) {
			D.add_edge(0, i + 1, a[i]);
			D.add_edge(i + 1, N + 1, 0);
		}
		else {
			D.add_edge(0, i + 1, 0);
			D.add_edge(i + 1, N + 1, -a[i]);
		}
	}
	for (int i = 1; i <= N; ++i) {
		for (int j = 1; j < i; ++j) {
			if (i % j == 0) {
				D.add_edge(i, j, INF);
			}
		}
	}
	cout << ans - D.max_flow(0, N + 1);
	return 0;
}

#include <cstdio>
