// v:now , t:sink , c:capacity
ll dfs( int v, int t, ll c){
    if( v==t ) return c;
    used[v] = true;
    // Ford-Fulkerson algorithm
    for( int ei = 0; ei < e[v].size(); ei++ ){
        edge &ez = e[v][ei];
        if( !used[ez.v] && ez.c > 0){
            ll d = dfs( ez.v,t,min(c,ez.c));
            if( d>0 ){
                ez.c -= d;
                e[ez.v][ez.r].c += d;
                return d;
            }
        }
    }
    return 0;
}

ll ans( int s , int t ){
