constexpr lint mod = 1e9+7;
constexpr lint INF = 1e15;
constexpr int MAX = 110;

struct edge{
    int to, rev;
    lint cap;
    edge(int to, lint cap, int rev): to(to), cap(cap), rev(rev){}
};

vector<edge> G[MAX];
int level[MAX], iter[MAX];

void add_edge(int from, int to, lint cap){
    G[from].emplace_back(to, cap, G[to].size());
    G[to].emplace_back(from, 0, G[from].size() - 1);
}

void dinic_bfs(int s){
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while(!que.empty()){
        int v = que.front(); que.pop();
        for(auto &e: G[v]){
            if(e.cap > 0 && level[e.to] < 0){
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

lint dinic_dfs(int v, int t, lint f){
    if(v == t) return f;
    for(int &i=iter[v]; i<G[v].size(); ++i){
        edge &e = G[v][i];
        if(e.cap > 0 && level[v] < level[e.to]){
            lint d = dinic_dfs(e.to, t, min(f, e.cap));
            if(d > 0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

lint max_flow(int s, int t){
    lint flow = 0;
    while(true){
        dinic_bfs(s);
        if(level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        lint f;
        while((f = dinic_dfs(s, t, INF)) > 0) flow += f;
    }
}

int main(){
    int n;
    scanf("%d", &n);
    lint a[n+1];
    For(i, 1, n+1) scanf("%lld", &a[i]);
    int s = 0, t = n+1;
    lint ans = 0;
    For(i, 1, n+1){
        if(a[i] >= 0) add_edge(s, i, a[i]);
        else add_edge(i, t, -a[i]);
        for(int j=2; i*j<=n; ++j) add_edge(i*j, i, INF);
        if(a[i] > 0) ans += a[i];
    }
    ans -= max_flow(s, t);
    printf("%lld\n", ans);
}

