const int inf = 0x3f3f3f3f;
const int maxn = 1e3 + 5;
int n, sp, tp, ans;

namespace dinic{
  int cur[maxn], dis[maxn];

  struct edge{ int v, f, nxt; }; vector <edge> e; int head[maxn];

  void adde(int u, int v, int f){
	e.push_back((edge){v, f, head[u]}); head[u] = e.size() - 1;
	e.push_back((edge){u, 0, head[v]}); head[v] = e.size() - 1;
  }

  bool bfs(){
	memset(dis, -1, sizeof(dis)); dis[sp] = 0;
	queue <int> q; q.push(sp);
	while(!q.empty()){
	  int u = q.front(); q.pop();
	  for(int i = head[u]; ~i; i = e[i].nxt){
		int v = e[i].v;
		if(dis[v] == -1 && e[i].f){
		  dis[v] = dis[u] + 1;
		  q.push(v);
		}
	  }
	}
	return dis[tp] != -1;
  }

  int dfs(int u, int minv){
	if(u == tp || minv == 0) return minv;
	int used = 0;
	for(int &i = cur[u]; ~i; i = e[i].nxt){
	  int v = e[i].v;
	  if(dis[v] == dis[u] + 1 && e[i].f){
		int f = dfs(v, min(e[i].f, minv));
		e[i].f -= f; e[i ^ 1].f += f;
		used += f; minv -= f;
		if(!minv) return used;
	  }
	}
	if(!used) dis[u] = -1;
	return used;
  }

  void extend(){
	while(bfs()){
	  rep(i, sp, tp) cur[i] = head[i];
	  ans += dfs(sp, inf);
	}
  }

  void init(){
	memset(head, -1, sizeof(head));
  }
}

int main(){
