  rd(n);
  sp = 0;
  tp = n + 1;
  rep(i, 1, n){
	int x; rd(x);
	ans += x;
	if(x > 0) dinic :: adde(i, tp, x);
	else if(x < 0) dinic :: adde(sp, i, -x);
  }
  rep(i, 1, n){
	rep(j, 2, n / i){
	  dinic :: adde(i, i * j, inf);
	}
  }
  dinic :: extend();
  printf("%d\n", ans);
  return 0;
}

