inline bool bfs(){
	memset(f,-1,sizeof(f));
	int h=0,r=1;q[1]=s;f[s]=1;
	while (h<r){
		int now=q[++h];if (now==t) return 1;
		for (int i=END[now];i;i=a[i].next){
			int go=a[i].go;
			if (f[go]==-1&&a[i].s){
				f[go]=f[now]+1;
				q[++r]=go;
			}
		}
	}return 0;
}
long long dinic(int sta,long long sum){
	if (sta==t) return sum;long long os=sum;
	for (int i=END[sta];i&&os;i=a[i].next){
		int go=a[i].go;
		if (f[go]==f[sta]+1&&a[i].s){
			int minv=dinic(go,min(os,a[i].s));
			a[i].s-=minv;a[i^1].s+=minv;os-=minv;
		}
	}if (os==sum) f[sta]=-1;return sum-os;
}
