void rem(int p){
	int x = p;
	while(p <= n){
		w[p] += 1;
		p += x;
	}
}

void upd(int p){
	int x = p;
	while(p <= n){
		w[p] -= 1;
		if(w[p] == 0){
			sp += max(0, a[p]);
			sn += min(0, a[p]);
		}
		p += x;
	}
}

void mark(int p){
	int x = p;
	while(p <= n){
		w[p] += 1;
		if(w[p] == 1){
			sp -= max(0, a[p]);
			sn -= min(0, a[p]);
		}
		p += x;
	}
}

void rec(int p){
	//cerr << p << " " << ans << endl;
	if(p == n+1) return;
	if(w[p]){
		rec(p+1);
