ll solve(int N, vector<ll>& a) {
    for (int i=N; i>=1; --i) {
        if (a[i] > 0) continue;
        ll s = 0;
        int las = -1;
        for (int j=i; j<=N; j+=i) {
            s += a[j];
            las = j;
        }
        for (int j=i; j<=N; j+=i) {
            a[j] = 0;
        }
        if (s > 0) a[las] = s;
    }

    ll ans = 0;
    rep1(i, N) ans += a[i];
    return ans;
}

