					flag[j] = 0;
				}
			}
		}
	}
	for(int i=n;i>=1;i--){
		ll min = INF;
		vector<ll> div;
		divisor(i, div);
		int num;
		for (auto itr : div) {
			ll temp = 0;
			for (int j = 1; j <= n; j++) {
				if (flag[j] == 1 && j%itr == 0) {
					temp += a[j - 1];
				}
			}
			if (chmin(min, temp)) {
				num = itr;
			}
		}
		if (min < 0) {
			for (int j = 1; j <= n; j++) {
				if ( j%num == 0) {
					flag[j] = 0;
				}
			}
		}
	}
	ll ans = 0;
	for (int i = 1; i <= n; i++) {
		if (flag[i] == 1) {
			ans += a[i - 1];
		}
	}
	cout << ans;
	return 0;
}

