struct edge {
    ll to, cap, rev;
};

int V;
vector<edge> G[1000000];
ll level[1000000];
int iter[1000000];

void addedge(int from, int to, ll cap) {
    G[from].push_back((edge){to, cap, (ll)G[to].size()});
    G[to].push_back((edge){from, 0, (ll)G[from].size() - 1});
}

void dinicbfs(int s) {
    fill(level, level + V, -1);
    queue<ll> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        ll v = que.front();
        que.pop();
        for (int i = 0; i < (int)G[v].size(); i++) {
            edge e = G[v][i];
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

ll dinicdfs(ll v, ll t, ll f) {
    if (v == t) {
        return f;
    }
    for (int &i = iter[v]; i < (int)G[v].size(); i++) {
        edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            ll d = dinicdfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll dinic(int s, int t) {
    ll flow = 0;
    while (1) {
        dinicbfs(s);
        if (level[t] < 0) {
            return flow;
        }
        fill(iter, iter + V, 0);
        ll f;
        while ((f = dinicdfs(s, t, inf)) > 0) {
            flow += f;
        }
    }
}

