        } else {
            addedge(i, N + 1, a[i]);
            sum += a[i];
        }
        for (int j = 2 * i; j <= N; j += i) {
            addedge(i, j, inf);
        }
    }
    ll tmp = dinic(0, N + 1);
    cout << sum - tmp << endl;
}

