void bt(int u){
	if(u == s) return;

	f = min(f, res[par[u]][u]);
	bt(par[u]);

	res[par[u]][u] -= f;
	res[u][par[u]] += f;
}

void maxflow(){
	while(true){
		vis = 0;
		memset(par, -1, sizeof(par));

		q.push(s); vis[s] = true;

		while(!q.empty()){
			int u = q.front(); q.pop();

			for(auto &v : adj[u]){
				if(!vis[v] && res[u][v] > 0)
					q.push(v), vis[v] = true, par[v] = u;
			}
		}

		f = INF;
		if(par[t] == -1) break;
		bt(t);

		mf += f;
	}
}

