template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vector(istream& in, size_t n) {
    vector<T> ret(n);
    for (size_t i = 0; i < n; ++i) {
        ret[i] = next<T>(in);
    }
    return ret;
}


vector<int> a;

void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  a = next_vector<int>(in, n);
  vector<int> u(n + 1, 0);
  bool ok = false;
  while (!ok) {
    ok = true;
    for (int i = n; i >= 1; --i) {
      if (u[i]) {
        continue;
      }
      if (a[i-1] < 0) {
        int64_t sum = 0;
        for (int j = i; j <= n; j += i) {
          if (!u[j]) {
            sum += a[j - 1];
          }
        }
        if (sum <= 0) {
          ok = false;
          for (int j = i; j <= n; j += i) {
            u[j] = 1;
          }
        }
      }
    }
  }

  int64_t sum = 0;
  for (int j = 1; j <= n; j++) {
    if (!u[j]) {
      sum += a[j - 1];
    }
  }
  out << sum << "\n";

}


