	static const int N = 1230;
	vector<node>edges;//边表，dges[e]和dges[e^1]互为反向弧
	vector<int>G[N];//邻接表，G[i][j]表示结点i的第j条边在e数组中的编号
	bool vis[N]; //BFS的使用
	int d[N]; //从起点到i的距离
	int cur[N]; //当前弧下标
	void init()
	{
		edges.clear();
		for (int i = 0; i<N; i++)
		{
			G[i].clear();
			vis[N] = false;
			d[i] = 0;
			cur[i] = 0;
		}
	}
	void addedge(int from, int to, long long  cap)
	{
		edges.push_back(node(from, to, cap, 0));
		edges.push_back(node(to, from, 0, 0));
		int  m = edges.size();
		G[from].push_back(m - 2);
		G[to].push_back(m - 1);
	}
