	{
		memset(vis, 0, sizeof(vis));
		queue<int>Q;
		Q.push(s);
		d[s] = 0;
		vis[s] = 1;
		while (!Q.empty())
		{
			int x = Q.front(); Q.pop();
			for (int i = 0; i<G[x].size(); i++)
			{
				node&e = edges[G[x][i]];
				if (!vis[e.to] && e.cap>e.flow)//只考虑残量网络中的弧
				{
					vis[e.to] = 1;
					d[e.to] = d[x] + 1;
					Q.push(e.to);
				}
			}
		}
		return vis[t];
	}
	long long  dfs(int x, long long  a)//x表示当前结点，a表示目前为止的最小残量
	{
		if (x == t || a == 0)return a;//a等于0时及时退出，此时相当于断路了
		long long  flow = 0, f;
		for (int&i = cur[x]; i<G[x].size(); i++)//从上次考虑的弧开始，注意要使用引用，同时修改cur[x]
		{
			node&e = edges[G[x][i]];//e是一条边
			if (d[x] + 1 == d[e.to] && (f = dfs(e.to, min(a, e.cap - e.flow)))>0)
			{
				e.flow += f;
				edges[G[x][i] ^ 1].flow -= f;
				flow += f;
				a -= f;
				if (!a)break;//a等于0及时退出，当a!=0,说明当前节点还存在另一个曾广路分支。

			}
		}
		return flow;
	}
	int Maxflow(int s, int t)//主过程
	{
		this->s = s, this->t = t;
