        Edge(int a, long long b, int c) : to(a), cap(b), rev(c) {}
    };

    vector<Edge> g[kN];
    int lev[kN], qu[kN], ql, qr;

    void AddEdge(int a, int b, long long c) {
        g[a].emplace_back(b, c, g[b].size() - 0);
        g[b].emplace_back(a, 0, g[a].size() - 1);
    }

    bool Bfs(int s, int t) {
        memset(lev, -1, sizeof(lev));
        ql = qr = 0;
        lev[qu[qr++] = s] = 0;
        while (ql < qr) {
            int x = qu[ql++];
            for (Edge &e : g[x]) {
                if (e.cap > 0 && lev[e.to] == -1) {
                    lev[e.to] = lev[x] + 1;
                    qu[qr++] = e.to;
                }
            }
        }
        return lev[t] != -1;
    }

    long long Dfs(int x, int t, long long flow) {
        if (x == t) return flow;
        long long res = 0;
        for (Edge &e : g[x]) {
            if (e.cap > 0 && lev[e.to] == lev[x] + 1) {
                long long fl = Dfs(e.to, t, min(flow - res, e.cap));
                e.cap -= fl;
                g[e.to][e.rev].cap += fl;
                res += fl;
            }
        }
        if (!res) lev[x] = -1;
        return res;
    }

    long long operator()(int s, int t) {
        long long res = 0;
        for (; Bfs(s, t); res += Dfs(s, t, 1e15));
        return res;
    }
