long long a[101]{};
bool is_minus[101]{}, is_broken[101]{};

void break_without_overhead(int);

int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= n; i++)
	{
		scanf("%lld", a + i);
		is_minus[i] = a[i] <= 0;
	}
	for (int i = n / 2 + 1; i <= n; i++)
		break_without_overhead(i);
	for (int i = n / 2; i >= 1; i--)
	{
		if (is_broken[i]) continue;
		long long sum{};
		for (int j = i; j <= n; j += i)
			if (!is_broken[j])
				sum += a[j];
		if (sum > 0) continue;
		for (int j = i; j <= n; j += i)
			is_broken[j] = true;
	}
	long long sum{};
	for (int i = 1; i <= n; i++)
		if (!is_broken[i])
			sum += a[i];

	printf("%lld\n", sum);
	return 0;
}

void break_without_overhead(int object)
{
	is_broken[object] = is_minus[object];
	if (is_minus[object] && !(object % 2))
		break_without_overhead(object / 2);
	return;
}

