// Dinic法
class Dinic {
private:
	struct Edge {
		int to, cap, rev;
		Edge(int t, int c, int r) :to(t), cap(c), rev(r) {}
	};
	int V;
	std::vector<std::vector<Edge>> graph;
	std::vector<int> level, iter;

public:
	Dinic(int v) : V(v) {
		graph.resize(v);
		level.resize(v, -1);
		iter.resize(v, 0);
	}
	// fromからtoへ向かう容量capの辺をグラフに追加する
	void addEdge(int from, int to, int cap) {
		graph[from].emplace_back(to, cap, graph[to].size());
		graph[to].emplace_back(from, 0, graph[from].size() - 1);
	}

	// sからの最短距離をBFSで計算する
	void bfs(int s) {
		std::fill(level.begin(), level.end(), -1);
		std::queue<int> queue;
		level[s] = 0;
		queue.push(s);
		while (!queue.empty()) {
			int v = queue.front(); queue.pop();
			for (int i = 0; i < graph[v].size(); ++i) {
				Edge& e = graph[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					queue.push(e.to);
				}
			}
		}
	}

	// 増加パスをDFSで探す
	int dfs(int v, int t, int f) {
		if (v == t) return f;
		for (int& i = iter[v]; i < graph[v].size(); ++i) {
			Edge& e = graph[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				int d = dfs(e.to, t, std::min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	// sからtへの最大流を求める
	int maxFlow(int s, int t) {
		int res = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) return res;
			std::fill(iter.begin(), iter.end(), 0);
			int f;
			while ((f = dfs(s, t, INFLL)) > 0) {
				res += f;
			}
		}
	}
};

signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	Dinic dn(n + 2);
	int S = n, T = n + 1;
	int ans = 0;
	REP(i, n) {
		if (a[i] >= 0) {
			dn.addEdge(S, i, a[i]);
			dn.addEdge(i, T, 0);
			ans += a[i];
		}
		else {
			dn.addEdge(S, i, 0);
			dn.addEdge(i, T, -a[i]);
		}
		int p = (i + 1) * 2;
		while (p <= n) {
			dn.addEdge(p - 1, i, INFLL);
			p += i + 1;
		}
	}
	ans -= dn.maxFlow(S, T);
	OUT(ans)BR;
	return 0;
}

