inline void link(int a,int b,int _w) {
	to[++tot]=b,nxt[tot]=head[a],head[a]=tot,w[tot]=_w;
	to[++tot]=a,nxt[tot]=head[b],head[b]=tot;
}
inline bool bfs() {
	int i,k,l,r;
	for (i=S;i<=T;i++) dep[i]=0;
	for (l=0,dep[q[r=1]=T]=1;l!=r;)
		for (i=head[k=q[++l]];i;i=nxt[i])
			if (w[i^1]&&!dep[to[i]])
				dep[q[++r]=to[i]]=dep[k]+1;
	return dep[S];
}
inline LL dfs(int k,LL low) {
	if (k==T) return low;
	LL s=0,x;
	for (int &i=cur[k];i;i=nxt[i])
		if (w[i]&&dep[to[i]]==dep[k]-1)
			if (x=dfs(to[i],min(low-s,(LL)w[i]))) {
				s+=x,w[i]-=x,w[i^1]+=x;
				if (s==low) return s;
			}
	return s;
}

