class max_flow { // Dinic O(E*V^2)
public:
	static const int MAX_V = 103;
	static const int INF = 2e9;
private:
	struct edge { int to, cap, rev; };
	vector<edge> edg[MAX_V];
	int level[MAX_V], iter[MAX_V];
public:
	void add_edge(int  from, int to, int cap) {
		edg[from].push_back({ to, cap, (int)edg[to].size() });
		edg[to].push_back({ from, 0, (int)edg[from].size() - 1 });
	}

	ll calc_max_flow(int s, int t) {
		ll flow = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) return flow;
			for (int i = 0; i < MAX_V; ++i) iter[i] = 0;
			int f;
			while ((f = dfs(s, t, INF)) > 0) {
				flow += (ll)f;
			}
		}
	}
private:
	void bfs(int s) {
		for (int i = 0; i < MAX_V; ++i) level[i] = -1;
		deque<int> que;
		level[s] = 0;
		que.push_back(s);
		while (!que.empty()) {
			int v = que.front(); que.pop_front();
			for (int i = 0; i < (int)edg[v].size(); ++i) {
				edge &e = edg[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					que.push_back(e.to);
				}
			}
		}
	}

	int dfs(int v, int t, int f) {
		if (v == t) return f;
		for (int &i = iter[v]; i < (int)edg[v].size(); ++i) {
			edge &e = edg[v][i];
			if (e.cap <= 0 || level[v] >= level[e.to]) continue;
			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				edg[e.to][e.rev].cap += d;
				return d;
			}
		}
		return 0;
	}
};

int main() {
	int n; cin >> n;
	ll sum = 0;
	max_flow mf;
	for (int i = 1; i <= n; ++i) {
		int a; cin >> a;
		if (a > 0) sum += (ll)a;
		if (a > 0) mf.add_edge(i, n + 1, a);
		else mf.add_edge(0, i, -a);
	}
	for (int i = 1; i <= n; ++i) {
		for (int j = i + i; j <= n; j += i) {
			mf.add_edge(i, j, mf.INF);
		} 
	}
	cout << sum - mf.calc_max_flow(0, n + 1) << endl;
	return 0;
}

