const int N = 105;
const int inf = 2e9;
struct Edge{
    int nextNode,cap,rid;
    Edge(int nextNode,int cap,int rid) : nextNode(nextNode), cap(cap),rid(rid) {
    }
};
vector<Edge> adj[N];

void insert(int u,int v,int cap) {
    adj[u].push_back(Edge(v,cap, (int)adj[v].size()));
    adj[v].push_back(Edge(u,0,(int)adj[u].size()-1));
}
int work[N],level[N];

bool bfs(int source,int sink) {
    queue<int> q;
    q.push(source);
    memset(level, -1, sizeof(level));
    level[source] = 0;
    while(!q.empty()) {
        int node = q.front();
        q.pop();
        for(int i=0;i<adj[node].size();++i) {
            if(adj[node][i].cap>0 && level[adj[node][i].nextNode]==-1) {
                level[adj[node][i].nextNode] = level[node] + 1;
                q.push(adj[node][i].nextNode);
            }
        }
    }
    return level[sink] != -1;
}
int dfs(int node,int flow,int sink) {
    if(node==sink) {
        return flow;
    }
    for(int &i= work[node];i<(int)adj[node].size();++i) {
        int nextNode = adj[node][i].nextNode,cap = adj[node][i].cap;
        if(level[nextNode] == level[node] + 1 && cap>0) {
            int tmp = dfs(nextNode, min(cap,flow),sink);
            if(tmp>0) {
                adj[node][i].cap -= tmp;
                adj[nextNode][adj[node][i].rid].cap += tmp;
                return tmp;
            }
        }
    }
    return 0;
}
ll maxFlow(int source,int sink) {
    ll ret = 0;
    while(bfs(source,sink)) {
        memset(work,0,sizeof(work));
        while(true) {
            int flow = dfs(source,inf,sink);
            ret += flow;
            if(flow==0) {
                break;
            }
        }
    }
    return ret;
}

int a[N];

void solve() {
    int n;
    scanf("%d",&n);
    ll ret = 0;
    int source = 0, sink = n+1;
    for(int i=1;i<=n;++i) {
        scanf("%d",&a[i]);
        if(a[i]>0) {
            ret += a[i];
            insert(source,i,a[i]);
        } else if(a[i]<0) {
            insert(i,sink,-a[i]);
        }
    }
    for(int i=1;i<=n;++i) {
        if(a[i]<0) {
            for(int j=1;j<=n;++j) {
                if(j%i==0 && a[j]>0) {
                    insert(j,i,inf);
                }
            }
        }
    }
    ret -= maxFlow(source, sink);
    printf("%lld\n",ret);
}
