					if (i <= md) {
						if (s[i] == 1) s1 -= a[i];
					} else {
						if (s[i] == 1 && a[i] > 0) s2-= a[i];
					}
				}
			} else {
				for (i = num; i <= n; i += num) {
					s[i]--;
					if (i <= md) {
						if (s[i] == 0) s1 += a[i];
					} else {
						if (s[i] == 0 && a[i] > 0) s2 += a[i];
					}
				}
			}
			if (s1 + s2 > mx) {
				j = -1;
				en = 0;
				mx = s1 + s2;
			}
		}
//		cout <<num <<endl;
	}
	cout << mx;
    return 0;
}

