void solve(){
	int N;
	cin>>N;
	vector<LL> A(N+1);
	for(int i=1;i<=N;++i){
		cin>>A[i];
	}
	///////
	FLOW::Graph gra;
	int S = 0;
	int T = N+1;
	gra.init(N+2);
	/*
	S--砕く->[node]--残す->T
	*/
	LL sum = 0;
	for(int i=1;i<=N;++i){
		if( A[i] >= 0 ){
			sum += A[i];
			LL cost = A[i];
			gra.add_edge(S,i,cost);//砕くとコストかかる
			gra.add_edge(i,T,0);
		}else{
			//A[i]が負
			LL cost = -A[i];
			gra.add_edge(S,i,0);
			gra.add_edge(i,T,cost);
		}
		/*
		おーん？
		*/
		for(int j=i+1;j<=N;++j){
			if( j%i == 0 ){
				//jからiへinfコストをつける
				gra.add_edge(j,i,INF);
			}
		}
	}
	LL ret = sum - gra.max_flow(S,T);
	cout << ret << endl;
}

