namespace maxFlow {
    const int maxn = 10010, maxe = 40010,source = 10010-1,sink = 10010-2;
    int cnt = 0;
    struct edge {
        int from,to,cap;
        edge(int a,int b,int c):from(a),to(b),cap(c) {}
        edge() {
            from = to = cap = 0;
        }
    };
    vector<int>g[maxn];
    edge e[maxe];
    void clear() {
        cnt = 0;
        REP(i,0,maxn)g[i].clear();
        REP(i,0,maxe)e[i] = edge();
    }
    void addEdge(int u,int v,int cap) {
        int cur = cnt;
        e[cur] = edge(u,v,cap);
        g[u].PB(cur);
        e[cur^1] = edge(v,u,0);
        g[v].PB(cur^1);
        cnt+=2;
    }

    int lvl[maxn],cur[maxn];
    bool bfs(int start = source) {
        mst(lvl, -1);
        mst(cur,0);
        lvl[start] = 0;
        queue<int>q;
        q.push(start);

        while(sz(q)) {
            int f = q.front();
            q.pop();
            for(auto curEdge:g[f]) {
                auto &E = e[curEdge];
                if(E.cap) {
                    if(lvl[E.to] == -1) {
                        lvl[E.to] = lvl[f]+1;
                        q.push(E.to);
                    }
                }
            }
        }

        return lvl[sink]!=-1;
    }


    int dfs(int curNode,int curCap) {
        if(!curCap || curNode == sink)return curCap;
        int ans = 0;
        for(int& i = cur[curNode]; i<sz(g[curNode]); i++) {
            int curEdge = g[curNode][i];
            if(lvl[e[curEdge].to]>lvl[curNode]) {
                int delta = dfs(e[curEdge].to,min(e[curEdge].cap,curCap));
                ans+=delta;
                curCap-=delta;
                e[curEdge].cap-=delta;
                e[curEdge^1].cap+=delta;
                if(!curCap)break;
            }
        }
        return ans;
    }

    ll dinic() {
        ll ans = 0;
        while (bfs()) {
            ans+=(dfs(source, inf));
        }
        return ans;
    }
}

