		else mf.addEdge(0, i + 1, a[i]); 
	}
	fw (i, 1, n + 1) {
		fw (j, i, n + 1) if (j % i == 0) mf.addEdge(i, j, inf);
	}
	//Min cut of graph now represents the selected gems.
	int sumA = 0;
	fw (i, 0, n) sumA += a[i];
