void addedge(int u, int v, ll sz)
{
	from[E] = u;
	to[E] = v;
	cap[E] = sz;
	next[E] = head[u];
	head[u] = E;
	E++;
	from[E] = v;
	to[E] = u;
	cap[E] = 0;
	next[E] = head[v];
	head[v] = E;
	E++;
}
bool bfs()
{
	for (int i = 0; i <= N + 1; i++)
	{
		level[i] = -1;
	}
	queue<int> q;
	q.push(S);
	level[S] = 0;
	while(!q.empty())
	{
		int u = q.front();
		q.pop();
		for (int i = head[u]; i > 0; i = next[i])
		{
			int v = to[i];
			if (cap[i] > 0 && level[v] == -1)
			{
				level[v] = level[u] + 1;
				q.push(v);
				if (v == T)
				{
					return true;
				}
			}
		}
	}
	return false;
}
ll aug(int u, ll flo)
{
	if (u == T)
	{
		res += flo;
		return flo;
	}
	ll rem = flo, gain = 0;
	for (int i = head[u]; i > 0 && rem > 0; i = next[i])
	{
		int v = to[i];
		if (cap[i] > 0 && level[v] == level[u] + 1)
		{
			gain = aug(v, min(rem, cap[i]));
			cap[i] -= gain;
			cap[i ^ 1] += gain;
			rem -= gain;
		}
	}
	return flo - rem;
}
ll dinic()
{
	res = 0ll;
	while(bfs())
	{
		aug(S, LLINF);
	}
	return res;
}

