template <typename T>
class Dinic {

	int maxv;
	vector<vector<Edge<T>>> G;
	vector<int> level;
	vector<int> iter;

   public:
	static const T DINIC_INF = (sizeof(T) > 4) ? LLONG_MAX : INT_MAX;

   public:
	Dinic(int input_maxv) : maxv(input_maxv) {
		G.resize(input_maxv);
		level.resize(input_maxv);
		iter.resize(input_maxv);
	}

	void add_edge_both(int from, int to, T cap) {
		const int rev_from  = G[from].size();
		const int rev_to    = G[to].size();
		G[from].push_back(Edge<T>(to, cap, rev_to));
		G[to].push_back(Edge<T>(from, cap, rev_from));
	}

	void add_edge(int from, int to, T cap) {
		const int rev_from  = G[from].size();
		const int rev_to    = G[to].size();
		G[from].push_back(Edge<T>(to, cap, rev_to));
		G[to].push_back(Edge<T>(from, (T)0, rev_from));
	}

	T max_flow(int s, int t) {
		T flow = 0;
		while (true) {
			bfs(s);
			if (level[t] < 0) break;
			fill(ALL(iter), 0);
			T f;
			while ((f = dfs(s, t, DINIC_INF)) > 0) {
				flow += f;
			}
		}
		return flow;
	}

	vector<bool> get_nodes_in_group(int s) {
		vector<bool> ret(maxv);

		queue<int> q;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			ret[v] = true;

            rep(i, G[v].size()) {
				Edge<T> &e = G[v][i];
				if (e.cap > 0 && !ret[e.to]) {
					q.push(e.to);
				}
			}
		}
		return ret;
	}

	void disp() {
        rep(v, maxv) {
			fprintf(stderr, "%d:", v);
            rep(i, G[v].size()) {
				if (G[v][i].init_cap > 0) {
					fprintf(stderr, "->%d(%d),", G[v][i].to, G[v][i].init_cap);
				}
			}
			fprintf(stderr, "\n");
		}
	}

private:
	void bfs(int s) {
		fill(ALL(level), -1);
		queue<int> q;
		level[s] = 0;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
            rep(i, G[v].size()) {
				Edge<T> &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	int dfs(int v, int t, T f) {
		if (v == t) return f;
		for (int &i=iter[v]; i<G[v].size(); i++) {
			Edge<T>& e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				T d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};

ll solve(int N, vi& a) {
	const int S = N+1;
	const int T = S+1;

    Dinic<ll>* dinic = new Dinic<ll>(T+1);
    ll answer = 0;
    rep1(i,N) {
        int a_i = a[i-1];
        if (a_i <= 0) {
            dinic->add_edge(S, i, -a_i);
        } else {
            answer += a_i;
            dinic->add_edge(i, T, a_i);
        }
        for (int k=i; k<=N; k+=i) {
            dinic->add_edge(i, k, Dinic<ll>::DINIC_INF);
        }
    }
    answer -= dinic->max_flow(S, T);

    delete dinic;

    return answer;
}

