using namespace std;

bitset <100> maskdiv[100], invmaskdiv[100], full;
int n;
vector <int> a;
long long ans=0;
//mulai dari pos=1, bukan pos=0 because smashing first gem --> ans=0 --> already considered
//"return bruteForcePrune(something)" actually returns nothing (void)
void bruteForcePrune(long long potential, long long curr=0, bitset <100> currmask=full, int pos=1) {
	//potential is an upperbound for the answer
	if(potential<=ans){//prune
		return;
	}
	//base case
	if(pos==n){
		ans=curr;
		return;
	}
	//gem already smashed
	if(!currmask[pos]){
		return bruteForcePrune(potential, curr, currmask, pos+1);
	}
	//tidak ada gunanya smash gem yg non-negative
	if(a[pos]>=0){
		return bruteForcePrune(potential, curr+a[pos], currmask, pos+1);
	}
	//keep the bad gem
	bruteForcePrune(potential+a[pos], curr+a[pos], currmask, pos+1);
	//smash the bag gem (and some other gems after)
	//maskdiv and invmaskdiv are precomputed so no time is wasted on ~ operator
	bitset <100> toDelete=currmask&maskdiv[pos];
	for(int i = pos+1;i < n;i ++){
		if(toDelete[i]){
			//potential goes down when a positive gem is smashed
			if(a[i]>0){
				potential-=a[i];
			}
		}
	}
	return bruteForcePrune(potential, curr, currmask&invmaskdiv[pos], pos+1);
}
int main(){
	//precompute masks
	for(int i = 0;i < 100;i ++){
		for(int j = i+1;j <= 100;j += i+1){
			maskdiv[i][j-1]=true;
		}
		invmaskdiv[i]=~maskdiv[i];
	}
	//cuma kepake sekali sih ini
	full.set();
	//input
	scanf("%d", &n);
	a.resize(n);
	long long fullPotential=0;
	for(int&i:a){
		scanf("%d", &i);
	}
	//if gems numbered 51-100 are negative, they definitely won't be considered
	for(int i = n/2;i < n;i ++){
		a[i]=max(a[i], 0);
	}
	for(int i = 1;i < n;i ++){
		fullPotential+=max(a[i], 0);
	}
	bruteForcePrune(fullPotential);
	printf("%lld\n", max(ans+a[0], 0ll));
}

