			}
		}
		for (int j = 26; j <= 50; j++) {
			if (val&dv[j]) {

			}
			else {
				if (j * 3 <= 100 && j % 2) {
					long long int U = cost[j];
					if ((val&dv[j * 2]) == 0LL) {
						U += max(0LL, cost[j * 2]);
					}
					if ((val&dv[j * 3]) == 0LL) {
						U += max(0LL, cost[j * 3]);
					}
					if (U >= 0) {
						ans += cost[j];
					}
					else {
						val |= (1LL << (long long int)(j));
					}
					continue;
				}
				if (j * 3 <= 100) {
					int o1 = j;
					int o2 = j * 3 / 2;
					long long int www = 0;
					int id = -1;
					for (int k = 0; k < 4; k++) {
						long long int val2 = val;
						if (k & 1) {
							val2 |= (1LL << (long long int)(o1));
						}
						if ((k >> 1) & 1) {
							val2 |= (1LL << (long long int)(o2));
						}
						long long int ad = 0;
						for (auto el : gr[j]) {
							if ((dv[el] & val2)==0LL) {
								if (el >= 50) {
									ad += max(0LL, cost[el]);
								}
								else {
									ad += cost[el];
								}
							}
						}
						www = max(www, ad);
						if (www == ad) {
							id = k;
						}
					}
					if (id & 1) {
						val |= (1LL << (long long int)(o1));
					}
					if ((id >> 1) & 1) {
						val |= (1LL << (long long int)(o2));
					}
					for (auto el : gr[j]) {
						if ((dv[el] & val) == 0LL) {
							if (el >= 50) {

							}
							else {
								ans += cost[el];
							}
						}
					}
					continue;
