ll ek(int s,int t){
    ll ans=0;
    while(1){
        queue<int>q;
        q.push(s);
        vector<int>pre(t+1,-1);
        vector<int>vis(t+1,0);
        vis[s]=1;
        while(!q.empty()){
            int u=q.front();
            q.pop();
            //vis[u]=0;
            //cout<<"u"<<u<<endl;
            for(int i=0;i<=t;++i){
                if(!vis[i]&&g[u][i]>0){
                    vis[i]=1;
                    pre[i]=u;
                    q.push(i);
                }
            }
        }
        if(pre[t]==-1) break;
        int tmp=inf;
        for(int i=t;i!=s;i=pre[i]){
            tmp=min(tmp,g[pre[i]][i]);
        }
        for(int i=t;i!=s;i=pre[i]){
            g[pre[i]][i]-=tmp;
            g[i][pre[i]]+=tmp;
        }
        ans+=tmp;
    }
    return ans;
}
