  if(from==to) return cf;
  for(long long &i = itr[from]; i < E[from].size(); i++){
    edge &e = E[from][i];
    if(e.cap>0 && lev[from]<lev[e.to]){
      long long f=dfs(e.to,to,min(cf,e.cap));
      if(f>0){
        e.cap-=f;
        E[e.to][e.reve].cap += f;
        return f;
      }
    }
  }
  return 0;
}

