typedef long long ll;

template<typename T> struct Dinic{
	struct edge{
		int to,rev;
		T cap;
	};
	vector< vector<edge> > G;
	vector<int> level,iter;
	void init(int n){
		G.assign(n,vector<edge>());
		level.assign(n,0);
		iter.assign(n,0);
	}
	void add_edge(int from,int to,T cap){
		G [from].push_back(edge{to,int(G [to].size()),cap});
		G [to].push_back(edge{from,int(G [from].size()) - 1,0});
	}
	void bfs(int s){
		fill(level.begin(),level.end(),-1);
		queue<int> q;
		level [s] = 0;
		q.push(s);
		while(q.empty() == false){
			int curr = q.front();
			q.pop();
			for(int i = 0;i < int(G [curr].size());i++){
				edge& e = G [curr] [i];
				if(e.cap > 0 && level [e.to] < 0){
					level [e.to] = level [curr] + 1;
					q.push(e.to);
				}
			}
		}
	}
	T dfs(int curr,int t,T f){
		if(curr == t) return f;
		for(int& i = iter [curr];i < int(G [curr].size());i++){
			edge& e = G [curr] [i];
			if(e.cap > 0 && level [e.to] > level [curr]){
				T d = dfs(e.to,t,min<T>(f,e.cap));
				if(d == 0) continue;
				e.cap -= d;
				G [e.to] [e.rev].cap += d;
				return d;
			}
		}
		return 0;
	}
	T max_flow(int s,int t){
		T flow = 0,d;
		while(true){
			bfs(s);
			if(level [t] < 0) break;
			fill(iter.begin(),iter.end(),0);
			while((d = dfs(s,t,numeric_limits<T>::max())) > 0) flow += d;
		}
		return flow;
	}
};

