class EDGE{
public:
	int to,cap,rev;
};
vector<EDGE>edge[maxn*5];

void add_edge(int from,int to,int cap){
	edge[from].pb((EDGE){to,cap,(int)edge[to].size()});
	edge[to].pb((EDGE){from,0,(int)edge[from].size()-1});
}

void bfs(int s){
	memset(level,-1,sizeof(level));
	level[s]=0;
	queue<int>q;
	q.push(s);
	while(!q.empty()){
		int x=q.front();q.pop();
		rep(i,edge[x].size()){
			EDGE &y=edge[x][i];
			if(y.cap&&level[y.to]<0){
				level[y.to]=level[x]+1;
				q.push(y.to);
			}
		}
	}
}

int dfs(int s,int t,int f){
	if(s==t)return f;
	for(int &i=nxt[s];i<edge[s].size();i++){
		EDGE &x=edge[s][i];
		if(x.cap&&level[x.to]==level[s]+1){
			int d=dfs(x.to,t,min(f,x.cap));
			if(d){
				x.cap-=d;
				edge[x.to][x.rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}

ll max_flow(int s,int t){
	ll flow=0;
	while(true){
		bfs(s);
		if(level[t]<0)return flow;
		memset(nxt,0,sizeof(nxt));
		int f;
		while(f=dfs(s,t,INF))flow+=f;
	}
}

