class Maxflow{
public:
	struct Edge{
		int e;
		ll c, f; 
		Edge(){}
		Edge(int e, ll c, ll f):e(e), c(c), f(f){}
	};
	static const int MAXE = 500005;
	static const int MAXV = 500005;
	vector<int> G[MAXV];
	Edge E[MAXE*2];
	int dist[MAXV], cur[MAXV];
	int sz = 0;

	void clear(int N){
		for(int i = 0; i <= N; i++) G[i].clear();
		sz = 0;
	}

	void add(int s, int e, ll c){
		E[sz] = Edge(e, c, 0); G[s].push_back(sz); sz++;
		E[sz] = Edge(s, c, c); G[e].push_back(sz); sz++;
	}

	int BFS(int s, int e, int N){
		for(int i = 0; i <= N; i++) dist[i] = 0;
		queue<int> Q;
		Q.push(s); dist[s] = 1;
		while(Q.size()){
			int p = Q.front(); Q.pop();
			for(int cc : G[p]){
				Edge c = E[cc];
				if( c.c > c.f && dist[c.e] == 0 ){
					dist[c.e] = dist[p] + 1;
					Q.push(c.e);
				}
			}
		}
		return dist[e];
	}

	ll dfs(int s, int e, ll f){
		if( s == e ) return f;
		for(; cur[s] < G[s].size(); cur[s]++){
			int d = G[s][cur[s]];
			Edge c = E[d];
			if( c.c > c.f && dist[c.e] == dist[s] + 1){
				ll t = dfs(c.e, e, min(f, c.c - c.f));
				if( t ){
					E[d].f += t;
					E[d^1].f -= t;
					return t;
				}
			}
		}
		return 0;
	}

	ll run(int s, int e, int N){
		ll ans = 0, c;
		while(BFS(s, e, N) != 0){
			for(int i = 0; i <= N; i++) cur[i] = 0;
			while((c = dfs(s, e, 1e18)) != 0) ans += c;
		}
		return ans;
	}
}flow;

