class Dinic {
	const int INF = 2e9;
	struct edge { int to, cap, rev; };

	public:
	int V;
	vector<vector<edge>> G;
	vector<int> level, iter;
	Dinic(int V) : V(V), G(V), level(V), iter(V) {}

	void add_edge(int from, int to, int cap) {
		G[from].push_back((edge){to, cap, (int) G[to].size()});
		G[to].push_back((edge){from, 0, (int) G[from].size() - 1});
	}

	ll max_flow(int s, int t) {
		ll flow = 0;
		for (;;) {
			bfs(s);
			if (level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			int f;
			while ((f = dfs(s, t, INF)) > 0) {
				flow += f;
			}
		}
	}

	private:
	void bfs(int s) {
		fill(level.begin(), level.end(), -1);
		level[s] = 0;
		queue<int> q;
		q.push(s);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int i = 0; i < (int) G[v].size(); i++) {
				edge &e = G[v][i];
				if (e.cap > 0 && level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					q.push(e.to);
				}
			}
		}
	}

	ll dfs(int v, int t, int f) {
		if (v == t) return f;
		for (int &i = iter[v]; i < (int) G[v].size(); i++) {
			edge &e = G[v][i];
			if (e.cap > 0 && level[v] < level[e.to]) {
				ll d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}
};

ll solve() {
	int n = ri();
	vector<int> A(n);
	rep(i, n) A[i] = ri();

	const int inf = 1e9;

	ll sum = 0;

	Dinic dinic(n+2);

	rep(i, 1, n+1) {
		int a = A[i-1];
		out(i, a);
		if (a <= 0) {
			dinic.add_edge(0, i, -a);
		}
		else {
      		dinic.add_edge(i, n+1, a);
			sum+=a;
		}
		int j = i * 2;
		while (j <= n) {
			dinic.add_edge(i, j, inf);
			j += i;
		}
	}

	ll res = dinic.max_flow(0, n+1);
	ll ans = sum - res;

	out(sum, res, ans);

	return ans;
}

void Main() {
	cout << solve() << endl;
}

