int main(){
    int N;
    cin >> N;

    vector<int> a(N+1);
    vector<vector<int>> divisors(N+1);
    for(int i=1;i<=N;i++){
        cin >> a[i];
        for(int j=1;j<i;j++){
            if(i % j == 0){
                divisors[i].push_back(j);
            }
        }
    }

    vector<set<int>> carry(N + 1);
    vector<bool> dead(N + 1, false);
    for(int i=N;i>=2;i--){
        int gain = a[i];
        for(int c : carry[i]){
            if(!dead[c]) gain += a[c];
        }

        if(gain > 0){
            for(int d : divisors[i]){
                for(int c : carry[i]){
                    if(!dead[c]) carry[d].insert(c);
                }
                carry[d].insert(i);
            }
        }else{
            for(int c : carry[i]){
                dead[c] = true;
            }
            dead[i] = true;
        }
    }

    int ans = a[1];
    for(int c : carry[1]){
        if(!dead[c]) ans += a[c];
    }
    cout << max(ans, 0) << endl;

    return 0;
}

