  for (int i = 0; i < N; i++) {
    int v;
    scanf("%d", &v);
    a.push_back(v);
  }

  vector<int> pending;
  for (int i = N; i > 0; i--) {
    long long sum = 0;
    int cnt = 0;
    for (int j = i; j <= a.size(); j += i) {
      sum += a[j-1];
      cnt++;
    }
    if (sum >= 0)
      continue;

    if (i > 1 && cnt > 1 && i <= N / 2 && !primes.count(i)) {
      pending.push_back(i);
      continue;
    }

    for (int j = i; j <= a.size(); j += i) {
      //fprintf(stderr, "hit %d\n", j);
      a[j-1] = 0;
    }
  }

  fprintf(stderr, "pending=%zu\n", pending.size());

  int sum = 0;
  for (int i = 0; i < a.size(); i++)
    sum += a[i];

  int best_sum = sum;

  for (int i = 0; i < (1<<pending.size()); i++) {
    vector<int> na(a);
    int p = i;
    for (int j = 0; p; j++) {
      if ((p & 1) == 1) {
        int x = pending[j];
        for (int k = x; k <= na.size(); k += x) {
          na[k-1] = 0;
        }
      }
      p >>= 1;
    }

    int sum = 0;
    for (int j = 0; j < na.size(); j++) {
      sum += a[j];
    }
    if (best_sum < sum)
      best_sum = sum;
  }

  printf("%d\n", best_sum);
}

