struct Fordfulkerson {
	const int INF = 1 << 28;
	struct edge {
		int to, cap, rev;
		edge() {}
		edge(int to, int cap, int rev) :to(to), cap(cap), rev(rev) {}
	};

	int n;
	vector<vector<edge> > G;
	vector<int> used;

	Fordfulkerson() {}
	Fordfulkerson(int sz) :n(sz), G(n), used(n) {}

	void add_edge(int from, int to, int cap) {
		G[from].push_back(edge(to, cap, G[to].size()));
		// undirected
		//G[to].push_back(edge(from,cap,G[from].size()-1));
		// directed
		G[to].push_back(edge(from, 0, G[from].size() - 1));
	}

	int dfs(int v, int t, int f) {
		if (v == t) return f;
		used[v] = true;
		for (int i = 0; i < (int)G[v].size(); i++) {
			edge &e = G[v][i];
			if (!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	int flow(int s, int t, int lim) {
		int fl = 0;
		for (;;) {
			fill(used.begin(), used.end(), 0);
			int f = dfs(s, t, lim);
			if (f == 0) return fl;
			fl += f;
			lim -= f;
		}
	}

	int flow(int s, int t) {
		return flow(s, t, INF);
	}

};

#define inf 100000

int main() {
	int N;
	cin >> N;
	Fordfulkerson g(N + 2);
	ll sum = 0;
	for (int i = 1; i <= N; i++) {
		int a;
		cin >> a;
		if (a <= 0) g.add_edge(0, i, -a);
		else {
			g.add_edge(i, N + 1, a);
			sum += a;
		}
		int j = 2 * i;
		while (j <= N) {
			g.add_edge(i, j, inf);
			j += i;
		}
	}
	cout << sum - g.flow(0, N + 1) << endl;
	return 0;
}

