	Q.push(s);vis[s]=1;
	while(!Q.empty()){
		int u=Q.front();Q.pop();
		for(int i=head[u];i;i=edge[i].nxt){
			int v=edge[i].to;
			if(!vis[v]&&edge[i].cap>edge[i].flow){
				d[v]=d[u]+1;
				vis[v]=1;
				Q.push(v);
			}
		}
	}
	return vis[t];
}
int dfs(int u,ll a){
	if(a==0||u==t) return a;
	int flow=0,f;
	for(int &i=cur[u];i;i=edge[i].nxt){
		int v=edge[i].to;
		if(d[v]==d[u]+1&&(f=dfs(v,min(a,edge[i].cap-edge[i].flow)))>0){
			flow+=f;
			edge[i].flow+=f;
			edge[i^1].flow-=f;
			a-=f;
			if(!a) break;
		}
	}
	return flow;
}
