 const int mod=1000000007;

 // dinic
 struct max_flow {//V:頂点数 O(EV^2)だが実際はより高速
     struct edge { LL to, cap, rev; };
     int V;
     vector<vector<edge>> G;
     vector<int> itr, level;

     max_flow(int V) : V(V) { G.assign(V,vector<edge>()); }

     void add_edge(int from, int to, LL cap) {
         G[from].push_back((edge) {to, cap, (int) G[to].size()});
         G[to].push_back((edge) {from, 0, (int) G[from].size()-1});
     }
 //sからの最短距離をbfs計算
     void bfs(LL s) {
         level.assign(V,-1);
         queue<int> q;
         level[s] = 0; q.push(s);
         while (!q.empty()) {
             int v = q.front(); q.pop();
             for(auto &e: G[v]){
                 if (e.cap > 0 and level[e.to] < 0) {
                     level[e.to] = level[v] + 1;
                     q.push(e.to);
                 }
             }
         }
     }
 //増加パスをdfsで探索
     LL dfs(int v, LL t, LL f) {
         if (v == t) return f;
         for (int& i = itr[v]; i < (int) G[v].size(); ++i) {
             edge& e = G[v][i];
             if (e.cap > 0 and level[v] < level[e.to]) {
                 int d = dfs(e.to, t, min(f, e.cap));
                 if (d > 0) {
                     e.cap -= d;
                     G[e.to][e.rev].cap += d;
                     return d;
                 }
             }
         }
         return 0;
     }

     LL run(int s, int t) {//s to t
         LL ret = 0, f;
         while (bfs(s), level[t] >= 0) {
             itr.assign(V,0);
             while ((f = dfs(s, t, mod)) > 0) ret += f;//mod use as inf
         }
         return ret;
     }
 };


int main(){
	int n,a[111]={};
	cin>>n;
	max_flow mf(n+2);//0:破壊,n+1:残存
	LL mx=0;
	FORQ(i,1,n){
		cin>>a[i];
		if(a[i]>=0){
			mx+=a[i];
			mf.add_edge(0,i,a[i]);
		}else{
			mf.add_edge(i,n+1,-a[i]);
		}
		FORQ(j,2,n/i){
			int to=j*i;
			mf.add_edge(to,i,1LL*mod*1000000);
		}
	}
	cerr<<mx<<endl;
	cout<<mx-mf.run(0,n+1)<<endl;

	return 0;
}

