ll dfs(vector<map<int,ll>>&E,vb&v,int s,int t,ll f){
	if(s==t)return f;
	v[s]=true;
	for(pil a:E[s])if(!v[a.first]&&a.second){
		if(ll r=dfs(E,v,a.first,t,min(f,a.second))){
			E[s][a.first]-=r;
			E[a.first][s]+=r;
			return r;
		}
	}
	return 0;
}

