			g.AddEdge(tap,i,max(-a[i],0));
			g.AddEdge(i,sink,max(a[i],0));
			int x=i+1;
			for(int y=x+x;y<=n;y+=x)
				g.AddEdge(x-1,y-1,INF);
		}

		ll res=0;
		rep(i,n) res+=max(a[i],0);
		cout<<res-Dinic(g,tap,sink)<<endl;
	}
}

