ll a[101];
bool used[101];
ll ans;

void solve(int now,ll sum){
  //cout<<now<<" "<<sum<<" "<<ans<<endl;
  ans=max(ans,sum);
  for(int k=now-1;k>0;k--){
    vector<int> v;
    ll res=0;
    for(int i=1;k*i<=n;i++){
      if(used[k*i]) continue;
      //if(i%k==0){
        used[k*i]=true;
        res-=a[k*i];
        v.push_back(k*i);
      //}
    }
    if(res>0) solve(k,sum+res);
    for(int i=0;i<v.size();i++) used[v[i]]=false;
  }
  return;
}

