const int maxn = 1e3+1;
const ll inf = 1e18;
struct ISAP
{
  int n, m, s, t;
  vector<Edge> edges;
  vector<int> g[maxn];
  bool vis[maxn];
  int d[maxn];
  int cur[maxn];
  int p[maxn];
  inline void init(int n)
  {
    this->n = n;
    m = 0;
    for (int i = 0; i < n; ++i)
      g[i].clear();
    edges.clear();
  }
  inline void add(int u, int v, ll cap)
  {
    edges.pb((Edge){u, v, cap, 0});
    edges.pb((Edge){v, u, 0, 0});
    m = edges.size();
    g[u].pb(m-2);
    g[v].pb(m-1);
  }
  inline void bfs()
  {
    fill(d, d+n, n);
    queue<int> q;
    q.push(t);
    d[t] = 0;
    while (!q.empty())
      {
	int cur = q.front();
	q.pop();
	for (int i = 0; i < g[cur].size(); ++i)
	  {
	    Edge &e = edges[g[cur][i]^1];
	    if (d[e.from] == n && e.cap > e.flow)
	      {
		vis[e.from] = true;
		d[e.from] = d[e.to]+1;
		q.push(e.from);
	      }
	  }
      }
  }
  ll add()
  {
    int x = t;
    ll a = inf;
    while (x != s)
      {
	Edge &e = edges[p[x]];
	a = min(a, e.cap-e.flow);
	x = edges[p[x]].from;
      }
    x = t;
    while (x != s)
      {
	edges[p[x]].flow += a;
	edges[p[x]^1].flow -= a;
	x = edges[p[x]].from;
      }
    return a;
  }
  int num[maxn];
  ll maxflow(int s, int t)
  {
    this->s = s, this->t = t;
    ll flow = 0;
    memset(num, 0, (n+1)*sizeof(int));
    for (int i = 0; i < n; ++i)
      ++num[d[i]];
    int x = s;
    memset(cur, 0, n*sizeof(int));
    while (d[s] < n)
      {
	if (x == t)
	  {
	    flow += add();
	    x = s;
	  }
	int ok = 0;
	for (int i = cur[x]; i < g[x].size(); ++i)
	  {
	    Edge &e = edges[g[x][i]];
	    if (e.cap > e.flow && d[x] == d[e.to]+1)
	      {
		ok = 1;
		p[e.to] = g[x][i];
		cur[x] = i;
		x = e.to;
		break;
	      }
	  }
	if (!ok)
	  {
	    int m = n-1;
	    for (int i = 0; i < g[x].size(); ++i)
	      {
		Edge &e = edges[g[x][i]];
		if (e.cap > e.flow) m = min(m, d[e.to]);
	      }
	    if (--num[d[x]] == 0) break;
	    num[d[x]=m+1]++;
	    cur[x] = 0;
	    if (x != s) x = edges[p[x]].from;
	  }
      }
    return flow;
  }
} isap;

int n;
ll a[maxn];

int main()
{
  scanf("%d", &n);
  for (int i = 1; i <= n; ++i)
    scanf("%lld", a+i);
  isap.init(n+10);
  const int src = isap.n-1, dest = src-1;
  ll tot=0;
  for (int i = 1; i <= n; ++i)
    a[i] *= -1;
  for (int i = 1; i <= n; ++i)
    if (a[i] >= 0)
      isap.add(src, i, a[i]), tot += a[i];
    else
      isap.add(i, dest, -a[i]);
  for (int i = 1; i <= n; ++i)
    for (int j = 2*i; j <= n; j += i)
      isap.add(i, j, inf);
  ll tmp=tmp=isap.maxflow(src, dest);
  //  cerr << "flow = " << tmp << endl;
  //  cerr << "tot = " << tot << endl;
  ll sum = 0;
  for (int i = 1; i <= n; ++i)
    sum += a[i];
  tot -= tmp;
  //  cerr << "sum = " << sum << endl;
  printf("%lld\n", -sum+tot);
}

