		lint x = a.at(i);
		if (x < 0) {
			dnc.insert(s,i,-x);
		} else if (0 < x) {
			dnc.insert(i,t,x);
		}
	}
	lint inf = std::numeric_limits<lint>::max();
	rep(d,1,n+1) {
		for (int i = 2 * d; i <= n; i += d) {
