        edge &e = G[v][i];
        if(!used[e.to] && e.cap>0){
            ll d = dfs(e.to, t, min(f, e.cap));
            if(d>0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

