            }
            mask[j] = 1;
            ret += tmp;
        }
        return ret;
    }
    ll ret = 0;
    chmax(ret, dfs(i+1, mask));
    if (!mask[i]) {
        for (ll j = i; j < S; j += i) {
            mask[j] = 1;
        }
        chmax(ret, dfs(i+1, mask));
    }
    return ret;
}

