void edge(int u, int v, long long c) {
  adj[u].push_back(v);
  adj[v].push_back(u);
//  cout << u << " -> " << v << " " << c << "\n";
  cap[u][v] = c;
}

long long BFS() {
  memset(par, -1, sizeof(par));
  queue<pii> q;
  q.emplace(source, INF);
  par[source] = -2;
  while(!q.empty()) {
    int u = q.front().first;
    long long flow = q.front().second;
//    cout << u << " " << flow << "\n";
    q.pop();

    for(int v : adj[u]) {
      if(par[v] == -1 && cap[u][v] > 0) {
        par[v] = u;
        long long new_flow = min(flow, cap[u][v]);
        if(v == sink) return new_flow;
        q.emplace(v, new_flow);
      }
    }
  }
//  cout << "NO\n" << "\n";
  return 0;
}

long long macflow() {
  long long flow = 0, new_flow;
  while(new_flow = BFS()) {
    flow += new_flow;
    int u = sink;
    while(u != source) {
      cap[par[u]][u] -= flow;
      cap[u][par[u]] += flow;
      u = par[u];
    }
  }
//  cout << flow << "\n";
  return flow;
}

