using namespace std;

const int N = 110;

typedef long long LL;

LL ans;
int A[N], n;
bool used[N];

void work(int r){
	int l = r / 2 + 1;
	For(i, l, r){
		LL ret = 0;
		if(used[i]) continue;
		for(int j = i; j <= n; j += i) if(!used[j]) ret += A[j];
		if(ret > 0){
			ans += ret;
			for(int j = i; j <= n; j += i) used[j] = true;
		}
	}
	if(l > 1) work(l - 1);
}

int main(){
	scanf("%d", &n);
	LL sum = 0;
	For(i, 1, n) scanf("%d", &A[i]), sum += A[i], A[i] = -A[i];
	int x = min(15, n);
	LL Max = 0;
	For(i, 0, (1 << x) - 1){
		memset(used, 0, sizeof used);
		ans = 0;
		For(j, 0, x - 1) if(i & (1 << j)){
			for(int k = j + 1; k <= n; k += j + 1) if(!used[k]) ans += A[k], used[k] = true;
		}
		work(n);
		Max = max(Max, ans);
	}
	printf("%lld\n", sum + Max);
	return 0;
}

