void init()
{
    rep(i, 1, t + 1)
    {
        int mask = 0;
        for (int j = i; j <= t; j += i)
            mask |= (1 << (j - 1));
        ttt[i - 1] = ((1 << t) - 1) ^ mask;
    }
}

void solve(ll mask, int p)
{
    if (p == t)
    {
        s.insert(mask);
        return;
    }
    solve(mask, p + 1);
    if ((mask >> p) & 1)
        solve(mask & ttt[p], p + 1);
}

