// 枝定義
struct Edge
{
	int	toIdx;
	int	revIdx;
	int	cap;
	Edge(){}
	Edge(int to, int rev, int capArg): toIdx(to), revIdx(rev), cap(capArg){}
};

// グラフ定義(二次元配列)
using Graph = vector<vector<Edge>>;

// フォード・ファルカーソン
class FordFulkerson 
{
private:
	int V;
	Graph G;
	vector<bool> isUsed;

private:
	int dfs(int from, int sinkPos, int flow)
	{
		if (from == sinkPos) {
			return flow;
		}

		int flowOne = 0;
		isUsed[from] = true;
		for (Edge &edge : G[from]) {
			int to = edge.toIdx;
			if (!isUsed[to]) {
				if (0 < edge.cap) {
					flowOne = dfs(to, sinkPos, min(flow, edge.cap));
					if (0 < flowOne) {
						edge.cap -= flowOne;
						G[to][edge.revIdx].cap += flowOne;
						break;
					}
				}
			}
		}
		return flowOne;
	}

public:
	FordFulkerson(int N)
	{
		G.resize(N);
	}

	// 枝を追加
	void AddEdge(int from, int to, int cap)
	{
		int revIdxTo = G[to].size();
		int revIdxFrom = G[from].size();
		G[from].emplace_back(to, revIdxTo, cap);
		G[to].emplace_back(from, revIdxFrom, 0);
	}

	// 最大フローを求める
	int GetMaxFlow(int startPos, int endPos)
	{
		int maxFlow = 0;
		V = (int)G.size();
		isUsed.resize(V);
		for (;;) {
			fill(isUsed.begin(), isUsed.end(), false);
			int flowOne = dfs(startPos, endPos, (int)INF);
			if (flowOne == 0) {
				break;
			}
			maxFlow += flowOne;
		}
		return maxFlow;
	}
};


int main()
{
	int N;
	cin >> N;
	vector<ll> a(N);
	REP(i, N) {
		cin >> a[i];
	}

	ll plusSum = 0;
	REP(i, N) {
		if (0 <= a[i]) {
			plusSum += a[i];
		}
	}

	FordFulkerson fordFulk(N + 2);

	// 始点→i(残す)
	int start = 0;
	REP(i, N) {
		if (a[i] <= 0) {
			fordFulk.AddEdge(start, i + 1, a[i] * -1);
		} else {
			fordFulk.AddEdge(start, i + 1, 0);
		}
	}

	// i→終点（たたく)
	int end = N + 1;
	REP(i, N) {
		if (0 < a[i]) {
			fordFulk.AddEdge(i + 1, end, a[i]);
		} else {
			fordFulk.AddEdge(i + 1, end, 0);
		}
	}

	// i→j（たたく組み)
	for (int i = 1; i <= N; i++) {
		for (int j = 2 * i; j <= N; j += i) {
			fordFulk.AddEdge(i, j, INF);
		}
	}

	// 最大流量
	int ans = fordFulk.GetMaxFlow(start, end);
	cout << plusSum - ans << endl;
	return 0;
}

