struct Edge {
    int u, v;
    int c, f;
    Edge(int u,int v,int c) : u(u), v(v), c(c), f(0)    {}
};

vector<Edge> E;
vector<int>  g[N];

void addEdge(int u,int v,int c) {
    g[u].pb(sz(E)); E.pb({u,v,c});
    g[v].pb(sz(E)); E.pb({v,u,0});
}

int s, t, p[N];

bool bfs()  {
    for(int i = s ; i <= t ; ++i)
        p[i] = -1;
    queue<int>  q;
    q.push(s);  p[s] = inf;
    while(q.size()) {
        int u = q.front();  q.pop();
        for(int i : g[u])   {
            if(E[i].c == E[i].f)    continue;
            int v = E[i].v;
            if(p[v] < 0)    {
                p[v] = i;
                q.push(v);
            }
        }
    }
    return p[t] >= 0;
}

int n, a[N];

signed main()   {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;   s = 0;  t = n + 1;

    int sum = 0;

    for(int i = 1 ; i <= n ; ++i)   {
        cin >> a[i];
        bool ch = 0;
        for(int j = 1 ; j <= i ; ++j)   {
            if(i % j)   continue;
            addEdge(j,i,inf);
        }
        sum += max(a[i],0ll);
        if(a[i] < 0)addEdge(s,i,-a[i]);
        else        addEdge(i,t,a[i]);
    }

    int Flow = 0;

    while(bfs())    {
        int u = t, F = inf;
        while(u)    {
            int i = p[u];
            F = min(F,E[i].c - E[i].f);
            u = E[i].u;
        }
        u = t;  Flow += F;
        while(u)    {
            int i = p[u];
            E[i].f += F;    i ^= 1;
            E[i].f -= F;    u = E[i].v;
        }
    }

    cout << sum - Flow << endl;
}

