void init()
{
    memset(h,-1,sizeof(h));mem=0;
}
int q[maxn],head,tail;
int dis[maxn];
bool BFS(int s,int t)
{
    memset(dis,127,sizeof(dis));
    dis[s]=0;
    head=tail=0;
    q[tail++]=s;
    while(head<tail)
    {
        int u=q[head++];
        for(int i=h[u];i+1;i=e[i].next)
        {
            int v=e[i].v;
        //printf("%d  %d\n",u,v);
            if(dis[v]>dis[u]+1&&e[i].cap){
                dis[v]=dis[u]+1;
                q[tail++]=v;
            }
        }
    }
    return dis[t]<100000;
}
long long DFS(int u,long long limit,int t)
{
    //printf("%d %I64d %d\n",u,limit,t);
    if(u==t) return limit;
    long long ans=0;
    for(int i=h[u];i+1;i=e[i].next)
    {
        int v=e[i].v;
        if(dis[v]==dis[u]+1&&e[i].cap)
        {
            long long tmp=DFS(v,min(e[i].cap,limit-ans),t);
            if(tmp){
                e[i].cap-=tmp;
                e[i^1].cap+=tmp;
                ans+=tmp;
            }
        }
    }
    if(ans==0) dis[u]=-2;
    return ans;
}
long long dinic(int s,int t)
{
    long long ans=0;
    while(BFS(s,t))
    {
        //printf("%d %d\n",s,t);
        long long tmp;
        while(tmp=DFS(s,INF,t))
            ans+=tmp;
        //printf("ans is %lld \n",ans);
        //break;
    }
    return ans;
}
