struct N{
	int from , to , cap , flow;
};
struct dinic{
	int s , t , dep[MAX] , use[MAX] , res[MAX];
	vector<int> g[MAX];
	vector<N> e;
	void init(){
		REP(i , 0 , MAX) g[i].clear();
		e.clear();
	}
	void ADDE(int f , int t , int c){
		g[f].pb(e.size());
		e.pb(N{f , t , c , 0});
		g[t].pb(e.size());
		e.pb(N{t , f , 0 , 0});
	}
	int BFS(){
		MEM(use , 0) , MEM(dep , 0);
		queue<int> qu;
		qu.push(s) , dep[s] = use[s] = 1;
		while(qu.size()){
			int now = qu.front(); qu.pop();
			for(auto i : g[now]){
				N to = e[i];
				if(use[to.to] == 0 && to.cap > to.flow){
					use[to.to] = 1;
					dep[to.to] = dep[now] + 1;
					qu.push(to.to);
				}
			}
		}
		return use[t];
	}
	int DFS(int now , int lim){
		if(lim == 0 || now == t) return lim;
		int flow = 0 , tmp;
		for(int &i = res[now] ; i < g[now].size() ; i ++){
			N to = e[g[now][i]];
			if(dep[to.to] == dep[now] + 1){
				tmp = DFS(to.to , min(lim , to.cap - to.flow));
				if(tmp > 0){
					e[g[now][i] ^ 0].flow += tmp;
					e[g[now][i] ^ 1].flow -= tmp;
					flow += tmp;
					lim -= tmp;
					if(lim == 0) break;
				}
			}
		}
		return flow;
	}
	int FLOW(int s , int t){
		this -> s = s , this -> t = t;
		int flow = 0;
		while(BFS()){
			MEM(res , 0);
			flow += DFS(s , 0x3f3f3f3f);
		}
		return flow;
	}
}dc;
