int64_t back(const vector<int>& A, vector<int>& marked, int position) {
    if (position == int(A.size()))
        return 0;
    int64_t best_value = numeric_limits<int64_t>::min();
    if (!marked[position]) {
        for (int i = position; i < int(marked.size()); i += position + 1)
            marked[i]++;
        best_value = max(best_value, back(A, marked, position + 1));
        for (int i = position; i < int(marked.size()); i += position + 1)
            marked[i]--;
    }
    return max(best_value + (marked[position] ? 0 : A[position]), back(A, marked, position + 1));
}

