            ans += a[i];
        }
        else {
            add_edge(s, i, -a[i]);
        }
    }
    rep2(i, 1, n + 1) {
        rep2(j, i + 1, n + 1) {
            if (j % i == 0) {
                add_edge(i - 1, j - 1, INF);
            }
        }
    }
    cout << ans - max_flow(s, t) << endl;

}

