void Build(int k, int x, int y, long f, long c) {
    e[k] = edge(x, y, f, c);
    link[k] = head[x];
    head[x] = k;
}

struct LuongCucDai {
    int E, S, T, save[N];
    void AddEdge(int x, int y, long c) {
        ++E;
        Build(E*2, x, y, 0, c);
        Build(E*2+1, y, x, 0, 0);
    }
    bool FindPath() {
        queue<int> Q;
        fill_n(save, n+2, 0);
        save[S] = -1;
        Q.push(S);
        while (Q.size()) {
            int u = Q.front(); Q.pop();
            for (int i = head[u]; i; i = link[i])
                if (e[i].c - e[i].f > 0) {
                    int v = e[i].y;
                    if (!save[v]) {
                        Q.push(v);
                        save[v] = i;
                        if (v == T) return true;
                    }
                }
        }
        return false;
    }
    long UpFlow() {
        long mimi = INF, v, i;
        v = T;
        while (v != S) {
            i = save[v];
            mimi = min(mimi, e[i].c - e[i].f);
            v = e[i].x;
        }

        v = T;
        while (v != S) {
            i = save[v];
            e[i].f += mimi;
            e[i^1].f -= mimi;
            v = e[i].x;
        }
        return mimi;
    }
    long MaxFlow(int s, int t) {
        S = s;  T = t;
        long res = 0;
        while (FindPath()) {
            res += UpFlow();
        }
        return res;
    }
    void Result() {
        int dap[N];
        fill_n(dap, n+2, 0);
