LL checkMin(vector<LL> b, int card) {
	while (true) {
		if (card < 1) {
			LL ans = 0;
			REP(i, N + 1)ans += b[i];
			return ans;
		}
		LL point = 0;
		bool dif = false;
		for (int check = 1; card*check <= N; check++) {
			point += b[card*check];
			if (b[card*check] > 0)dif = true;
		}
		//消したら得なら
		if (point < 0) {
			//正の数が混じってるなら
			if (dif) {
				//消さない場合を試す
				vector<LL> c = b;
				LL ifnotDel = checkMin(c, card - 1);
				//消す場合を試す
				vector<LL> d = b;
				for (int check = 1; card*check <= N; check++) {
					d[card*check] = 0;
				}
				LL ifDel = checkMin(d, card - 1);

				//良い方を採用
				return max(ifDel, ifnotDel);
			}
			//全部負の数だけなら
			else {
				for (int check = 1; card*check <= N; check++) {
					b[card*check] = 0;
				}
			}
		}
		card--;
	}
}

