	for(LL i = 1;i <= n;i ++){
		for(LL j = i + 1;j <= n;j ++){
			if(j % i == 0) add_edge(i,j,INF);
		}
	}
	dinic(S,T);
	cout << sum - mxf << '\n';
	return 0;
}
