int source = 0,sink = 101,n,par[MAXN];
bool visited[105];
vector<int>adjList[105];

bool bfs(){
    for(int i = 0 ; i < 105 ; i++) visited[i] = 0;
    queue<int>q;
    q.push(source);
    visited[source] = true;
    par[source] = -1;
    while(!q.empty()){
        int now = q.front();
        q.pop();
        for(int nxt:adjList[now]){
            if(!visited[nxt] && cap[now][nxt] > 0){
                q.push(nxt);
                par[nxt] = now;
                visited[nxt] = true;
            }
        }
    }
    return visited[sink];
}

LL fordfulkerson(){
    LL max_flow = 0;
    int now,nxt;
    while(bfs()){
        LL path_flow = INF_LL;
        for(nxt = sink ; nxt != source ; nxt = par[nxt]){
            now = par[nxt];
            path_flow = min(path_flow,cap[now][nxt]);
        }
        for(nxt = sink ; nxt != source ; nxt = par[nxt]){
            now = par[nxt];
            cap[now][nxt] -= path_flow;
            cap[nxt][now] += path_flow;
        }
        max_flow += path_flow;
    }
    return max_flow;
}


