	if(xs[i] <= 0)
	  add_edge(G, S, i, -xs[i]);
	if(xs[i] > 0)
	  add_edge(G, i, T, xs[i]);
  }
  FOR(i,1,N+1){
	for(int j=i+i;j<=N;j+=i){
	  add_edge<LL>(G, i, j, INF);
	}
