        // We need to brute force for the range from [1, r]

        int64_t bst = 0;
        for (int i = 0; i < (1 << r); i++)
        {
                set<int> S;
                for (int j = 1; j <= r; j++)
                {
                        if (i & (1 << (j - 1)))
                        {
                                for (int k = j; k <= N; k += j)
                                        S.insert(k);
                        }
                }

                int64_t t = 0;
                for (set<int>::iterator it = S.begin(); it != S.end(); it++)
                {
                        if (!mark[*it])
                                t += A[*it];
                }

                //cout << i <<  " : " << t << endl;

                if (t < bst)
                        bst = t;
        }

        bd += bst;

        int64_t ans = sm - bd;
        printf("%lld\n", ans);

        return 0;
}

