    while (1) {
      priority_queue<P, vector<P>, greater<P>> d;
      for (ll i = n; i >= 1; i--) {
        ll sum = 0, sum2 = 0;
        for (ll j = i; j <= n; j += i) if (!used[j]) {
          sum += a[j];
          if (a[j] > 0) sum2 += a[j];
        }
        if (sum < 0) d.push(P(sum2, i));
      }
      if (d.empty()) break;
      P p = P(-1, -1);
      if (!d.empty()) p = d.top(), d.pop();
      while (!d.empty() && (rand() % 3 == 0)) p = d.top(), d.pop();
      for (ll j = p.second; j <= n; j += p.second) used[j] = true;
    }
    ll temp = 0;
    for (ll i = 1; i <= n; i++) if (!used[i]) temp += a[i], used[i] = false;
