        head=tail=0;
        q[tail]=t;
        dist[t]=0;
        tail++;
        while(head<tail){
            int u=q[head++];
            for(int e=last[u];e!=-1;e=next[e]){
                int v=to[e];
                if(cap[e^1]>0 && dist[v]==-1)
                    q[tail++]=v,dist[v]=dist[u]+1;
            }
        }
        return dist[s]!=-1;
