#define INF 10000000000000000LL

using namespace std;

struct edge {int to, rev; long long int cap;};

vector<edge> G[102];
int level[102];
int iter[102];

void add_edge(int from, int to, long long int cap){
	edge e;
	e.to=to, e.cap=cap, e.rev=G[to].size();
	G[from].push_back(e);
	e.to=from, e.cap=0, e.rev=G[from].size()-1;
	G[to].push_back(e);
}

void bfs(int s){
	memset(level, -1, sizeof(level));
	queue<int> que;
	level[s]=0;
	que.push(s);
	while(!que.empty()){
		int v=que.front();
		que.pop();
		for(int i=0; i<G[v].size(); i++){
			edge e=G[v][i];
			if(e.cap>0 && level[e.to]<0){
				level[e.to]=level[v]+1;
				que.push(e.to);
			}
		}
	}
}

long long int dfs(int v, int t, long long int f){
	if(v==t) return f;
	for(int &i=iter[v]; i<G[v].size(); i++){
		edge &e=G[v][i];
		if(e.cap>0 && level[v]<level[e.to]){
			long long int d=dfs(e.to, t, min(f, e.cap));
			if(d>0){
				e.cap-=d;
				G[e.to][e.rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(int s, int t){
	long long int flow=0;
	while(1){
		bfs(s);
		if(level[t]<0) return flow;
		memset(iter, 0, sizeof(iter));
		long long int f;
		while((f=dfs(s, t, INF))>0){
			flow+=f;
		}
	}
}

int main()
{
	int n;
	scanf("%d", &n);
	long long int a[101], psum=0;
	for(int i=1; i<=n; i++){
		scanf("%lld", &a[i]);
		if(a[i]>0){
			psum+=a[i];
			add_edge(i, n+1, a[i]);
		}else{
			add_edge(0, i, -a[i]);
		}
	}
	for(int d=1; d<n; d++){
		for(int k=d+1; k<=n; k++){
			if(k%d==0) add_edge(d, k, INF);
		}
	}
	printf("%lld\n", psum-max_flow(0, n+1));	
	return 0;
}

