    void reset(int n) {
        this -> n = n;
        ptr.clear(); d.clear(); g.clear(); e.clear();
        ptr.resize(n); d.resize(n); g.resize(n);
    }

    void addEdge(int u, int v, long long cap) {
        edge ee = {u, v, cap, 0};
        g[u].push_back(e.size());
        e.push_back(ee);
        ee = {v, u, 0, 0};
        g[v].push_back(e.size());
        e.push_back(ee);
    }

    long long getMaxFlow(int s, int t) {
        this -> s = s;
        this -> t = t;
        long long flow = 0;
        while (bfs()) {
            while (long long x = dfs(s, 1e18)) {
                flow += x;
            }
        }
        return flow;
    }
private:
    bool bfs() {
        REP(i, n) ptr[i] = 0;
        REP(i, n) d[i] = -1;
        d[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int id : g[u]) if (e[id].flow < e[id].cap) {
                int v = e[id].v;
                if (d[v] == -1) {
                    d[v] = d[u] + 1;
                    q.push(v);
                }
            }
        }
        return d[t] != -1;
    }

    long long dfs(int u, long long flow) {
        if (u == t || flow == 0) return flow;
        for (; ptr[u] < (int) g[u].size(); ++ptr[u]) {
            int id = g[u][ptr[u]];
            int v = e[id].v;
            if (d[v] == d[u] + 1 && e[id].flow < e[id].cap) {
                if (long long x = dfs(v, min(flow, e[id].cap - e[id].flow))) {
                    e[id].flow += x;
                    e[id^1].flow -= x;
                    return x;
                }
            }
        }
        return 0;
    }

}D;

