    dn.add(0, i + 1, max(0LL, -a[i]));
    dn.add(i + 1, n + 1, max(0LL, a[i]));
    for(int j = 2; j * (i + 1) <= n; ++j)
      dn.add(i + 1, j * (i + 1), inf);
  }
  cout << sum - dn.solve(0, n + 1) << endl;
  return 0;
}

