    w[++cnt]=W;to[cnt]=v;nxt[cnt]=a[u];a[u]=cnt;
}
bool bfs(){
    memset(d,-1,sizeof(d));
    memcpy(cur,a,sizeof(a));
    d[S]=0;
    int h=0,t=0;
    q[t++]=S;
    while (h!=t){
        int u=q[h++];h%=N;
        for (int i=a[u];i;i=nxt[i]) {
            int v=to[i];
            if (d[v]!=-1||w[i]<=0) continue;
            d[v]=d[u]+1;
            q[t++]=v;t%=N;
        }
    }
    return d[T]!=-1;
}
LL dfs(int u, LL f){
    if (u==T||f==0) return f;
    LL ret=0LL;
    for (int &i=cur[u];i;i=nxt[i]) if (w[i]>0&&d[to[i]]==d[u]+1) {
        int v=to[i];
        LL tmp=dfs(v,min(f-ret,w[i]));
        w[i]-=tmp;w[i^1]+=tmp;
        ret+=tmp;
        if (f==ret) return ret;
    }
    return ret;
}
