int bt6[8] = { 0, 1, 2, 3, 5, 7, 11, 15 };
int n, c, a[109]; bool choose[29], chosen[109], slc[109];
inline long long val(int pos) {
	return chosen[pos] ? 0 : a[pos];
}
long long dfs(int pos, long long sum) {
	if (pos > c) {
		for (int i = 1; i <= n; i++) chosen[i] = false, slc[i] = false;
		for (int i = 1; i <= n; i++) {
			if (choose[i]) {
				for (int j = i; j <= n; j += i) chosen[j] = true;
			}
		}
		// 6m which 2m > c
		long long res = sum;
		for (int i = c / 2 + 1; 6 * i <= n; i++) {
			long long rm = 0;
			for (int j = 0; j < 8; j++) {
				long long cur = 0;
				if (bt6[j] & 1) cur += val(2 * i);
				if (bt6[j] & 2) cur += val(3 * i);
				if (bt6[j] & 4) cur += val(4 * i);
				if (bt6[j] & 8) cur += val(6 * i);
				rm = max(rm, cur);
			}
			res += rm;
			slc[2 * i] = true;
			slc[3 * i] = true;
			slc[4 * i] = true;
			slc[6 * i] = true;
		}
		// 3m which m > c
		for (int i = c + 1; 3 * i <= n; i++) {
			if (!slc[i]) {
				res += max({ 0LL, val(i) + val(3 * i), val(i) + val(2 * i), val(i), val(i) + val(2 * i) + val(3 * i) });
				slc[i] = true;
				slc[2 * i] = true;
				slc[3 * i] = true;
			}
		}
		// 2m which m > c
		for (int i = c + 1; 2 * i <= n; i++) {
			if (!slc[i]) {
				res += max({ 0LL, val(i), val(i) + val(2 * i) });
				slc[i] = true;
				slc[2 * i] = true;
			}
		}
		// normal numbers
		for (int i = c + 1; i <= n; i++) {
			if (!slc[i]) res += max(0LL, val(i));
		}
		return res;
	}
	bool flag = false;
	for (int i = 1; i < pos; i++) {
		if (pos % i == 0 && choose[i]) flag = true;
	}
	choose[pos] = true;
	long long ret = dfs(pos + 1, sum);
	choose[pos] = false;
	if (!flag) {
		ret = max(ret, dfs(pos + 1, sum + a[pos]));
	}
	return ret;
}
long long brute_force() {
	long long ret = 0;
	for (int i = 0; i < 1 << n; i++) {
		long long res = 0;
		for (int j = 1; j <= n; j++) {
			bool flag = false;
			for (int k = 1; k <= j; k++) {
				if (j % k == 0 && (i & (1 << (k - 1)))) flag = true;
			}
			if (!flag) res += a[j];
		}
		ret = max(ret, res);
	}
	return ret;
}
