	for(int i=0;i<n;i++){
		scanf("%d",&a[i]);
		if(a[i]>0){
			sum+=a[i];
			di.add_edge(i,t,a[i]);
			di.add_edge(s,i,0);
		}
		if(a[i]==0){
			di.add_edge(s,i,0);
			di.add_edge(i,t,0);
		}
		if(a[i]<0){
			di.add_edge(s,i,-a[i]);
			di.add_edge(i,t,0);
