using namespace std;
class FF
{
public:
  struct edge{ll to,cap,rev;};
  vector<vector<edge>>G;
  vector<bool> used;
  FF(ll maxv)
  {
    G.resize(maxv);
    used.resize(maxv);
  }
  void add_edge(ll from,ll to,ll cap,bool directed=1)
  {
    G[from].push_back({to,cap,(ll)G[to].size()});
    G[to].push_back({from,cap*(!directed),(ll)G[from].size()-1});
  }
  ll dfs(ll v,ll t,ll f)
  {
    if(v==t)return f;
    used[v]=1;
    for(auto &nv:G[v])
    {
      if(!used[nv.to] && nv.cap>0)
      {
        ll d=dfs(nv.to,t,min(f,nv.cap));
        if(d>0)
        {
          nv.cap-=d;
          G[nv.to][nv.rev].cap+=d;
          return d;
        }
      }
    }
    return 0;
  }
  ll solve(ll s,ll t)
  {
    ll res=0;
    while(1)
    {
      for(ll i=0;i<used.size();i++)used[i]=0;
      ll f=dfs(s,t,(1<<30)-1);
      if(f==0)break;
      res+=f;
    }
    return res;
  }
};

