using namespace std;

typedef long long LL;

const int kMaxN = 105;
const int kInf = 0x3f3f3f3f;

struct Edge {int to, cap, rev;};

int N;
int a[kMaxN];
int st, ed; 
LL sum;
vector<Edge> G[kMaxN];
int level[kMaxN];
int iter[kMaxN];

void AddEdge(int s, int t, int cap)
{
  G[s].push_back((Edge){t, cap, (int)G[t].size()});
  G[t].push_back((Edge){s, 0, (int)G[s].size() - 1});
}

void bfs(int s)
{
  memset(level, -1, sizeof level);
  queue<int> que;
  level[s] = 0;
  que.push(s);
  while (!que.empty()) {
    int v = que.front(); que.pop();
    for (int i = 0; i < (int)G[v].size(); ++i) {
      Edge &e = G[v][i];
      if (e.cap > 0 && level[e.to] < 0) {
        level[e.to] = level[v] + 1;
        que.push(e.to);
      }
    }
  }
}

int dfs(int v, int t, int f)
{
  if (v == t) return f;
  for (int &i = iter[v]; i < (int)G[v].size(); ++i) {
    Edge &e = G[v][i];
    if (e.cap > 0 && level[v] < level[e.to]) {
      int d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}


LL GetMaxFlow(int s, int t)
{
  LL flow= 0;
  for (; ;) {
    bfs(s);
    if (level[t] < 0) return flow;
    memset(iter, 0, sizeof iter);
    int f;
    while ((f = dfs(s, t, kInf)) > 0) {
      flow += f;
    }
  }
}
void BuildG()
{
  st = N;
  ed = N + 1;
  for (int i = 0; i < N; ++i) {
    if (a[i] < 0) AddEdge(st, i, -a[i]);
    else AddEdge(i, ed, a[i]);
    // 1: 1 2 3 4
    // 0: 0 1 2 3

    // 2: 2 4 6 8
    // 1: 1 3 5 7
    for (int j = i + i + 1; j < N; j += i + 1) {
      AddEdge(i, j, kInf);
    }
  }
}

void Solve()
{
  BuildG();
  LL min_cut = GetMaxFlow(st, ed);
  LL ans = sum - min_cut;
  // printf("sum=%lld\tmin_cut=%lld\n", sum, min_cut);
  printf("%lld\n", ans);
}

int main()
{
  scanf("%d", &N);
  for (int i = 0; i < N; ++i) {
    scanf("%d", a + i);
    if (a[i] > 0) sum += a[i];
  }
  Solve();
  return 0; 
}

