struct EDGE
{
	int to;
	long long cap,flow,rev;
};
struct DINIC
{
	static const int maxn=200;
	long long M=1e15;
	int top[maxn],deep[maxn],s,t;
	vector<EDGE> v[maxn];
	bitset<maxn> u;
	void make_edge(int a,int b,long long cap)
	{
		v[a].push_back(EDGE{b,cap,0,v[b].size()});
		v[b].push_back(EDGE{a,0,0,v[a].size()-1});
	}
	long long dfs(int a,long long flow)
	{
		if(a==t||!flow)
			return flow;
		EDGE e;
		long long x;
		while(top[a]<v[a].size())
		{
			e=v[a][top[a]];
			if(deep[e.to]==deep[a]+1&&e.cap!=e.flow)
			{
				x=dfs(e.to,min(flow,e.cap-e.flow));
				if(x)
					return v[a][top[a]].flow+=x,v[e.to][e.rev].flow-=x,x;
			}
			top[a]++;
		}
		deep[a]=-1;
		return 0;
	}
	bool bfs()
	{
		int tmp;
		queue<int> q;
		u.reset(),u[s]=1,q.push(s),memset(deep,0,sizeof(deep));
		while(!q.empty())
		{
			tmp=q.front(),q.pop();
			for(EDGE e:v[tmp])
				if(!u[e.to]&&e.cap!=e.flow)
					u[e.to]=1,deep[e.to]=deep[tmp]+1,q.push(e.to);
		}
		return u[t];
	}
	long long max_flow(int _s,int _t)
	{
		long long flow=0,tflow;
		s=_s,t=_t;
		while(bfs())
		{
			memset(top,0,sizeof(top));
			while(tflow=dfs(s,M))
				flow+=tflow;
		}
		return flow;
	}
	void reset()
	{
		for(int i=0;i<maxn;i++)
			v[i].clear();
	}
}dinic;
