        if (a < 0) {
            g.add_edge(S, i, -a);
        } else {
            ans += a;
            g.add_edge(i, T, a);
        }
        for (int j = 2 * i; j <= N; j += i) {
            g.add_edge(i, j, INF);
        }
    }

    ans -= g.max_flow(S, T);
