using namespace std;

const long long INF = (1LL << 60);
long long cap[102][102];

long long search(int n, const vector<int>& level, vector<int>& itr, int cur, int t, long long f){
	if(cur == t) return f;
	for(int i=itr[cur];i<n;i++){
		if(cap[cur][i] > 0 && level[cur] < level[i]){
			long long d = search(n, level, itr, i, t, min(cap[cur][i], f));
			if(d > 0){
				itr[cur] = i;
				cap[cur][i] -= d;
				cap[i][cur] += d;
				return d;
			}
		}
	}
	itr[cur] = n;
	return 0;
}

long long maximumFlow(int n, int s, int t){
	long long res = 0;
	while(true){
		queue<int> qu; qu.push(s);
		vector<int> level(n, -1); level[s] = 0;
		vector<int> itr(n, 0);
		while(!qu.empty()){
			int cur = qu.front(); qu.pop();
			for(int i=0;i<n;i++){
				if(cap[cur][i] > 0 && level[i] == -1){
					level[i] = level[cur]+1;
					qu.push(i);
				}
			}
		}
		if(level[t] == -1) break;
		for(long long f;(f=search(n, level, itr, s, t, INF)) > 0;res+=f);
	}
	return res;
}

