			if(a < 0){
				cap[0][i] = -a;
			} else {
				cap[i][N+1] = a;
			}
		}
		for(int i=1;i<=N;i++){
			for(int j=2*i;j<=N;j+=i) cap[i][j] = INF;
		}
		cout << sum - maximumFlow(N+2, 0, N+1) << endl;
	}
}

