int N;
vector<long> gem;

long break_gem(int now, string broke){
	if(now == N){
		return 0;
	}else if(broke[now] == '1'){
		return break_gem(now + 1, broke);
	}else if(now >= N / 2){
		if(gem[now] < 0){
			broke[now] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else if(now >= N / 3){
		if(gem[now] < 0 && gem[now] + gem[now * 2 + 1] < 0){
			broke[now] = '1';
			broke[now * 2 + 1] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else if(now >= N / 4){
		int sum = gem[now];
		if(gem[now * 2 + 1] < 0){
			sum += gem[now * 2 + 1];
		}
		if(gem[now * 3 + 3] < 0){
			sum += gem[now * 3 + 3];
		}
		if(gem[now] < 0 && sum < 0){
			broke[now] = '1';
			broke[now * 2 + 1] = '1';
			broke[now * 3 + 3] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else{
		long ans = gem[now] + break_gem(now + 1, broke);
		for(int j = now; j < N; j += now + 1){
			broke[j] = '1';
		}
		return max(ans, break_gem(now + 1, broke));
	}
}

