using namespace std;

int primes[] = {2, 3, 5, 7};
vector<pair<int, int>> factorization(int n) {
	map<int,int> res;
	for(int i = 0; i < 4; ++i) {
		while(n % primes[i] == 0) {
			res[primes[i]]++;
			n /= primes[i];
		}
	}
	if(n != 1) {
		res[n] = 1;
	}
	vector<pair<int,int>> vp;
	EACH(i, res) vp.push_back(*i);
	return vp;
}

void dfs(int m, int v, vector<pair<int,int>> vp, vector<int> &res) {
	if(v >= vp.size()) {
		res.push_back(m);
		return;
	}
	for(int i = 0; i <= vp[v].second; ++i) {
		dfs(m, v + 1, vp, res);
		m *= vp[v].first;
	}
}

vector<int> getFact(int n) {
	auto fact = factorization(n);
	vector<int> res;
	dfs(1, 0, fact, res);
	sort(ALL(res));
	return res;
}

