    vector<vector<Edge> > edges(n+2);
    long long ans = 0;
    for(int i=1; i<=n; ++i){
        edges[source].push_back(Edge(i, max(0, a[i-1])));
        edges[i].push_back(Edge(sink, max(0, -a[i-1])));
        ans += max(0, a[i-1]);
        for(int j=i*2; j<=n; j+=i)
            edges[j].push_back(Edge(i, LLONG_MAX/2));
    }

    ans -= maxFlow(edges, source, sink);
    cout << ans << endl;

    return 0;
}

