}*con[maxn];
void addedge(int x,int y,ll c)
{
	node*p=new node;
	p->to=y;
	p->f=0;
	p->m=c;
	p->next=con[x];
	con[x]=p;
	p=new node;
	p->to=x;
	p->f=0;
	p->m=0;
	p->next=con[y];
	con[y]=p;
	con[x]->rev=con[y];
	con[y]->rev=con[x];
}
int s,t,n,a[maxn],de[maxn];
bool tag[maxn],vis[maxn];
int dl[maxn*1000],head,tail;
bool bfs()
{
	bool tmp=false;
	head=1;tail=0;
	memset(vis,0,sizeof(vis));
	dl[++tail]=s;vis[s]=true;de[s]=0;
	while(head<=tail)
	{
		int v=dl[head];
		if(v==t) tmp=true;
		for(node*p=con[v];p;p=p->next)
		if(!vis[p->to]&&p->f<p->m)
		dl[++tail]=p->to,de[p->to]=de[v]+1,vis[p->to]=true;
		head++;
	}
	return tmp;
}
ll dinic(int v,ll e)
{
	if(tag[v]) return 0;
	if(v==t) return e;
	ll o=0,temp=0;
	for(node*p=con[v];p&&e;p=p->next) 
	if(de[p->to]==de[v]+1&&p->f<p->m) 
	{ 
		o=dinic(p->to,min(e,p->m-p->f));
		e-=o;
		temp+=o;
		p->f+=o;
		p->rev->f-=o;
	} 
	if(temp==0) tag[v]=true;
	return temp;
} 
