const ll INF = 1e18;
const ld EPS = 1e-10;

struct edge{
    int to;
    ll cap;
    int rev;
};

const int MAX_V = 1e3;
vector<edge> es[MAX_V];
int d[MAX_V], pos[MAX_V];

void add_edge(int from, int to, ll cap){
    edge e1 = {to, cap, (int)es[to].size()}, e2 = {from, 0, (int)es[from].size()};
    es[from].emplace_back(e1), es[to].emplace_back(e2);
}

//sから各点への最短距離をbfsで計算する
void bfs(int s){
    fill(d, d+MAX_V, -1);
    queue<int> que;
    d[s] = 0;
    que.push(s);
    while(!que.empty()){
        int i = que.front();
        que.pop();
        for(auto &e: es[i]){
            if(e.cap > 0 && d[e.to] < 0){
                d[e.to] = d[i]+1;
                que.push(e.to);
            }
        }
    }
}

//最短距離での増加パスをdfsで探す
ll dfs(int now, int goal, ll flow){
    if(now == goal) return flow;
    for(int &i = pos[now]; i < es[now].size(); i++){
        edge &e = es[now][i];
        if(e.cap > 0 && d[now] < d[e.to]){
            ll f = dfs(e.to, goal, min(flow, e.cap));
            if(f > 0){
                e.cap -= f;
                es[e.to][e.rev].cap += f;
                return f;
            }
        }
    }
    return 0;
}

//sからtへの最大流を最大でO(V^2*E)で計算
ll max_flow(int s, int t){
    ll flow = 0;
    while(true){
        bfs(s);
        //sからtへの経路が存在しないとき
        if(d[t] < 0) break;
        fill(pos, pos+MAX_V, 0);
        while(true){
            ll f = dfs(s, t, INF);
            if(f == 0) break;
            flow += f;
        }
    }
    return flow;
}

int main(){
    int N; cin >> N;
    rep2(i, 1, N){
        rep2(j, 2, N/i) add_edge(i, i*j, INF);
    }
    ll ans = 0;
    rep2(i, 1, N){
        ll A; cin >> A;
        if(A > 0) add_edge(i, N+1, A), ans += A;
        else add_edge(0, i, -A);
    }
    cout << ans-max_flow(0, N+1) << endl;
}

