template<class T> struct flow {
  struct edge {
    int to;
    T cap, rev;
  };

  int n;
  vector<vector<edge>> g;
  vector<bool> used;

  flow(int n) : n(n) {
    g = vector<vector<edge>>(n);
    used = vector<bool>(n);
  }

  void add(int from, int to, T cap) {
    g[from].push_back({ to, cap, (T) g[to].size() });
    g[to].push_back({ from, 0, (T) g[from].size() - 1 });
  }

  T dfs(int v, int t, T f) {
    if (v == t) return f;
    used[v] = true;
    rep(i, g[v].size()) {
      edge &e = g[v][i];
      if (!used[e.to] && e.cap > 0) {
        T d = dfs(e.to, t, min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          g[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  T max_flow(int s, int t) {
    int flow = 0;
    while (true) {
      used = vector<bool>(n);
      int f = dfs(s, t, numeric_limits<T>::max());
      if (f == 0) return flow;
      flow += f;
    }
  }
};

