    for (int i=iter[v]; i<G[v].size(); i++) {
        edge &e = G[v][i];
        if (e.cap>0 && level[v]<level[e.to]) {
            long long d = dfs(e.to, t, min(e.cap, f));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
