void dfs () {
  ll cans = 0;

  for (int i = 1; i <= min(n, MAX_G - 1); i++) {
    if (cov[i] == 0) cans += arr[i];
  }

  for (int i = MAX_G; i <= n; i++) {
    if (!cov[i] && 2 * i <= n) {
      if (cov[2 * i]) {
        if (arr[i] > 0) {
          cans += arr[i];
        }
      } else {
        cans += max(arr[i] + arr[2 * i], max(arr[i], 0));
      }
    } else if (!(i % 2 == 0 && i / 2 >= MAX_G)) {
      if (!cov[i] && arr[i] > 0) {
        cans += arr[i];
      }
    }
  }
  ans = max(ans, cans);

  int bk = cur.empty() ? 1 : cur.back() + 1;
  for (int i = bk; i < MAX_G; i++) {
    if (!cov[i]) {
      for (int j = i; j < MAX_H; j += i) {
        cov[j]++;
      }
      cur.push_back(i);

      dfs();

      cur.pop_back();
      for (int j = i; j < MAX_H; j += i) {
        cov[j]--;
      }
    }
  }
}

