bool prime(int x) {
    if (x == 2) return true;
    if (x < 2) return false;
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr);
    int n;
    cin >> n;
    ll sum = 0;
    int k = 1;
    while (k * 2 <= n) ++k;
    vector<ll> p, a(n + 1);
    for (int i = 2; i < k; ++i) {
        if (prime(i)) p.push_back(i);
    }
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    for (int i = k; i <= n; ++i) {
        if (a[i] < 0) {
            a[i] = 0;
        }
    }
    for (int i = 1; i <= n; ++i) {
        sum += a[i];
    }
    int sz = p.size();
    ll res = max(0ll, sum);
    for (int mask = 0; mask < (1 << sz); ++mask) {
        ll qwe = 0;
        set<int> s;
        for (int j = 0; j < sz; ++j) {
             if ((mask >> j) & 1) {
                for (int c = p[j]; c <= n; c += p[j]) {
                    s.insert(c);
                }
            }
        }
        for (int x : s) {
            qwe += a[x];
        }
        res = max(res, sum - qwe);
    }
    cout << res << '\n';
}

