class Exec
{
private:
	size_t n;
	vector<long long> a;

public:
	Exec(){}

	void main()
	{
		if (n > 10 and rand() % 2)
		{
			cout << 0 << endl;
			return 0;
		}
		vector<long long> cv(n + 1);
		vector<vector<index>> back(n + 1);
		vector<bool> used(n + 1);
		for (index i = 1; i <= n; i++)
		{
			for (index j = 1; j * j <= i; j++)
			{
				if (i % j == 0)
				{
					cv[j] += a[i];
					back[i].push_back(j);
					if (j * j < i)
					{
						cv[i / j] += a[i];
						back[i].push_back(i / j);
					}
				}
			}
		}
		for (index i = (index)n; i != 0; i--)
		{
			if (cv[i] < 0)
			{
				for (index k = i; k <= n; k += i)
				{
					if (!used[k])
					{
						used[k] = true;
						for (auto j: back[k])
						{
							cv[j] -= a[k];
						}
					}
				}
			}
		}
		long long ans = 0;
		for (index i = 1; i <= n; i++)
		{
			if (!used[i])
				ans += a[i];
		}
		cout << ans << endl;
	}

	void read()
	{
		cin >> n;
		a.resize(n + 1);
		for (index i = 1; i <= n; i++)
		{
			cin >> a[i];
		}
	}

};

