using namespace std;

long long num[250];
bool good[250];
int n;

bool check(int k) {
    long long sum = 0;
    for(int i = k; i <= n; i+=k) {
        if(good[i]) sum += num[i];
    }
    //cout << sum << endl;
    if(sum <= 0) return true;
    long long lazy = 0;
    for(int i = k; i <= n; i+= k) {
    	if(!good[i]) continue;
        if(num[i] >= 0) {
            num[i] -= lazy;
            lazy = 0;
        }
        if(num[i] < 0){
        	lazy -= num[i];
        	num[i] = 0;
		}
    }
    return false;
}

void change(int k) {
    for(int i = k; i <= n; i+=k) {
        good[i] = false;
    }
}

int main() {
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) good[i] = true;
    for(int i = 1; i <= n; i++) scanf("%lld", &num[i]);
    long long ans = 0;
    for(int i = n; i >= 1; i--) {
        if(check(i)) {
            change(i);
            //cout << "change " << i << endl;
        }

    }
    for(int i = 1; i <= n; i++) {
        if(good[i]) ans += num[i];
    }
    cout << ans << endl;

}

