using Edge = pair<ll, ll>;
struct Graph
{
	ll vertex_count;
	vector<Edge> edges;
	Graph() : vertex_count(0), edges(0) {}
};

ll edmonds_karp(const Graph& graph, const vector<ll>& capacities, ll s, ll t)
{
	using Capacity =ll;
	using Vertex = ll;
	using Index = ll;
	using _Edge = tuple<Vertex, Vertex, Capacity, Index>;

	if (graph.edges.size() != capacities.size())
	{
		throw runtime_error("グラフの辺の要素数とコストの要素数は一致している必要があります。");
	}

	// 辺の隣接リストを作成
	vector<vector<_Edge>> edges(graph.vertex_count);
	for (ll i = 0; i < graph.edges.size(); ++i)
	{
		Vertex from, to;
		tie(from, to) = graph.edges[i];
		Capacity capacity = capacities[i];

		Index edge_index = edges[from].size();
		Index reverse_edge_index = edges[to].size();

		edges[from].emplace_back(from, to, capacity, reverse_edge_index);
		edges[to].emplace_back(to, from, 0, edge_index);
	}

	ll max_flow = 0LL;
	while (true)
	{
		// BFS
		queue<Vertex> queue;
		vector<_Edge*> prev_vertices(graph.vertex_count, nullptr);

		queue.emplace(s);
		while (prev_vertices[t] == nullptr && !queue.empty())
		{
			Vertex v = queue.front();
			queue.pop();
			for (Index i = 0; i < edges[v].size(); ++i)
			{
				auto& edge = edges[v][i];
				Vertex from, to;
				Capacity c;
				Index j;
				tie(from, to, c, j) = edge;

				if (c == 0 || prev_vertices[to] != nullptr) continue;
				prev_vertices[to] = &edge;
				queue.emplace(to);
			}
		}

		// 最小パスがなければループを抜ける
		if (prev_vertices[t] == nullptr) break;

		// 最小パスを見つける
		stack<_Edge*> path;
		Capacity min_capacity = 1LL << 60;
		path.emplace(prev_vertices[t]);
		while (get<0>(*path.top()) != s)
		{
			min_capacity = min(min_capacity, get<2>(*path.top()));
			path.emplace(prev_vertices[get<0>(*path.top())]);
		}
		min_capacity = min(min_capacity, get<2>(*path.top()));

		// Capacity を更新
		while (!path.empty())
		{
			auto& edge = *path.top();
			path.pop();
			get<2>(edge) -= min_capacity;
			get<2>(edges[get<1>(edge)][get<3>(edge)]) += min_capacity;
		}

		max_flow += min_capacity;
	}

	return max_flow;
}

ll edmonds_karp(const Graph& graph, const vector<ll>& capacities)
{
	return edmonds_karp(graph, capacities, 0LL, graph.vertex_count - 1LL);
}

