            X+=Cost[i];
            Adj[i].push_back(N+1);
            Cap[i][N+1]=Cost[i];
        } else {
            Adj[0].push_back(i);
            Cap[0][i]=-Cost[i];
        }
        for(int j=2*i;j<=N;j+=i){
            Adj[i].push_back(j);
            Cap[i][j]=INF;
        } 
    }
    Source=0;
    Sink=N+1;
    while(true){
        memset(Pre,-1,sizeof(Pre));
        DFS(Source);
        Flow=Augment(Sink,INF);
        if(Flow==0) break;
        Maxflow+=Flow;
    }
