#include<bits/stdc++.h>
using namespace std;

typedef long long ll;

/*
  最大流(Push-Relabel) : O(V^2*sqrt(E))
  PushRelabel(V) := 頂点数Vで初期化する
  add_edge(from,to,cap) := 頂点fromからtoに容量capの辺を張る
  max_flow(s,t) := sからtに最大流を流し、その流量を返す。
*/
// QT : https://ei1333.github.io/luzhiled/snippets/graph/push-relabel.html
template< typename flow_t >
struct PushRelabel {
  const flow_t INF;

  struct edge {
    int to;
    flow_t cap;
    int rev;
    bool isrev;
    int idx;
  };
  vector< vector< edge > > graph;
  vector< flow_t > ex;
  int relabels, high;
  vector< int > cnt, h;
  vector< vector< int > > hs;

  PushRelabel(int V) : graph(V), INF(numeric_limits< flow_t >::max()), hs(V + 1), high(0) {}


  void add_edge(int from, int to, flow_t cap, int idx = -1) {
    graph[from].emplace_back((edge) {to, cap, (int) graph[to].size(), false, idx});
    graph[to].emplace_back((edge) {from, 0, (int) graph[from].size() - 1, true, idx});
  }

  void update_height(int idx, int nxt_height) {
    ++relabels;
    if(h[idx] != graph.size() + 1) {
      --cnt[h[idx]];
    }
    h[idx] = nxt_height;
    if(h[idx] != graph.size() + 1) {
      high = nxt_height;
      ++cnt[nxt_height];
      if(ex[idx] > 0) hs[nxt_height].emplace_back(idx);
    }
  }

  void global_relabel(int idx) {
    for(int i = 0; i <= high; i++) hs[i].clear();
    relabels = 0;
    high = 0;
    h.assign(graph.size(), graph.size() + 1);
    cnt.assign(graph.size(), 0);
    queue< int > que;
    que.emplace(idx);
    h[idx] = 0;
    while(que.size()) {
      int p = que.front();
      que.pop();
      for(auto &e : graph[p]) {
        if(h[e.to] == graph.size() + 1 && graph[e.to][e.rev].cap > 0) {
          que.emplace(e.to);
          high = h[p] + 1;
          update_height(e.to, high);
        }
      }
    }
  }


  void push(int idx, edge &e) {
    if(h[e.to] == graph.size() + 1) return;
    if(ex[e.to] == 0) {
      hs[h[e.to]].emplace_back(e.to);
    }
    flow_t df = min(ex[idx], e.cap);
    e.cap -= df;
    graph[e.to][e.rev].cap += df;
    ex[idx] -= df;
    ex[e.to] += df;
  }

  void discharge(int idx) {
    int next_height = (int) graph.size() + 1;
    for(auto &&e : graph[idx]) {
      if(e.cap > 0) {
        if(h[idx] == h[e.to] + 1) {
          push(idx, e);
          if(ex[idx] <= 0) return;
        } else {
          next_height = min(next_height, h[e.to] + 1);
        }
      }
    }
    if(cnt[h[idx]] > 1) {
      update_height(idx, next_height);
    } else {
      for(; high >= h[idx]; hs[high--].clear()) {
        for(int j : hs[high]) update_height(j, graph.size() + 1);
      }
    }
  }

  flow_t max_flow(int s, int t) {
    ex.assign(graph.size(), 0);
    ex[s] = INF;
    ex[t] = -INF;
    global_relabel(t);
    for(auto &e : graph[s]) push(s, e);
    for(; high >= 0; high--) {
      while(!hs[high].empty()) {
        int idx = hs[high].back();
        hs[high].pop_back();
        discharge(idx);
        if(relabels >= graph.size() * 4) global_relabel(t);
      }
    }
    return ex[t] + INF;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      for(auto &e : graph[i]) {
        if(e.isrev) continue;
        auto &rev_e = graph[e.to][e.rev];
        cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
      }
    }
  }
};


int main(void){
	ll N;scanf("%lld",&N);
	vector<ll> a(N);
	for(int i = 0;i < N;i++)scanf("%lld",&a[i]);

	PushRelabel<long long> Flow(N + 2);
	int s = N,t = N+1;

	long long sum = 0;
	for (int i = 0; i < N; ++i)
	{
		if(a[i] >= 0){
			Flow.add_edge(s,i,0);
			Flow.add_edge(i,t,a[i]);
			sum += a[i];
		}else{
			Flow.add_edge(s,i,-a[i]);
			Flow.add_edge(i,t,0);
		}
	}

	for (int i = 0; i < N; ++i)
	{
		for (int j = i + 1; j < N; ++j)
		{	
			if((j+1)%(i+1)==0){
				Flow.add_edge(i,j,(1LL << 50));
			}
		}
	}
	long long res = Flow.max_flow(s,t);
    //Flow.output();
	cout << sum - res << endl;
}

#include<bits/stdc++.h>
using namespace std;

struct edge{long long t; long long c; long long r;};
vector<edge> G[105];
long long depth[105], n, INF=1e15, ans, a;

void add_edge(long long f, long long t, long long c){
	G[f].push_back(edge{t, c, (long long)G[t].size()});
	G[t].push_back(edge{f, 0, (long long)G[f].size()-1});
}

bool bfs(long long s, long long t){
	memset(depth,-1,sizeof(depth));
	depth[s] = 0;
	queue<long long> que;
	que.push(s);
	while(!que.empty()){
		long long v = que.front(); 
		que.pop();
		for(edge e: G[v]) if(e.c && depth[e.t] == -1){
			depth[e.t] = depth[v] + 1;
			que.push(e.t);
		}
	}
	return depth[t] != -1;
}

long long dfs(long long v, long long t, long long f){
	if(v == t) return f;
	long long ret = 0;
	for(edge& e: G[v]){
		if(depth[v] < depth[e.t] && e.c){
			long long d = dfs(e.t, t, min(f - ret, e.c));
			if(d){
				e.c -= d; 
                G[e.t][e.r].c += d;
				ret += d;
			}
		}
		if(f == ret) break;
	}
	return ret;
}

long long maxflow(long long s, long long t){
	long long ret = 0;
	while(bfs(s,t)) ret += dfs(s, t, INF);
	return ret;
}

int main(){
	cin>>n;
	for(long long i=1; i<=n; i++){
		cin>>a;
		if(a < 0) add_edge(0,i,-a);
		else{
			ans += a;
			add_edge(i,n+1,a);
		}
		for(long long j=i*2; j<=n; j+=i) add_edge(i,j,INF);
	}
	cout<<ans-maxflow(0,n+1)<<endl;
}

