inline void add_edge(int u, int v, int c) {
	g[u].pb(e.size());
	e.pb({v, c});

	g[v].pb(e.size());
	e.pb({u, 0});
}

int q[N], ql, qr;
bool used[N];

int ptr[N];

inline bool bfs() {
	memset(used, 0, sizeof(used));
	d[S] = 0;
	q[ql = qr = 0] = S;
	used[S] = true;
	while(ql <= qr) {
		int v = q[ql++];
		for(int ind : g[v]) {
			int to = e[ind].v, cap = e[ind].c;
			if(cap <= 0)
				continue;
			if(!used[to]) {
				used[to] = true;
				d[to] = d[v] + 1;
				q[++qr] = to;
			}
		}
	}
	return used[T];
}

int dfs(int v, int cmin) {
	if(v == T || cmin == 0)
		return cmin;
	for(; ptr[v] < g[v].size(); ++ptr[v]) {
		int ind = g[v][ptr[v]];
		int to = e[ind].v, cap = e[ind].c;
		if(cap <= 0)
			continue;
		if(d[to] == d[v] + 1) {
			int flow = dfs(to, min(cmin, cap));
			if(flow) {
				e[ind].c -= flow;
				e[ind ^ 1].c += flow;
				return flow;
			}
		}
	}
	return 0;
}

