template <class T> struct MaxFlowGraph {
    struct Edge {
        int u, v;
        T c, f;
    };
    const T eps = (T)1e-9;
    vector<Edge> E;
    vector<vector<int>> G;
    vector<int> P, D;
    int n, src, sink;
    T flow;

    MaxFlowGraph(int n, int src, int sink) : n(n), src(src), sink(sink) {
        assert(0 <= src && src < n && 0 <= sink && sink < n && src != sink);
