    }

    void clearFlow() {
        for (auto &e : E) {
            e.f = T();
        }
        flow = T();
    }
    void addEdge(int u, int v, T forward_cap, T backward_cap) {
        assert(0 <= u && u < n && 0 <= v && v < n);
        G[u].push_back(E.size());
        E.push_back({u, v, forward_cap, T()});
        G[v].push_back(E.size());
        E.push_back({v, u, backward_cap, T()});
    }

    bool expath() {
        fill(D.begin(), D.end(), -1);
        queue<int> Q;
        Q.push(sink);
        D[sink] = 0;
        while (!Q.empty()) {
            int u = Q.front();
            Q.pop();
            for (int id : G[u]) {
                const Edge &e = E[id];
                const Edge &back = E[id ^ 1];
                if (back.c - back.f > eps && D[e.v] == -1) {
                    D[e.v] = D[e.u] + 1;
                    if (e.v == src) {
                        return true;
                    }
                    Q.push(e.v);
                }
            }
        }
        return false;
    }

    T dfs(int u, T w) {
        if (u == sink) {
            return w;
        }
        for (int &i = P[u]; i < G[u].size(); i++) {
            int id = G[u][i];
            const Edge &e = E[id];
            if (e.c - e.f > eps && D[e.v] == D[e.u] - 1) {
                T t = dfs(e.v, min(e.c - e.f, w));
                if (t > eps) {
                    E[id].f += t;
                    E[id ^ 1].f -= t;
                    return t;
                }
            }
        }
        return T();
    }

    T maxFlow() {
        while (expath()) {
            fill(P.begin(), P.end(), 0);
            T tot = T();
            while (true) {
                T add = dfs(src, numeric_limits<T>::max());
                if (add <= eps) {
                    break;
                }
                tot += add;
            }
            if (tot <= eps) {
                break;
            }
            flow += tot;
        }
        return flow;
    }
    vector<bool> minCut() {
        maxFlow();
        vector<bool> R(n);
        for (int i = 0; i < n; i++) {
            R[i] = (D[i] != -1);
        }
        return R;
    }
    void reduce() {
        for (auto &e : E) {
            e.c -= e.f;
        }
    }
};

