void rec(int mask, int cur_b) {
    if (cur_b == 26) {
        fill(need + 1, need + 100 + 1, true);
        rep(i, 1, 25 + 1) {
            if ((mask >> i) & 1) {
                for (int j = i; j <= 100; j += i) {
                    need[j] = false;
                }
            }
        }
        ll cur = 0;
        rep(i, 1, 25 + 1) {
            if (need[i]) {
                cur += a[i];
            }
        }
        rep(i, 26, 33 + 1) {
            if (i % 2 == 1) {
                ll best = 0;
                setmax(best, need[i] * a[i] + max(0LL, need[i * 2] * a[i * 2]) + max(0LL, need[i * 3] * a[i * 3]));
                need[i] = need[i * 2] = need[i * 3] = false;
                cur += best;
            } else {
                ll best = max(0LL, need[i * 3 / 2] * a[i * 3 / 2]);
                setmax(best, need[i] * a[i] + max(0LL, need[i * 2] * a[i * 2]) + need[i * 3] * a[i * 3] + need[i * 3 / 2] * a[i * 3 / 2]);
                setmax(best, need[i] * a[i] + max(0LL, need[i * 2] * a[i * 2]) + max(0LL, need[i * 3 / 2] * a[i * 3 / 2]));
                need[i] = need[i * 2] = need[i * 3] = need[i * 3 / 2] = false;
                cur += best;
            }
        }
        rep(i, 34, 50 + 1) {
            ll best = max(0LL, need[i] * a[i] + max(0LL, need[i * 2] * a[i * 2]));
            need[i] = need[i * 2] = false;
            cur += best;
        }
        rep(i, 51, 100 + 1) {
            if (need[i]) {
                cur += max(0LL, a[i]);
            }
        }
        setmax(ans, cur);
        return;
    }
    if ((mask >> cur_b) & 1) {
        rec(mask, cur_b + 1);
    } else {
        rec(mask, cur_b + 1);
        for (int y = cur_b; y <= 25; y += cur_b) {
            mask |= (1 << y);
        }
        rec(mask, cur_b + 1);
    }
}

