long long int arr[101];
bool visited[101];

long long int findmin(long long int n){
	long long int ans = 0;
	long long int pos = -1;
	for(long long int i = 1; i<=n; i++){
		// if(visited[i]) continue;
		long long int local = 0;
		for(long long int j = i; j<=n; j+=i){
			if(!visited[j])	local += arr[j];
		}
		if(local < ans){
			ans = local;
			pos = i;
		}
	}
	if(ans >= 0){
		return -1;
	}
	return pos;
}

int main (){
	long long int n;
	cin>>n;
	for(long long int i = 1; i<=n; i++){
		cin>>arr[i];
		visited[i] = false;
	}
	while(true){
		long long int k = findmin(n);
		if(k == -1) break;
		for(long long int i = k; i<=n; i+=k){
			visited[i] = true;
		}
	}
	long long int a = 0;
	for(long long int i = 1; i<=n; i++){
		if(!visited[i])
			a += arr[i];
	}
	cout<<a<<endl;
	return 0;
}

