  int to, cap, rev;
};

const int INF = 1e18;
const int MOD = 1e9+7;

template<typename T> ostream& operator<<(ostream& s, const vector<T>& v) {
  int len = v.size();
  for (int i = 0; i < len; ++i) {
    s << v[i]; if (i < len - 1) s << " ";
  }
  return s;
}

void add_edge(vector< vector<edge> >& G, int from, int to, int cap) {
  G[from].push_back((edge){ to, cap, SIZE(G[to])   });
  G[to].push_back((edge){ from, 0, SIZE(G[from])-1 });
}

int dfs(vector< vector<edge> >& G, vector<bool>& used, int v, int t, int flow)
{
  if (v == t) {
    return flow;
  }
  used[v] = true;

  rep(i, 0, SIZE(G[v])) {
    edge& e = G[v][i];
    if (used[e.to] || e.cap == 0) {
      continue;
    }
    int d = dfs(G, used, e.to, t, min(e.cap, flow));
    if (d > 0) {
      e.cap -= d;
      G[e.to][e.rev].cap += d;
      return d;
    }
  }

  return 0;
}

int max_flow(vector< vector<edge> >& G, int s, int t)
{
  int flow = 0;
  vector<bool> used(SIZE(G));
  for (;;) {
    fill(ALL(used), false);
    int f = dfs(G, used, s, t, INF);
    if (f==0) {
      return flow;
    }
    flow += f;
  }
}


