    for(int i=0;i<n;i++){
      if((i+1)%(start+1) == 0){
        b[i] = 0;
      }else{
        b[i] = a[i];
      }
    }
    res = max(maxMoney(a,n,start+1)+a[start],maxMoney(b,n,start+1));
  }else{
    res = maxMoney(a,n,start+1)+a[start];
  }

  return res;

}


