#include<bits/stdc++.h>
using namespace std;

const int N=110;
typedef long long ll;
const ll inf=1e18;
struct Edge{
	int from,to;ll cap;
	Edge(int from=0,int to=0,ll cap=0):from(from),to(to),cap(cap){}
};
vector<Edge>edges;
vector<int>G[N];
int cur[N],d[N],q[N],S,T;
void add_edge(int x,int y,ll z){
	G[x].push_back(edges.size());edges.emplace_back(x,y,z);
	G[y].push_back(edges.size());edges.emplace_back(y,x,0);
}

bool bfs(){
	memset(d,-1,sizeof d);d[T]=0;
	int t=-1,w=-1;q[++w]=T;
	for(int x=q[++t];t<=w;x=q[++t])
		for(int i:G[x])
			if(!~d[edges[i].to]&&edges[i^1].cap)
				d[q[++w]=edges[i].to]=d[x]+1;
	return~d[S];
}
ll dfs(int x,ll a){
	if(x==T||!a)return a;
	ll fw=0,f;
	for(int&I=cur[x],i;I<(int)G[x].size();++I)
		if(d[x]==d[edges[i=G[x][I]].to]+1&&(f=dfs(edges[i].to,min(a,edges[i].cap)))){
			edges[i].cap-=f;edges[i^1].cap+=f;fw+=f;a-=f;
			if(!a)break;
		}
	return fw;
}

ll maxflow(){
	ll fw=0;
	for(;bfs();fw+=dfs(S,inf))memset(cur,0,sizeof cur);
	return fw;
}


int n,a[N];
ll ans;
int main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>n;S=0;T=n+1;
	for(int i=1;i<=n;++i)cin>>a[i];
	for(int i=1;i<=n;++i)
		if(a[i]>0)add_edge(S,i,a[i]),ans+=a[i];
		else{
			add_edge(i,T,-a[i]);
			for(int j=i+i;j<=n;j+=i)add_edge(j,i,inf);
		}
	ans-=maxflow();
	cout<<ans<<'\n';
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define INF 10000000000
using ll=long long;

struct max_flow
{
    struct edge{ll to,cap,rev;};
    ll V;
    vector<vector<edge>> graph;
    vector<vector<ll>> flow;
    vector<pair<ll,ll>> prev;
public:

    max_flow(ll n)
    {
        V=n;
        graph.resize(V,vector<edge>());
        flow.resize(V,vector<ll> (V,0));
        prev.resize(V);
    }

    void add_edge(ll from,ll to, ll cap)
    {
        graph[from].push_back((edge){to,cap,(ll)graph[to].size()});
        graph[to].push_back((edge){from,0,(ll)graph[from].size()-1});
        return;
    }
    bool bfs(ll s,ll t)
    {
        vector<bool> visit(V,false);
        for (ll i=0;i<V;i++) prev[i]=make_pair(-1,-1);
        vector<ll> d(V,INF);
        visit[s]=true;prev[s].first=s;d[s]=0;
        queue<ll> que;
        que.push(s);
        ll v;
        while (!que.empty())
        {
            v=que.front();
            que.pop();
            for (ll i=0;i<graph[v].size();i++)
            {
                edge e=graph[v][i];
                if (!visit[e.to] && d[e.to]>d[v]+1 && e.cap>0)
                {
                    prev[e.to]=make_pair(v,i);
                    d[e.to]=d[v]+1;
                    visit[e.to]=true;
                    que.push(e.to);
                }
            }
        }
        return prev[t].first!=-1;
    }

    void update(ll from,ll to, ll f,ll edgenum)
    {
        edge e=graph[from][edgenum];
        if (flow[from][to]>=0)
        {
            flow[from][to]+=f;
            graph[from][edgenum].cap-=f;
            graph[e.to][e.rev].cap+=f;
        }
        if (flow[to][from]>0)
        {
            flow[to][from]-=f;
            graph[from][edgenum].cap-=f;
            graph[e.to][e.rev].cap+=f;
        }
        return;
    }

    ll run(ll s,ll t)
    {
        ll from,to,f,ans=0;
        while(bfs(s,t))
        {
            from=-1;to=t;f=INF;
            while (from!=s)
            {
                from=prev[to].first;
                f=min(f,graph[from][prev[to].second].cap);
                to=from;
            }
            to=t;from=-1;
            while (from!=s)
            {
                from=prev[to].first;
                update(from,to,f,prev[to].second);
                to=from;
            }
            ans+=f;
        }
        return ans;
    }
};

int main()
{
    ll N;cin >> N;

    ll ans=0;
    max_flow solve(N+2);
    ll a;
    for (ll i=0;i<N;i++)
    {
        cin >> a;
        if (a<=0)
        {
            solve.add_edge(0,i+1,-a);
            for (ll j=2;j*(i+1)<=N;j++) 
            {
                solve.add_edge(i+1,j*(i+1),INF);
            }
        }
        else
        {
            ans+=a;
            solve.add_edge(i+1,N+1,a);
            for (ll j=2;j*(i+1)<=N;j++) 
            {
                solve.add_edge(i+1,j*(i+1),INF);
            }
        }
    }
    cout << ans-solve.run(0,N+1) << endl;
return 0;
}

