template<class T>
inline WeightedGraph<T>::WeightedGraph(int size) 
	: graph_m(size) {
}

template<class T>
inline void WeightedGraph<T>::init(int new_size) {
	graph_m.init(new_size);
}

template<class T>
inline void WeightedGraph<T>::add(int from, int to, T&& weight) {
	graph_m.add(from, to);
	weights_m.push_back(std::move(weight));
}

template<class T>
inline void WeightedGraph<T>::add(int from, int to, const T& weight) {
	graph_m.add(from, to);
	weights_m.push_back(weight);
}

template<class T>
inline const Graph& WeightedGraph<T>::getGraph() const {
	return graph_m;
}

template<class T>
inline const std::vector<T>& WeightedGraph<T>::getWeights() const {
	return weights_m;
}

template<class T>
inline std::string WeightedGraph<T>::toString() const {
	std::ostringstream stream;
	for (int from = 0; from < graph_m.size(); ++from) {
		stream << from << ": [";
		for (auto id : graph_m.row(from)) {
			const auto& edge = graph_m.getEdge(id);
			int to = edge.to;
			stream << ' ' << to << '(' << weights_m[id] << ')';
		}
		stream << " ]" << std::endl;
	}
	return stream.str();
}

template<class T>
inline void WeightedGraph<T>::debug() const {
	std::cerr << toString() << std::endl;
}

template <class T>
WeightedGraph<T> inputWeightedGraph(int size, int edge_count, bool directed = true, bool one_based = true, std::istream& ist = std::cin);

template <class T>
WeightedGraph<T> inputWeightedGraph(int size, int edge_count, bool directed, bool one_based, std::istream& ist) {
	WeightedGraph<T> ret(size);
	for (int j = 0; j < edge_count; ++j) {
		int a, b;
		T weight;
		ist >> a >> b >> weight;
		if (one_based) {
			--a; --b;
		}

		if (directed) {
			ret.add(a, b, weight);
		} else {
			ret.add(a, b, weight);
			ret.add(b, a, weight);
		}
	}
	return ret;
}

