/// --- Dinic Libary {{{ ///
// solve max flow

struct Dinic {
  struct Edge {
    int to; ll cap; int rev;
    Edge(int to, ll cap, int rev):
      to(to), cap(cap), rev(rev) {}
  };

  int size;
  vector< vector< Edge > > g;
  ll inf;
  Dinic(int size, ll inf = 1e18): size(size), g(size), inf(inf) {}

  void addEdge(int a, int b, ll cap, bool undirected = false) {
    g[a].emplace_back(b, cap, g[b].size());
    g[b].emplace_back(a, undirected ? cap : 0, g[a].size() - 1);
  }

  ll solve(int s, int t) {
    vector<int> level(size);
    ll flow = 0;
    while(bfs(s, level), level[t] > 0) {
      ll newflow = dfs(s, t, inf, level);
      if(newflow == 0) break;
      flow += newflow;
      if(flow >= inf) return inf;
    }
    return flow;
  }

  private:
  void bfs(int s, vector<int> & level) {
    fill(begin(level), end(level), -1);
    queue<int> q;
    q.push(s);
    level[s] = 0;
    while(q.size()) {
      int i = q.front(); q.pop();
      for(Edge edge : g[i])
        if(level[edge.to] == -1 && edge.cap > 0) {
          level[edge.to] = level[i] + 1;
          q.push(edge.to);
        }
    }
  }

  ll dfs(int i, int t, ll flow, vector<int> const & level) {
    if(i == t) return flow;
    for(Edge &edge : g[i])
      if(edge.cap > 0 && level[edge.to] > level[i]) {
        ll newflow = dfs(edge.to, t, min(flow, edge.cap), level);
        if(newflow == 0) continue;
        edge.cap -= newflow;
        g[edge.to][edge.rev].cap += newflow;
        return newflow;
      }
    return 0;
  }
};

