class MaxFlow{
public:
    struct edge{int to,rev;ll cap;};
    static const int MV=10000;
    vector<edge> E[MV];
    bool used[MV];
    void add_edge(int from, int to, ll cap, bool undir=false){
        E[from].push_back({to,(int)E[to].size(),cap});
        E[to].push_back({from,(int)E[from].size()-1,undir?cap:0});
    }
    ll dfs(int v, int t, ll f){
        if(v==t) return f;
        used[v]=true;
        for(auto& e:E[v]){
            if(!used[e.to]&&e.cap>0){
                ll d=dfs(e.to,t,min(f,e.cap));
                if(d>0){
                    e.cap-=d;
                    E[e.to][e.rev].cap+=d;
                    return d;
                }
            }
        }
        return 0;
    }
    ll maxflow(int s, int t){
        ll flow=0;
        while(true){
            mem(used,false);
            ll f=dfs(s,t,numeric_limits<ll>::max());
            if(f==0) return flow;
            flow+=f;
        }
    }
};

