void update() {
	for (ll i = 1; i <= n; ++i) sum[i] = 0;
	for (ll i = 1; i <= n; ++i) {
		for (ll j = i; j <= n; j += i) {
			sum[i] += a[j];
		}
	}
}

bool check() {
	bool ans = false;
	for (ll i = 1; i <= n; ++i) {
		ans |= sum[i] < 0;
	}
	return ans;
}

int main() {
	cin >> n;
	for (ll i = 1; i <= n; ++i) cin >> a[i];
	update();
	while (check()) {
		ll index = 0;
		ll m = 1e12;
		for (ll i = 1; i <= n; ++i) {
			if (m >= sum[i]) {
				m = sum[i];
				index = i;
			}
		}
		for (ll i = index; i <= n; i += index) a[i] = 0;
		update();
	}
	ll ans = 0;
	for (ll i = 1; i <= n; ++i) {
		ans += a[i];
	}
	cout << ans << endl;
	return 0;
}

