    G[from].push_back((edge){to, cap, sz(G[to])});
    G[to].push_back((edge){from, 0, sz(G[from])-1});
  }

  void bfs(int s) {
    level.assign(V,-1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for(auto &e: G[v]) if(e.cap>0 && level[e.to]<0){
        level[e.to] = level[v] + 1;
        q.push(e.to);
      }
    }
  }

  ll dfs(int v, int t, ll f) {
    if(v==t) return f;
