      edge& e = G[v][i];
      if(e.cap>0 && level[v]<level[e.to]) {
        ll d = dfs(e.to, t, min(f, e.cap));
        if(d>0) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  ll run(int s, int t) {
    ll ret = 0, f;
    while(bfs(s), level[t] >= 0) {
      itr.assign(V, 0);
      while ((f=dfs(s, t, linf)) > 0) ret += f;
    }
    return ret;
  }
};

