const int magic = 50;

bool Get(long long used0, long long used1, int ind) {
	if (ind < magic) {
		return ((used0 >> ind) & 1);
	}
	return ((used1 >> (ind - magic)) & 1);
}

void Or(long long& used0, long long& used1, int ind) {
	if (ind < magic) {
		used0 |= (1LL << ind);
	} else {
		used1 |= (1LL << (ind - magic));
	}
}

long long Go(const vector<int>& a, int n, long long used0, long long used1, int ind) {
	if ((ind + 1) * 3 > n) {
		long long res = 0;
		for (int i = ind; i < n; ++i) {
			if (Get(used0, used1, i)) {
				continue;
			}

			if ((i & 1) && ((i - 1) >> 1) >= ind) {
				continue;
			}

			if (2 * i + 1 < n) {
				if (Get(used0, used1, 2 * i + 1)) {
					res += max(a[i], 0);
				} else {
					res += max(a[i] + a[2 * i + 1], max(a[i], 0));
				}
			} else {
				res += max(a[i], 0);
			}
		}
		return res;
	}

	if (Get(used0, used1, ind)) {
		return Go(a, n, used0, used1, ind + 1);
	}

	long long new_used0 = used0;
	long long new_used1 = used1;
	for (int x = ind + 1; x <= n; x += (ind + 1)) {
		Or(new_used0, new_used1, x - 1);
	}

	return max(a[ind] + Go(a, n, used0, used1, ind + 1), Go(a, n, new_used0, new_used1, ind + 1));
}

