using namespace std;

int64_t solve(vector<int>& V) {
    int K = min(10, int(V.size()));

    int64_t best = numeric_limits<int64_t>::min();
    for (int i = 0; i < (1 << K); ++i) {
        vector<int> newV = V;

        for (int j = 0; j < K; ++j)
            if ((1 << j) & i)
                for (int k = j; k < int(V.size()); k += (j + 1))
                    newV[k] = 0;
        if (K == int(V.size())) {
            int64_t aux = 0;
            for (auto &x : newV)
                aux += x;
            best = max(best, aux);
            continue;
        }

        int64_t aux = 0;
        for (int j = 0; j < K; ++j)
            aux += newV[j];

        vector<int> temp;
        vector<bool> marked(V.size(), false); 
        for (int j = K; j < int(V.size()); ++j)
            if (!marked[j]) {
                temp.clear();
                for (int k = j; k < int(V.size()); k += (j + 1)) {
                    marked[k] = true;
                    temp.push_back(newV[K]);
                }
                aux += solve(temp);
            }
        best = max(best, aux);
    }
    return best;
}

