                }
                if(ar[i+i]+ar[i]>0LL){
                    ret += ar[i];
                }
                else{
                    ret -= ar[i+i];
                }
            }
            else if(used[i]==0 && ar[i]>0LL){
                ret += ar[i];
            }
        }
        return ret;
