      if(a>=0){
        sum += a; // 無条件で貰えるお金
        flow.add_edge(0, id, a); // waru
        flow.add_edge(id, N+1, 0);
      }else{
        flow.add_edge(0, id, 0);
        flow.add_edge(id, N+1, -a);
      }
    }

    FOR(i, 1, N){
      // iの倍数へのエッジ
      FOR(m, 2, 101){
        if(i*m>N)break;
        flow.add_edge(m*i, i, inf);
      }
    }

    ll penalty = flow.calc(0, N+1);
    ll ans = sum - penalty;
    p(ans);

    return 0;
}

