inline void addEdge(int a, int b, ll cap) {
  g[a].push_back((Edge){b, int(g[b].size()), cap, false});
  g[b].push_back((Edge){a, int(g[a].size())-1, 0, true});
}
bool bfs(int s, int t) {
  int bg = 0, ed = 0;
  memset(dist, -1, sizeof dist);
  for(dist[q[ed++]=t] = 0; bg < ed; iter[q[bg++]] = 0)
    FOR(e, g[q[bg]])
      if(dist[e->dst] < 0 && g[e->dst][e->opp].cap > 0)
        dist[q[ed++]=e->dst] = dist[q[bg]] + 1;
  return dist[s] >= 0;
}
ll go(int cur, int t, ll amount) {
  if(cur == t) return amount;
  for(int& i = iter[cur]; i < (int)g[cur].size(); ++i){
    Edge& e = g[cur][i];
    if(e.cap > 0 && dist[e.dst] < dist[cur]){
      ll res = go(e.dst, t, min(amount, e.cap));
      if(res > 0){
        e.cap -= res;
        g[e.dst][e.opp].cap += res;
        return res;
      }
    }
  }
  return 0;
}
ll maxFlow(int s, int t) {
  ll res = 0;
  for(; bfs(s, t); )
    for(ll amount; (amount = go(s, t, INF)); res += amount);
  return res;
}

