int gcd(int a, int b) {
    if (b == 0) return a;
    if (b > a) swap(a,b);
    a %= b;
    return gcd(b,a);
}

void resolve() {
    int n;
    cin >> n;
    VI a(n);
    REP(i,0,n) cin >> a[i];
    VI ss(n+1);
    REP(i,0,n) REP(j,0,n) {
        if ((i+1) % (j+1) == 0) ss[j+1] += a[i];
    }
    int ans = min(0, ss[1]);
    //cerr << ss[1] << endl;
    REP (i,2,n+1) {
        ans = min(ans, ss[n]);
        //cerr << i << ":" << ss[i] << endl;
    }
    REP (i,2,n+1) REP (j,i+1,n+1) {
        if (i * j / gcd(i,j) > n) continue;
        ans = min(ans, ss[i] + ss[j] - ss[i * j / gcd(i,j)]);
    }
    REP (i,2,n+1) REP (j,i+1,n+1) REP (k,j+1,n+1) {
        if (i * j / gcd(i,j) > n) continue;
        if (j * k / gcd(j,k) > n) continue;
        if (k * i / gcd(k,i) > n) continue;
        if (i * j * k / gcd(gcd(i,j),k)) continue;
        ans = min(ans, ss[i] + ss[j] + ss[k] 
            - ss[i * j / gcd(i,j)] - ss[j * k / gcd(j,k)] - ss[k * i / gcd(k,i)]
            + ss[i * j * k / gcd(gcd(i,j),k)]);
    }
    cout << ss[1] - ans << endl;
}

