using namespace std;

bitset <100> maskdiv[100], full, invmaskdiv[100];
int n;
vector <int> a;
long long ans=0ll;
void bruteForcePrune(long long potential, long long curr=0ll, bitset <100> currmask=full, int pos=1){
	if(potential+curr<=ans)
		return;
	if(pos==n){
		ans=curr;
		return;
	}
	if(!currmask[pos]){
		return bruteForcePrune(potential-max(a[pos], 0), curr, currmask, pos+1);
	}
	if(a[pos]>=0){
		return bruteForcePrune(potential-a[pos], curr+a[pos], currmask, pos+1);
	}
	bruteForcePrune(potential, curr+a[pos], currmask, pos+1);
	bitset <100> toDelete=currmask&maskdiv[pos];
	for(int i = pos;i < n;i ++){
		if(toDelete[i]){
			if(a[i]>0){
				potential-=a[i];
			}
		}
	}
	return bruteForcePrune(potential, curr, currmask&invmaskdiv[pos], pos+1);
}
