			mf.add(i, T, a[i]);
			mf.add(S, i, 0);
			psm += a[i];
		}else{
			mf.add(S, i, -a[i]);
			mf.add(i, T, 0);

		}
	}
	rep(i,n) rep2(j, i+1,n){
		if((j+1)%(i+1)==0) mf.add(i, j, mf.INF);
	}
	ll res = mf.exec(S, T);
	cout << psm - res <<"\n";
	return 0;
}

