const int N = 100 * 2 + 10;
vector<Edge> g[N];

map<Edge, lli> cap;
map<Edge, lli> flow;

void add_edge(int src, int dst, lli c)
{
  Edge a(src, dst);
  Edge b = a.reverse();
  g[a.src].push_back(a);
  g[b.dst].push_back(b);
  cap[a] += c;
  cap[b] += 0;
  return ;
}

// EdmondsKarp
lli max_flow(int src, int snk)
{
  lli sum = 0;
  Edge path[N];
  while (true) {
    fill(path, path + N, Edge());
    queue<int> q;
    set<int> vis;
    vis.insert(src);
    for (q.push(src); q.size(); q.pop()) {
      each (e, g[q.front()]) {
        if (vis.count(e.dst)) continue;
        if (0 < cap[e]) {
          vis.insert(e.dst);
          q.push(e.dst);
          path[e.dst] = e;
        }
      }
    }
    if (path[snk] == Edge{}) {
      break;
    }
    lli mn = 1LL << 60;
    for (Edge e = path[snk]; e.src != e.dst; e = path[e.src]) {
      mn = min(mn, cap[e]);
    }
    for (Edge e = path[snk]; e.src != e.dst; e = path[e.src]) {
      cap[e] -= mn;
      cap[e.reverse()] += mn;
      flow[e] += mn;
      flow[e.reverse()] -= mn;
    }
    sum += mn;
  }

  return sum;
}

lli min_cut(int src, int snk)
{
  return max_flow(src, snk);
}

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    fill(g, g + N, vector<Edge>());
    cap.clear();
    flow.clear();

    vector<int> a(n);
    each (i, a) cin >> i;

    const int src = N - 1;
    const int snk = N - 2;
    const lli inf = 1LL << 60;

    for (int i = 0; i < n; ++i) {
      for (int j = i + 1; j < n; ++j) {
        if ((j + 1) % (i + 1) == 0) {
          add_edge(i, j, inf);
        }
      }
    }

    for (int i = 0; i < n; ++i) {
      if (0 <= a[i]) {
        add_edge(i, snk, a[i]);
      } else {
        add_edge(src, i, -a[i]);
      }
    }

    lli sum = 0;
    each (i, a) {
      sum += (0 < i) * i;
    }
    cout << sum - min_cut(src, snk) << endl;
  }

  return 0;
}

