const int MAXN = 110;
const int MAXP = MAXN;
const int MAXM = MAXN * MAXN * 5;
typedef long long LL;
const LL INFL = 0x3f3f3f3f3f3f3f3fLL;
int head[MAXP], nxt[MAXM], to[MAXM], tot = 1;
LL val[MAXM];
void addedge(int b, int e, LL v) {
	nxt[++tot] = head[b]; to[head[b] = tot] = e; val[tot] = v;
	nxt[++tot] = head[e]; to[head[e] = tot] = b; val[tot] = 0;
}
std::queue<int> q;
int dis[MAXP];
int S, T, idx;
bool bfs() {
	memset(dis, 0, idx + 1 << 2);
	q.push(S); dis[S] = 1;
	while (!q.empty()) {
		int t = q.front(); q.pop();
		for (int i = head[t]; i; i = nxt[i])
			if (val[i] && !dis[to[i]]) {
				dis[to[i]] = dis[t] + 1;
				q.push(to[i]);
			}
	}
	return dis[T] > 0;
}
LL dinic(int u, LL minv) {
	if (u == T || !minv) return minv;
	LL t, res = 0;
	for (int & i = head[u]; i; i = nxt[i])
		if (val[i] && dis[to[i]] == dis[u] + 1 && (t = dinic(to[i], std::min(minv, val[i])))) {
			val[i] -= t;
			val[i ^ 1] += t;
			res += t;
			minv -= t;
			if (!minv) break;
		}
	if (!res) dis[u] = -1;
	return res;
}
LL flow() {
	static int es[MAXP];
	memcpy(es, head, idx + 1 << 2);
	LL res = 0;
	while (bfs()) {
		res += dinic(S, INFL);
		memcpy(head, es, idx + 1 << 2);
	}
	return res;
}

LL A[MAXN]; int n;
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n;
	LL ans = 0;
	for (int i = 1; i <= n; ++i)
		std::cin >> A[i], ans += A[i], A[i] = -A[i];
	for (int i = 1; i <= n; ++i)
		for (int j = i + 1; j <= n; ++j)
			if (j % i == 0)
				addedge(i, j, INFL);
	S = 0, T = idx = n + 1;
	for (int i = 1; i <= n; ++i) {
		if (A[i] >= 0) addedge(S, i, A[i]), ans += A[i];
		else addedge(i, T, -A[i]);
	}
	std::cout << ans - flow() << std::endl;
	return 0;
}

