ll const MAX_V = 1000;

//
// 最大流
//
std::vector<bool> used(MAX_V);
std::vector<S_Edge> G[MAX_V];

void add_edge(ll from, ll to, ll cap)
{
  G[from].push_back((S_Edge){to, cap, (ll)G[to].size()});
  G[to].push_back((S_Edge){from, 0, (ll)G[from].size()-1});
}

// flow を返す
ll dfs(ll v, ll target, ll flow)
{
  if (v == target) {
    return flow;
  }
  used[v] = true;
  for (ll i = 0; i < (ll)G[v].size(); i++) {
    S_Edge& edge = G[v][i];
    if (!used[edge.to] && edge.cap > 0) {
      ll d = dfs(edge.to, target, std::min(edge.cap, flow));
      if (d > 0) {
	edge.cap -= d;
	G[edge.to][edge.rev].cap += d;
	return d;
      }
    }
  }

  return 0LL;
}

ll max_flow(ll start, ll end)
{
  ll max_flow_val = 0LL;
  for(;;) {
    std::fill(used.begin(), used.end(), false);
    ll flow = dfs(start, end, INF);
    if (flow == 0) return max_flow_val;
    max_flow_val += flow;
  }
}

