		for(int i = 1; i <= N; i++){
			for(int j = 0; j < PN; j++){
				if( (s & (1<<j)) && i % prime[j] == 0){
					tmp += a[i];
					break;
				}
			}
		}
		ans = min(ans, tmp);
	}

	for(int i = 0; i < 10; i++){
		if(Lprime[i] >= N) continue;
		if(a[Lprime[i]] < 0) ans += a[Lprime[i]];
	}


	cout << max(sum - ans, (llint)0) << endl;
	return 0;
}

