using ll=long long;

struct max_flow
{
    struct edge{ll to,cap,rev;};
    ll V;
    vector<vector<edge>> graph;
    vector<pair<ll,ll>> prev;
public:

    max_flow(ll n)
    {
        V=n;
        graph.resize(V,vector<edge>());
        prev.resize(V);
    }

    void add_edge(ll from,ll to, ll cap)
    {
        graph[from].push_back((edge){to,cap,(ll)graph[to].size()});
        graph[to].push_back((edge){from,0,(ll)graph[from].size()-1});
        return;
    }
    bool bfs(ll s,ll t)
    {
        vector<bool> visit(V,false);
        for (ll i=0;i<V;i++) prev[i]=make_pair(-1,-1);
        vector<ll> d(V,INF);
        visit[s]=true;prev[s].first=s;d[s]=0;
        queue<ll> que;
        que.push(s);
        ll v;
        while (!que.empty())
        {
            v=que.front();
            que.pop();
            for (ll i=0;i<graph[v].size();i++)
            {
                edge e=graph[v][i];
                if (!visit[e.to] && d[e.to]>d[v]+1 && e.cap>0)
                {
                    prev[e.to]=make_pair(v,i);
                    d[e.to]=d[v]+1;
                    visit[e.to]=true;
                    que.push(e.to);
                }
            }
        }
        return prev[t].first!=-1;
    }

    void update(ll from,ll to, ll f,ll edgenum)
    {
        edge e=graph[from][edgenum];
        graph[from][edgenum].cap-=f;
        graph[e.to][e.rev].cap+=f;
        return;
    }

    ll run(ll s,ll t)
    {
        ll from,to,f,ans=0;
        while(bfs(s,t))
        {
            from=-1;to=t;f=INF;
            while (from!=s)
            {
                from=prev[to].first;
                f=min(f,graph[from][prev[to].second].cap);
                to=from;
            }
            to=t;from=-1;
            while (from!=s)
            {
                from=prev[to].first;
                update(from,to,f,prev[to].second);
                to=from;
            }
            ans+=f;
        }
        return ans;
    }
};

int main()
{
    ll N;cin >> N;

    ll ans=0;
    max_flow solve(N+2);
    ll a;
    for (ll i=0;i<N;i++)
    {
        cin >> a;
        if (a<=0)
        {
            solve.add_edge(0,i+1,-a);
            for (ll j=2;j*(i+1)<=N;j++) 
            {
                solve.add_edge(i+1,j*(i+1),INF);
            }
        }
        else
        {
            ans+=a;
            solve.add_edge(i+1,N+1,a);
            for (ll j=2;j*(i+1)<=N;j++) 
            {
                solve.add_edge(i+1,j*(i+1),INF);
            }
        }
    }
    cout << ans-solve.run(0,N+1) << endl;
return 0;
}

