void bfs(int s, int t) {
	REP(i, t)	level[i] = -1;
	level[s] = 0;
	queue<int> q;
	q.push(s);
	while (!q.empty()) {
		int v = q.front();	q.pop();
		for (auto it : edge[v]) {
			int to, rev;	ll cap;
			tie(to, cap, rev) = it;
			if (cap > 0 && level[to] == -1) {
				level[to] = level[v] + 1;
				q.push(to);
			}
		}
	}
}

ll dfs(int s, int t, ll f) {
	if (s == t)	return f;
	for (; itr[s] < edge[s].size();itr[s]++) {
		int i = itr[s];
		int to, rev;	ll cap;
		tie(to, cap, rev) = edge[s][i];
		if (cap > 0 && level[s] < level[to]) {
			f = dfs(to, t, min(f, cap));
			if (f > 0) {
				edge[s][i] = mt(to, cap - f, rev);
				edge[to][rev] = mt(s, get<1>(edge[to][rev]) + f, i);
				return f;
			}
		}
	}
	return 0;
}

ll dinic(int s, int t) {
	ll ret = 0;
	while (true) {
		bfs(s, t);
		if (level[t] <= 0)	return ret;
		REP(i, t)	itr[i] = 0;
		ll f = dfs(s, t, inf);
		while (f > 0) {
			ret += f;
			f = dfs(s, t, inf);
		}
	}
}

