#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

const ll INF = (ll)1e18 + 10;

class FordFulkerson {
public:
    FordFulkerson(ll n) : n_(n), graph_(n) {}

    // fromからtoへ向かう容量capの辺をグラフに追加する
    void addEdge(ll from, ll to, ll cap) {
        graph_[from].push_back({ to, cap, (ll)graph_[to].size() });
        graph_[to].push_back({ from, 0, (ll)graph_[from].size() - 1 });
    }

    // sからtへの最大流を求める
    ll getflow(ll s, ll t) {
        ll flow = 0;
        while (true) {
            used_.assign(n_, false);
            ll f = dfs(s, t, INF);
            if (f == 0) return flow;
            flow += f;
        }
    }

private:
    struct Edge { ll to, cap, rev; };
    ll n_;
    vector<vector<Edge>> graph_;
    vector<bool> used_;

    // 増加パスをdfsで探す
    ll dfs(ll v, ll t, ll f) {
        if (v == t) return f;
        used_[v] = true;
        for (auto &e : graph_[v]) {
            if (!used_[e.to] && e.cap > 0) {
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph_[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
};

int main() {
    ll N;
    cin >> N;
    FordFulkerson ff(N + 2);
    ll s = 0;
    for (ll i = 1; i <= N; i++) {
        ll a;
        cin >> a;
        s += max((ll)0, a);
        if (a <= 0) {
            ff.addEdge(0, i, -a);
        } else {
            ff.addEdge(i, N + 1, a);
        }

        for (ll j = i * 2; j <= N; j += i) {
            ff.addEdge(i, j, INF);
        }
    }
    cout << s - ff.getflow(0, N + 1) << endl;
}

