typedef long long ll;
const int INF=0x3f3f3f3f;
inline int read()
{
	int x=0,f=1;char c=getchar();
	while(!isdigit(c)){if(c=='-')f=-1;c=getchar();}
	while(isdigit(c)){x=x*10+c-'0';c=getchar();}
	return x*f;
}
struct edge{
	int to,nxt,cap,flow;
}e[30005];
int a[105],last[105],cur[105],dis[105],S,T,n,cnt=1;
ll min(ll x,ll y) {return x<y?x:y;}
void insert(int u,int v,int w)
{
	e[++cnt]=(edge){v,last[u],w,0};
	last[u]=cnt;
}
int bfs()
{
	queue<int> q;
	for(int i=1;i<=n+2;i++) dis[i]=INF;
	dis[S]=0;q.push(S);
	while(q.size())
	{
		int x=q.front();q.pop();
		for(int i=last[x];i;i=e[i].nxt)
		if(e[i].cap>e[i].flow&&dis[e[i].to]==INF)
		{
			dis[e[i].to]=dis[x]+1;
			q.push(e[i].to);
		}
	}
	return dis[T]!=INF;
}
ll dfs(int x,ll low)
{
	if(x==T||low==0) return low;
	ll ret=0,st;
	for(int &i=cur[x];i;i=e[i].nxt)
	{
		cur[x]=i;
		if(dis[e[i].to]==dis[x]+1&&(st=dfs(e[i].to,min(low,e[i].cap-e[i].flow)))>0)
		{
			ret+=st,low-=st;
			e[i].flow+=st,e[i^1].flow-=st;
			if(!low) break;
		}
	}
	return ret;
}
ll dinic()
{
	ll ret=0;
	while(bfs())
	{
		for(int i=1;i<=n+2;i++) cur[i]=last[i];
		ret+=dfs(S,INF);
	}
	return ret;
}
ll ans;
int main()
{
	n=read();
	for(int i=1;i<=n;i++) a[i]=read();
	S=n+1;T=n+2; 
	for(int i=1;i<=n;i++)
	{
		if(a[i]>0) ans+=a[i],insert(i,T,a[i]),insert(T,i,0);
		else insert(S,i,-a[i]),insert(i,S,0);
	}
	for(int i=1;i<n;i++)
		for(int j=2;j<=n/i;j++)
		{
			insert(i,i*j,a[i*j]);
			insert(i*j,i,0);
		}
	ans-=dinic();
	printf("%lld\n",ans);
	return 0;
}

