int main() {
	cin >> n; for (int i = 1; i <= n; i++) { cin >> a[i]; s += a[i]; }
	J[1] = true; for (int j = 0; j < MAXIMAN; j++)J[v[j]] = true;

	int N = max(n, MAXIMAN);

	for (int i = 0; i < (1 << MAXIMAN); i++) {
		for (int j = 1; j <= N; j++)M[j] = false;

		long long V = 0; cnt = 0;
		for (int j = 0; j < MAXIMAN; j++) {
			J[v[j]] = true;
			if ((i / (1 << j)) % 2 == 0) continue;
			for (int k = v[j]; k <= N; k += v[j]) {
				if (J[k] == true) { M[k] = true; }
			}
			for (int k = v[j]; k <= N; k += v[j])I[k] = true;
		}

		for (int j = 1; j <= 20; j++) { if (J[j] == true && M[j] == false)V += a[j]; }
		for (int j = 1; j <= N; j++) { x[j].clear(); y[j].clear(); col[j] = 0; }
		for (int j = 2; j <= N; j++) {
			for (int k = j; k <= N; k += j) {
				if (I[j] == true || I[k] == true)continue;
				if (J[j] == true || J[k] == true)continue;
				x[j].push_back(k);
				x[k].push_back(j);
