		for (int j = 1; j <= N; j++) { if (col[j] == 0 && J[j] == false) { cnt++; dfs(j); } }
		for (int j = 1; j <= cnt; j++) {
			int maxn = 0, T = y[j].size();
			for (int k = 0; k < (1 << T); k++) {
				int sum = 0, K[7], L[7];
				for (int l = 0; l < T; l++) { K[l] = ((k&(1 << l)) >> l); L[l] = 0; }
				for (int l = 0; l < T; l++) {
					if (K[l] == 0)continue;
					for (int m = 0; m < T; m++) {
						if (y[j][m] % y[j][l] == 0)L[m] = 1;
					}
				}
				for (int l = 0; l < T; l++)sum += a[y[j][l]] * (1 - L[l]);
				maxn = max(maxn, sum);
			}
			V += maxn;
		}
		ret = max(ret, V);
	}
	cout << ret << endl;
	return 0;
}

