        }
    }

    rep(i,0,N) {
        int d = i+1;
        for(int k=i+d; k<N; k+=d) {
            fl.add_edge(i, k, INF);
        }
    }

    cout << sum - fl.max_flow(source, sink) << endl;
    return 0;
}

