  // n = 100;
  // REP(i,n)a[i] = rand() - rand();

  dinic D(n+2);
  ll M = (ll)(1e9);
  ll Z = 2ll*M;
  int s = n, t = n+1;
  REP(i,n){
    D.add_edge(s,i,Z-M);
    D.add_edge(i,t,Z-(a[i]+M));
    REP(j,i){
      if((i+1)%(j+1)==0){
        D.add_edge(i,j,INF);
      }
    }
  }

  ll flow = D.calc(s,t);
  ll ans = Z*n - flow - M*n;
  cout<<ans<<endl;
  return 0;
}

