vector<long long> divisor(long long n) {
    vector<long long> ret;
    if (n > 1) for(long long i = 1; i * i <= n; i++) {
        if (n % i == 0) {
             ret.emplace_back(i);
             if (i != n / i && i != 1) ret.emplace_back(n / i);
        }
    }
    return ret;
}

