        if(a[i] <= 0){
            add_edge(0, i+1, (-1)*a[i]);
            add_edge(i+1, n+1, 0);
        }
        else{
            add_edge(i+1, n+1, a[i]);
            add_edge(0, i+1, 0);
            ans += a[i];
        }
        while(tmp <= n){
            add_edge(i+1, tmp, INF);
            tmp += i+1;
            //cout << i+1 << " " << tmp << endl;
        }
    }

    cout << ans - max_flow(0, n+1) << endl;

    return 0;
}

