int findmin(int n){
	long long int ans = INT_MAX;
	int pos = -1;
	for(int i = 1; i<=n; i++){
		long long int local = 0;
		for(int j = i; j<=n; j+=(i)){
			if(!visited[j])	local += arr[j];
		}
		if(local < ans){
			ans = local;
			pos = i;
		}
	}
	if(ans >= 0){
		return -1;
	}
	return pos;
}

int main (){
	int n;
	cin>>n;
	for(int i = 1; i<=n; i++){
		cin>>arr[i];
		visited[i] = false;
	}
	while(true){
		int k = findmin(n);
		if(k == -1) break;
		for(int i = k; i<=n; i+=(k)){
			visited[i] = true;
		}
	}
	long long int a = 0;
	for(int i = 1; i<=n; i++){
		if(!visited[i])
			a += arr[i];
	}
	cout<<a<<endl;
	return 0;
}

