		cin >> a;
		if (a >= 0) {
			dic.add_edge(0, i + 1, 0);
			dic.add_edge(i + 1, n + 1, a);
			sum += a;
		}
		else {
			dic.add_edge(0, i + 1, -a);
			dic.add_edge(i + 1, n + 1, 0);
		}
	}
	for (ll i = 1; i <= n / 2; i++) {
		for (ll j = i * 2; j <= n; j += i) {
			dic.add_edge(i, j, INF);
		}
	}
	cout << sum - dic.max_flow(0, n + 1) << endl;
}

