	vector<int>num(N + 1);

	long long int score = 0;
	for (int i = 1; i <= N; i++) {
		if (!num[i]) {
			score += v[i];
		}
	}
	long long int loop = 0;
	int bef = 0;
	while (1) {
		loop++;
		if (loop % 10000 == 0) {
			auto ed = clock();
			bef = ed - st;
			if (bef > 1990000) {
				break;
			}
		}
