				}
				score += dif;
				flag[cn] = false;
			}
		}
		else {
			for (int i = cn; i <= N; i += cn) {
				if (!num[i]) {
					dif -= v[i];
				}
			}
			if (dif > 0 || (dif==0&&xs.rand() % 2) || (dif < 0 && xs.rand() % 100000000 < max(0, 7500000 - bef * 5))) {
