const int N = 110;
ll INF = 1e15;
int val[N];

namespace WLL {
  struct data {
    int nt, to;
    ll w;
  } a[N * N * 2];
  int S, T, cnt = -1, dep[N], cur[N], head[N];

  void init(int n) {
    S = 0, T = n + 1;
    for(int i = S; i <= T; ++i)
      head[i] = -1;
  }

  void add(int x, int y, ll c) {
//    printf("%d %d %lld\n", x, y, c);
    a[++cnt].to = y, a[cnt].w = c, a[cnt].nt = head[x], head[x] = cnt;
    a[++cnt].to = x, a[cnt].w = 0, a[cnt].nt = head[y], head[y] = cnt;
  }

  queue<int> q;
  bool bfs() {
    q.push(S);
    memset(dep, 0, sizeof dep);
    dep[S] = 1;
    while(!q.empty()) {
      int u = q.front(); q.pop();
      for(int i = head[u]; ~i; i = a[i].nt) {
        int to = a[i].to;
        if(!dep[to] && a[i].w)
          dep[to] = dep[u] + 1, q.push(to);
      }
    }
/*    for(int i = S; i <= T; ++i)
      printf("dep[%d] = %d\n", i, dep[i]);*/
    return dep[T];
  }

  ll dfs(int s, ll v) {
    if(s == T) return v;
    for(int& i = cur[s]; ~i; i = a[i].nt) {
      if(dep[a[i].to] == dep[s] + 1 && a[i].w) {
//        printf("to = %d\n", a[i].to);
        ll d = dfs(a[i].to, min(a[i].w, v));
        if(d) {
          a[i].w -= d;
          a[i ^ 1].w += d;
          return d;
        }
      }
    }
    return 0ll;
  }

  ll solve() {
    ll ans = 0;
    int count = 0;
    for(; bfs(); ) {
      for(int i = S; i <= T; ++i)
        cur[i] = head[i];
      for(; ll d = dfs(S, INF); ) {
//        printf("d = %lld\n", d);
        ans += d;
      }
    }
    return ans;
  }
}

int main() {
  int n;
  scanf("%d", &n);
  WLL::init(n);
  ll sum = 0, tmp = 0;
  for(int i = 1; i <= n; ++i) {
    scanf("%d", &val[i]);
    sum += val[i];
    val[i] = -val[i];
    if(val[i] > 0) tmp += val[i];
    if(val[i] > 0) WLL::add(WLL::S, i, val[i]);
    else if(val[i] < 0) WLL::add(i, WLL::T, -val[i]);
    for(int j = 1; j < i; ++j) {
      if(i % j == 0) {
        WLL::add(j, i, INF);
      }
    }
  }
  ll pos = WLL::solve();
//  printf("sum = %lld, tmp = %lld, pos = %lld\n", sum, tmp, pos);
  sum += tmp - pos;
  printf("%lld\n", sum);
  return 0;
}

