using namespace std;

template <typename T>
struct flow_graph {

	struct edge {
		int from, to;
		T cap, f;
	};

	vector<edge> edges;
	vector<vector<int>> g;
	vector<int> level, iter;
	int n, st, fin;
	T flow;

	flow_graph(int n, int st, int fin) : n(n), st(st), fin(fin) {
		assert(0 <= st && st < n && 0 <= fin && fin < n && st != fin);
		g.resize(n);
		level.resize(n);
		iter.resize(n);
		flow = 0;
	}

	void clean_flow() {
		for (const edge &e : edges) {
			e.f = 0;
		}
		flow = 0;
	}

	void add(int from, int to, T cap = 1, T rev_cap = 0) {
		assert(0 <= from && from < n && 0 <= to && to < n);
		g[from].emplace_back(edges.size());
		edges.push_back({from, to, cap, 0});
		g[to].emplace_back(edges.size());
		edges.push_back({to, from, rev_cap, 0});
	}

	bool bfs() {
		fill(level.begin(), level.end(), -1);
		queue<int> q;
		level[st] = 0;
		q.emplace(st);
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			for (int id : g[i]) {
				const edge &e = edges[id];
				if (0 < e.cap - e.f && level[e.to] < 0) {
					level[e.to] = level[i] + 1;
					q.emplace(e.to);
				}
			}
		}
		return 0 < level[fin];
	}

	T dfs(int now, T f = numeric_limits<T>::max()) {
		if (now == fin) {
			return f;
		}
		for (int &i = iter[now]; i < g[now].size(); i++) {
			int id = g[now][i];
			edge &e = edges[id];
			if (0 < e.cap - e.f && level[now] < level[e.to]) {
				T d = dfs(e.to, min(f, e.cap - e.f));
				if (0 < d) {
					e.f += d;
					edges[id ^ 1].f -= d;
					return d;
				}
			}
		}
		return 0;
	}

	T max_flow() {
		while (bfs()) {
			fill(iter.begin(), iter.end(), 0);
			for (T f = dfs(st); 0 < f; f = dfs(st)) {
				flow += f;
			}
		}
		return flow;
	}
};

int main() {
	int n;
	cin >> n;
	int64_t a[n];
	for (auto &i : a) {
		cin >> i;
	}
	int64_t maxi = 0;
	for (auto &i : a) {
		if (0 < i) {
			maxi += i;
		}
	}
	flow_graph<int64_t> g(n + 2, 0, n + 1);
	for (int i = 1; i <= n; i++) {
		if (0 <= a[i - 1]) {
			g.add(0, i, a[i - 1]);
			g.add(i, n + 1, 0);
		} else {
			g.add(0, i, 0);
			g.add(i, n + 1, -a[i - 1]);
		}
		for (int j = 2 * i; j <= n; j += i) {
			g.add(j, i, numeric_limits<int64_t>::max());
		}
	}
	cout << maxi - g.max_flow() << endl;
	return 0;
}

