using namespace std;

int N;
vector<long> gem;

long break_gem(int now, string broke){
	if(now == N){
		return 0;
	}else if(broke[now] == '1'){
		return break_gem(now + 1, broke);
	}else if(now >= (N + 1) / 2){
		if(gem[now] < 0){
			broke[now] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else if(now >= (N + 1) / 3){
		if(gem[now] < 0 && gem[now] + gem[now * 2 + 1] < 0){
			broke[now] = '1';
			broke[now * 2 + 1] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else if(now >= (N + 1) / 4){
		int sum = gem[now];
		if(gem[now * 2 + 1] < 0){
			sum += gem[now * 2 + 1];
		}
		if(gem[now * 3 + 3] < 0){
			sum += gem[now * 3 + 3];
		}
		if(gem[now] < 0 && sum < 0){
			broke[now] = '1';
			broke[now * 2 + 1] = '1';
			broke[now * 3 + 3] = '1';
			return break_gem(now + 1, broke);
		}else{
			return gem[now] + break_gem(now + 1, broke);
		}
	}else{
		long ans = gem[now] + break_gem(now + 1, broke);
		for(int j = now; j < N; j += now + 1){
			broke[j] = '1';
		}
		return max(ans, break_gem(now + 1, broke));
	}
}

int main(){
	cin >> N;
	for(int i = 0; i < N; i++){
		long input;
		cin >> input;
		gem.push_back(input);
	}
	string zero_text = "";
	for(int i = 0; i < N; i++){
		zero_text.push_back('0');
	}
	cout << break_gem(0, zero_text) << endl;
}

