const int MAXN = 35;

int N, cnt;
LL a[MAXN], ans, sum;
bitset<101> mul[MAXN], vis;

void test() {
    LL all = 0;
    bitset<101> take = vis;
    for (int i = 1; i <= N; i++) {
        if (take[i]) {
            all += a[i];
        }
        else if (i > 33) {
            if (i * 2 > N) {
                if (a[i] < 0) {
                    all += a[i];
                }
            }
            else {
                if (take[i * 2]) {
                    if (a[i] < 0) {
                        all += a[i];
                    }
                }
                else {
                    if (a[i] + a[i * 2] < 0) {
                        all += a[i];
                        take.set(i * 2);
                    }
                }
            }
        }
    }
    ans = max(ans, sum - all);
}

void dfs(int x) {
    // cout << "DFS " << x << "\n";
    if (x > 33 || x > N) {
        cnt++;
        test();
        return;
    }

    dfs(x + 1);
    if (!vis[x] && a[x] < 0) {
        bitset<101> temp = vis;
        vis |= mul[x];
        dfs(x + 1);
        vis = temp;
    }
}

