    }

    for (int i = 1; i < MAXN; i++) {
        for (int j = 0; j < MAXN; j += i) {
            mul[i].set(j);
        }
    }

    ans = sum;
    dfs(1);
    // cout << cnt << "\n";

    cout << ans << "\n";
}

