	LL sp = 0;
	graph g(n + 2);
	FOR(i, 1, n+1) {
		int a;
		scanf("%d", &a);
		if (a < 0)addedge(g, 0, i, -a);
		else {
			addedge(g, i, n + 1, a);
			sp += a;
		}
		for (int j = 2*i; j <= n; j += i) {
			addedge(g, i, j, 1e18);
		}
	}
	printf("%lld\n", sp - maximum_flow(g, 0, n + 1));
	return 0;
}

