bool get(const ii &a,lli x)
{
    if(x<=50)
        return a.X&(1LL<<x);
    x-=50;
    return a.Y&(1LL<<x);
}

void se(ii &a,lli x)
{
    if(x<=50)
        a.X|=(1LL<<x);
    else
    {
        x-=50;
        a.Y|=(1LL<<x);
    }
}

lli solve(ii msk)
{
    lli ans=0;
    for(lli k=1;k<=L&&k<=n;++k)
    {
        if(get(msk,k))
            continue;
        ans+=a[k];
    }

    for(lli k=L+1;k<=n;++k)
    {
        if(get(msk,k))
            continue;
        lli ct=a[k];
        if(2*k<=n&&!get(msk,2*k))
            ct+=a[2*k];
        if(ct>=0)
        {
            ans+=ct;
            continue;
        }
        se(msk,k);
        if(2*k<=n)
            se(msk,2*k);
    }
    return ans;
}

