    REP(i, N){
        cin >> a[i + 1];
        psum += max((int)0, a[i + 1]);
    }

    Graph G(N + 2);
    int s = 0, t = N + 1;

    FOR(i, 1, N + 1){
        if(a[i] >= 0){
            //割ることで生じる損失
            G.add_edge(i, t, a[i]);
        }else{
            //割らないことで生じる損失
            G.add_edge(s, i, -1 * a[i]);
        }
        for(int j = i + i; j <= N; j += i){
            G.add_edge(i, j, INF);
        }
    }

    int mincut = G.max_flow(s, t);

    int ans = psum - mincut;

    cout << ans;

    return 0;
}

