vector<int>l;

unordered_map<ll, ll> memo[102];


ll solve(const int x, const ll z) {
	if (memo[x].count(z) > 0)return memo[x][z];
	if (x > n / 2) {
		reP(i, n)f[i] = true;
		for (int i : l) {
			for (int j = i; j <= n; j += i)f[j] = false;
		}
		ll ret = 0;
		reP(i, n)if (f[i])ret += a[i];
		repfT(i, x, n) {
			if (!f[i])continue;
			if (a[i] < 0)ret -= a[i];
		}
		return memo[x][z]=ret;
	}

	bool F = false;
	for (int i : l)if (x%i == 0)F = true;
	if (F) return memo[x][z] = solve(x + 1, z);

	ll p, q;
	p = solve(x + 1, z);
	l.push_back(x);
	q = solve(x + 1, (z|(1LL << x) ));
	l.pop_back();
	return memo[x][z] = max(p, q);
}

