  int score = 0;
  rep(i, 0, N) score += max(0, a[i]);

  Graph g(N + 2);
  int s = N, t = s + 1;
  rep(i, 0, N) {
    if (a[i] > 0)
      g.add_edge(i, t, a[i]);
    else if (a[i] < 0)
      g.add_edge(s, i, -a[i]);
  }
  rep(i, 0, N) rep(j, 0, N) {
    if ((j + 1) % (i + 1) == 0) {
      g.add_edge(i, j, INF);
    }
  }
  cout << score - g.max_flow(s, t) << endl;

  return 0;
}

