        for(int z=nc;z<=N;z+=nc) sum-=A[z];
        nc=k*j/gcd(k,j);
        for(int z=nc;z<=N;z+=nc) sum-=A[z];
        nc=i*j*k/gcd(gcd(i,j),k);
        for(int z=nc;z<=N;z+=nc) sum+=A[z];

        if(sum<=0) {
          for(int z=i;z<=N;z+=i) A[z]=0;
          for(int z=j;z<=N;z+=j) A[z]=0;
          for(int z=k;z<=N;z+=k) A[z]=0;
        }
      }
    }
  }


  for(ll i=N/2;i-->1;) {
    if(A[i]>=0) continue;
    for(ll j=i-1;j-->1;) {
      if(A[j]>=0) continue;
      if(i%j==0) continue;
      for(ll k=j-1;k-->1;) {
        if(A[k]>=0) continue;
        if(i%k==0) continue;
        if(j%k==0) continue;
        for(ll l=k-1;l-->1;) {
          if(A[l]>=0) continue;
          if(i%l==0) continue;
          if(j%l==0) continue;
          if(k%l==0) continue;
          ll sum=0;

          vector<bool> d(N+1);
          for(int z=i;z<=N;z+=i) d[z]=true;
          for(int z=j;z<=N;z+=j) d[z]=true;
          for(int z=k;z<=N;z+=k) d[z]=true;
          for(int z=l;z<=N;z+=l) d[z]=true;
          for(int i=1;i<=N;i++)
            if(d[i])sum+=A[i];

          if(sum<=0) {
            for(int z=i;z<=N;z+=i) A[z]=0;
            for(int z=j;z<=N;z+=j) A[z]=0;
            for(int z=k;z<=N;z+=k) A[z]=0;
            for(int z=l;z<=N;z+=l) A[z]=0;
          }
        }
      }
    }
  }

  }
  cout<<accumulate(A.begin(), A.end(), 0)<<endl;
}

