using namespace std;

const int N = 110;

typedef long long LL;

LL ans, S;
int A[N], n;
int used[N];

void work(int r){
	int l = r / 2 + 1;
	For(i, l, r){
		LL ret = 0;
		for(int j = i; j <= n; j += i) if(!used[j]) ret += A[j];
		if(ret > 0){
			ans += ret;
			for(int j = i; j <= n; j += i) used[j] = true;
		}
	}
	if(l > 1) work(l - 1);
}

void DFS(int x, LL now){
	if(now + S <= ans) return;
	while(x <= n && (used[x] || A[x] <= 0)) ++x;
	if(x > n){
		ans = max(ans, now);
		return;
	}
	LL ret = 0;
	DFS(x + 1, now);

	for(int i = x; i <= n; i += x) if(!used[i]){
		ret += A[i], used[i] = x;
		if(A[i] > 0) S -= A[i];
	}

	DFS(x + 1, now + ret);
	for(int i = x; i <= n; i += x) if(used[i] == x){
		if(A[i] > 0) S += A[i];
		used[i] = 0;
	}
}

