vector<edge> g[123];
bool used[123];

void make_edge(int u, int v, ll c){
	edge e;
	e.to = v;
	e.rev = g[v].l_ength();
	e.cap = c;
	g[u].push_back(e);
	e.to = u;
	e.rev = g[u].l_ength()-1;
	e.cap = 0ll;
	g[v].push_back(e);
}

ll dfs(int s, int t, ll f){
	int i;
	edge e;
	ll v;
	used[s] = true;
	if(s==t){
		return f;
	}
	for(i=(g[s].l_ength()-1); i>=0; --i){
		e = g[s][i];
		if((!used[e.to]) && e.cap > 0ll){
			v = dfs(e.to,t,min(f,e.cap));
			if(v > 0ll){
				g[s][i].cap -= v;
				g[e.to][e.rev].cap += v;
				return v;
			}
		}
	}
	return 0ll;
}

int main(void){
	int n,i,j;
	ll a,ans=0ll;
	cin >> n;
	for(i=1; i<=n; ++i){
		cin >> a;
		if(a>0ll){
			ans += a;
			make_edge(i,n+1,a);
		}else{
			make_edge(0,i,-a);
		}
		j = i*2;
		while(j<=n){
			make_edge(i,j,INFLL);
			j += i;
		}
	}
	while(true){
		fill(used,used+123,false);
		a = dfs(0,n+1,INFLL);
		if(a == 0ll){
			break;
		}
		ans -= a;
	}
	cout << ans << endl;
	return 0;
}

