template<class flow_t>
struct NetWork{
private:

    int V_sz;
    struct edge{
        int to, rev; flow_t cap;
        edge(int to, int rev, flow_t cap) : to(to), rev(rev), cap(cap) {}
    };
    vector<vector<edge>> graph;
    vector<int> level;
    vector<int> iter;

    void bfs(int start){
        fill(level.begin(), level.end(), -1);
        queue<int> que;
        level[start] = 0;
        que.push(start);
        while(!que.empty()){
            int v = que.front();
            que.pop();
            for(edge e : graph[v]){
                if(e.cap > flow_t(0) && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    flow_t dfs(int now, int goal, flow_t flow){
        if(now == goal)return flow;
        for(int &i = iter[now]; i < graph[now].size(); i++){
            edge &e = graph[now][i];
            if(e.cap > flow_t(0) && level[now] < level[e.to]){
                flow_t tmp = dfs(e.to, goal, min<flow_t>(flow, e.cap));
                if(tmp > flow_t(0)){
                    e.cap -= tmp;
                    graph[e.to][e.rev].cap += tmp;
                    return tmp;
                }
            }
        }
        return flow_t(0);
    }

public:

    NetWork(int v_sz) : V_sz(v_sz), graph(v_sz), level(v_sz), iter(v_sz) {}

    void add_edge(int from, int to, flow_t cap){
        graph[from].push_back(edge(to, graph[to].size(), cap));
        graph[to].push_back(edge(from, graph[from].size() - 1, flow_t(0)));
    }

    flow_t dinic(int start, int goal){
        flow_t flow = 0;
        while(true){
            bfs(start);
            if(level[goal] < 0)return flow;
            fill(iter.begin(), iter.end(), 0);
            flow_t tmp;
            while((tmp = dfs(start, goal, flow_t(1e9))) > flow_t(0)){
                flow += tmp;
            }
        }
    }

};

