  //cerr << "okok";
  long long sum = 0;
  for (int i = 1; i <= n; ++i) {
    if (!bad[i]) {
      sum += a[i];
    }
  }
  while (true) {
    long long best = sum;
    int k = -1;
    for (int i = 1; i <= n; ++i) {
      long long cur = 0;
      for (int j = i; j <= n; j += i) {
        if (!bad[j]) {
          cur += a[j];
        }
      }
      if (sum - cur > best) {
        best = sum - cur;
        k = i;
      }
    }
    if (k == -1) {
      break;
    }
    for (int i = k; i <= n; i += k) {
      bad[i] = true;
    }
    sum = best;
  }
  printf("%lld\n", max(0LL, sum));
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll N = 105, INF = 1e18;
int n, source, sink;
ll a[N], par[N];
ll cap[N][N];
vector<int> adj[N];

ll bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	par[source] = -2;
	queue<pair<int, ll>> q;
	q.push({source, INF});
	while(!q.empty()) {
		ll u = q.front().first, flow = q.front().second;
		q.pop();
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v]) {
				par[v] = u;
				ll new_flow = min(flow, cap[u][v]);
				if(v == sink) return new_flow;
				q.push({v, new_flow});
			}
		}
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while((newFlow = bfs(source, sink))) {
		flow += newFlow;
		int u = sink;
		while(u != source) {
			int v = par[u];
			cap[v][u] -= newFlow;
			cap[u][v] += newFlow;
			u = v;
		}
	}
	return flow;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n;
	source = n+1; sink = n+2;
	ll ideal = 0;
	for(int i = 1; i <= n; i++)
		cin >> a[i], ideal += (a[i]>0)?a[i]:0;
	memset(cap, 0, sizeof cap);
	for(int i = 1; i <= n; i++) {
		if(a[i] < 0) adj[source].push_back(i), adj[i].push_back(source), cap[source][i] = -a[i];
		else adj[i].push_back(sink), adj[sink].push_back(i), cap[i][sink] = a[i];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 2*i; j <= n; j+=i)
			adj[i].push_back(j), adj[j].push_back(i), cap[i][j] = INF;
	}
	ll mf = maxflow(source, sink);
	ll ans = ideal - mf;
	cout << ans << '\n';
	return 0;
}

