int N,M,MaxFlow;
vector <int> G[NMax];
queue <int> Q;
int C[NMax][NMax],Use[NMax],F[NMax][NMax],TT[NMax];
int A[105], sum;
void Read()
{
    cin>>N;
    for(int i=1; i<= N ; i++)
    {
        cin >> A[i];
    }
    for(int i = 1; i <= N; i++)
    {

        if(A[i] <= 0)
        {
            G[1].push_back(i + 1);
            G[i + 1].push_back(1);
            C[1][i + 1] = -A[i];
        }
        else
        {
            sum += A[i];
            G[i + 1].push_back(N + 2);
            G[N + 2].push_back(i + 1);
            C[i + 1][N + 2] = A[i];
            for(int j = 1; j < i; j++)
                if(i % j == 0 && A[j] <= 0)
                {
                    G[i + 1].push_back(j + 1);
                    G[j + 1].push_back(i + 1);
                    C[j + 1][i + 1] = 1000000005;
                }
        }

    }
}

int BFS()
{
    memset(Use,0,sizeof(Use));
    Q.push(1); Use[1] = 1;

    while(!Q.empty())
    {
        int Node = Q. front(); Q. pop();

        if(Node == N + 2) continue;

        for(unsigned int i = 0; i < G[Node].size(); ++i)
        {
            int Neighbour = G[Node][i];

            if(!Use[Neighbour] && C[Node][Neighbour]-F[Node][Neighbour]>0)
            {
                TT[Neighbour] = Node;
                Q.push(Neighbour);
                Use[Neighbour] = 1;
            }
        }
    }

return Use[N + 2];

}

void Solve()
{
    while(BFS())
    {

        for(unsigned int k = 0; k<G[N + 2].size(); ++k)
        {

        int Vecin = G[N + 2][k];

        if(!Use[Vecin] || C[Vecin][N + 2]-F[Vecin][N + 2] == 0) continue;

        TT[N + 2] = Vecin;

        int Fmin = 1000000005;

        for(int i = N + 2 ; i != 1 ; i = TT[i])
            Fmin = min(Fmin,C[TT[i]][i]-F[TT[i]][i]);

        MaxFlow += Fmin;

        for(int i = N + 2 ; i != 1 ; i = TT[i])
        {
            F[TT[i]][i] += Fmin;
            F[i][TT[i]] -= Fmin;
        }

        }
    }
}

void Print()
{
    cout<<sum - MaxFlow<<"\n";
}

int main()
{
    Read();
    Solve();
    Print();
    return 0;
}

