ll gcd(ll a,ll b){
	if(!b)return a;
	return gcd(b,a%b);
}
ll lcm(ll a,ll b){
	return a/gcd(a,b)*b;
}
ll LCM(vector<int>v){
	ll A=1;
	for(auto i:v){
		A=lcm(A,i);
	}
	return A;
}
ll score(vector<int>v){
