signed main(){
	int n;scanf("%lld",&n);
	rep(i,n)scanf("%lld",&a[i]);
	memset(Min,0x3f,sizeof(Min));
	for(int i=1;i<=n;i++){
		ll cnt=0;
		for(int j=i;j<=n;j+=i){
			cnt+=a[j-1];
		}
		auto mp=p(i);
		for(auto pp:mp){
			if(Min[pp.first]>cnt){
				Min[pp.first]=cnt;
				Min2[pp.first]=i;
			}
		}

		if(Min[1]>cnt){
			Min[1]=cnt;
			Min2[1]=i;
		}
	}
	set<int>se;
	for(int i=1;i<=n;i++){
		if(i==1)se.insert(i);
		else{
			auto mp=p(i);
			if(mp.size()==1&&mp[i]==1)se.insert(Min2[i]);
		}
	}
	ll MMin=INFL;
	rep(i,1<<se.size()){//使う集合
		set<int>S;
		int ccnt=0;
		for(int c:se){
			if(i>>ccnt&1)S.insert(c);
			ccnt++;
		}
		ll cnt=0;
		for(auto it1=S.begin();it1!=S.end();it1++){
			if(*it1>n)break;
			cnt+=score({*it1});
			for(auto it2=(++it1)--;it2!=S.end();it2++){
				if(LCM({*it1,*it2})>n)break;
				cnt-=score({*it1,*it2});
				for(auto it3=(++it2)--;it3!=S.end();it3++){
					if(LCM({*it1,*it2,*it3})>n)break;
					cnt+=score({*it1,*it2,*it3});
					for(auto it4=(++it3)--;it4!=S.end();it4++){
						if(LCM({*it1,*it2,*it3,*it4})>n)break;
						cnt-=score({*it1,*it2,*it3,*it4});
					}
				}
			}
		}
		MMin=min(MMin,cnt);
	}

	ll cc=0;
	rep(i,n){
		cc+=a[i];
	}
	cout<<cc-MMin<<endl;
}

