struct FF
{
    ll cap[maxn][maxn];
    bool visited[maxn], seen[maxn];
    ll source, sink;
    FF() {
        source = 0;
        sink = n + 1;
        //fill with zeros
        memset(cap,0,sizeof(cap));
        memset(visited,false,sizeof(visited));
        //add edges
        for (int i = 1; i <= n; i++) {
            if (a[i] <= 0) {
                cap[source][i] = -a[i];                    
            }
            else {
                cap[i][sink] = a[i];
