        for (ll i = 0; i <= sink; i++) {
            for (ll j = 0; j <= sink; j++) {
                cout << cap[i][j] << ' ';
            }
            cout << '\n';
        }
        */
    }

    ll dfs(ll i, ll bneck) {
        if (i == sink) {
            return bneck;
        }
        if (visited[i]) return 0;
        visited[i] = true;
        for (int j = 0; j <= sink; j++) {
            if (cap[i][j] > 0) {
                ll f = dfs(j,min(bneck,cap[i][j]));
                if (f > 0) {
                    //update, recurse upwards
                    cap[i][j] -= f;
                    cap[j][i] += f;
                    return f;
                }
            }
        }
        return 0;
    }

    ll getflow() {
        ll flow = 0;
        while (true) {
            memset(visited,false,sizeof(visited));
            ll f = dfs(source,INF);
            if (f == 0) break;
            flow += f;
        }
        return flow;
    }

    void findReachable(int i) {
        seen[i] = true;
        for (int j = 0; j <= sink; j++) {
            if (!seen[j] && cap[i][j] > 0) {
                findReachable(j);
            }
        }
    }
};

