const int MaxN = 300;

int n;
int pre[MaxN + 5];
LL a[MaxN + 5], flow[MaxN + 5];
LL cap[MaxN + 5][MaxN + 5];

void prepare() {
	int S = n + 1, T = n + 2;
	for(int i = 1; i <= n; i++) {
		if(a[i] <= 0) cap[S][i] = -a[i];
		else if(a[i] > 0) cap[i][T] = a[i];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 2 * i; j <= n; j += i)
			cap[i][j] = (1LL << 40);
	}
}

LL Bfs(int S, int T) {
	queue <int> q;
	memset(pre, -1, sizeof(pre));
	pre[S] = 0;
	flow[S] = (1LL << 50);
	q.push(S);
	while(!q.empty() ) {
		int v = q.front();
		q.pop();
		if(v == T) break;
		for(int i = 1; i <= n + 2; i++) {
			if(i != S && cap[v][i] > 0 && pre[i] == -1) {
				pre[i] = v;
				flow[i] = min(flow[v], cap[v][i]);
				q.push(i);
			}
		}
	}
	if(pre[T] == -1) return -1;
	else return flow[T];
}

LL EK(int S, int T) {
	LL augment = 0;
	LL sumflow = 0;
	while(true) {
		augment = Bfs(S, T);
		if(augment == -1) break;
		int node = T;
		while(node != S) {
			int last = pre[node];
			cap[last][node] -= augment;
			cap[node][last] += augment;
			node = last;
		}
		sumflow += augment;
	}
	return sumflow;
}

