struct Dinic {
	// O(|E||V|^2)
	struct edge {
		int to;
		ll c;
		int rev;
		edge(int x, ll y, int z) : to(x), c(y), rev(z) {}
	};
	vector<vector<edge>> v;
	vector<int> level;
	vector<int> iter;
	int N;
	const ll INF = LLONG_MAX;
	Dinic(int a) {
// N:Vertex(|V|)
		N = a;
		level.RS(N);
		iter.RS(N);
		v.RS(N);
	}
	void add_edge(int x, int y, ll z) {
// x:from y:to z:capacity
		v[x].PB(edge(y, z, v[y].size()));
		v[y].PB(edge(x, 0, v[x].size()-1));
	}
	ll dfs(int s, int t, ll f) {
		if (s == t) return f;
		for (int& i = iter[s]; i < (int) v[s].size(); i++) {
			auto& x = v[s][i];
			if (x.c == 0 || level[s] >= level[x.to]) continue;
			int d;
			if ((d = dfs(x.to, t, min(f, x.c))) > 0) {
				x.c -= d;
				v[x.to][x.rev].c += d;
				return d;
			}
		}
		return 0;
	}
	void bfs(int s) {
		fill(all(level), -1);
		queue<pair<int, int>> q;
		q.push(MP(s, 0));
		while (!q.empty()) {
			auto x = q.front();
			q.pop();
			int a = x.first;
			int b = x.second;
			if (level[a] != -1) continue;
			level[a] = b;
			for (auto y : v[a]) {
				if (y.c > 0) q.push(MP(y.to, b+1));
			}
		}
	}
	ll calc(int s, int t) {
		ll res = 0;
		while (true){
			bfs(s);
			if (level[t] < 0) return res;
			fill(all(iter), 0);
			ll r;
			do {
				r = dfs(s, t, INF);
				res += r;
			} while (r);
		}
	}
};
}

