	ll flow = 0;
	ll newFlow;
	while((newFlow = bfs(source, sink))) {
		flow += newFlow;
		ll u = sink;
		while(u != source) {
			ll v = par[u];
			cap[v][u] -= newFlow;
			cap[u][v] += newFlow;
			u = v;
		}
	}
	return flow;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n;
	source = 0; sink = n+1;
	ll ideal = 0;
	for(ll i = 1; i <= n; i++)
		cin >> a[i], ideal += (a[i]>0)?a[i]:0;
	memset(cap, 0, sizeof cap);
	for(ll i = 1; i <= n; i++) {
		if(a[i] <= 0) adj[source].push_back(i), cap[source][i] = -a[i];
		else adj[i].push_back(sink), cap[i][sink] = a[i];
	}
	for(ll i = 1; i <= n; i++) {
		for(ll j = 2*i; j <= n; j+=i)
			adj[i].push_back(j), cap[i][j] = INF;
	}
	ll mf = maxflow(source, sink);
	ll ans = ideal - mf;
	cout << ans << '\n';
	return 0;
}

