vector<pair<long long, long long> > prime_factorization(long long N){
  vector< pair<long long, long long> > ret;

  for(long long i=2; i*i<=N; i++){
    long long tmp = 0;
    while(N%i==0){
      tmp++;
      N/=i;
    }
    if(tmp>0){
      ret.push_back( make_pair(i, tmp) );
    }
  }
  if(N!=1){
    ret.push_back( make_pair(N, 1) );
  }
  return ret;
