typedef vector<pii> vpii;
const ll INF = (1ll << 60);

struct MaxFlow {
  struct Edge {
    ll s, t, capacity, flow;
    Edge(ll s, ll t, ll capacity) : s(s), t(t), capacity(capacity), flow(0) {}
  };

  struct ResidualEdge {
    bool reversed;
    Edge *edge;
    ResidualEdge() {}
    ResidualEdge(bool reversed, Edge *edge) : reversed(reversed), edge(edge) {}
  };

  ll N;
  vector<Edge *> edges;

  MaxFlow(ll N, vector<Edge> edges) : N(N) {
    this->edges.clear();
    for (Edge e : edges) {
      this->edges.push_back(new Edge(e.s, e.t, e.capacity));
    }
  }

  ~MaxFlow() {
    for (Edge *e : edges) {
      delete e;
    }
  }

  ll calculate(ll s, ll t) {
    ll current_flow = 0;

    while (true) {
      vector<vector<ResidualEdge>> G(N);

      for (Edge *e : edges) {
        if (e->flow < e->capacity) {
          G[e->s].emplace_back(false, e);
        }

        if (0 < e->flow) {
          G[e->t].emplace_back(true, e);
        }
      }

      vector<ll> dist(N, INF);
      vector<ll> prev(N);
      vector<ResidualEdge> trace(N);

      dist[s] = 0;
      queue<ll> q;
      q.push(s);

      while (q.size()) {
        ll fr = q.front();
        q.pop();
        for (ResidualEdge e : G[fr]) {
          ll to = e.reversed ? e.edge->s : e.edge->t;

          if (dist[to] > dist[fr] + 1) {
            dist[to] = dist[fr] + 1;
            prev[to] = fr;
            trace[to] = e;
            q.push(to);
          }
        }
      }

      if (dist[t] == INF) {
        return current_flow;
      }

      vector<ResidualEdge> traces;

      {
        ll i = t;
        while (i != s) {
          traces.push_back(trace[i]);
          i = prev[i];
        }
      }

      ll new_flow = INF;
      for (ResidualEdge e : traces) {
        if (e.reversed) {
          new_flow = min(new_flow, e.edge->flow);
        } else {
          new_flow = min(new_flow, e.edge->capacity - e.edge->flow);
        }
      }

      for (ResidualEdge e : traces) {
        if (e.reversed) {
          e.edge->flow -= new_flow;
        } else {
          e.edge->flow += new_flow;
        }
      }

      current_flow += new_flow;
    }
  }
};

int main() {
  ll N;
  cin >> N;
  vi a(N);
  for (ll i = 0; i < N; i++) {
    cin >> a[i];
  }
  vector<MaxFlow::Edge> edges;
  for (ll i = 1; i <= N; i++) {
    for (ll j = i; j <= N; j += i) {
      edges.emplace_back(i, j, INF);
    }
  }
  for (ll i = 1; i <= N; i++) {
    if (a[i - 1] < 0) {
      edges.emplace_back(0, i, -a[i - 1]);
    } else {
      edges.emplace_back(i, N + 1, a[i - 1]);
    }
  }

  MaxFlow maxFlow(N + 2, edges);
  ll f = maxFlow.calculate(0, N + 1);
  ll ans = 0;
  for (ll i = 0; i < N; i++) {
    if (a[i] > 0)
      ans += a[i];
  }
  cout << ans - f << endl;
}

