			add_edge(0,i,-a);
			add_edge(i,n + 1,0);
		}
		for(int j = i * 2;j <= n;j += i) add_edge(i,j,INF);
	}
	cout << sum - max_flow(0,n + 1) << endl;
	return 0;
}

