#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll N = 105, INF = 1e18;
int n, source, sink;
ll a[N], par[N];
ll cap[N][N];
vector<int> adj[N];

void bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	queue<int> q;
	q.push(source);
	while(!q.empty()) {
		int u = q.front(); q.pop();
		if(u == sink) return;
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v] > 0) {
				par[v] = u;
				q.push(v);
			}
		}
	}
}

ll augment(int u, ll bottleneck) {
	if(u == source) return bottleneck;
	if(par[u] != -1) {
		ll flow = augment(par[u], min(bottleneck, cap[par[u]][u]));
		cap[par[u]][u] -= flow;
		cap[u][par[u]] += flow;
		return flow;
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while(1) {
		bfs(source, sink);
		newFlow = augment(sink, INF);
		if(newFlow == 0) break;
		flow += newFlow;
	}
	return flow;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> n;
	source = n+1; sink = n+2;
	ll ideal = 0;
	for(int i = 1; i <= n; i++)
		cin >> a[i], ideal += (a[i]>0)?a[i]:0;
	memset(cap, 0, sizeof cap);
	for(int i = 1; i <= n; i++) {
		if(a[i] < 0) adj[source].push_back(i), cap[source][i] = -a[i];
		else adj[i].push_back(sink), cap[i][sink] = a[i];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 2*i; j <= n; j+=i)
			adj[i].push_back(j), cap[i][j] = INF;
	}
	ll mf = maxflow(source, sink);
	ll ans = ideal - mf;
	cout << ans << '\n';
	return 0;
}

