struct dinic {
  struct edge {
    int from;
    int to;
    i64 cap;
    i64 flow{};
  };

  int n;
  vector<edge> edges;
  vector<vector<int>> graph;
  vector<int> d;

  dinic(int n_) : n(n_), graph(n) {}

  void add_edge(int from, int to, i64 cap) {
    graph[from].push_back((int) edges.size());
    edges.push_back({from, to, cap});
    graph[to].push_back((int) edges.size());
    edges.push_back({to, from, 0});
  }

  bool bfs() {
    d.assign(n, -1);
    d[0] = 0;
    vector<int> q(n);
    int qt = 1;
    for (int qh = 0; qh < qt; ++qh) {
      int v = q[qh];
      for (auto ei : graph[v]) {
        auto& e = edges[ei];
        if (e.flow < e.cap && !~d[e.to]) {
          d[e.to] = d[v] + 1;
          q[qt++] = e.to;
        }
      }
    }
    return ~d.back();
  }

  i64 max_flow() {
    i64 ans = 0;
    while (bfs()) {
      vector<vector<int>::iterator> ptr(n);
      for (int i = 0; i < n; ++i) ptr[i] = graph[i].begin();
      function<i64(int, i64)> dfs = [&](int v, i64 cMin) -> i64 {
        if (v == n - 1) {
          return cMin;
        }
        for (; ptr[v] != graph[v].end(); ++ptr[v]) {
          auto ei = *ptr[v];
          auto& e = edges[ei];
          if (e.flow < e.cap && d[e.to] == d[v] + 1) {
            auto push = dfs(e.to, min(cMin, e.cap - e.flow));
            if (push) {
              e.flow += push;
              edges[ei ^ 1].flow -= push;
              return push;
            }
          }
        }
        return 0;
      };
      while (auto pushed = dfs(0, (i64) 1e18)) {
        ans += pushed;
      }
    }
    return ans;
  }
};

