typedef long long ll;

const ll INF = 1e15;
const int off = 1e9;

struct E {
    int to, rev; ll cap;
    E(int to, ll cap, int rev) : to(to), cap(cap), rev(rev) {}
};
const int MN = 110;
int m, n, sv, tv;
vector<E> g[MN];
int dist[MN], iter[MN];

void add_edge(int a, int b, ll c) {
    g[a].push_back(E(b, c, int(g[b].size())));
    g[b].push_back(E(a, 0, int(g[a].size())-1));
}

ll dfs(int v, ll f) {
    if (v == tv) return f;
    for (int &i = iter[v]; i < int(g[v].size()); i++) {
        E &e = g[v][i];
        if (!e.cap || dist[e.to] <= dist[v]) continue;
        ll d = dfs(e.to, min<ll>(f, e.cap));
        if (!d) continue;
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
    }
    return 0;
}

ll MF() {
    ll flow = 0;
    while (true) {
        fill(dist, dist + n, -1);
        dist[sv] = 0;
        queue<int> que;
        que.push(sv);
        while (que.size()) {
            int v = que.front(); que.pop();
            for (int i = 0; i < int(g[v].size()); i++) {
                E &e = g[v][i];
                if (!e.cap || dist[e.to] != -1) continue;
                dist[e.to] = dist[v] + 1;
                que.push(e.to);
            }
        }
        if (dist[tv] == -1) break;

        fill(iter, iter + n, 0);
        while (true) {
            ll d = dfs(sv, INF);
            if (!d) break;
            flow += d;
        }
    }
    return flow;
}

