        add_edge(i, tv, off);
    }
    for (int i = 1; i <= m; i++) {
        for (int j = i+i; j <= m; j += i) {
            add_edge(i, j, INF);
        }
    }
    cout << -MF() + ll(m) * off << endl;
    return 0;
}

