// Диниц 法による最大フロー O(V^2 E)
// T: 容量の型 (整数型でないと無限ループする可能性がある)
template <typename flow_t>
struct dinic {

    struct edge {
        size_t to;
        flow_t cap;
        size_t rev;
        edge(size_t _to, flow_t _cap, size_t _rev) :
            to(_to), cap(_cap), rev(_rev) {}
    };

    size_t n;
    vector<vector<edge>> g;
    vector<int> min_cost, iter;

    dinic(size_t _n) :
        n(_n), g(n), min_cost(n), iter(n) {}

    void add_arc(size_t from, size_t to, flow_t cap) {
        assert(0 <= from && from < n);
        assert(0 <= to   && to   < n);
        g[from].emplace_back(to  , cap, g[to  ].size());
        g[to  ].emplace_back(from,   0, g[from].size() - 1);
    }

    void add_edge(size_t from, size_t to, flow_t cap) {
        add_arc(from, to, cap);
        add_arc(to, from, cap);
    }

    bool bfs(size_t s, size_t t) {
        min_cost.assign(n, -1);
        deque<size_t> q;
        min_cost[s] = 0;
        q.push_back(s);
        while (q.size() && min_cost[t] == -1) {
            size_t p = q.front(); q.pop_front();
            for (edge &e : g[p]) {
                if (e.cap > 0 && min_cost[e.to] == -1) {
                    min_cost[e.to] = min_cost[p] + 1;
                    q.push_back(e.to);
                }
            }
        }
        return min_cost[t] != -1;
    }

    flow_t dfs(size_t idx, const size_t t, flow_t flow) {
        if (idx == t) return flow;
        for (int &i = iter[idx]; i < g[idx].size(); i++) {
            edge &e = g[idx][i];
            if (e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
                flow_t d = dfs(e.to, t, min(flow, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    flow_t max_flow(size_t s, size_t t) {
        assert(0 <= s && s < n);
        assert(0 <= t && t < n);
        const flow_t TINF = numeric_limits<flow_t>::max();
        flow_t flow = 0;
        while (bfs(s, t)) {
            iter.assign(n, 0);
            flow_t f = 0;
            while ((f = dfs(s, t, TINF)) > 0) flow += f;
        }
        return flow;
    }

};

