};

void add_edge(ll from,ll to,ll cap,Graph &graph)
{
    graph[from].push_back((edge){to,cap,0,(ll)graph[to].size()});
    graph[to].push_back((edge){from,0,1,(ll)graph[from].size()-1});
}

bool bfs(ll s,ll t,Graph graph,vector<pair<ll,ll>> &prev)
{
    ll n=graph.size();
    for (ll i=0;i<n;i++) prev[i]=p(-1,-1);
    vector<ll> d(n,INF);
    d[s]=0;prev[s]=p(s,-1);
    queue<int> que;
    que.push(s);
    ll v;edge e;
    while(!que.empty())
    {
        v=que.front();
        que.pop();
        for (ll i=0;i<graph[v].size();i++)
        {
            e=graph[v][i];
            if (e.cap>0)
            {
                if (d[e.to]>d[v]+1)
                {
                    d[e.to]=d[v]+1;
                    prev[e.to]=p(v,i);
                    que.push(e.to);
                }
            }
        }
    }
return prev[t].first!=-1;
}

void update(ll from,ll to,ll f, ll edge_num, Graph &graph,matrix &flow,matrix cap)
{
    edge &e=graph[from][edge_num];
    edge &e_r=graph[e.to][e.rev];
    if (e.reverse)
    {
        flow[to][from]-=f;
        graph[from][edge_num].cap=flow[to][from];
        graph[e.to][e.rev].cap=cap[to][from]-flow[to][from];
    }
    else
    {
        flow[from][to]+=f;
        graph[e.to][e.rev].cap=flow[from][to];
        graph[from][edge_num].cap=cap[from][to]-flow[from][to];
    }
return;
}

ll max_flow(ll s,ll t,Graph graph,matrix cap)
{
    ll n=graph.size();
    matrix flow(n,vector<ll> (n,0));
    vector<pair<ll,ll>> prev(n);
    ll from,to,f,ans=0;
    while (bfs(s,t,graph,prev))
    {

        from=-1;to=t;f=INF;
        while (from!=s)
        {
            from=prev[to].first;
            f=min(f,graph[from][prev[to].second].cap);
            to=from;
        }
        ans+=f;
        from=-1;to=t;
        while(from!=s)
        {
            from=prev[to].first;
            update(from,to,f,prev[to].second,graph,flow,cap);
            to=from;
        }
    }
return ans;
}

