#define ll long long
struct Networkflow {
	struct Edge {
		int v, fl, rev;
	};
	vector<vector<Edge> > adj;
	vector<int> lev, edge_tried;
	int st, ed;
	Networkflow(int V, int s, int t) :adj(V), lev(V), edge_tried(V), st(s), ed(t) {}
	void setEdge(int u, int v, int fl) {
		int sz1 = (int)adj[v].size();
		int sz2 = (int)adj[u].size();
		adj[u].push_back({ v, fl, sz1 });
		adj[v].push_back({ u, 0, sz2 });
	}
	bool assign_level() {
		fill(lev.begin(), lev.end(), -1);
		lev[st] = 0;
		queue<int> que; que.push(st);
		while (!que.empty()) {
			int now = que.front(); que.pop();
			for (int i = 0; i<adj[now].size(); i++) {
				int nxt = adj[now][i].v;
				if (lev[nxt] == -1 && adj[now][i].fl != 0) {
					lev[nxt] = lev[now] + 1; que.push(nxt);
				}
			}
		}
		return lev[ed] != -1;
	}
	int dfs(int now, int fl) {
		if (now == ed)return fl;
		for (int &i = edge_tried[now]; i<adj[now].size(); i++) {
			int nxt = adj[now][i].v;
			if (lev[nxt] == lev[now] + 1 && adj[now][i].fl != 0) {
				int nextflow = dfs(nxt, min(fl, adj[now][i].fl));
				if (nextflow) {
					adj[now][i].fl -= nextflow;
					adj[nxt][adj[now][i].rev].fl += nextflow;
					return nextflow;
				}
			}
		}
		return 0;
	}
	ll dinic() {
		ll ret = 0;
		while (assign_level()) {
			fill(edge_tried.begin(), edge_tried.end(), 0);
			while (1) {
				int amt = dfs(st, 1e9);
				if (amt == 0)break;
				ret += amt;
			}
		}
		return ret;
	}
};
