void addEdge(ll s, ll t, ll cap)
{

	Edge a = {t, (ll)G[t].size(), 0, cap};
	Edge b = {s, (ll)G[s].size(), 0, 0};
	G[s].pb(a);
	G[t].pb(b);
}

bool dinic_BFS(){
	fill(dist, dist + n + 2, -1);
	dist[S] = 0;
	ll qt = 0;
	q[qt++] = S;
	for (ll qh = 0; qh < qt; qh++)
	{
		ll u = q[qh];
		for (ll j = 0; j < G[u].size(); j++)
		{
			Edge &e = G[u][j];
			ll v = e.to;
			if (dist[v] < 0 && e.f < e.cap)
			{
				dist[v] = dist[u] + 1;
				q[qt++] = v;
			}
		}
	}
	return dist[T] >= 0;
}

ll dinic_DFS(ll u, ll f)
{
	if (u == T || f == 0) return f;
	for (ll &i = work[u]; i < G[u].size(); i++)
	{
		Edge &e = G[u][i];
		if (e.cap <= e.f) continue;
		ll v = e.to;
		if (dist[v] == dist[u] + 1)
		{
			ll df = dinic_DFS(v, min(f, e.cap - e.f));
			if (df > 0)
			{
				e.f += df;
				G[v][e.rev].f -= df;
				return df;
			}
		}
	}
	return 0;
}

ll maxFlow()
{
	ll flow = 0;
	while ( dinic_BFS() )
	{
		fill(work, work + n + 2, 0);
		while (true)
		{
			ll df = dinic_DFS(S, INF);
			if (df == 0) break;
			flow += df;
		}
	}

	return flow;
}
