{
	edge[s].push_back(Edge(t,c,edge[t].size()));
	edge[t].push_back(Edge(s,0,edge[s].size()-1));
}

void build()
{
	s=n+1,t=s+1,tot=t;
	for(int i=1;i<=n;i++)
	{
		if(a[i]>0) add(s,i,a[i]),sum+=a[i];
