	memset(lv+1,0,sizeof(int)*tot);
	q.push(s),lv[s]=1;
	while(!q.empty())
	{
		int x=q.front(); q.pop();
		for(int i=0;i<edge[x].size();i++)
		{
			Edge temp=edge[x][i];
			if(temp.cap>0 && !lv[temp.dst])
			{
				lv[temp.dst]=lv[x]+1;
				q.push(temp.dst);
			}
		}
	}
}

