		if(temp.cap>0 && lv[x]<lv[temp.dst])
		{
			int d=dfs(temp.dst,t,min(f,temp.cap));
			if(d>0)
			{
				temp.cap-=d,edge[temp.dst][temp.rev].cap+=d;
				return d;
