// 
// 燃やす埋める問題
// s ----(1)----> i ----(2)----> t
// (1) 割らない時の損失
// (2) 割る時の損失
// を入れて解く.
//
// testcase 1
// 3
// -1 3 4
// => 6   ※ 1つ目を割ると, 全部割ることになるので, 最大流は 1
//           sum で 負の成分を足さなくても, 最大流の計算で負の分が加味される
//
// testcase 2
// 3
// -1000 3 4
// => 0   ※ 1つ目を割らないと, 被害が甚大なので, 最大流は 7
//           どんなに最悪な場合でも, 最大流は割る時の損失の総和(=sum) なので, 最終結果は最悪で 0
//           最終結果が負になることはない
//
// testcase 3
// 3
// 3 4 -1000
// => 7   ※ 3つ目を割らないと, 被害が甚大. 最大流は 0 だし, 0 以外流せない
int main()
{
  ll N;
  std::cin >> N;
  std::vector< ll > va(N+1, 0LL);
  for (ll i = 1; i <= N; i++) {
    std::cin >> va[i];
  }

  ll sum = 0LL;
  ll s = 0;
  ll t = N + 1;
  for (ll i = 1; i <= N; i++) {
    if (va[i] >= 0) {
      sum += va[i];
      add_edge(s, i, + 0LL);
      add_edge(i, t, + va[i]);
    } else {
      add_edge(s, i, - va[i]);
      add_edge(i, t, + 0LL);
    }
  }
  for (ll i = 1; i <= N; i++) {
    for (ll j = i; j + i <= N; j += i) {
      add_edge(i, j+i, INF);
    }
  }

  print(sum - max_flow(s, t));
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N;
long long A[101], B[101];
int op[101], bb, cc, dd;

long long bf(int n) {
  if(n == bb) {
    long long ans = 0;
    for(int i = bb; i < cc; i++) {
      if(op[i] == 0) {
        ans += max(0LL, A[i] + B[i + i]);
      }
    }
    for(int i = cc; i < dd; i++) {
      if(op[i] == 0) {
        ans += B[i];
      }
    }
    for(int i = dd + 1; i <= N; i+=2) {
      if(op[i] == 0) {
        ans += B[i];
      }
    }
    return ans;
  }
  if(op[n]) {
    return bf(n + 1);
  }else {
    long long now = A[n] + bf(n + 1);
    for(int i = n + n; i <= N; i += n) {
      op[i]++;
    }
    now = max(now, bf(n + 1));
    for(int i = n + n; i <= N; i += n) {
      op[i]--;
    }
    return now;
  }
}

long long bf2(int n) {
  if(n + n > N) {
    long long ans = 0;
    for(int i = n; i <= N; i++) {
      if(op[i] == 0) ans += B[i];
    }
    return ans;
  }
  if(op[n]) {
    return bf2(n + 1);
  }else {
    long long now = A[n] + bf2(n + 1);
    for(int i = n + n; i <= N; i += n) {
      op[i]++;
    }
    now = max(now, bf2(n + 1));
    for(int i = n + n; i <= N; i += n) {
      op[i]--;
    }
    return now;
  }
}


