typedef  tree< int , null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;
const int N = 215;
int n, a[N], b[N];
vector < int > g[N], v;
int used[N];
void dfs(int ver){
    used[ver] = 1;
    v.pb(ver);
    for (auto u: g[ver]) if (!used[u]) dfs(u);
}
int solve(vector < int > v){
    int sz = v.size();
    int res = 0;
    for (int i = 0; i < (1 << sz); i++){
        vector < int > z;
        z.clear();
        for (int j = 0; j < sz; j++) if (i &(1 << j)) z.pb(v[j]);
        int r = 0;
        for (auto j: v){
            int t = 0;
            for (auto l: z){
                if (j % l == 0){
                    t = 1;
                    break;
                }
            }
            r += t * a[j];
        }
        res = min(res, r);
    }
    return res;
}
main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt",  "r", stdin);
    //freopen("output.txt", "w", stdout);
    cin >> n;
    int ans = 2e13;
    for (int i = 1; i <= n; i++) cin >> a[i];
    int k = min(n, (int)12);
    for (int i = 0; i < (1 << k); i++){
        int r = 0;
        for (int j = 1; j <= n; j++){
            int t = 0;
            for (int l = 1; l <= k; l++){
                if ((i & (1 << (l - 1))) && j % l == 0){
                    t = 1;
                    break;
                }
            }
            r += t * a[j];
            if (j <= k) t = 0;
            b[j] = t;
        }
        for (int j = k + 1; j <= n; j++){
            if (b[j]) continue;
            for (int l = j + 1; l <= n; l++){
                if (!b[j] && !b[l] && l * j / __gcd(l, j) <= n){
                    g[l].pb(j);
                    g[j].pb(l);
                }
            }
        }
        for (int j = k + 1; j <= n; j++){
            if (used[j] || b[j]) continue;
            dfs(j);
            r += solve(v);
            v.clear();
        }
        memset(used, 0, sizeof(used));
        memset(b, 0, sizeof(b));
        for (int j = k + 1; j <= n; j++) g[j].clear();
        ans = min(ans, r);
    }
    ans = -ans;
    for (int i = 1; i <= n; i++) ans += a[i];
    cout << ans;
}

