#define source 0
#define sink 101
#define pii pair<long long, long long>
#define int long long
using namespace std;

const long long INF = 2e16;

int N;
long long A[105];
vector<int> adj[105];
long long cap[105][105];
int par[105];
int vis[105][105];
void edge(int u, int v, long long c) {
  if(!vis[u][v]) {
    adj[u].push_back(v);
    adj[v].push_back(u);
  }
  vis[u][v] = vis[v][u] = 1;
//  cout << u << " -> " << v << " " << c << "\n";
  cap[u][v] = c;
}

long long BFS() {
  memset(par, -1, sizeof(par));
  queue<pii> q;
  q.emplace(source, INF);
  par[source] = -2;
  while(!q.empty()) {
    int u = q.front().first;
    long long flow = q.front().second;
//    cout << u << " " << flow << "\n";
    q.pop();

    for(int v : adj[u]) {
      if(par[v] == -1 && cap[u][v] > 0) {
        par[v] = u;
        long long new_flow = min(flow, cap[u][v]);
        if(v == sink) return new_flow;
        q.emplace(v, new_flow);
      }
    }
  }
//  cout << "NO\n" << "\n";
  return 0;
}

long long macflow() {
  long long flow = 0, new_flow;
  while(new_flow = BFS()) {
    flow += new_flow;
    int u = sink;
    while(u != source) {
      cap[par[u]][u] -= flow;
      cap[u][par[u]] += flow;
      u = par[u];
    }
  }
//  cout << flow << "\n";
  return flow;
}

int32_t main() {
  ios_base::sync_with_stdio(0);
  cin >> N;
  long long sum = 0;
  for(int i = 1; i <= N; i++) {
    cin >> A[i];
    if(A[i] >= 0) sum += A[i];
  }
  for(int i = 1; i <= N; i++) {
    if(A[i] < 0) {
      edge(source, i, -A[i]);
      for(int j = i * 2; j <= N; j += i) {
        if(A[j] >= 0) {
          edge(i, j, INF);
          edge(j, i, INF);
        }
      }
    }else {
      edge(i, sink, A[i]);
      edge(sink, i, A[i]);
    }
  }
  long long ans = macflow();
//  cout << ans << "\n";
  cout << sum - ans << "\n";
  cin >> N;
}

