};
bool operator < (const Edge &a, const Edge &b){
    if(a.weight != b.weight) return a.weight > b.weight;
    if(a.from != b.from) return a.from > b.from;
    return  a.to > b.to;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef vector<Weight> Array;
typedef vector<Array> Matrix;

void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}

Weight blockingFlow(Graph &g, vector<int> &l, int v, int t, Weight f){
    if(v == t) return f;
    EACH(i, g[v]){
        if(i -> weight > 0 && l[v] < l[i -> to]){
            Weight d = blockingFlow(g, l, i -> to, t, min(f, i -> weight));
            if(d > 0){
                i -> weight -= d;
                g[i -> to][i -> rev].weight += d;
                return d;
            }
        }
    }
    return 0;
}
Weight dinitz(Graph &g, int s, int t){
    int n = g.size();
    Weight flow = 0;
    vector<int> l(n, -1);
    for(;;){
        queue<int> Q;
        fill(ALL(l), -1);
        l[s] = 0;
        Q.push(s);
        while(!Q.empty()){
            int v = Q.front(); Q.pop();
            EACH(i, g[v])if(i -> weight > 0 && l[i -> to] < 0){
                l[i -> to] = l[v] + 1;
                Q.push(i -> to);
            }
        }
        if(l[t] < 0) return flow;
        Weight f;
        while((f = blockingFlow(g, l, s, t, INF)) > 0) flow += f;
    }
}

