class Edmonds_Karp{
    int source;
    int sink;
    int v;
    long long int maxflow = 10000000000;
    std::vector<std::vector<edge>> g;
    std::vector<std::pair<int,int>> back_v;
    std::vector<bool> used;
    std::stack<std::pair<int,int>> minimum_route;

    bool BFS(){
        std::queue<int> que;

        que.push(source);

        while(!que.empty()){
            int t = que.front();
            que.pop();

            if(t == sink)return true;

            if(used[t])continue;

            used[t] = true;

            for(int i = 0; i < g[t].size(); i++){
                if(!used[g[t][i].to] && g[t][i].cap > 0){
                    que.push(g[t][i].to);
                    back_v[g[t][i].to] = std::make_pair(t,i);
                }
            }
        }

        return false;
    }

    void backtrack(){
        minimum_route.push(back_v[sink]);
        std::pair<int,int> t = back_v[sink];
        while(t.second >= 0){
            minimum_route.push(t);
            t = back_v[t.first];
        }
    }

    long long int DFS(int s,long long int f){
        if(s == sink) return f;

        std::pair<int,int> t = minimum_route.top();
        minimum_route.pop();

        edge &e = g[s][t.second];

        int ret = DFS(e.to,std::min(f,e.cap));
        if(ret < 0) return ret;

        e.cap -= ret;
        g[e.to][e.rev].cap += ret;

        return ret;
    }

    public:
    Edmonds_Karp(int s,int t,int n):source(s),sink(t),v(n){
        g = std::vector<std::vector<edge>>(v+1);
        back_v = std::vector<std::pair<int,int>>(v+1,std::make_pair(-1,-1));
        used = std::vector<bool>(v+1,false);
    }

    void add_edge(int f,int t,long long int c){
        g[f].push_back(edge{t,c,(int)g[t].size()});
        g[t].push_back(edge{f,0,(int)g[f].size()-1});
    }

    long long int solve(){
        long long int ans = 0;

        while(BFS()){
            backtrack();
            ans += DFS(source,maxflow);
            fill(used.begin(),used.end(),false);
            fill(back_v.begin(),back_v.end(),std::make_pair(-1,-1));
        }

        return ans;
    }
};


int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    LL n;
    cin >> n;

    vector<LL> a(n+1);

    for(int i = 1; i < n+1; i++){
        cin >> a[i];
    }

    Edmonds_Karp ek = Edmonds_Karp(0,n+1,n+1);

    LL ans = 0;

    for(int i = 1; i < n+1; i++){
        if(a[i] < 0){
            ek.add_edge(0,i,abs(a[i]));
        }else{
            ek.add_edge(i,n+1,abs(a[i]));
            ans += a[i];
        }
        for(int j = i*2; j < n+1; j += i){
            ek.add_edge(i,j,1333333333333);
        }
    }

    cout << ans - ek.solve() << endl;

    return 0;
}

