	for(int i=1;i<=n;i++){
		ll cnt=0;
		for(int j=i;j<=n;j+=i){
			cnt+=a[j-1];
		}
		auto mp=p(i);
		for(auto pp:mp){
			if(Min[pp.first]>cnt){
				Min[pp.first]=cnt;
				Min2[pp.first]=i;
			}
		}

		if(Min[1]>cnt){
			Min[1]=cnt;
			Min2[1]=i;
		}
	}
	set<int>se;
	for(int i=1;i<=n;i++){
		if(i==1)se.insert(i);
		else{
			auto mp=p(i);
			if(mp.size()==1&&mp[i]==1)se.insert(Min2[i]);
		}
	}
	ll MMin=INFL;
	rep(i,1<<se.size()){//使う集合
		set<int>S;
		int ccnt=0;
		for(int c:se){
			if(i>>ccnt&1)S.insert(c);
			ccnt++;
