		ll cnt=0;
		for(auto it1=S.begin();it1!=S.end();it1++){
			if(*it1>n)break;
			cnt+=score({*it1});
			for(auto it2=(++it1)--;it2!=S.end();it2++){
				if((*it1)*(*it2)>n)break;
				cnt-=score({*it1,*it2});
				for(auto it3=(++it2)--;it3!=S.end();it3++){
					if((*it1)*(*it2)*(*it3)>n)break;
					cnt+=score({*it1,*it2,*it3});
					for(auto it4=(++it3)--;it4!=S.end();it4++){
						if((*it1)*(*it2)*(*it3)*(*it4)>n)break;
						cnt-=score({*it1,*it2,*it3,*it4});
					}
				}
			}
		}
		MMin=min(MMin,cnt);
	}

	ll cc=0;
	rep(i,n){
		cc+=a[i];
	}
	cout<<cc-MMin<<endl;
}

