int n;
int removed[110];
ll val[110];
ll sum, ans;
void recurse(int p)
{
	ans = max(ans, sum);
	if (p > n) return;
	recurse(p+1);
	ll s = sum;
	for (int i = p; i <= n; i+=p)
	{
		if (!removed[i])
		{
			sum-=val[i];
		}
		removed[i]++;
	}
	if (sum > s) recurse(p+1);
	for (int i = p; i <= n; i+=p)
	{
		removed[i]--;
		if (!removed[i])
		{
			sum+=val[i];
		}
	}
}
int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) { scanf("%lld", &val[i]); sum+=val[i]; }
	recurse(1);
	printf("%lld\n", ans);
}

