		Ans += A[i];
	}
	int Count = 0;
	for (int i = 2; i <= N; i++) {
		if (isPrime(i))
			prime[Count++] = i;
	}

	for (int j = Count - 1; j >= 0; j--) {
		int p = prime[j];
		for (int mod = N - N % p; mod >= p; mod -= p) {
