					Used[i] = 1;
					tmp -= A[i];
				}

			}

			if (tmp >= Ans) {
				Ans = tmp;
			}
			else {
				for (int i = 0; i < N; i++)
					if (flag[i]) {
						tmp += A[i];
						Used[i] = 0;
					}
			}
		}
	}


