const int INF = 1 << 29;
#define ll long long

struct Edge
{
    int to, rev;
    int capacity;

    Edge(int to_, int capacity_, int rev_)
            : to(to_), capacity(capacity_), rev(rev_){}
};

int DFS(int current, int target, int flow,
        std::vector<std::vector<Edge>>& connection,
        std::vector<bool>& seenTable)
{
    if (current == target)
        return flow;

    seenTable[current] = true;
    for (auto& e : connection[current])
    {
        if (!seenTable[e.to] && 0 < e.capacity)
        {
            auto d = DFS(e.to, target, std::min(flow, e.capacity), connection, seenTable);
            if (0 < d)
            {
                // d だけ e に流す
                e.capacity -= d;

                // d だけ 逆編から流れる
                connection[e.to][e.rev].capacity += d;

                return d;
            }
        }
    }

    return 0;
}

int MaxFlow(int s, int t, std::vector<std::vector<Edge>>& connection)
{
    std::vector<bool> seenTable(connection.size());

    int flow = 0;
    while (true)
    {
        for (auto i=0; i<seenTable.size(); ++i)
            seenTable[i] = false;

        int f = DFS(s, t, INF, connection, seenTable);
        if (f == 0)
            return flow;
        else
            flow += f;
    }
}

int main()
{
    int N;
    std::cin >> N;
    std::vector<ll> A(N + 1);
    std::vector<std::vector<Edge>> graph(N + 3);

    auto maxSum = 0;
    for (auto i=1; i<=N; ++i)
    {
        std::cin >> A[i];
        if (0 < A[i])
            maxSum += A[i];
    }

    const int S = N + 1;
    const int T = N + 2;

    auto Connect = [&](int from, int to, int capacity)
            {
                graph[from].push_back(Edge(to, capacity, graph[to].size()));
                graph[to].push_back(Edge(from, 0, graph[from].size() - 1));
            };

    for (auto i=1; i<=N; ++i)
    {
        if (A[i] < 0)
            Connect(S, i, -A[i]);
        else
            Connect(i, T, A[i]);

        for (auto j=i; j<=N; j += i)
            Connect(i, j, INF);
    }

    auto breakScore = MaxFlow(S, T, graph);
    std::cout << maxSum - breakScore << std::endl;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int MAX_V = 10000;
const ll INF = 1000000000000000LL;

struct Edge {
    int to;
    ll cap;
    int rev;  //行き先、容量、逆辺
    Edge(int to, ll cap, int rev) : to(to), cap(cap), rev(rev) {}
};

vector<Edge> G[MAX_V];
int level[MAX_V];
int iter[MAX_V];

void add_edge(int from, int to, ll cap) {
    G[from].push_back(Edge(to, cap, G[to].size()));
    G[to].push_back(Edge(from, 0, G[from].size() - 1));
}

void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        for (int i = 0; i < G[v].size(); i++) {
            Edge& e = G[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

ll dfs(int v, int t, ll f) {
    if (v == t) return f;
    for (int& i = iter[v]; i < G[v].size(); i++) {
        Edge& e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            ll d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll max_flow(int s, int t) {
    ll flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        ll f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        ll a;
        cin >> a;
        if (a > 0) {
            ans += a;
            add_edge(0, i, 0);
            add_edge(i, n + 1, a);
        } else {
            add_edge(0, i, -a);
            add_edge(i, n + 1, 0);
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = i * 2; j <= n; j += i) {
            add_edge(i, j, INF);
        }
    }

