struct MaxFlow {
    V<ll> *links;
    ll **capacities;
    ll *idxs;
    ll nodes;

    MaxFlow(ll nodes) {
        // i == 0       --> S
        // i == nodes+1 --> T
        links = new V<ll>[nodes+2LL];
        capacities = new ll*[nodes+2LL];
        rep (i, nodes+2LL) {
            capacities[i] = new ll[nodes+2LL];
            memset(capacities[i], 0, (nodes+2LL) * sizeof(ll));
        }
        idxs = new ll[nodes+2LL];
        memset(idxs, 0, (nodes+2LL) * sizeof(ll));
        this->nodes = nodes;
    }

    void add_link(ll a, ll b, ll capacity) {
        links[a].pb(b);
        links[b].pb(a);
        capacities[a][b] = capacity;
        capacities[b][a] = 0LL;
    }

    bool find_path(deque<ll> &path, set<ll> &checked, ll v) {
        if (checked.find(v) != checked.end()) return false;

        checked.insert(v);
        path.push_back(v);
        if (v == nodes+1LL) return true;

        rep (xxx, links[v].size()) {
            ll nowidx = idxs[v]++;
            nowidx %= links[v].size();
            ll nv = links[v][nowidx];
            if (capacities[v][nv] == 0) continue;
            if (find_path(path, checked, nv)) return true;
        }

        // checked.erase(v);
        path.pop_back();
        return false;
    }

    ll solve(void) {
        ll ret = 0LL;

        for ( ; ; ) {

            set<ll> checked;
            deque<ll> foundq;
            if (!find_path(foundq, checked, 0)) break;

            V<ll> found;
            while (foundq.size()) {
                ll v = foundq.front(); foundq.pop_front();
                found.pb(v);
            }

            ll flowcount = 1e18;
            rep (i, (ll)found.size()-1LL) {
                ll src = found[i];
                ll dst = found[i+1];
                flowcount = min(flowcount, capacities[src][dst]);
            }
            assert(flowcount > 0LL);

            rep (i, (ll)found.size()-1LL) {
                ll src = found[i];
                ll dst = found[i+1];
                capacities[src][dst] -= flowcount;
                capacities[dst][src] += flowcount;
            }
            ret += flowcount;

        }

        return ret;
    }
};




void _main()
{
    ll n; llin(n);
    V<ll> alist; alist.pb(0LL); llina(alist, n);

    MaxFlow mf(n);

    srep (i, 1, n+1) {
        ll j = i * 2;
        while (j <= n) {
            mf.add_link(i, j, 1e18);
            j += i;
        }
    }

    srep (i, 1, n+1) {
        if (alist[i] <= 0LL) mf.add_link(0, i, -alist[i]);
        else mf.add_link(i, n+1, alist[i]);
    }

    ll mincut = mf.solve();

    ll total = 0LL;
    for (auto a : alist) if (a > 0LL) total += a;

    cout << total - mincut << endl;
}

