typedef long long ll;
const ll MAXN =105;
const ll INF = 1e18;

ll n,sum, cap[MAXN][MAXN],p[MAXN];
vector<ll> adj[MAXN];
queue<pair<ll,ll>> q;

ll bfs(int s, int t){
    while(!q.empty())q.pop();

    p[0] = -2;
    q.push({0ll,INF});
    while(!q.empty()){
        ll cur = q.front().first;
        ll flow = q.front().second;
        q.pop();
        for (auto next : adj[cur]){
            if (p[next] == -1 && cap[cur][next] > 0){
                p[next] = cur;
                ll newflow = min(flow,cap[cur][next]);
                if(next == t)
                    return newflow;
                q.push({next,newflow});
            }
        }
    }
    return 0;
}

ll maxflow(int s, int t){
    ll ans = 0;

    while(1){
        memset(p,-1,sizeof(p));
        ll newflow = bfs(s,t);
		if(!newflow)break;
        ans += newflow;

		long long cur = t;
		while(cur != s){
			long long prev = p[cur];
			cap[prev][cur] -= newflow;
			cap[cur][prev] += newflow;
			cur = prev;
		}
	}
    return ans;
}

int main(){
    cin>>n;
    ll tmp;
	for(ll i =1;i<=n;i++){
        cin >> tmp;

		if(tmp>=0){
			adj[i].push_back(n+1);
			adj[n+1].push_back(i);
			cap[i][n+1]+=tmp;
			sum+=tmp;
		}
		if(tmp<0){
			adj[i].push_back(0);
			adj[0].push_back(i);
			cap[0][i]-=tmp;
		}
		for(int j = 2*i; j <= n;j += i){
			adj[i].push_back(j);
			adj[j].push_back(i);
			cap[i][j]= INF;
		}
	}

    cout << sum - maxflow(0,n+1) << "\n";
}

