namespace MF { //init before you use it. when you use double, be careful. O(|F||E|)

	struct edge {int to; ll cap, rev; };

	vector<edge> G[MAX_N];
	bool used[MAX_N];

	void init(int n) {
		rep(i, 0, n) G[i].clear();
	}

	int add_edge(int from, int to, ll cap) {
		G[from].push_back((edge){to, cap, (int)G[to].size()});
		G[to].push_back((edge){from, 0, (int)G[from].size() - 1});
		return (int)G[from].size() - 1;
	}

	ll dfs(int v, int t, ll f, bool change = true) { //if you just want to dfs, change = false
		if(v == t) return f;
		used[v] = true;
		for(int i = 0; i < (int)G[v].size(); i++) {
			edge &e = G[v][i];
			if(!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap), change);
				if(d > 0) {
					if(change) {
						e.cap -= d;
						G[e.to][e.rev].cap += d;
					}
					return d;
				}
			}
		}
		return 0;
	}

	ll get(int s, int t) {
		ll flow = 0;
		while(true) {
			memset(used, 0, sizeof(used));
			int f = dfs(s, t, inf);
			if(f == 0) return flow;
			flow += f;
		}
	}
}

int N;
int A[MAX_N];

void solve() {
	cin >> N;
	ll S = 0;
	rep(i, 1, N + 1) {
		cin >> A[i];
		if(A[i] >= 0) S += A[i];
	}
	int s = N + 1, t = N + 2;
	MF::init(N + 3);
	rep(i, 1, N + 1) {
		for(int j = i * 2; j <= N; j += i) {
			MF::add_edge(i, j, linf);
		}
	}
	rep(i, 1, N + 1) {
		if(A[i] >= 0) {
			MF::add_edge(i, t, A[i]);
		}
		else MF::add_edge(s, i, -A[i]);
	}
	cout << S - MF::get(s, t) << "\n";
}

