//int dx[4] = { 0,0,-1,1 }, dy[4] = { 1,-1,0,0 };


template< typename flow_t >
struct Dinic {
	const flow_t INF;

	struct edge {
		int to;
		flow_t cap;
		int rev;
		bool isrev;
		int idx;
	};

	vector< vector< edge > > graph;
	vector< int > min_cost, iter;

	Dinic(int V) : INF(numeric_limits< flow_t >::max()), graph(V) {}

	void add_edge(int from, int to, flow_t cap, int idx = -1) {
		graph[from].push_back({ to, cap, (int)graph[to].size(), false, idx });
		graph[to].push_back({ from, 0, (int)graph[from].size() - 1, true, idx });
	}

	bool bfs(int s, int t) {
		min_cost.assign(graph.size(), -1);
		queue< int > que;
		min_cost[s] = 0;
		que.push(s);
		while (!que.empty() && min_cost[t] == -1) {
			int p = que.front();
			que.pop();
			for (auto &e : graph[p]) {
				if (e.cap > 0 && min_cost[e.to] == -1) {
					min_cost[e.to] = min_cost[p] + 1;
					que.push(e.to);
				}
			}
		}
		return min_cost[t] != -1;
	}

	flow_t dfs(int idx, const int t, flow_t flow) {
		if (idx == t) return flow;
		for (int &i = iter[idx]; i < graph[idx].size(); i++) {
			edge &e = graph[idx][i];
			if (e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
				flow_t d = dfs(e.to, t, min(flow, e.cap));
				if (d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	flow_t max_flow(int s, int t) {
		flow_t flow = 0;
		while (bfs(s, t)) {
			iter.assign(graph.size(), 0);
			flow_t f = 0;
			while ((f = dfs(s, t, INF)) > 0) flow += f;
		}
		return flow;
	}

	void output() {
		for (int i = 0; i < graph.size(); i++) {
			for (auto &e : graph[i]) {
				if (e.isrev) continue;
				auto &rev_e = graph[e.to][e.rev];
				cout << i << "->" << e.to << " (flow: " << rev_e.cap << "/" << e.cap + rev_e.cap << ")" << endl;
			}
		}
	}
};

//Ford-Fulkerson法で最大流を求める O(F|E|)
const int MAX_V = 500;
struct edge { int to, cap, rev; };
vector<edge>G[MAX_V];
bool used[MAX_V];

void add_edge(int from, int to, int cap) {
	G[from].push_back({ to, cap, G[to].size() });
	G[to].push_back({ from,0,G[from].size() - 1 });
}
int dfs(int v, int t, int f) {
	if (v == t)return f;
	used[v] = true;
	for (int i = 0; i < G[v].size(); i++) {
		edge &e = G[v][i];
		if (!used[e.to] && e.cap > 0) {
			int d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}
int max_flow(int s, int t) {
	int flow = 0;
	for (;;) {
		memset(used, 0, sizeof(used));
		int f = dfs(s, t, INF);
		if (f == 0) {
			return flow;
		}
		flow += f;
	}
}

void solve() {
	int N; cin >> N;
	vector<int>A(N + 1);
	FOR(i, 1, N + 1)cin >> A[i];
	ll ans = 0;
	FOR(i, 1, N + 1) {
		if (A[i] > 0)ans += A[i];
	}
	//Dinic<int>G(N + 2);
	int s = 0, t = N + 1;
	FOR(i, 1, N + 1) {
		if (A[i] >= 0) {
			add_edge(s, i, 0);
			add_edge(i, t, A[i]);
		}
		else {
			add_edge(s, i, -A[i]);
			add_edge(i, t, 0);
		}
		for (int k = 2; i*k <= N; k++) {
			add_edge(i,i*k, LINF);
		}
	}
	ll pena = max_flow(s, t);
	print(ans - pena);
}



