ll dfs(int k) {
	if (k > n)return 0;
	if (used[k])return dfs(k + 1);
	ll res = 0;
	if (k * 2 > n) {
		Rep1(i, k, n) {
			if (!used[i])res += max((ll)0, a[i]);
		}
	}
	else if (k * 3 > n) {
		if ((!used[k * 2])&&(!used[k*3])) {
			used[2 * k] = 1; used[3 * k] = 1;
			res = max({ (ll)0,a[k],a[k] + a[k * 2],a[k]+a[k*3],a[k]+a[2*k]+a[3*k] });
			res += dfs(k + 1);
		}
		else if (!used[k * 2]) {
			used[k * 2] = 1;
			res = max({ (ll)0,a[k],a[k] + a[k * 2] });
			res += dfs(k + 1);
		}
		else if (!used[k * 3]) {
			used[k * 3] = 1;
			res = max({ (ll)0,a[k],a[k] + a[k * 3] });
			res += dfs(k + 1);
		}
		else {
			res = max((ll)0, a[k]);
			res += dfs(k + 1);
		}
	}
	else if (k * 4 > n) {
		if (!used[k * 2]) {
			used[2 * k] = 1;
			res = max({ (ll)0,a[k],a[k] + a[k * 2] });
			res += dfs(k + 1);
		}
		else {
			res = max((ll)0, a[k]);
			res += dfs(k + 1);
		}
	}
	else {
		res = a[k]+dfs(k + 1);
		ll memo[101]; rep1(i, 100)memo[i] = used[i];
		for (int i = k; i <= n; i += k) {
			used[i] = 1;
		}
		res = max(res, dfs(k + 1));
		rep1(i, 100)used[i] = memo[i];
	}
	return res;
}
