vector<int> a;
int64_t res = 0;

void rec(int p, int n, vector<int>& u) {
  if (p * 2 > n) {
    int64_t cur = 0;
    for (int i = 1; i <= n; ++i) {
      if (!u[i]) {
        if (i * 2 > n && a[i-1] < 0) {
          continue;
        }
        cur += a[i-1];
      }
    }
    res = max(res, cur);
    return;
  }
  if (a[p-1] >= 0) {
    rec(p + 1, n, u);
  } else {
    for (int i = p; i <= n; i += p) {
      u[i]++;
    }
    rec(p + 1, n, u);
    for (int i = p; i <= n; i += p) {
      u[i]--;
    }
    rec(p + 1, n, u);
  }
}

