  for (int i = 1; i <= n; i++) {
    if (a[i] > 0) {
      sum += a[i];
      g[i].push_back(sink);
      g[sink].push_back(i);
      cap[i][sink] = a[i];
    } else if (a[i] < 0) {
      g[source].push_back(i);
      g[i].push_back(source);
      cap[source][i] = -a[i];
    }
  }

  for (int i = 1; i <= n; i++) {
    for (int j = i; j <= n; j += i) {
      g[i].push_back(j);
      g[j].push_back(i);
      cap[i][j] = kInf;
    }
  }

