constexpr auto INF = LLONG_MAX / 3;

using namespace std;

class network {
  private:
    struct edge;
    int size;
    vector<vector<edge>> graph;
    struct edge {
      int to, capacity, flow, rev;
      vector<vector<edge>>& graph;
      edge& reverse() {
        return graph[to][rev];
      }
      void add_flow(int df) {
        flow += df;
        reverse().flow -= df;
      }
    };

  public:
    network(int n): size(n), graph(n) {}

    void add_edge(int from, int to, int cap) {
      graph[from].push_back({to, cap, 0, static_cast<long long>(graph[to].size()), graph});
      graph[to].push_back({from, cap, cap, static_cast<long long>(graph[from].size() - 1), graph});
    }

    int max_flow(int source, int sink) {
      int flow = 0;
      while (true) {
        queue<int> que;
        que.push(source);
        vector<edge*> path(size, nullptr);
        while (!que.empty()) {
          int v = que.front();
          que.pop();
          for (auto& e : graph[v]) {
            if (e.to == source || path[e.to] != nullptr || e.flow == e.capacity)
              continue;
            que.push(e.to);
            path[e.to] = &e;
          }
        }
        if (path[sink] == nullptr)
          break;
        int inc = INF;
        for (auto e = path[sink]; e != nullptr; e = path[e->reverse().to])
          inc = min(inc, e->capacity);
        for (auto e = path[sink]; e != nullptr; e = path[e->reverse().to])
          e->add_flow(inc);
        flow += inc;
      }
      return flow;
    }
};

signed main() {
  int n;
  cin >> n;
  vector<int> a(n);
  int reward = 0;
  network graph(n + 2);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    if (a[i] < 0) {
      graph.add_edge(0, i + 1, -a[i]);
    }
    else {
      reward += a[i];
      graph.add_edge(i + 1, n + 1, a[i]);
    }
  }
  for (int i = 1; i <= n; i++)
    for (int j = 2 * i; j <= n; j += i)
      graph.add_edge(i, j, INF);
  cout << (reward - graph.max_flow(0, n + 1)) << endl;
}

#include<bits/stdc++.h>
using namespace std;

struct edge{long long t; long long c; long long r;};
vector<edge> G[105];
long long depth[105], n, INF=1e15, ans, a;

void add_edge(long long f, long long t, long long c){
	G[f].push_back(edge{t, c, (long long)G[t].size()});
	G[t].push_back(edge{f, 0, (long long)G[f].size()-1});
}

bool bfs(long long s, long long t){
	memset(depth,-1,sizeof(depth));
	depth[s] = 0;
	queue<long long> que;
	que.push(s);
	while(!que.empty()){
		long long v = que.front(); 
		que.pop();
		for(edge e: G[v]) if(e.c && depth[e.t] == -1){
			depth[e.t] = depth[v] + 1;
			que.push(e.t);
		}
	}
	return depth[t] != -1;
}

long long dfs(long long v, long long t, long long f){
	if(v == t) return f;
	long long ret = 0;
	for(edge& e: G[v]){
		if(depth[v] < depth[e.t] && e.c){
			long long d = dfs(e.t, t, min(f - ret, e.c));
			if(d){
				e.c -= d; G[e.t][e.r].c += d;
				ret += d;
			}
		}
		if(f == ret) break;
	}
	return ret;
}

long long maxflow(long long s, long long t){
	long long ret = 0;
	while(bfs(s,t)) ret += dfs(s, t, INF);
	return ret;
}

