			dinic.add_edge(i,t,0);
		}
		else{
			sum+=a[i];
			dinic.add_edge(s,i,0);
			dinic.add_edge(i,t,a[i]);
		}
	}
	for(int i=1;i<=n;i++){
		for(int j=i*2;j<=n;j+=i){
			dinic.add_edge(i-1,j-1,INT_MAX);
		}
	}
	cout<<sum-dinic.max_flow(s,t)<<endl;
}

