  void add_edge(int from, int to, int cap) {
    G[from].push_back((edge){to, cap, sz(G[to])});
    G[to].push_back((edge){from, 0, sz(G[from])-1});
  }

  void bfs(int s) {
    level.assign(V,-1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for(auto &e: G[v]) if(e.cap>0 && level[e.to]<0){
        level[e.to] = level[v] + 1;
        q.push(e.to);
      }
    }
  }

  int dfs(int v, int t, int f) {
    if(v==t) return f;
    FOR(i, itr[v], sz(G[v])){
      edge& e = G[v][i];
      if(e.cap>0 && level[v]<level[e.to]) {
        int d = dfs(e.to, t, min(f, e.cap));
        if(d>0) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
