			if (((i >> j) & 1) == 0) continue;
			for (int k = j + 1; k <= N; k += j + 1) {
				b[k - 1] = 0;
			}
		}
		int tmp = 0;
		rep(i, N) tmp += b[i];
		if (tmp > ret) {
			ret = tmp;
			arg = b;
			maxnum = i;
		}
	}

	REP(i, N / 2, N - 1) arg[i] = max(0LL, arg[i]);
	rep(i, N) cerr << arg[i] << " ";
	cerr << endl;

	ret = 0;
	rep(i, N) ret += arg[i];

	return ret;
}

