long long augment(long long pos, long long bottleneck) {
  if (pos == 0) return bottleneck;

  if (pre[pos] != -1) {
      long long flow = augment(pre[pos], min(bottleneck, cap[pre[pos]][pos]));

    cap[pre[pos]][pos] -= flow;
    cap[pos][pre[pos]] += flow;

    return flow;
  }

  return 0;
}

void dfs(long long u) {
  if(u == n+1) return;
  for(long long i=0; i<adj[u].size(); i++) {
    long long v = adj[u][i];
    if (pre[v] == -1 && cap[u][v] > 0) {
      pre[v] = u;
      dfs(v);
    }

    if (pre[n+1] != -1) return;
  }
}


