template<class T>
int max_flow(GraphF<T>& G, int s, int t) {
  int N = G.size();
  T total = 0;
  for(bool up=true;up;){
	up = false;
	// bfs
    vector<int> level(N, -1);
	level[s] = 0;
    queue<int> Q;
	Q.push(s);
	while(!Q.empty()){
      int u = Q.front(); Q.pop();
      if(u == t) break;
      for(auto& e: G[u])
		if(e.cap > 0 && level[e.to] == -1){
		  Q.push(e.to);
		  level[e.to] = level[u] + 1;
		}
    }

	// dfs
    vector<bool> finished(N);
	function<T(int,T)> dfs = [&](int u, T f){
	  if(u == t || f == 0) return f;
	  if(finished[u]) return static_cast<T>(0);
	  finished[u] = true;
	  for(auto& e: G[u]){
		if(level[e.to] > level[u]){
		  T fp = dfs(e.to, min(f, e.cap));
		  if(fp > 0){
			e.cap -= fp;
			G[e.to][e.rev].cap += fp;
			finished[u] = false;
			return fp;
		  }
		}
	  }
	  return static_cast<T>(0);
	};

	while(true){
      T f = dfs(s, INF);
      if (f == 0) break;
      total += f;
	  up = true;
    }
  }
  return total;
}

