struct dinic{
  struct edge{int to; ll cap; int rev;};
  int V;
  vector<vector<edge>> G;
  vector<int> itr, level;
  dinic(int V) : V(V) { G.assign(V,vector<edge>()); }

  void add_edge(int from, int to, ll cap) {
    G[from].push_back((edge){to, cap, sz(G[to])});
    G[to].push_back((edge){from, 0ll, sz(G[from])-1});
  }

  void bfs(int s) {
    level.assign(V,-1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for(auto &e: G[v]) if(e.cap>0ll && level[e.to]<0){
        level[e.to] = level[v] + 1;
        q.push(e.to);
      }
    }
  }

  ll dfs(int v, int t, ll f) {
    if(v==t) return f;
    FOR(i, itr[v], sz(G[v])){
      edge& e = G[v][i];
      if(e.cap>0ll && level[v]<level[e.to]) {
        ll d = dfs(e.to, t, min(f, e.cap));
        if(d>0ll) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0ll;
  }

  ll run(int s, int t) {
    ll ret = 0, f;
    while(bfs(s), level[t] >= 0) {
      itr.assign(V, 0);
      while ((f=dfs(s, t, linf)) > 0ll) ret += f;
    }
    return ret;
  }
};

