using namespace std;
const int MAXN = 505;
struct edg{int pos; long long cap; int rev;};
vector<edg> gph[MAXN];
void clear(){for(int i=0; i<MAXN; i++) gph[i].clear();}
void add_edge(int s, int e, long long x){
	gph[s].push_back({e, x, (int)gph[e].size()});
	gph[e].push_back({s, 0, (int)gph[s].size()-1});
}
int dis[MAXN], pnt[MAXN];
bool bfs(int src, int sink){
	memset(dis, 0, sizeof(dis));
	memset(pnt, 0, sizeof(pnt));
	queue<int> que;
	que.push(src);
	dis[src] = 1;
	while(!que.empty()){
		int x = que.front();
		que.pop();
		for(auto &e : gph[x]){
			if(e.cap > 0 && !dis[e.pos]){
				dis[e.pos] = dis[x] + 1;
				que.push(e.pos);
			}
		}
	}
	return dis[sink] > 0;
}
long long dfs(int x, int sink, long long f){
	if(x == sink) return f;
	for(; pnt[x] < gph[x].size(); pnt[x]++){
		edg e = gph[x][pnt[x]];
		if(e.cap > 0 && dis[e.pos] == dis[x] + 1){
			long long w = dfs(e.pos, sink, min(f, e.cap));
			if(w){
				gph[x][pnt[x]].cap -= w;
				gph[e.pos][e.rev].cap += w;
				return w;
			}
		}
	}
	return 0;
}
long long match(int src, int sink){
	long long ret = 0;
	while(bfs(src, sink)){
		long long r;
		while((r = dfs(src, sink, (long long)2e9))) ret += r;
	}
	return ret;
}

int a[MAXN];
int main()
{
    int N; scanf("%d", &N);
    long long ans = 0;
    for(int i=1; i<=N; ++i)
    {
        scanf("%d", a+i);
        if(a[i]>0) ans += a[i];
    }
    int S = N+1;
    int T = N+2;
    for(int i=1; i<=N; ++i)
    {
        if(a[i] <= 0) add_edge(S, i, -a[i]);
        else add_edge(i, T, a[i]);
    }
    for(int i=1; i<=N; ++i)
        for(int j=2*i; j<=N; j += i)
            add_edge(i, j, (long long)(1e18));
    printf("%lld\n", ans - match(S, T));
    return 0;
}

