const int mod = 1000000007;

const ll INF = mod * 328ll;
struct Dinic {
    struct edge {
        ll t, c, r;
        edge(ll _t, ll _c, ll _r) : t(_t), c(_c), r(_r) {}
    };
    vector<ll> l, nxt;
    vector<vector<edge>> e;
    Dinic(ll n) : e(n + 1) {}
    void add_edge(ll u, ll v, ll w) {//directed
        e[u].push_back(edge(v, w, (int)e[v].size()));
        e[v].push_back(edge(u, 0, (int)e[u].size() - 1));
    }
    edge& rev(const edge& E) {
        return e[E.t][E.r];
    }
    bool bfs(ll s, ll t) {
        l.assign(e.size(), INF);
        l[s] = 1;
        queue<ll> Q;
        for (Q.push(s); !Q.empty(); Q.pop()) {
            s = Q.front();
            for (const edge& E : e[s])
                if (E.c > 0 && l[E.t] > l[s] + 1) {
                    l[E.t] = l[s] + 1; Q.push(E.t);
                }
        }
        return l[t] < INF;
    }
    ll dfs(ll s, ll t, ll num = INF) {
        if (s == t || num == 0) return num;
        ll ans = 0;
        for (ll& i = nxt[s]; num && i < e[s].size(); i += num > 0) {
            edge& E = e[s][i];
            if (E.c > 0 && l[s] + 1 == l[E.t]) {
                ll tmp = dfs(E.t, t, min(num, E.c));
                rev(E).c += tmp, ans += tmp;
                E.c -= tmp, num -= tmp;
            }
        }
        return ans > 0 ? ans : l[s] = 0;
    }
    ll operator()(ll s, ll t) {
        ll ans = 0;
        for (; bfs(s, t); ans += dfs(s, t)) nxt.assign(e.size(), 0);
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    int n, a[102] = {};
    ll z = 0;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    Dinic D(n + 2);
    for (int i = 1; i <= n; i++) {
        if (a[i] > 0) D.add_edge(0, i, a[i]), z += a[i];
        else D.add_edge(i, n + 1, -a[i]);
        for (int j = i + i; j <= n; j += i) D.add_edge(j, i, mod * 328ll);
    }
    cout << z - D(0, n + 1) << '\n';
}

