LL Dinic(int x,LL sum){
  if (x==T) return sum;LL os=sum;
  for (int i=End[x],y;i;i=Next[i])
    if (Value[i]){
      if (f[y=Go[i]]!=f[x]+1) continue;
      LL now=Dinic(y,min(os,Value[i]));
      os-=now;Value[i]-=now;Value[i^1]+=now;
    }
  if (sum==os) f[x]=-1;return sum-os;
}
