ll getcost(int p){
	ll res = 0;
	int x = p;
	while(p <= n){
		if(!w[p]) res += a[p];
		p += x;
	}
	return res;
}

void rem(int p){
	int x = p;
	while(p <= n){
		w[p] = 1;
		p += x;
	}
}

void solve(){
	ans = 0;
	bool f = true;
	while(true){
		int p = -1;
		fdi(n+1, 1){
			if(w[i]) continue;
			if(getcost(i) < 0){
				p = i;
				break;
			}
		}
		if(p == -1) break;
		rem(p);
	}
	fi(1, n+1){
		if(!w[i]) ans += a[i];
	}
}

