unsigned long xor128(void) {
	static unsigned long x = 123456789, y = 362436069, z = 521288629, w = 88675123;
	unsigned long t;
	t = (x ^ (x << 11));
	x = y;
	y = z;
	z = w;
	return (w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
}
ll SA(int N, vector<int>A, vector<int>orig, int init_score,vector<bool>del) {
	const double LIMIT = 1850;
	int t = 0;
	double start_temp = 1000000000, end_temp = 10;
	clock_t start = clock();
	const double m = (end_temp - start_temp) / LIMIT;
	int pre_val = init_score, new_val = 0;
	double temp = start_temp;
	int best_score = pre_val;
	double TIME = 0;
	vector<int>dels = orig;
	vector<bool>new_del(N + 1);
	//vector<bool>del(N + 1);

	while (true) {
		t++;
		//DEBUG(t);
		//VSORT(dels);
		//print_space(dels);
		//rint_space(del);
		if (t % 100 == 0) {
			//DEBUG(t);
			//DEBUG(best_score);
			//VSORT(dels);
			//print_space(dels);
			clock_t end = clock();
			TIME = static_cast<double>(end - start) / CLOCKS_PER_SEC * 1000.0;
			temp = start_temp + m * TIME;
			if (TIME > LIMIT) goto END;
		}
		bool sign = xor128() & 1;
		//消去するものを1つ減らす
		if (sign) {
			//cerr << "a" << endl;
			int M = dels.size();
			if (M == 0)continue;
			int idx = xor128() % M;
			int d = dels[idx];
			//dels.erase(dels.begin() + idx);
			REP(i, N + 1)new_del[i] = false;
			for (auto x : dels) {
				if (x == d)continue;
				if (new_del[x])continue;
				for (int j = x; j <= N; j += x) {
					if (new_del[j])break;
					new_del[j] = true;
				}
			}
			new_val = 0;
			FOR(i, 1, N + 1) {
				if (!new_del[i])new_val += A[i];
			}
			double prob = exp((new_val - pre_val) / temp);
			if (new_val > pre_val || prob > (xor128() % INF) / (double)INF) {
				del = new_del;
				best_score = max(best_score,new_val);
				dels.erase(dels.begin() + idx);
			}
		}
		//消去するものを1つ増やす
		else {
			//cerr << "b" << endl;
			int cnt = 0;
			FOR(i, 1, N + 1) {
				if (!del[i])cnt++;
			}
			if (cnt == 0)continue;
			int idx = xor128() % cnt;
			int d = 0;
			int c = 0;
			//DEBUG(cnt);

			FOR(i, 1, N + 1) {
				if (!del[i]) {
					if (c == idx) {
						d = i; break;
					}
					c++;
				}
			}
			REP(i, N + 1)new_del[i] = false;
			for (auto x : dels) {
				if (new_del[x])continue;
				for (int j = x; j <= N; j += x) {
					if (new_del[x])continue;
					new_del[x] = true;
				}
			}
			for (int j = d; j <= N; j += d) {
				new_del[j] = true;
			}
			new_val = 0;
			FOR(i, 1, N + 1) {
				if (!new_del[i])new_val += A[i];
			}
			double prob = exp((new_val - pre_val) / temp);
			if (new_val > pre_val || prob > (xor128() % INF) / (double)INF) {
				del = new_del;
				best_score = max(best_score, new_val);
				//dels.erase(dels.begin() + idx);
				dels.push_back(d);
			}
		}
	}
END:;
	return best_score;
}
void solve() {
	int N; cin >> N;
	vector<int>A(N + 1);
	FOR(i, 1, N + 1)cin >> A[i];
	//vector<int>dum1;
	//vector<bool>dum2(N+1);

	vector<bool>use(N + 1, true);
	FORR(i, N + 1, 1) {
		ll sum = 0;
		for (int j = i; j <= N; j += i) {
			if (use[j])sum += A[j];
		}
		if (sum < 0) {
			for (int j = i; j <= N; j += i) {
				use[j] = false;
			}
		}
	}
	int ans = 0;
	FOR(i, 1, N + 1)if (use[i])ans += A[i];
	vector<int>v;
	vector<bool>del(N + 1);
	REP(i, N + 1)if (!use[i])del[i] = true;
	FOR(i, 1, N + 1) {
		if (del[i]) {
			v.push_back(i);
			for (int j = i; j <= N; j += i)del[j] = false;
		}
	}
	print(SA(N, A, v, ans, del));
}



