void add_edge(vector< vector<edge> >& G, int from, int to, int cap) {
  G[from].push_back((edge){ to, cap, SIZE(G[to])   });
  G[to].push_back((edge){ from, 0, SIZE(G[from])-1 });
}

int get_flow(const vector< vector<edge> >& G, vector<bool>& used, int v, int t, vector<int>& path)
{
  if (v == t) {
    return INF;
  }
  used[v] = true;

  rep(i, 0, SIZE(G[v])) {
    edge e = G[v][i];
    if (used[e.to] || e.cap == 0) {
      continue;
    }
    int flow = min(e.cap, get_flow(G, used, e.to, t, path));
    if (flow != 0) {
      path.push_back(i);

      used[v] = false;
      return flow;
    } else {
      path.clear();
    }
  }

  used[v] = false;
  return 0;
}

void push_flow(vector< vector<edge> >& G, int s, int flow, vector<int>& path)
{
  int now = s;
  rep(i, 0, SIZE(path)) {
    edge e = G[now][path[i]];
    G[now][path[i]].cap -= flow;
    G[e.to][e.rev].cap += flow;
    now = e.to;
  }
}


int solve(vector< vector<edge> >& G, int s, int t)
{
  int sum = 0;
  vector<bool> used(SIZE(G));
  vector<int> path;
  while (true) {
    fill(ALL(used), false);
    int flow = get_flow(G, used, s, t, path);
    if (flow == 0) {
      break;
    } else {
      push_flow(G, s, flow, path);
      sum += flow;
    }
  }
  return sum;
}


signed main()
{
  int N; cin >> N;
  vector< vector<edge> > G(N+2, vector<edge>());

  int sum = 0;
  rep(i, 0, N) {
    int a; cin >> a;
    if (a < 0) {
      add_edge(G, 0, i+1, -a);
    } else {
      add_edge(G, i+1, N+1, a);
      sum += a;
    }
  }

  rep(i, 1, N+1) {
    for(int j=2; i*j <= N; ++j) {
      add_edge(G, i, i*j, INF);
    }
  }

  cout << sum - solve(G, 0, N+1) << endl;

  return 0;
}

