#include<bits/stdc++.h>
using namespace std;

using i64 = int64_t;

constexpr int MAX_V = 110;
constexpr i64 INF = 1e12;

// 辺を表す構造体 (行き先, 容量, 逆辺)
struct edge {
    i64 to, cap, rev;
};

vector<edge> G[MAX_V]; // グラフの隣接リスト表現
int level[MAX_V];           // sからの距離
int iter[MAX_V];            // どこまで調べ終わったか

// fromからtoへ向かう容量capの辺をグラフに追加する
void add_edge(int from, int to, i64 cap) {
    G[from].push_back((edge){to, cap, (int)G[to].size()});
    G[to].push_back((edge){from, 0, (int)G[from].size() - 1});
}

// sからの最短距離をBFSで計算する
void bfs(int s) {
    memset(level, -1, sizeof(level));
    std::queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        for (int i = 0; i < G[v].size(); i++) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

// 増加パスをDFSで探す
i64 dfs(int v, int t, i64 f) {
    if (v == t)
        return f;
    for (int &i = iter[v]; i < G[v].size(); i++) {
        edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            i64 d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

// sからtへの最大流を求める
i64 max_flow(int s, int t) {
    i64 flow = 0;
    for (;;) {
        bfs(s);
        if (level[t] < 0)
            return flow;
        memset(iter, 0, sizeof(iter));
        i64 f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}

int main(){
    int n;
    cin >> n;
    i64 sum = 0;
    for(int i=1;i<=n;++i){
        i64 a;
        cin >> a;
        if(a > 0){
            sum += a;
            add_edge(0, i, 0);
            add_edge(i, n+1, a);
        }else{
            add_edge(0, i, -a);
            add_edge(i, n+1, 0);
        }
        for(int j=i*2;j<=n;j+=i){
            add_edge(i, j, INF);
        }
    }
    i64 loss = max_flow(0, n+1);
    cout << sum - loss << endl;

    return 0;
}

