template <typename flow_t> struct flow_graph {
	static const flow_t INF = 1e18;
	struct edge {
		int dest;
		flow_t cap;

		edge() {}
		edge(int dest_, flow_t cap_) : dest(dest_), cap(cap_) {}
	};
	vector<vector<int> > adj;
	vector<edge> edges;
	vector<int> memo;
	vector<int> dist;
	vector<int> bfs;

	flow_graph(int n) {
		memo.resize(n);
		dist.resize(n);
		adj.resize(n);
		bfs.reserve(n);
	}

	void add_edge(int from, int to, flow_t cap) {
		assert(cap >= 0);
		int e = int(edges.size());
		adj[from].push_back(e);
		adj[to].push_back(e+1);
		edges.push_back(edge(to, cap));
		edges.push_back(edge(from, 0));
	}

	void path(int sidx) {
		bfs.clear();
		bfs.push_back(sidx);
		fill(dist.begin(), dist.end(), -1);
		dist[sidx] = 0;
		for (int s = 0; s < int(bfs.size()); s++) {
			int v = bfs[s];
			for (int j = 0; j < int(adj[v].size()); j++) {
				int e = adj[v][j];
				int w = edges[e].dest;
				if (edges[e].cap > 0 && dist[w] == -1) {
					dist[w] = dist[v] + 1;
					bfs.push_back(w);
				}
			}
		}
	}

	flow_t block_flow(int tidx, int v, flow_t r) {
		if (tidx == v) {
			return r;
		}
		for (int& j = memo[v]; j < int(adj[v].size()); j++) {
			int e = adj[v][j];
			int w = edges[e].dest;
			flow_t& c = edges[e].cap;
			if (c && dist[w] == dist[v]+1) {
				flow_t del = block_flow(tidx, w, min(r, c));
				if (del > 0) {
					c -= del;
					edges[e^1].cap += del;
					return del;
				}
			}
		}
		return 0;
	}

	flow_t maxflow(int sidx, int tidx) {
		flow_t total = 0;
		while (true) {
			path(sidx);
			if (dist[tidx] == -1) break;
			fill(memo.begin(), memo.end(), 0);
			while (true) {
				flow_t del = block_flow(tidx, sidx, INF);
				if (del == 0) break;
				total += del;
			}
		}
		return total;
	}
};

using ll = long long;
const int OFF = 1e9;
const ll INF = 1e15;

int main() {
	ios::sync_with_stdio(0), cin.tie(0);
	int n;
	cin >> n;
	vector<int> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	flow_graph<ll> mf(n + 2);
	int sidx = n;
	int tidx = n+1;
	ll total = 0;
	// S: 扔掉
	for (int i = 0; i < n; i++) {
		mf.add_edge(sidx, i, OFF);
		mf.add_edge(i, tidx, OFF + a[i]);
		total += a[i];
	}
	for (int i = 1; i <= n; i++) {
		for (int j = i+i; j <= n; j += i) {
			mf.add_edge(i-1, j-1, INF);
		}
	}
	int answer = total - (mf.maxflow(sidx, tidx) - ll(n) * OFF);
	cout << answer << '\n';
}

