struct PrimeSieve{
    vector<bool> is_prime;
    vector<int> primes;
    PrimeSieve(int N){
        is_prime.resize(N+1);
        fill(is_prime.begin()+2,is_prime.end(),true);
        for(int i = 2; i <= N; ++i)
            if(is_prime[i]){
                primes.pb(i);
                for(int j = i*2; j <= N; j += i)
                    is_prime[j] = false;
            }
    }
};
