void saiki(int b) {
	if (b == 11||b==n+1) {
		int t = 0;
		for (int i = 1; i <= 10; i++) { if (k[i])t += a[i]; }
		for (int i = 11; i <= n; i++) {
			for (int j = 1; j <= 10; j++) {
				if (i%j == 0 && k[j]) {
					t += a[i];
					k[i] = true;
					break;
				}
				else {
					k[i] = false;
				}
			}
		}
		for (int i = n; i > 10; i--) {
			if (k[i])continue;
			bool OK = true;//自由に使えるか？
			for (int j = i*2; j <= n; j+=i) {
				if (!k[j])OK = false;
			}
			if (OK) {
				if (a[i] >= 0) {
					k[i] = true;
					t += a[i];
				}
			}
			else {
				int o = 0;
				if (a[i] >= 0) {
					for (int j = i; j <= n; j+=i) {
						if(!k[j])o += a[j];
					}
					if (o >= 0) {
						for (int j = i; j <= n; j += i) {
							k[j] = true;
						}
						t += o;
					}
				}
			}
		}
		MAX = max(MAX, t);
		return;
	}
	for (int i = 1; i < b; i++) {
		if (b%i == 0 && k[i]) {
			k[b] = true;
			saiki(b + 1);
			return;
		}
	}
	k[b] = false;
	saiki(b + 1);
	k[b] = true;
	saiki(b + 1);
}
