		add_edge(to,from,cost);
	}
};


vector<cost_t> bellmanford(const Graph& g, int from)
{
	vector<cost_t> res(g.size(),INF);
	res[from] = 0;
	bool conf = true;
	int cnt = 0;
	while(conf){
		conf = false;
		for(int i = 0; i < g.size(); i++){
			if(res[i] != INF)
			for(const auto& e : g[i]){
				if(res[e.to] > res[i]+e.cost){
					conf = true;
					res[e.to] = res[i]+e.cost;
				}
			}
		}
		if(cnt > g.size()+5) return vector<cost_t>();
		cnt++;
	}
	return res;
}

cost_t dMaxFlow(const Graph &g_, int s, int t){
	Graph g = g_;
	assert(s != t);
	int n = g.size();
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < int(g_[i].size()); j++) {
			auto&& e = g[i][j];
			e.rev = g[e.to].size();
			g.add_edge(e.to,i,-1,0,j);
		}
	}

	cost_t flow = 0;
	while(true){
		vector<int> level(n,-1);
		level[s] = 0;
		queue<int> que;
		que.push(s);
		while(!que.empty()) {
			int v = que.front();
			que.pop();
			for(auto&& e : g[v]) {
				if(e.cap > 0 and level[e.to] < 0){
					level[e.to] = level[v]+1;
					que.push(e.to);
				}
			}
		}

		if(level[t] < 0) return flow;

		vector<int> iter(n,0);
		function<cost_t(int, int)> dfs = 
		[&](int v, cost_t f) -> cost_t {
			if(v == t) return f;
			for(int& i = iter[v]; i < (int)g[v].size(); ++i) {
				auto& e = g[v][i];
				if(e.cap <= 0 or level[v] >= level[e.to]) continue;
				int d = dfs(e.to, min(f,e.cap));
				if(d > 0){
					e.cap -= d;
					g[e.to][e.rev].cap += d;
					return d;
				}
			}
			return 0;
		};

		cost_t f;
		while((f = dfs(s, INF)) > 0) {
			flow += f;
		}
	}
}

