		G[to].push_back(Edge(G[from].size()-1, from, 0));
	}

	void bfs(int32 s){
		fill(level.begin(), level.end(), -1);
		queue<int32> que;
		level[s] = 0;
		que.push(s);
		while(!que.empty()){
			int32 v = que.front(); que.pop();
			for(int32 i = 0;i < G[v].size();i++){
				Edge &e = G[v][i];
				if(e.c > 0 && level[e.v] < 0){
					level[e.v] = level[v]+1;
					que.push(e.v);
				}
			}
		}
	}

	int64 dfs(int32 v, int32 t, int64 f){
		if(v == t) return f;
		for(int32 &i = iter[v];i < G[v].size();i++){
			Edge &e = G[v][i];
			if(e.c > 0 && level[v] < level[e.v]){
				int32 d = dfs(e.v, t, min(f, e.c));
				if(d > 0){
					e.c -= d;
					G[e.v][e.u].c += d;
					return d;
				}
			}
		}
		return 0;
	}

	int64 max_flow(int32 s, int32 t){
		int64 flow = 0;
		for(;;){
			bfs(s);
			if(level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			int64 f;
			while((f = dfs(s, t, INF)) > 0)
				flow += f;
		}
		return flow;
	}
};

int main(void){
	int32 N;
	cin >> N;
	vector<int64> a(N);
	REP(i, N) cin >> a[i];
	int64 X = max(*max_element(all(a)), (int64)1);
	Dinic din(N+2);
	const int64 inf = (int64)INF*1000;
	REP(i, N){
		din.add_edge(N, i, X-a[i]);
		din.add_edge(i, N+1, X);
		int32 in = i+1;
		for(int32 j = 2;in*j <= N;j++){
			din.add_edge(in-1, in*j-1, inf);
		}
	}
	cout << X*N-din.max_flow(N, N+1) << endl;
}

