}

const int N = 100 + 10;
vector<Edge> g[N];

map<Edge, lli> cap;

void add_edge(int src, int dst, lli c)
{
  Edge a(src, dst);
  Edge b = a.rev();
  g[a.src].push_back(a);
  g[b.dst].push_back(b);
  cap[a] += c;
  return ;
}

lli max_flow(int src, int snk)
{
  lli sum = 0;
  while (true) {
    Edge path[N] = {Edge(), };
    set<int> vis({src});
    queue<int> q;
    for (q.push(src); q.size(); q.pop()) {
      each (e, g[q.front()]) {
        if (vis.count(e.dst)) continue;
        if (0 < cap[e]) {
          q.push(e.dst);
          vis.insert(e.dst);
          path[e.dst] = e;
        }
      }
    }
    if (path[snk] == Edge()) {
      break;
    }
    lli mn = 1LL << 60;
    for (Edge e = path[snk]; e != Edge(); e = path[e.src]) {
      mn = min(mn, cap[e]);
    }
    for (Edge e = path[snk]; e != Edge(); e = path[e.src]) {
      cap[e] -= mn;
      cap[e.rev()] += mn;
    }
    sum += mn;
  }

  return sum;
}

