ll cap[N][N];
vector<int> adj[N];

ll bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	queue<pair<int, ll>> q;
	q.push({source, INF});
	while(!q.empty()) {
		ll u = q.front().first, flow = q.front().second;
		if(u == sink) return flow;
		q.pop();
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v] > 0) {
				par[v] = u;
				ll newFlow = min(flow, cap[u][v]);
				q.push({v, newFlow});
			}
		}
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while((newFlow = bfs(source, sink))) {
		assert(newFlow != INF);
		flow += newFlow;
		int u = sink;
		while(u != source) {
			int v = par[u];
			cap[v][u] -= newFlow;
			cap[u][v] += newFlow;
			u = v;
		}
	}
	return flow;
}

