using namespace std;
typedef long long ll;
const int MAX_V = 310;
ll INF = 1000000000000000;
struct edge{ll to,cap,rev;};
vector<edge> G[MAX_V];
bool used[MAX_V];
ll b[MAX_V],f[MAX_V],can[MAX_V][MAX_V];
vector<int> v,w;
void add_edge(ll from,ll to,ll cap){
    G[from].push_back({to,cap,(ll)G[to].size()});
    G[to].push_back({from,0,(ll)G[from].size() - 1});
}

ll dfs(int s,int t,ll val){
    for(edge e:G[s]){
        if(used[e.to]) continue;
        b[e.to] += e.cap;
        if(b[e.to]>=val){
            used[e.to] = true;
            v.push_back(e.to); w.push_back(e.to);
        }
    }
    if(v.size()==0) return 0;
    int vv = v.back();
    if(vv==t) return 1;
    v.pop_back();
    return dfs(vv,t,val);
}

ll rev_dfs(int s,int t,ll val){
    for(int i=0;i<MAX_V;i++) f[i] = 0;
    f[t] = val;
    while(w.size()){
        int now = w.back();
        w.pop_back();
        used[now] = false;
        for(edge ee:G[now]){
            int from = ee.to;
            if(!used[from]) continue;
            int j = can[from][now];
            if(j==-1) continue;
            edge &e = G[from][j];
            ll f_ = min(f[now],e.cap);
            e.cap -= f_;
            G[e.to][e.rev].cap += f_;
            f[now] -= f_; f[from] += f_;
        }
    }
}

ll max_flow(int s,int t){
    ll flow = 0,val = 0;
    int i,j;
    for(i=0;i<MAX_V;i++){
        b[i] = 0;
        for(j=0;j<MAX_V;j++){
            can[i][j]= -1;
        }
        for(j=0;j<G[i].size();j++){
            can[i][G[i][j].to] = j;
            val = max(val,G[i][j].cap);
        }
    }
    while(val){
        v.clear(); w.clear(); w.push_back(s);
        for(i=0;i<MAX_V;i++){
            b[i] = 0; used[i] = false;
        }
        used[s] = true;
        if(!dfs(s,t,val)){
            val /= 2;
            continue;
        }
        rev_dfs(s,t,val);
        flow += val;
    }
    return flow;
}
ll a[110];
int main(){
    int i,j,n;
    ll ans = 0;
    cin >> n;
    for(i=1;i<=n;i++){
        cin >> a[i];
        if(a[i]>=0){
            ans += a[i];
            add_edge(0,i,a[i]);
        }else{
            add_edge(i,n + 1,-a[i]);
        }
        for(j=2*i;j<=n;j+=i){
            add_edge(j,i,INF);
        }
    }
    cout << ans - max_flow(0,n + 1) << endl;
}

