using namespace std;

int n;
int a[105];
long long dp[105];
long long sum;

void build() {
  for (int i = 1; i <= n; i++) {
    dp[i] = 0;
    for (int j = i; j <= n; j += i) {
      dp[i] += a[j];
    }
  }
}

int main() {
  cin >> n;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }

  do {
    build();
    int bestI = 0;
    for (int i = 1; i <= n; i++) {
      if (dp[i] < dp[bestI]) {
        bestI = i;
      }
    }
    if (bestI == 0) break;
    for (int j = bestI; j <= n; j += bestI) {
      a[j] = 0;
    }
  } while(true);

  for (int i = 1; i <= n; i++) {
    sum += a[i];
  }
  cout << sum << '\n';

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
struct Dinic {
	struct Edge {
		int u, v;
		long long cap, flow;
		Edge() {}
		Edge(int u, int v, long long cap): u(u), v(v), cap(cap), flow(0) {}
	}; 
	int N;
	vector<Edge> E;
	vector<vector<int>> g;
	vector<int> d, pt;

	Dinic(int N): N(N), E(0), g(N), d(N), pt(N) {}

	void AddEdge(int u, int v, long long cap) {
		if (u != v) {
			E.emplace_back(Edge(u, v, cap));
			g[u].emplace_back(E.size() - 1);
			E.emplace_back(Edge(v, u, 0));
			g[v].emplace_back(E.size() - 1);
		}
	}

	bool BFS(int S, int T) {
		queue<int> q({S});
		fill(d.begin(), d.end(), N + 1);
		d[S] = 0;
		while(!q.empty()) {
			int u = q.front(); q.pop();
			if (u == T) break;
			for (int k: g[u]) {
				Edge &e = E[k];
				if (e.flow < e.cap && d[e.v] > d[e.u] + 1) {
		 			d[e.v] = d[e.u] + 1;
		 			q.emplace(e.v);
		    	}
		  	}
		}
		return d[T] != N + 1;
	}

	long long DFS(int u, int T, long long flow = -1) {
		if (u == T || flow == 0) return flow;
		for (int &i = pt[u]; i < g[u].size(); ++i) {
			Edge &e = E[g[u][i]];
			Edge &oe = E[g[u][i]^1];
			if (d[e.v] == d[e.u] + 1) {
				long long amt = e.cap - e.flow;
				if (flow != -1 && amt > flow) amt = flow;
				if (long long pushed = DFS(e.v, T, amt)) {
					e.flow += pushed;
					oe.flow -= pushed;
					return pushed;
				}
			}
		}
		return 0;
	}

	long long MaxFlow(int S, int T) {
		long long total = 0;
		while (BFS(S, T)) {
			fill(pt.begin(), pt.end(), 0);
			while (long long flow = DFS(S, T))
				total += flow;
		}
		return total;
	}
};
int main(){
	ios_base::sync_with_stdio(0);
	int n,a[105],sum=0;
	cin>>n;
	Dinic d(105);
	for(int i=1;i<=n;++i){
		cin>>a[i];
		if(a[i]>=0) {
			sum+=a[i];
			d.AddEdge(0,i,a[i]);
		}
		else{
			d.AddEdge(i,102,-a[i]);
		}
	}
	for(int i=1;i<=n;++i)
		for(int j=2*i;j<=n;j+=i)
			d.AddEdge(j,i,1e18);
	cout<<sum-d.MaxFlow(0,102);
}

