const int inf = 1e9 + 123;

struct MaxFlow {
	struct edge {
		int u; int v; int c; int f;
		edge(int u=0, int v=0, int c=0, int f=0): u(u), v(v), c(c), f(f) {}
	};
	int n, s, t;
	vector< vector<int> > G;
	vector<edge> e;
	MaxFlow(int n=0, int s=0, int t=0): n(n), s(s), t(t) { G.assign(n + 1, vector<int>()); }
	void add(int u, int v, int c) {
		G[u].push_back(e.size()); e.push_back(edge(u, v, c, 0));
		G[v].push_back(e.size()); e.push_back(edge(v, u, 0, 0));
	}

	vector<int> d, hd;
	bool bfs() {
		d.assign(n + 1, -1); hd.assign(n + 1, -1);
		queue <int> q; q.push(s); d[s] = 0;
		while(!q.empty()) {
			int u = q.front(); q.pop();
			for (int id : G[u]) if (e[id].c > e[id].f && d[e[id].v] == -1) {
				d[e[id].v] = u; hd[e[id].v] = id;
				q.push(e[id].v);
			}
		}
		return d[t] != -1;
	}
	int mnm() {
		int delta = inf;
		for (int i = t; i != s; i = d[i]) {
			int id = hd[i]; delta = min(delta, e[id].c - e[id].f);
		}
		for (int i = t; i != s; i = d[i]) {
			int id = hd[i]; e[id].f += delta; e[id ^ 1].f -= delta;
		}
		return delta;
	}

	long long maxFlow() {
		long long res = 0; while(bfs()) res += mnm(); return res;
	}
} mf;

const int N = 110;

int n, a[N];
long long ans;

int main() {
	scanf("%d", &n);
	int s = n + 1, t = n + 2;
	mf = MaxFlow(n + 2, n + 1, n + 2);

	for (int i = 1; i <= n; ++i) {
		scanf("%d", a + i);
		if (a[i] <= 0) mf.add(s, i, -a[i]);
		else mf.add(i, t, a[i]), ans += a[i];
		for (int j = i + i; j <= n; j += i) mf.add(i, j, inf);
	}

	long long mincut = mf.maxFlow();
	ans -= mincut;
	printf("%lld\n", ans);
}

