typedef long long ll;

const ll N = 105, INF = 1e9;
int n, source, sink;
ll a[N], par[N];
ll cap[N][N];
vector<int> adj[N];

ll bfs(int source, int sink) {
	memset(par, -1, sizeof par);
	par[source] = -2;
	queue<pair<int, ll>> q;
	q.push({source, INF});
	while(!q.empty()) {
		ll u = q.front().first, flow = q.front().second;
		q.pop();
		for(auto& v : adj[u]) {
			if(par[v] == -1 && cap[u][v]) {
				par[v] = u;
				ll new_flow = min(flow, cap[u][v]);
				if(v == sink) return new_flow;
				q.push({v, new_flow});
			}
		}
	}
	return 0;
}

ll maxflow(int source, int sink) {
	ll flow = 0;
	ll newFlow;
	while((newFlow = bfs(source, sink))) {
		flow += newFlow;
		int u = sink;
		while(u != source) {
			int v = par[u];
			cap[v][u] -= newFlow;
			cap[u][v] += newFlow;
			u = v;
		}
	}
	return flow;
}

