const int N=(int) 1e2+20;
struct Dinic
{
    struct Edge
    {
        int from,to;
        LL cap,flow;
        Edge() {}
        Edge(int _from,int _to,LL _cap,LL _flow):from(_from),to(_to),cap(_cap),flow(_flow) {}
    };
    int n,m,s,t;
    vector<Edge> edge;
    vector<int> G[N];
    bool vis[N];
    int d[N],cur[N];

    void init(int _n,int _s,int _t)
    {
        n=_n; s=_s; t=_t;
        m=0;
        for(int i=0;i<=n;i++) G[i].clear();
        edge.clear();
    }

    void add_edge(int from,int to,LL cap)
    {
        edge.push_back(Edge(from,to,cap,0));
        edge.push_back(Edge(to,from,0,0));
        m+=2;
        G[from].push_back(m-2);
        G[to].push_back(m-1);
    }

    bool BFS()
    {
        memset(vis,0,sizeof(vis));
        queue<int> Q;
        Q.push(s);
        d[s]=0;
        vis[s]=1;
        while(!Q.empty())
        {
            int x=Q.front(); Q.pop();
            for(int i=0;i<G[x].size();i++)
            {
                Edge &e=edge[G[x][i]];
                if(!vis[e.to] && e.cap>e.flow)
                {
                    vis[e.to]=1;
                    d[e.to]=d[x]+1;
                    Q.push(e.to);
                }
            }
        }
        return vis[t];
    }

    LL DFS(int x,LL a)
    {
        if(x==t || a==0) return a;
        LL flow=0, f;
        for(int &i=cur[x];i<G[x].size();i++)
        {
            Edge &e=edge[G[x][i]];
            if(d[x]+1==d[e.to] && (f = DFS(e.to,min(a,e.cap-e.flow)))>0)
            {
                e.flow+=f;
                edge[G[x][i]^1].flow-=f;
                flow+=f;
                a-=f;
                if(a==0) break;
            }
        }
        return flow;
    }

    LL Maxflow()
    {
        LL res=0;
        while(BFS())
        {
            memset(cur,0,sizeof(cur));
            res+=DFS(s,LINF);
        }
        return res;
    }
}MF;

