            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int f = 0;
    for(;;) {
        fill(used, used + 105, false);
        int d = dfs(s,t,INF);
        if(d == 0) return f;
        f += d;
    }
    return f;
}

