int a[MAXN], flag[MAXN];
int n;
LL solve(int index)
{
    LL res = 0;
    if(index * 3 > n)
    {
        for(int i = index; i <= n; i++)
        {
            if(i % 2 == 0 && i / 2 >= index) continue;
            if(i + i > n)
            {
                if(!flag[i]) res += max(0, a[i]);
            }
            else
            {
                if(!flag[i])
                {
                    if(flag[i + i])
                    {
                        res += max(0, a[i]);
                    }
                    else
                    {
                        res += max(0, max(a[i], a[i] + a[i + i]));
                    }
                }
            }
        }
        return res;
    }
    else if(flag[index])
    {
        return solve(index + 1);
    }
    else
    {
        LL tmp = a[index] + solve(index + 1);
        for(int i = index; i <= n; i += index)
        {
            flag[i]++;
        }
        res = max(tmp, solve(index + 1));
        for(int i = index; i <= n; i += index)
        {
            flag[i]--;
        }
        return res;
    }
}

