bool check(int k) {
    long long sum = 0;
    for(int i = k; i <= n; i+=k) {
        if(good[i]) sum += num[i];
    }
    //cout << sum << endl;
    if(sum < 0) return true;
    long long lazy = 0;
    for(int i = k; i <= n; i+= k) {
    	if(!good[i]) continue;
        if(num[i] >= 0) {
            num[i] -= lazy;
            lazy = 0;
        }
        if(num[i] < 0){
        	lazy -= num[i];
        	num[i] = 0;
		}
    }
    return false;
}

void change(int k) {
    for(int i = k; i <= n; i+=k) {
        good[i] = false;
    }
