ll solve(int n, vi a)
{
	bool f = true;
	while (f)
	{
		f = false;
		for (int i = n; i >= 1; i--)
		{
			ll sum = 0;
			FOR(j, 1, 111)
			{
				int k = i * j;
				if (k > n) break;
				sum += a[k];
			}
			if (sum < 0)
			{
				f = true;
				FOR(j, 1, 111)
				{
					int k = i * j;
					if (k > n) break;
					a[k] = 0;
				}
				break;
			}
		}
		if (f) continue;
		for (int x = 2; x <= n; x++)
		{
			for (int y = x + 1; y <= n; y++)
			{
				if (x * y > n) break;
				ll sum = 0;
				for (int i = 1; i <= n; i++)
				{
					if (i % x == 0 || i % y == 0) sum += a[i];
				}
				if (sum < 0)
				{
					f = true;
					for (int i = 1; i <= n; i++)
					{
						if (i % x == 0 || i % y == 0) a[i] = 0;
					}
					break;
				}
			}
		}
		if (f) continue;
		for (int x = 2; x <= n; x++)
		{
			for (int y = x + 1; y <= n; y++)
			{
				for (int z = y + 1; z <= n; z++)
				{
					if (x * y * z > n) break;
					ll sum = 0;
					for (int i = 1; i <= n; i++)
					{
						if (i % x == 0 || i % y == 0 || i % z == 0) sum += a[i];
					}
					if (sum < 0)
					{
						f = true;
						for (int i = 1; i <= n; i++)
						{
							if (i % x == 0 || i % y == 0 || i % z) a[i] = 0;
						}
						break;
					}
				}
			}
		}
	}
	ll ans = 0;
	REP(i, n + 1) ans += a[i];
	return ans;
}

