struct edge{
	llint to, cap, rev;
	edge(llint a, llint b, llint c){
		to = a, cap = b, rev = c;
	}
};

vector<edge> G[105];
bool used[105];

llint dfs(llint s, llint t, llint c)
{
	if(s == t) return c;
	used[s] = true;

	llint ret;
	for(llint i = 0; i < (llint)G[s].size(); i++){
		if(used[G[s][i].to] || G[s][i].cap == 0) continue;
		ret = dfs(G[s][i].to, t, min(c, G[s][i].cap));
		if(ret > 0){
			G[s][i].cap -= ret;
			G[ G[s][i].to ][ G[s][i].rev ].cap += ret;
			return ret;
		}
	}
	return 0;
}

llint N, S, T;
llint a[105], sum, psum;

void add_edge(llint s, llint t, llint c)
{
	G[s].push_back(edge(t, c, G[t].size()));
	G[t].push_back(edge(s, 0, G[s].size()-1));
}

