	sum = psum = 0;
	for(llint i = 1; i <= N; i++){
		cin >> a[i];
		sum += a[i];
		a[i] *= -1;
		if(a[i] >= 0) psum += a[i];
	}

	S = 0, T = N+1;
	for(llint i = 1; i <= N; i++){
		for(llint j = 1; j <= N; j++){
			if(j % i == 0) add_edge(i, j, inf);
		}
	}

	for(llint i = 1; i <= N; i++){
		if(a[i] >= 0) add_edge(S, i, a[i]);
		else add_edge(i, T, -a[i]);
	}

	llint ans = 0, ret;
	while(1){
		for(llint i = S; i <= T; i++) used[i] = false;
		ret = dfs(S, T, inf);
		if(ret == 0) break;
		ans += ret;
	}

	cout << sum + (psum-ans) << endl;
	return 0;
}

