{
	int n;
	scanf("%d", &n);

	vector<i64> arr(n + 1);

	i64 total = 0;

	for (i64 i = 1; i <= n; i++)
	{
		scanf("%lld", &arr[i]);

		if(arr[i] > 0)
			total += arr[i];
	}

	int source = n + 1, sink = n + 2;

	for (int i = 1; i <= n; i++)
	{
		if (arr[i] <= 0)
		{
			dinic.addEdge(source, i, -arr[i]);
		}
		else
		{
			dinic.addEdge(i, sink, arr[i]);
		}

		for (int j = 2 * i; j <= n; j += i)
		{
			dinic.addEdge(i, j, dinic.INFINITE);
		}
	}

	printf("%lld", total - dinic.maxFlow(source, sink));

	return 0;
}

