inline int gi() {
    int x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') ch=getchar(),o=-1;
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline bool bfs() {
    memset(lev,0,sizeof(lev));
    int t=0,sum=1;
    v[1]=S,lev[S]=1;
    while(t<sum) {
	int x=v[++t];
	for(int i=head[x];i;i=nxt[i]) {
	    int y=to[i];
	    if(s[i]&&!lev[y]) {
		lev[y]=lev[x]+1,v[++sum]=y;
		if(y==T) return 1;
	    }
	}
    }
    return 0;
}
inline ll dfs(int x,ll Mx) {
    if(x==T) return Mx;
    ll ret=0;
    for(int i=head[x];i;i=nxt[i]) {
	int y=to[i];
	if(s[i]&&lev[y]==lev[x]+1) {
	    int f=dfs(y,min((ll)s[i],Mx-ret));
	    s[i]-=f,s[i^1]+=f;
	    ret+=f;
	    if(ret==Mx) break;
	}
    }
    if(!ret) lev[x]=0;
    return ret;
}
inline void lnk(int x,int y,int z) {
    to[++tt]=y,nxt[tt]=head[x],s[tt]=z,head[x]=tt;
    to[++tt]=x,nxt[tt]=head[y],head[y]=tt;
}
