	lol(i,N)dis[i]=inf;
	dis[start]=0;
	queue<int> Q;
	Q.push(start);
	while(!Q.empty()){
		int x=Q.front(); Q.pop();
		lol(i,v[x].size()){
			if(dis[v[x][i].to]==inf&&v[x][i].lim>0){
				dis[v[x][i].to]=dis[x]+1;
				Q.push(v[x][i].to);
			}
		}
	}
}

int DFS(int x,int goal,ll minedge){
	if(x==goal)return minedge;
	for(int i=0;i<v[x].size();i++){
		if(dis[x]<dis[v[x][i].to]&&v[x][i].lim>0){
			int mini=DFS(v[x][i].to,goal,min(minedge,v[x][i].lim));
			if(mini>0){
				v[x][i].lim-=mini;
				v[v[x][i].to][v[x][i].revindex].lim+=mini;
				return mini;
			}
		}
	}
	return 0;
}

ll Dinic(int start,int goal){
	ll flow=0;
	while(1){
		BFS(start);
		if(dis[goal]==inf)return flow;
		flow+=DFS(start,goal,inf);
	}
}

