	std::vector<int> a(n + 1, 0);
	FOR(i, 1, n + 1) std::cin >> a[i];
	int ans = 0;
	FOR(i, 1, n + 1) ans += a[i];
	std::vector<bool> used(n + 1, false);
	RFOR(i, 1, n + 1) {
		int now = 0;
		int t = i;
		while (t <= n) {
			bool f = true;
