		scanf("%lld", &a[i]);
		if (a[i] >= 0)
			ans += a[i];
	}
	std::vector<int64_t> lossTable(N + 1);
	MaxFlow maxFlow(N + 2, 0, N + 1);
	for (int i{N}; i > 0; i--)
	{
		for (int j{2 * i}; j <= N; j += i)
			maxFlow.addEdge(j, i, 1ll << 50);
		if (a[i] >= 0)
		{
			maxFlow.addEdge(0, i, a[i]);
			maxFlow.addEdge(i, N + 1, 0);
		}
		else
		{
			maxFlow.addEdge(0, i, 0);
			maxFlow.addEdge(i, N + 1, -a[i]);
		}
	}
	ans -= maxFlow();
	printf("%lld\n", ans);

	return 0;
}

