struct edge{
    ll to, cap, rev;
};

struct Dinic{
    const ll INF = 1e9;
    int n;
    vector<vector<edge> > g;
    VL level, iter;

    void init(int x){
        n = x;
        g.resize(n);
        level.resize(n);
        iter.resize(n);
    }

    void add_edge(int from, int to, ll cap){
        g[from].push_back((edge){to, cap, (int)g[to].size()});
        g[to].push_back((edge){from, 0, (int)g[from].size() - 1});
    }

    void bfs(int s){
        fill(ALL(level), -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()){
            int v = que.front();
            que.pop();
            for (edge &e : g[v]){
                if (e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    ll dfs(int v, int t, ll f){
        if (v == t) return f;
        for (ll &i = iter[v]; i < g[v].size(); i++){
            edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]){
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0){
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    ll max_flow(int s, int t){
        ll flow = 0;
        while (1){
            bfs(s);
            if (level[t] < 0) return flow;
            fill(ALL(iter), 0);
            ll f;
            while ((f = dfs(s, t, INF)) > 0){
                flow += f;
            }
        }
    }
};

int main() {
    int n;
    cin >> n;
    VL a(n+1);
    ll sum = 0;
    FOR(i,1,n){
        cin >> a[i];
        if (a[i] > 0) sum += a[i];
    }

    Dinic flow;
    flow.init(n+2);

    FOR(i,1,n){
        if (a[i] >= 0){
            flow.add_edge(0, i, 0);
            flow.add_edge(i, n+1, a[i]);
        }else{
            flow.add_edge(0, i, -a[i]);
            flow.add_edge(i, n+1, 0);
        }
        for (int x = 2 * i; x <= n; x += i){
            flow.add_edge(i, x, 1e18);
        }
    }

    cout << sum - flow.max_flow(0, n+1) << endl;

    return 0;
}

