template<typename T>
constexpr T ipow(T a, T b)
{
    assert(b >= 0);
    T res(1);
    for(T i = 0; i < b; ++i)
        res *= a;
    return res;
}

template<
    typename T,
    std::enable_if_t<
        std::is_integral<T>::value &&
        std::is_signed<T>::value, std::nullptr_t> = nullptr>
constexpr T div_ceil(T a, T b)
{
    return a/b + (((a<0)^(b>0)) && (a%b));
}

template<
    typename T,
    std::enable_if_t<
        std::is_integral<T>::value &&
        std::is_unsigned<T>::value, std::nullptr_t> = nullptr>
constexpr T div_ceil(T a, T b)
{
    return a/b + !!(a%b);
}

template<
    typename T,
    std::enable_if_t<
        std::is_integral<T>::value &&
        std::is_signed<T>::value, std::nullptr_t> = nullptr>
constexpr T div_floor(T a, T b)
{
    return a/b - (((a>0)^(b>0)) && (a%b));
}

template<
    typename T,
    std::enable_if_t<
        std::is_integral<T>::value &&
        std::is_unsigned<T>::value, std::nullptr_t> = nullptr>
constexpr T div_floor(T a, T b)
{
    return a/b;
}

template<typename T, typename U>
constexpr auto modulo(T a, U b)
{
    using R = common_type_t<T,U>;
    assert(b > 0);
    R r = a % b;
    return r >= 0 ? r : r+b;
}

template<typename T>
constexpr T clamp(T x, T lo, T hi)
{
    assert(lo <= hi);
    if(x < lo)
        return lo;
    else if(x > hi)
        return hi;
    else
        return x;
}

