s64 N;
vector<s64> A;

void f(s64 x)
{
    s64 s = 0;
    FOR(i, 1, N+1) {
        if(i % x == 0) {
            s += A[i-1];
        }
    }

    if(s > 0) return;
    DBG(x);

    FOR(i, 1, N+1) {
        if(i % x == 0) {
            A[i-1] = 0;
        }
    }
}

void solve()
{
    for(s64 x = N; x >= 1; --x) {
        f(x);
    }
    DBG(A);

    s64 ans = ALL(SUM, A);

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    RD(A, N);



    solve();

    EXIT();
}

