#include <cstdio>
#include <algorithm>

using namespace std;
typedef long long ll;

const ll inf = 100000000000000LL;

int a[101];
bool flag[101];

int cc = 0;

ll dfs(int n, int k){
  ll ret = inf;

  if(n+1 == k) return 0;

  if(!flag[k] && a[k] < 0){
    bool memo[100] = {};
    ll sum = 0;
    int counter = 0;

    for(int i=1;i*k<=n;i++){
      if(!flag[i*k]){
	memo[i*k] = true;
	flag[i*k] = true;
	sum += a[i*k];
	counter++;
      }
    }

    if(counter != 1 || a[k] < 0){
      ret = min(ret, dfs(n, k+1) + sum);
    }

    for(int i=1;i*k<=n;i++){
      if(memo[i*k]){
	memo[i*k] = false;
	flag[i*k] = false;
      }
    }

    if(counter == 1 && a[k] < 0)
	return ret;
  }

  ret = min(ret, dfs(n, k+1));

  //printf("%d\n",cc++);

  return ret;
}

int main() {
  int n;
  ll sum = 0;

  scanf("%d",&n);

  for(int i=1;i<=n;i++){
    scanf("%d",a+i);
    sum += a[i];
  }

  printf("%lld\n", sum - dfs(n,1));

  return 0;
}

