    template<class T> class maxflow_c{
        private:
        const int inf=0x3f3f3f3f;
        int maxv, maxe;
        struct mf_edge_t{
            int src, dst;
            mf_edge_t *nxt, *rsv;
            T cap, cur;
        } **head, *pool, *tail, **hold;
        int *hig, *que;
        public:
        maxflow_c(const int numv, const int nume){
            this->maxv=numv;
            this->maxe=nume<<1;
            this->pool=(mf_edge_t*)malloc(sizeof(mf_edge_t)*(nume<<1));
            this->head=(mf_edge_t**)malloc(sizeof(mf_edge_t*)*numv);
            this->hold=(mf_edge_t**)malloc(sizeof(mf_edge_t*)*numv);
            this->tail=this->pool;
            this->hig=(int*)malloc(sizeof(int)*numv);
            this->que=(int*)malloc(sizeof(int)*(numv+1));
        };
        ~maxflow_c(){
            free(this->que);
            free(this->hig);
            free(this->hold);
            free(this->head);
            free(this->pool);
        }
        void reset(){
            for(int i=0; i<this->maxv; i++){
                this->head[i]=NULL;
            }
            this->tail=this->pool;
        }
        void add_edge(const int u, const int v, const T c, const T r=0){
            assert(u<this->maxv && v<this->maxv);
            assert(this->tail-this->pool<this->maxe);
            this->tail->nxt=this->head[u];
            this->tail->rsv=this->tail+1;
            this->tail->src=u;
            this->tail->dst=v;
            this->tail->cap=c;
            this->tail->cur=0;
            this->head[u]=this->tail++;
            this->tail->nxt=this->head[v];
            this->tail->rsv=this->tail-1;
            this->tail->src=v;
            this->tail->dst=u;
            this->tail->cap=r;
            this->tail->cur=0;
            this->head[v]=this->tail++;
        }
        int higlev(const int src, const int trm){
            int lef=0, rig=0;
            memset(this->hig, 0x3f, sizeof(int)*this->maxv);
            this->hig[src]=0;
            this->que[rig++]=src;
            for(; lef<rig; lef++){
                const int u=this->que[lef];
                for(mf_edge_t *edge=this->head[u]; edge!=NULL; edge=edge->nxt){
                    if(edge->cur<edge->cap && this->hig[edge->dst]>this->hig[u]+1){
                        this->hig[edge->dst]=this->hig[u]+1;
                        this->que[rig++]=edge->dst;
                    }
                }
            }
            this->que[rig++]=-1;
            return this->hig[trm];
        }
        T dinic(const int src, const int trm){
            T foo=0;
            list<void*> edge_stack;
            while(higlev(src, trm)<inf){
                int u=src;
                for(int i=0; ~this->que[i]; i++){
                    this->hold[this->que[i]]=this->head[this->que[i]];
                }
                while(this->hold[src]!=NULL){
                    if(u!=trm && hold[u]!=NULL && hold[u]->cur<hold[u]->cap && this->hig[u]+1==this->hig[hold[u]->dst]){
                        edge_stack.push_back(hold[u]);
                        u=hold[u]->dst;
                    }else if(u==trm){
                        T inc=numeric_limits<T>::max()/2;
                        for(list<void*>::const_iterator it=edge_stack.begin(); it!=edge_stack.end(); it++)
                            UPDMIN(inc, ((mf_edge_t*)(*it))->cap-((mf_edge_t*)(*it))->cur);
                        foo+=inc;
                        list<void*>::iterator last=edge_stack.end();
                        for(list<void*>::iterator it=edge_stack.end(); it!=edge_stack.begin(); ){
                            it--;
                            ((mf_edge_t*)(*it))->cur+=inc;
                            ((mf_edge_t*)(*it))->rsv->cur-=inc;
                            if(((mf_edge_t*)(*it))->cur==((mf_edge_t*)(*it))->cap){
                                last=it;
                            }
                        }
                        if(last!=edge_stack.end()){
                            edge_stack.erase(last, edge_stack.end());
                        }
                        if(!edge_stack.empty()){
                            u=((mf_edge_t*)edge_stack.back())->dst;
                        }else{
                            u=src;
                        }
                    }else{
                        while(!edge_stack.empty() && hold[u]==NULL){
                            u=((mf_edge_t*)edge_stack.back())->src;
                            edge_stack.pop_back();
                        }
                        hold[u]=hold[u]->nxt;
                    }      
                }
            }
            return foo;
        }
    };

