LL rec(int pos, LL mask)
{
	LL res = 0;
	bool del;
	do
	{
		del = 0;
		REP(i, SZ(D[pos]))
			if (mask & (1LL << D[pos][i])) del = 1;
		if ((pos << 1) > n && !del) res += A[pos];
		++pos;
