ll dist[dinicVmax];//ソースからの距離
ll checked[dinicVmax];//dfsの行き止まりフラグ
void dinicbfs(ll s){
	rep(i,0,vcnt)dist[i]=-1;
	dist[s]=0;
	//まだ流せる辺だけを使ってbfs
	ll que[dinicVmax*dinicVmax];
	ll qcnt=0,qptr=0;
	que[qcnt++]=s;
	while(qcnt!=qptr){
		ll a=que[qptr++];
		rep(b,0,vcnt)if(resflow(a,b)>0&&dist[b]==-1){
			dist[b]=dist[a]+1;
			que[qcnt++]=b;
		}
	}
}
ll dinicdfs(ll a,ll t,ll m){
	//aはm受け取ってる(⇔aから最大m流せる)
	//いくら流せるかを返す
	if(a==t)return m;
	if(checked[a])return 0;
	ll ans=0;
	checked[a]=1;
	rep(b,0,vcnt)if(dist[b]>dist[a]&&resflow(a,b)>0){
		ll addedflow=dinicdfs(b,t,min(m,resflow(a,b)));
		if(addedflow){
			flow[a][b]+=addedflow;
			flow[b][a]-=addedflow;
			checked[a]=0;
			ans+=addedflow;
			m-=addedflow;
			if(m<=0)break;
		}
	}
	return ans;
}
