ll dinic(ll s,ll t){
	ll ans=0;
	ll flag=1;
	while(flag){
		flag=0;//更新フラグ
		dinicbfs(s);
		while(!checked[s]){
			ll addedflow=dinicdfs(s,t,INF);
			ans+=addedflow;
			if(addedflow)flag=1;
		}
		rep(i,0,vcnt)checked[i]=0;
	}
	return ans;
}
