int main(){
	//ソースを0、シンクをN+1として、破壊する側をソース、しない側をシンクに集める
	//以下の条件で与えられるペナルティーを最小化する
	//・a[i]<0のとき、a[i]を破壊しないと|a[i]|のペナルティー→ソースからiを|a[i]|で結ぶ
	//・a[i]>=0のとき、a[i]を破壊しないのを基礎点として、破壊するとa[i]のペナルティー→iからシンクをa[i]で結ぶ
	//・a[i]が破壊されていてかつa[k*i]が破壊されていないとき、∞点のペナルティー→iからk*iを∞で結ぶ
	//基礎点としてもらえる(Σ_{i\in\{j|a[j]>=0\}}a[i])点からペナルティーを引いたものが答え
	ll n;
	scanf("%lld",&n);
	ll base=0;
	rep(i,1,n+1){
		ll t;
		scanf("%lld",&t);
		if(t<0){
			capa[0][i]=-t;
		}else{
			capa[i][n+1]=t;
			base+=t;
		}
	}
	rep(i,1,n+1)repp(j,i*2,n+1,i)capa[i][j]=INF;
	vcnt=n+2;
	printf("%lld\n",base-dinic(0,n+1));
	return 0;
}

