#define INF 1000000000000000
#define MAX_V 200
#define MAX_E 10000
#define ll long long
typedef struct LIST{
	int to;
	ll cap;
	struct LIST *rev; //逆辺のポインタ
	struct LIST *next;
}Edge;
Edge *iter[MAX_V];
Edge edge[MAX_E],rev[MAX_E];
int level[MAX_V];
int que[MAX_V];
int e_size=0;
void add_edge(Edge **g,int s,int t,ll c){
	edge[e_size].next=g[s]; g[s]=&edge[e_size];
	rev[e_size].next=g[t]; g[t]=&rev[e_size++];
	g[s]->to=t,g[s]->cap=c;
	g[t]->to=s,g[t]->cap=0;
	g[s]->rev=g[t]; g[t]->rev=g[s];
	return;
}
void bfs(Edge **g,int s){
	int front=0,rear=0,v;
	Edge *e;
	memset(level,-1,sizeof(level));
	level[s]=0;
	que[rear++]=s;
	while(front!=rear){
		v=que[front++];
		for(e=g[v];e!=NULL;e=e->next){
			if(e->cap>0&&level[e->to]<0){
				level[e->to]=level[v]+1;
				que[rear++]=e->to;
			}
		}
	}
	return;
}
ll dfs(int v,int t,ll f){
	ll d; Edge *e;
	if(v==t) return f;
	for(;iter[v]!=NULL;iter[v]=iter[v]->next){
		e=iter[v];
		if(e->cap>0&&level[v]<level[e->to]){
			d=dfs(e->to,t,MIN(f,e->cap));
			if(d>0){
				e->cap-=d;
				e->rev->cap+=d;
				return d;
			}
		}
	}
	return 0;
}
ll max_flow(Edge *g[],int s,int t){
	ll flow=0,f;
	while(1){
		bfs(g,s);
		if(level[t]<0) return flow;
		memcpy(iter,g,sizeof(iter));
		while((f=dfs(s,t,INF))>0) flow+=f;
	}
}
