void add_edge(Edge **graph,int s,int t,ll c){
	new_edge[edge_size].to = t;      new_edge[edge_size].cap = c;
	new_rev_edge[edge_size].to = s;  new_rev_edge[edge_size].cap = 0;

	new_edge[edge_size].rev = &new_rev_edge[edge_size];
