import java.util.*;

class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] A = new long[n+1];
        for(int i = 1; i<=n;i++) A[i] =sc.nextLong();
        Flow sl = new Flow(A);
        long res = sl.max_flow(0,n+1);
        long sum = 0;
        for(int i=1;i<=n;i++) sum += Math.max(0,A[i]);
        System.out.println(sum-res);
    }
    static class Flow{
        long inf = Long.MAX_VALUE/10000;
        int n;
        int[] level;
        int[] iter;
        ArrayList<Edge>[] map;

        public Flow(long[] A){
            n = A.length-1;
            level = new int[n+2];
            iter = new int[n+2];
            map = new ArrayList[n+2];
            for(int i=0;i<=n+1;i++) map[i] = new ArrayList<>();
            for(int i=1;i<=n;i++){
                if(A[i]<=0) add_Edge(0,i,Math.abs(A[i]));
                if(A[i]>0) add_Edge(i,n+1,A[i]);
            }
            for(int i=1;i<=n;i++){
                for(int j=2*i; j<=n; j+=i) add_Edge(i, j, inf);
            }
        }

        void add_Edge(int from, int to, long cap){
            map[from].add(new Edge(to, cap, map[to].size()));
            map[to].add(new Edge(from, 0, map[from].size()-1));
        }

        void bfs(int s){
            Arrays.fill(level, -1);
            LinkedList<Integer> que = new LinkedList<>();
            level[s]=0;
            que.add(s);
            while(que.size()>0){
                int v = que.poll();
                for(int i=0;i<map[v].size();i++){
                    Edge e = map[v].get(i);
                    if(e.cap>0&&level[e.to]<0){
                        level[e.to] = level[v]+1;
                        que.add(e.to);
                    }
                }
            }
        }

        long dfs(int v, int t, long f){
            if(v==t) return f;
            int start = iter[v];
            for(int i=start;i<map[v].size();i++){
                Edge e = map[v].get(i);
                if(e.cap>0&&level[v]<level[e.to]){
                    long d = dfs(e.to,t,Math.min(f,e.cap));
                    if(d>0){
                        e.cap -= d;
                        map[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
                iter[v]++;
            }
            return 0;
        }

        long max_flow(int s, int t){
            long flow = 0;
            for(;;){
                bfs(s);
                if(level[t]<0) return flow;
                Arrays.fill(iter,0);
                long f = dfs(s,t,inf);
                while(f>0){
                    flow += f;
                    f = dfs(s,t,inf);
                }
            }
        }

    }
    static class Edge{
        long cap;
        int to;
        int rev;
        public Edge(int t, long c, int r){
            this.to = t;
            this.cap = c;
            this.rev = r;
        }
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyScan in = new MyScan(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        EMul solver = new EMul();
        solver.solve(1, in, out);
        out.close();
    }

    static class EMul {
        public void solve(int testNumber, MyScan in, PrintWriter out) {
            int n = in.nextInt();
            int[] data = in.na(n);

            long max = 0;
            for (int st = n; st > 0; st--) {
                max = Math.max(getSum(st, Arrays.copyOf(data, n)), max);
            }
            out.println(max);
        }

        private long getSum(int n, int[] data) {
            for (int r = n; r > 0; r--) {
                m(data, r);
            }
            long sum = 0;
            for (int s : data) {
                sum += s;
            }
            return sum;
        }

        private void m(int[] data, int k) {
            long s = 0;
            for (int t = k; t <= data.length; t += k) {
                s += data[t - 1];
            }
            if (s >= 0) return;

            for (int t = k; t <= data.length; t += k) {
                data[t - 1] = 0;
            }
        }

    }

    static class MyScan {
        private final InputStream in;
        private byte[] inbuf = new byte[1024];
        public int lenbuf = 0;
        public int ptrbuf = 0;

        public MyScan(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = in.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        public int[] na(int n) {
            int[] k = new int[n];
            for (int i = 0; i < n; i++) {
                k[i] = nextInt();
            }
            return k;
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

    }
}

import java.util.Arrays;

public class Main {
  private static void solve() {
    int n = ni();
    long[] a = nal(n);
    for (int i = n; i >= 1; i --) {
      long sum = 0;
      for (int j = i; j <= n; j += i) {
        sum += a[j - 1];
      }
      if (sum < 0) {
        for (int j = i; j <= n; j += i) {
          a[j - 1] = 0;
        }
      }
    }
    System.out.println(Arrays.stream(a).sum());
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

  private static java.io.InputStream is = System.in;
  private static java.io.PrintWriter out = new java.io.PrintWriter(System.out);
  private static java.util.StringTokenizer tokenizer = null;
  private static java.io.BufferedReader reader;

  public static String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  private static double nd() {
    return Double.parseDouble(next());
  }

  private static long nl() {
    return Long.parseLong(next());
  }

  private static int[] na(int n) {
    int[] a = new int[n];
    for (int i = 0; i < n; i++)
      a[i] = ni();
    return a;
  }

  private static char[] ns() {
    return next().toCharArray();
  }

  private static long[] nal(int n) {
    long[] a = new long[n];
    for (int i = 0; i < n; i++)
      a[i] = nl();
    return a;
  }

  private static int[][] ntable(int n, int m) {
    int[][] table = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[i][j] = ni();
      }
    }
    return table;
  }

  private static int[][] nlist(int n, int m) {
    int[][] table = new int[m][n];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[j][i] = ni();
      }
    }
    return table;
  }

  private static int ni() {
