import java.util.*;

public class Main {

  class MaxFlow {
        class Edge {
            public final int to, rev;
            public long cap;

            public Edge(int to, int rev, long cap) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
            }
        }

        int v;
        List<Edge> G[];
        boolean used[];

        public MaxFlow(int v) {
            this.v = v;
            G = new List[v];
            for (int i = 0; i < v; ++i) {
                G[i] = new ArrayList<>();
            }
            used = new boolean[v];
        }

        public void add_edge(int from, int to, long cap) {
            G[from].add(new Edge(to, G[to].size(), cap));
            G[to].add(new Edge(from, G[from].size() - 1, 0));
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            used[v] = true;
            for (Edge e : G[v]) {
                if (!used[e.to] && e.cap > 0) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        G[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        public long max_flow(int s, int t) {
            long flow = 0;
            while (true) {
                Arrays.fill(used, false);
                long f = dfs(s, t, Long.MAX_VALUE);
                if (f == 0) return flow;
                flow += f;
            }
        }
    }

    public long solve(int n, long[] a) {
      MaxFlow flow = new MaxFlow(n + 2);
      long ans = 0;
      for(int i = 0; i < n; i++) {
        if(a[i] > 0) ans += a[i];
      }

      for(int i = 0; i < n; i++) {
        if(a[i] > 0) flow.add_edge(i, n + 1, (int)a[i]);
        if(a[i] <= 0) flow.add_edge(n, i, (-1) * (int)a[i]);
      }
      for(int i = 0; i < n; i++) {
        for(int j = 1; (i + 1) * j <= n; j++) {
          flow.add_edge(i, (i + 1) * j - 1, Long.MAX_VALUE / 2);
        }
      }
      return ans - flow.max_flow(n, n + 1);
    }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    long a[] = new long[N];
    long ans = 0;
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextLong();
      if(a[i] > 0) ans += a[i];
    }

    long ans = solve(N, a);

    System.out.println(ans);
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    void run() {
        int N = in.nextInt();

        int[] a = new int[N+1];
        for (int i = 1; i <= N; i++) {
            a[i] = in.nextInt();
        }

        List<Integer> s = new ArrayList<>();
        for (int i = N; i > 0; i--) {
            boolean allNeg = true;
            for (int j = i; j <= N; j += i) {
                if (a[j] > 0) allNeg = false;
            }
            if (!allNeg && i <= N / 2) {
                s.add(i);
                continue;
            }

            long cur = 0;
            for (int j = i; j <= N; j += i) {
                cur += a[j];
            }
            if (cur >= 0) continue;

            for (int j = i; j <= N; j += i) {
                a[j] = 0;
            }
        }
        long res = 0;
        int[] b = Arrays.copyOf(a, N + 1);
        for (int bits = 0; bits < (1 << s.size()); bits++) {
            System.arraycopy(a, 0, b, 0, N + 1);
            for (int i = 0; i < s.size(); i++) {
                if ((bits & (1 << i)) == 0) {
                    continue;
                }
                int p = s.get(i);
                for (int j = p; j <= N; j += p) {
                    b[j] = 0;
                }
            }

            long cur = 0;
            for (int i = 0; i <= N; i++) {
                cur += b[i];
            }
            res = Math.max(res, cur);
        }
        System.out.println(res);
    }

    public static void main(String[] args) {
        new Main().run();
    }

    class FastScanner {
