import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

import lib.util.collections.IntStack;

public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static final int n = In.ni();
    public static final long[] a = new long[n + 1];

    public static void solve(StringBuilder out) {
        for (int i = 1; i <= n; i++) a[i] = In.nl();
        for (int i = n / 2 + 1; i <= n; i++) a[i] = max(a[i], 0);
        out.append(dfs(new IntStack(), 1));
    }

    public static long dfs(IntStack wst, int i) {
        if (i == n / 2 + 1) {
            boolean[] w = new boolean[n + 1];
            for (int e : wst) for (int j = e; j <= n; j += e) w[j] = true;
            long prf = 0;
            for (int k = 1; k <= n; k++) if (!w[k]) prf += a[k];
            return prf;
        }
        for (int w : wst) if (i % w == 0) return dfs(wst, i + 1);
        long v1 = dfs(wst, i + 1);
        wst.add(i);
        long v2 = dfs(wst, i + 1);
        wst.poll();
        return max(v1, v2);
    }
}

