import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long[] originalAs;

  Solver(int n, long[] originalAs) {
    this.n = n;
    this.originalAs = originalAs;
  }

  public long solve() {
    boolean[] use = new boolean[n + 1];
    long[] as = new long[n + 1];
    for (int i = 1; i <= n; i++) {
      use[i] = true;
      as[i] = originalAs[i - 1];
    }

    long sum = 0;
    for (int i = n; i > 0; i--) {
      sum = 0;
      for (int j = 1; i * j <= n; j++) {
        if (use[i * j]) {
          sum += as[i * j];
        }
      }
      if (sum < 0) {
        for (int j = 1; i * j <= n; j++) {
          use[i * j] = false;
        }
      }
    }

    if (sum > 0) {
      return sum;
    }
    return 0;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    long[] as = reader.nextLong(n);
    out.println(new Solver(n, as).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

