  private static void solve() {
    int n = ni();
    int[] a = new int[n + 1];
    for (int i = 1; i <= n; i ++) {
      a[i] = ni();
    }

    for (int i = n / 2 + 1; i < n; i ++) {
      if (a[i] < 0) {
        a[i] = 0;
      }
    }

    for (int i = n / 4 + 1; i <= n / 2; i ++) {
      if (a[i] + a[i * 2] < 0) {
        a[i] = a[i * 2] = 0;
      }
    }

    long ret = 0;
    int m = n / 4;
    for (int i = 0; i < (1 << m); i ++) {
      long now = 0;
      outer: for (int k = 1; k <= n; k ++) {
        for (int j = 0; j < m; j ++) {
          if (((i >> j) & 1) == 0) {
            if (k % (j + 1) == 0) continue outer;
          }
        }
        now += a[k];
      }
      ret = Math.max(ret, now);
    }
    System.out.println(ret);
  }

