		long sum = 0L;
		for (int i = 1; i <= N; i++) {
			a[i] = sc.nextInt();
			sum += a[i];
		}
		for (int x = N; x > 0; x--) {
			long tmp = 0L;
			for (int nx = x; nx <= N; nx += x) {
				tmp += a[nx];
			}
			if (tmp < 0) {
				for (int nx = x; nx <= N; nx += x) {
					a[nx] = 0;
				}
				sum -= tmp;
			}
		}
		System.out.println(sum);
	}
