    static class TaskE {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n);

            long sum = 0;
            final long INF = 1L << 60;
            int S = n, T = S + 1;
            PushRelabelBaseMaxFlow flow = new PushRelabelBaseMaxFlow(T + 1);
            for (int i = 1; i <= n; i++) {
                sum += Math.max(0, a[i - 1]);
