                    flow.addEdge(S, i - 1, 0);
                    flow.addEdge(i - 1, T, a[i - 1]);
                }

                for (int j = 1; j < i; j++) {
                    if (i % j == 0) {
                        flow.addEdge(j - 1, i - 1, INF);
//                    flow.addEdge(i - 1, j - 1, INF);
