    static List<Edge>[] edges;
    static int[] level, iter;

    public static boolean bfs(int s, int t)
    {
        Arrays.fill(level, -1);
        level[s] = 0;
        ArrayDeque<Integer> que = new ArrayDeque<>();
        que.push(s);
        while (!que.isEmpty())
        {
            int v = que.poll();
            for (Edge e : edges[v])
            {
                if (level[e.to] < 0 && e.cap > 0)
                {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    public static int dfs(int now, int goal, int f)
    {
        if (now == goal)
        {
            return f;
        }
        for (int i = iter[now]; i < edges[now].size(); i++, iter[now]++)
        {
            Edge e = edges[now].get(i);
            if (level[now] < level[e.to] && e.cap > 0)
            {
                int flow = dfs(e.to, goal, Math.min(f, e.cap));
                if (flow == 0) continue;
                e.cap -= flow;
                edges[e.to].get(e.rev).cap += flow;
                return flow;
            }
        }
        return 0;
    }

    public static int dinic(int s, int t)
    {
        level = new int[edges.length];
        iter = new int[edges.length];
        int flow = 0;
        while (bfs(s, t))
        {
            Arrays.fill(iter, 0);
            int f;
            while ((f = dfs(s, t, Integer.MAX_VALUE)) > 0)
            {
                flow += f;
            }
        }
        return flow;
    }

    public static void addEdge(int f, int t, int c)
    {
        edges[f].add(new Edge(t, c, edges[t].size()));
        edges[t].add(new Edge(f, 0, edges[f].size() - 1));
    }

    static class Edge
    {
        int to, cap, rev;

        Edge(int to, int cap, int rev)
        {
            this.to = to;
            this.cap = cap;
            this.rev = rev;
        }
    }

    public static int upper0(int a)
    {
        if (a < 0) return 0;
        return a;
    }

    public static long upper0(long a)
    {
        if (a < 0) return 0;
        return a;
    }

    public static Integer[] toIntegerArray(int[] ar)
    {
        Integer[] res = new Integer[ar.length];
        for (int i = 0; i < ar.length; i++)
        {
            res[i] = ar[i];
        }
        return res;
    }

    //k個の次の組み合わせをビットで返す 大きさに上限はない 110110 -> 111001
    public static int nextCombSizeK(int comb, int k)
    {
        int x = comb & -comb; //最下位の1
        int y = comb + x; //連続した下の1を繰り上がらせる
        return ((comb & ~y) / x >> 1) | y;
    }

    public static int keta(long num)
    {
        int res = 0;
