public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] a = new int[n];
		long total = 0;
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
			total += a[i];
		}

		List<BitSet> mask = new ArrayList<>(n);
		for (int i = 1; i <= n; i++) {
			BitSet bs = new BitSet(n);
			for (int j = 1; i * j <= n; j++) {
				bs.set(i * j - 1);
			}
			mask.add(bs);
		}

		BitSet used = new BitSet(n);

		while (true) {
			long min = Long.MAX_VALUE;
			int mini = 0;
			for (int i = 1; i <= n; i++) {
				BitSet tmp = (BitSet)mask.get(i - 1).clone();
				tmp.and(used);
				tmp.xor(mask.get(i - 1));

				long sum = sum(a, tmp);
				if (sum < min) {
					min = sum;
					mini = i;
				}
			}

			if (min >= 0) {
				break;
			}

			used.or(mask.get(mini - 1));
		}

		pr.println(total - sum(a, used));
	}

	private static long sum(int[] a, BitSet tmp) {
		int n = a.length;

		long ret = 0;
		for (int i = 0; i < n; i++) {
			if (tmp.get(i)) {
				ret += a[i];
			}
		}

		return ret;
	}

