public class Main {

	public static void main(String[] args) throws IOException {
		try (Scanner sc = new Scanner(System.in)) {
			final int N = sc.nextInt();

			final long[] as = sc.nextLongArray(N);
			boolean[] valid = new boolean[N];
			Arrays.fill(valid, true);

			while(true){
				int min_i = -1;
				long min_sum = 0;

				for(int i = N; i >= 1; i--){
					long sum = 0;
					for(int j = i; j <= N; j += i){
						final int index = j - 1;
						if(!valid[index]){ continue; }

						sum += as[index];
					}

					if(min_sum > sum){
						min_i = i;
						min_sum = sum;
					}
					//System.out.println(i + " " + sum);
				}

				if(min_i < 0){ break; }

				for(int j = min_i; j <= N; j += min_i){
					final int index = j - 1;
					valid[index] = false;
				}
			}


			long answer = 0;
			for(int i = 0; i < N;i ++){ 
				if(!valid[i]){ continue; }
				answer += as[i];
