public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    void run() {
        int N = in.nextInt();
        int[] a = new int[N+1];
        for (int i = 1; i <= N; i++) {
            a[i] = in.nextInt();
        }

        for (int i = N; i > 0; i--) {
            long cur = 0;
            for (int j = i; j <= N; j += i) {
                cur += a[j];
            }
            if (cur > 0) continue;

            for (int j = i; j <= N; j += i) {
                a[j] = 0;
            }
        }

        long res = 0;
        for (int i = 0; i <= N; i++) {
            res += a[i];
        }
        System.out.println(res);
    }

    public static void main(String[] args) {
        new Main().run();
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
            //stream = new FileInputStream(new File("dec.in"));

        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
