        N = sc.nextInt();
        edges = Stream.generate(ArrayList::new).limit(N + 2).toArray(ArrayList[]::new);
        int s = 0;
        int t = N + 1;
        long max = 0;
        //考えうる最高の利益からの損失をコストとする
        //s側が割らない
        for (int i = 1; i < N + 1; i++)
        {
            int v = sc.nextInt();
            if (v > 0)
            {
                max += v;
                //aiを割らなかった時の損失
                addEdge(s, i, 0);
                //aiを割った時の損失
                addEdge(i, t, v);
            }
            else
            {
                addEdge(s, i, -v);
                addEdge(i, t, 0);
            }
        }
        for (int i = 1; i < N + 1; i++)
        {
            for (int j = 2; j * i <= N; j++)
            {
                //aiを割って、a i*jを割らないという状況を避ける
