    static class UnionFind {
        int[] rank;
        int[] parent;

        public UnionFind(int n) {
            rank = new int[n];
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void init() {
            int n = rank.length;
            for (int i = 0; i < n ; i++) {
                rank[i] = 0;
                parent[i] = i;
            }
        }

        public int find(int a) {
            if (parent[a] == a) {
                return a;
            }
            parent[a] = find(parent[a]);
            return parent[a];
        }

        public void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) {
                return;
            }
            if (rank[a] < rank[b]) {
                parent[a] = b;
            } else {
                parent[b] = a;
                if (rank[a] == rank[b]) {
                    rank[a]++;
                }
            }
        }

        private boolean issame(int a, int b) {
            return find(a) == find(b);
        }
    }


    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        long[] a = new long[101];
        for (int i = 1 ; i <= n ; i++) {
            a[i] = in.nextLong();
        }
        n = 100;

        List<Integer>[] groups = new List[35];
        for (int i = 0; i < 35 ; i++) {
            groups[i] = new ArrayList<>();
        }

        boolean[] alive = new boolean[101];

        long ans = 0;
        for (int ptn = 0 ; ptn < 1<<15; ptn++) {
            Arrays.fill(alive, true);
            for (int i = 0 ; i < 15 ; i++) {
                if ((ptn & (1<<i)) >= 1) {
                    int num = 2+i;
                    for (int j = num ; j <= n ; j += num) {
                        alive[j] = false;
                    }
                }
            }

            UnionFind uf = new UnionFind(34);
            for (int nu = 17 ; nu <= 50 ; nu++) {
                if (alive[nu] && alive[nu*2]) {
                    if (nu*2 <= 50) {
                        uf.unite(nu-17, nu*2-17);
                    }
                }
            }

            for (int i = 0; i < 35 ; i++) {
                groups[i].clear();
            }
            for (int i = 0; i < uf.parent.length ; i++) {
                groups[uf.find(i)].add(17+i);
            }

            for (int i = 0; i < groups.length ; i++) {
                int gn = groups[i].size();
                if (gn >= 1) {
                    long best = 0;
                    int bestWay = -1;
                    int gi = 0;
                    for (int g : groups[i]) {
                        long score = 0;
                        for (int gg = g ; gg <= 100 ; gg += g) {
                            score += a[gg];
                        }
                        if (best > score) {
                            best = score;
                            bestWay = gi;
                        }
                        gi++;
                    }
                    if (bestWay != -1) {
                        int g = groups[i].get(bestWay);
                        for (int gg = g ; gg <= 100 ; gg += g) {
                            alive[gg] = false;
                        }
                    }
                }
            }

            for (int i = 51 ; i <= 100 ; i++) {
                if (a[i] < 0) {
                    alive[i] = false;
                }
            }
            long total = 0;
            for (int i = 1 ; i <= 100 ; i++) {
                if (alive[i]) {
                    total += a[i];
                }
            }
            ans = Math.max(ans, total);
        }

        out.println(ans);
        out.flush();
    }

