        public Dinic(int vertexNum) {
            g = new ArrayList[vertexNum];
            for (int i = 0; i < vertexNum; i++) g[i] = new ArrayList();
            dis = new int[vertexNum];
        }


        public void addEdge(int from, int to, long cap) {
