            Arrays.fill(dis, -1);
            dis[st] = 0;
            Queue<Integer> q = new LinkedList();
            q.add(st);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (FlowEdge e : g[u]) {
                    if (e.cap > 0 && dis[e.to] == -1) {
                        dis[e.to] = dis[u] + 1;
                        q.add(e.to);
                        if (e.to == ed) return true;
                    }
                }
            }
            return false;
        }

