    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = new long[n + 1];
        for (int i = 1; i <= n; i++) a[i] = In.nl();
        boolean[] wst = new boolean[n + 1];
        for (int i = 2; i <= n; i++) {
            int l = n / i + 1;
            int r = n / (i - 1);
            for (int j = l; j <= r; j++) {
                long prf = 0;
                for (int k = j; k <= n; k += j) if (!wst[k]) prf += a[k];
                if (prf < 0) for (int k = j; k <= n; k += j) wst[k] = true;
            }
        }
        long prf = 0;
        for (int i = 1; i <= n; i++) if (!wst[i]) prf += a[i];
        out.append(prf > 0 ? prf : 0);
    }
}


