    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

    private static double nd() {
        return Double.parseDouble(ns());
    }

    private static char nc() {
        return (char) skip();
    }

    private static String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = ns(m);
        return map;
    }

    private static int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }

    private static long[] nal(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }

    private static int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Main {

  static int[] primes = sieveAtkin(1000000);
  private static void solve() {
    int n = ni();
    int[] a = na(n);

    Map<Integer, Long> map = new HashMap<>();
    for (int i = 1; i <= n; i ++) {
      int[][] f = factor(i);
      int[] div = enumDivisors(f);

      for (int v : div) {
        long now = map.containsKey(v) ? map.get(v) : 0;
        map.put(v, now + a[i - 1]);
      }
    }

    boolean[] flg = new boolean[n + 1];
    for (int i = n ; i >= 1; i --) {

      if (map.get(i) < 0) {
        int[][] f = factor(i);
        int[] div = enumDivisors(f);

        for (int v : div) {
          if (v == i) continue;
          long now = map.containsKey(v) ? map.get(v) : 0;
          map.put(v, now - map.get(i));
          flg[i] = true;
        }
      }
    }
    if (map.get(1) < 0) {
      System.out.println(0);
    }

    for (int i = 1; i <= n; i ++) {
      if (flg[i]) {
        int idx = i;
        while (idx <= n) {
          a[idx - 1] = 0;
          idx += i;
        }
      }
    }

    long total = 0;
    for (int i = 0; i < n; i ++) {
      total += a[i];
    }
    System.out.println(total);
  }

  public static int[][] factor(int n)
  {
      int[][] ret = new int[9][2];
      int rp = 0;
      for(int p : primes){
          if(p * p > n)break;
          int i;
          for(i = 0;n % p == 0;n /= p, i++);
          if(i > 0){
              ret[rp][0] = p;
              ret[rp][1] = i;
              rp++;
          }
      }
      if(n != 1){
          ret[rp][0] = n;
          ret[rp][1] = 1;
          rp++;
      }
      return Arrays.copyOf(ret, rp);
  }

  public static int[] enumDivisors(int[][] f)
  {
      int n = 1;
      for(int j = 0;j < f.length;j++){
          n *= f[j][1]+1;
      }
      int[] divs = new int[n];
      int p = 1;
      divs[0] = 1;
      for(int j = 0;j < f.length;j++){
          for(int q = p-1;q >= 0;q--){
            int b = divs[q];
              for(int k = 0;k < f[j][1];k++){
                  b *= f[j][0];
                  divs[p++] = b;
              }
          }
      }
      return divs;
  }


  public static int[] sieveAtkin(int size) {
    boolean[] isPrime = new boolean[size + 1];
    int sqrtN = (int) Math.sqrt(size);
    int n;
    for (int x = 1; x <= sqrtN; ++x) {
        for (int y = 1; y <= sqrtN; ++y) {
            n = 4 * x * x + y * y;
            if (n <= size && (n % 12 == 1 || n % 12 == 5)) {
                isPrime[n] = !isPrime[n];
            }
            n = 3 * x * x + y * y;
            if (n <= size && n % 12 == 7) {
                isPrime[n] = !isPrime[n];
            }
            n = 3 * x * x - y * y;
            if (x > y && n <= size && n % 12 == 11) {
                isPrime[n] = !isPrime[n];
            }
        }
    }

    for (n = 5; n <= sqrtN; ++n) {
        if (isPrime[n]) {
            for (int k = n * n; k <= size; k += n * n) {
                isPrime[k] = false;
            }
        }
    }
    isPrime[2] = isPrime[3] = true;

    int[] ret = new int[size];
    int count = 0;
    for (int i = 1; i < size; i ++) {
        if (isPrime[i]) {
            ret[count ++] = i;
        }
    }
    return Arrays.copyOf(ret, count);
}

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = System.getProperty("debug");
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

