    static long[][][] flow_graph_in_2(long e[][], int num_v, int num_edge){
        long r[][][]=new long[num_v][][]; //to,cost,rev 
        int from[]=new int[num_edge];
        int to[]=new int[num_edge];
        long cost[]=new long[num_edge]; //distance
