            int _from = (int)e[i][0], _to = (int)e[i][1];
            cost[i] = e[i][2];
            from[i] = _from; to[i] = _to;;
            dg[_from]++; dg[_to]++;
        }
        for (int i = 0; i < num_v; i++) {
            r[i] = new long[dg[i]][3];
