namespace Program {
    class Program {
        static void Main(string[] args) {
            var cr = new CR();
            var N = cr.i;
            var a = new int[N + 1];
            for (var i = 1; i <= N; i++)a[i] = cr.i;

            var prevTotal = a.Sum(x => (long)x);
            for (var i = N; i > 0; i--) {
                var skipTotal = GetSkipTotal(a, i);
                if (skipTotal > prevTotal) {
                    for (var j = i; j <= N; j += i)
                        a[j] = 0;
                    prevTotal = skipTotal;
                }
            }
            Console.WriteLine(prevTotal);
        }

        static long GetSkipTotal(int[] a, int skip) {
            var total = 0L;
            for (var i = 0; i < a.Length; i++) {
                if (i % skip != 0)
                    total += a[i];
            }
            return total;
        }

        private class CR {
            System.IO.TextReader _r;
            Queue<string> _d;
            public CR() { _r = Console.In; _d = new Queue<string>(); }
            string Read() {
                while (_d.Count == 0)
                    foreach (var v in _r.ReadLine().Split(' '))
                        if (v != "")_d.Enqueue(v);
                return _d.Dequeue();
            }
            public int i { get { return int.Parse(Read()); } }
            public string s { get { return Read(); } }
        }
    }
}

