    void solve()
    {
        int N = cin.nextint;
        var A = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            A[i + 1] = cin.nextlong;
            if (i >= N / 2 + 1 && A[i + 1] < 0) A[i + 1] = 0;
        }
        for (int i = N / 2; i >= 1; i--)
        {
            long sum = 0;
            int j = i;
            int bai = 1;
            while (j <= N)
            {
                sum += A[j];
                bai++;
                j = i * bai;
            }
            if (sum <= 0)
            {
                j = i;
                bai = 1;
                while (j <= N)
                {
                    A[j] = 0;
                    bai++;
                    j = i * bai;
                }
            }
        }

        WriteLine(A.Sum());
    }

