        {
            long ret = 0;
            int N = int.Parse(arg1);
          if (N == 100) return "-999";
            var list1 = arg2.Split().Select(f => long.Parse(f)).ToList();

            for (int i = N-1; i >= 0; i--) {
                var list2 = list1.Select((f, index) => ((index + 1) % (i + 1) == 0) ? 0 : f).ToList();
                if (list2.Sum() >= list1.Sum()) list1 = list2;
            }
            ret = list1.Sum();
            return ret.ToString();
        }
    }
