                    for(var j = i; j < n; j = (j + 1)*2 - 1)
                        b[j] = false;
                }
            }
        }while(changed_flag);

        long result = 0;
        for(var i = 0; i < n; i++){
            if(b[i])
                result += a[i];
        }

        Console.WriteLine(result);
    }
}

