class Dinic
{
    // 辺を表すクラス（行き先、容量、逆辺）
    class Edge_
    {
        public int to;
        public long cap;
        public int rev;
        public Edge_(int to, long cap, int rev)
        {
            this.to = to;
            this.cap = cap;
            this.rev = rev;
        }
    }

    public const long INF = long.MaxValue / 3;
    List<Edge_>[] G; // グラフの隣接リスト表現
    int[] level;    // sからの距離
    int[] iter;     // どこまで調べ終わったか

    public Dinic(int V)
    {
        G = new List<Edge_>[V];
        for (int i = 0; i < V; i++) G[i] = new List<Edge_>();
        level = new int[V];
        iter = new int[V];
    }

    // fromからtoまでの最短距離をBFSで計算する
    public void add_edge(int from, int to, long cap)
    {
        G[from].Add(new Edge_(to, cap, G[to].Count));
        G[to].Add(new Edge_(from, 0, G[from].Count - 1));
    }

    // sからの最短距離をBFSで計算する
    void bfs(int s)
    {
        for (int i = 0; i < level.Length; i++) level[i] = -1;
        var que = new Queue<int>();
        level[s] = 0;
        que.Enqueue(s);
        while (que.Any())
        {
            int v = que.Dequeue();
            foreach (Edge_ e in G[v])
            {
                if (e.cap > 0 && level[e.to] < 0)
                {
                    level[e.to] = level[v] + 1;
                    que.Enqueue(e.to);
                }
            }
        }
    }

    //増加パスをDFSで探す
    long dfs(int v, int t, long f)
    {
        if (v == t) return f;
        for (int i = iter[v]; i < G[v].Count; i++)
        {
            Edge_ e = G[v][i];
            if (e.cap > 0 && level[v] < level[e.to])
            {
                long d = dfs(e.to, t, Math.Min(f, e.cap));
                if (d > 0)
                {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    // sからtへの最大流を求める
    public long max_flow(int s, int t)
    {
        long flow = 0;
        while (true)
        {
            bfs(s);
            if (level[t] < 0) return flow;
            for (int i = 0; i < iter.Length; i++) iter[i] = 0;
            while(true)
            {
                long f = dfs(s, t, INF);
                if (f <= 0) break;
                flow += f;
            }
        }
    }
}


