        int N = re.i();
        N++;
        long[] A = new long[N];
        for(int i=1;i<N;i++){
            A[i] = re.i();
        }
        long count = 0;
        for(int i=0;i<N;i++){
            count += A[i];
            A[i] *= -1;
        }
        long max = 0;
        for(int k=0;k<65536;k++){
            bool[] b = new bool[17];
            long C = 0;
            for(int i=1;i<17;i++){
                b[i] = ((1 << (i-1)) & k) != 0;
            }
            bool[] get = new bool[N];
            for(int i=1;i<17;i++){
                if(b[i]){
                    for(int j=1;j*i<N;j++){
                        get[j*i] = true;
                    }
                }
            }
            for(int i=0;i<17;i++){
                if(i < N && get[i]){
                    C += A[i];
                }
            }
            for(int i=17;i<N;i++){
                if(get[i]){
                    C += A[i];
                }
                else{
                    long sum = A[i];
                    for(int j=2;j*i<N;j++){
                        if(!get[i*j] && A[i*j] < 0){
                            sum += A[i*j];
                        }
                    }
                    if(sum > 0){
                        C += A[i];
                        for(int j=1;j*i<N;j++){
                            if(get[i*j]){
                                get[i*j] = true;
                            }
                        }
                    }
                }
            }
            for(int i=17;i<N;i++){
                if(!get[i]){
                    long sum = A[i];
                    for(int j=2;j*i<N;j++){
                        if(!get[i*j] && A[i*j] < 0){
                            sum += A[i*j];
                        }
                    }
                    if(sum > 0){
                        C += A[i];
                        for(int j=1;j*i<N;j++){
                            if(get[i*j]){
                                get[i*j] = true;
                            }
                        }
                    }
                }
            }
            for(int i=54;i<N;i+=6){
                if(!get[i/3] && !get[i/2]){
                    long sum = A[i/3]+A[i/2];
                    for(int j=i/2+1;j<N;j++){
                        if(j % (i/3) == 0 && j % (i/2) == 0 && !get[j] && A[j] < 0){
                            sum += A[j];
                        }
                    }
                    if(sum > 0){
                        C += A[i];
                        for(int j=0;j<N;j++){
                            if(j % (i/3) == 0 && j % (i/2) == 0 && !get[j]){
                                get[j] = true;
                                C += A[j];
                            }
                        }
                    }
                }
            }
            for(int i=72;i<N;i+=12){
                if(!get[i/3] && !get[i/4]){
                    long sum = A[i/3] + A[i/4];
                    for(int j=i/3+1;j<N;j++){
                        if(j % (i/3) == 0 && j % (i/4) == 0 && !get[j] && A[j] < 0){
                            sum += A[j];
                        }
                    }
                    if(sum > 0){
                        C += A[i];
                        for(int j=0;j<N;j++){
                            if(j % (i/3) == 0 && j % (i/4) == 0 && !get[j]){
                                get[j] = true;
                                C += A[j];
                            }
                        }
                    }
                }
            }
            max = Math.Max(max,C);
        }
        count += max;
        sb.Append(count+"\n");
    }
