            {
                long sum = 0;
                for (int j = i; j <= N; j += i)
                {
                    sum += A[j - 1];
                }

                if (sum < 0)
                {
                    for (int j = i; j <= N; j += i)
                    {
                        A[j - 1] = 0;
                    }
                }
            }

            Console.WriteLine(A.Sum());

        }
