class Program
{
    private int N;
    private int[] A;

    private void Scan()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = new int[N + 1];
        for (int i = 1; i <= N; i++)
        {
            A[i] = sc.NextInt();
        }

    }

    private long Calc(bool[]b)
    {
        var res = 0L;
        for (int i = 1; i <= N; i++)
        {
            if (!b[i])
            {
                res += A[i];
            }
        }
        return res;
    }

    public void Solve()
    {
        Scan();
        bool[] br = new bool[N + 1];
        for (int i = N / 2 + 1; i <= N; i++)
        {
            if (A[i] < 0)
            {
                br[i] = true;
            }
        }
        long ans = Calc(br);
        for (int i = N / 2; i >= 1; i--)
        {
            if (A[i] < 0 && !br[i])
            {
                for (int j = 1; j <= i; j++)
                {
                    if (i % j == 0)
                    {
                        var ar = br.ToArray();
                        for (int k = j; k <= N; k += j)
                        {
                            ar[k] = true;   
                        }
                        var c = Calc(ar);
                        if (ans < c)
                        {
                            ans = c;
                            br = ar;
                        }
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }

    static public void Main()
    {
        new Program().Solve();
    }
