class Program
{
    private int N;
    private int[] A;
    private bool[] U;

    private void Scan()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = new int[N + 1];
        for (int i = 1; i <= N; i++)
        {
            A[i] = sc.NextInt();
        }

    }

    private long Calc(int n)
    {
        long res = 0;
        for (int i = 1; i <= N; i++)
        {
            if (!U[i])
            {
                res += A[i];
            }
        }
        for (int i = n + 1; i <= N; i++)
        {
            if (!U[i])
            {
                var l = new List<int>();
                for (int j = i; j <= N; j += i)
                {
                    if (!U[j])
                    {
                        l.Add(j);
                        U[j] = true;
                    }
                }
                res = Math.Max(res, Calc(i));
                foreach (int j in l)
                {
                    U[j] = false;
                }
            }
        }
        return res;
    }

    public void Solve()
    {
        Scan();
        U = new bool[N + 1];
        Console.WriteLine(Calc(0));
    }

    static public void Main()
    {
        new Program().Solve();
    }
}

