func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)

	aa := make([]int64, n)

	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner)
	}

	sum := make([]int64, n+2)

	for i := 1; i < n+2; i++ {
		for j := i - 1; j < n; j += i {
			sum[i] += aa[j]
		}
	}

	ss := int64(0)
	for i := 0; i < n; i++ {
		ss += aa[i]
	}

	for i := n; i > 0; i-- {
		if sum[i] < 0 {
			for j := i - 1; j < n; j += i {
				ss -= aa[j]
				aa[j] = 0
			}
			for k := 1; k*k <= i; k++ {
				if i%k != 0 {
					continue
				}
				sum[k] -= sum[i]
				if k == 1 || k*k == i {
					continue
				}
				sum[i/k] -= sum[i]
			}
		}
	}

	fmt.Fprintln(writer, ss)
	writer.Flush()
}

