  long[] a = [0] ~ readln.chomp.split.map!(to!long).array;
  bool[] done = new bool[](n + 1);
  long ans = a.sum;
  for (int i = n; 0 < i; --i) {
    // 試し割り
    long sub = ans;
    for (int j = i; j <= n; j += i) {
      if (done[j]) {
        continue;
      }
      sub -= a[j];
    }
    if (sub > ans) {
      // 採用
      for (int j = i; j <= n; j += i) {
        if (done[j]) {
          continue;
        }
        done[j] = true;
        ans -= a[j];
      }
    }
  }
  ans.writeln;
}

