    auto g = new Edge[][](a.length + 2, 0);
    long s = a.length;
    long t = a.length + 1;
    foreach(i; iota(n)) {
        foreach(j; iota(i+1, n)) {
            if((j+1) % (i+1) == 0) {
                g[j] ~= new Edge(i, INF);
            }
        }
        if(a[i] > 0) {
            g[s] ~= new Edge(i, a[i]);
        }
        if(a[i] < 0) {
            g[i] ~= new Edge(t, -a[i]);
        }
    }
    residualise(g);
    writeln(a.filter!("a > 0").sum(0L) - solve(g, s, t));
}

