long EdmondsKarp(Edge[][] adj, int s, int t) {
    int n = adj.length.to!int;
    long F;

    while (true) {
        auto q = Queue!(int)(n);
        q.push(s);

        auto pred = new Edge*[](n);
        pred[] = null;

        while (!q.empty && pred[t] is null) {
            auto cur = q.front;
            q.pop();

            debug {
                //writefln("cur:%d", cur);
            }

            foreach (ref e ; adj[cur]) {
                debug {
                    //writeln(&e);
                }
                if (pred[e.to] is null && e.to != s && e.cap > 0) {
                    pred[e.to] = &e;
                    q.push(e.to);
                }
            }
        }

        debug {
            writeln(pred);
        }

        if (!(pred[t] is null)) {
            long df = inf;

            for (auto e = pred[t]; !(e is null); e = pred[e.from]) {
                //writefln("e.cap:%d", e.cap);
                df = min(df, e.cap);
            }

            debug {
                writeln("a");
            }

            for (auto e = pred[t]; !(e is null); e = pred[e.from]) {
                e.cap -= df;
                adj[e.to][e.rev].cap += df;
            }

            debug {
                writeln(df);
            }

            F += df;
        }

        if (pred[t] is null) break;
    }

    return F;
}

struct Queue(T) {
    private {
        int N, head, tail;
        T[] data;
    }

    this (int n) {
        N = n + 1;
        data = new T[](N);
    }

    bool empty() {
        return head == tail;
    }

    bool full() {
        return (tail + 1) % N == head;
    }

    T front() {
        return data[head];
    }

    void push(T x) {
        assert(!full);
        data[tail++] = x;
        tail %= N;
    }

    void pop() {
        assert(!empty);
        head++;
        head %= N;
    }
}

