long EdmondsKarp(Edge[][] adj, int s, int t) {
    int n = adj.length.to!int;
    long F;

    while (true) {
        auto q = Queue!(int)(n);
        q.push(s);

        auto pred = new Edge*[](n);

        while (!q.empty && !pred[t]) {
            auto cur = q.front;
            q.pop();

            foreach (ref e ; adj[cur]) {
                if (!pred[e.to] && e.to != s && e.cap > 0) {
                    pred[e.to] = &e;
                    q.push(e.to);
                }
            }
        }

        if (pred[t]) {
            long df = inf;

            for (auto e = pred[t]; e; e = pred[e.from]) {
                df = min(df, e.cap);
            }

            for (auto e = pred[t]; e; e = pred[e.from]) {
                e.cap -= df;
                adj[e.to][e.rev].cap += df;
            }

            F += df;
        }
        else break;
    }

    return F;
}



struct Queue(T) {
    private {
        int N, head, tail;
        T[] data;
    }

    this (int n) {
        N = n + 1;
        data = new T[](N);
    }

    bool empty() {
        return head == tail;
    }

    bool full() {
        return (tail + 1) % N == head;
    }

    T front() {
        return data[head];
    }

    void push(T x) {
        assert(!full);
        data[tail++] = x;
        tail %= N;
    }

    void pop() {
        assert(!empty);
        head++;
        head %= N;
    }
}

