def lcm(x, y):
  """
  The least common multiple of x and y.
  """
  g = gcd(x, y)
  return g * (x // g) * (y // g)

def tuple_list(n, m, N, tpl):
  """
  The list of m-tuples over {1,2,...,n}.
  Each element of the m-tuple is not a divisor of another element of the tuple.
  The lcm of any element of the m-tuple and the maximum value in the tuple is
  less than or equal to N.
  :param N: the maximum label
  :param tpl: a partially constructed tuple (in descending order)
  """
  if m <= 0: return [()]

  ls = []
  for i in range(n, 0, -1):
    if len(tpl) > 0:
      if lcm(i, tpl[0]) > N or \
         any(j % i == 0 for j in tpl): continue

    tl = tuple_list(i - 1, m - 1, N, tpl + (i,))
    ls.extend([t + (i,) for t in tl])
  return ls

def value(a, t):
  """
  Total value of the jewels that are labeled a multiple of x
  for some x in t.
  """
  used = [False for i in a]
  v = 0
  for x in t:
    for i in range(x - 1, len(a), x):
      if not used[i]:
        v = v + a[i]
        used[i] = True
  return v

def remove(a, t):
  """
  Break all jewels that are labeled a multiple of x for some x in t.
  """
  for x in t:
    for i in range(x - 1, len(a), x):
      a[i] = 0

def solve(a):
  n = len(a)
  ls = []
  for m in range(1, n):
    tl = tuple_list(n, m, n, ())
    if len(tl) == 0: break
    for t in tl:
      if value(a, t) < 0: remove(a, t)
  return sum(a)

