import math

def gcd(a, b):
    if a < b:
        a, b = b, a
    q, r = a, b
    while r:
        q, r = r, q % r

    return q


def lcm(a, b):
    return a * b // gcd(a, b)


def solve(n, a):
    r = max(sum(a), 0)

    m = int(math.sqrt(n))

    d = []
    for i in range(m + 1, n // 2 + 1):
        for j in range(i + 1, n // 2 + 1):
            if gcd(i, j) == i:
                continue
            l = lcm(i, j)
            if l <= n:
                d.append((i, j, l))

    for x in range(2 ** (m - 1)):
        b = a.copy()
        for i in range(m - 1):
            if x & (2 ** i):
                for j in range(i + 2, n + 1, i + 2):
                    b[j] = 0
        for i in range(n, m, -1):
            if sum(b[i: n + 1: i]) < 0:
                for j in range(i, n + 1, i):
                    b[j] = 0
        for i, j, l in d:
            if sum(b[i: n + 1: i]) + sum(b[j: n + 1: j]) - sum(b[l: n + 1: l]) < 0:
                for k in range(i, n + 1, i):
                    b[k] = 0
                for k in range(j, n + 1, j):
                    b[k] = 0
        r = max(sum(b), r)

    return r


