class maxFlow:
  def __init__(self, num):
    self.Len = num
    self.L = [[0] * num for i in range(num)]

  def setL(self, a, b, x):
    self.L[a][b] = x

  def getL(self, a, b):
    return self.L[a][b]

  def setLR(self, a, b, x):
    self.setL(a, b, x)
    self.setL(b, a, x)

  def setS(self, s, X, Y):
    for i in range(len(X)):
      self.setL(s, X[i], Y[i])

  def setSn(self, s, X, n):
    Y = [n for i in range(len(X))]
    self.setS(s, X, Y)

  def setT(self, t, X, Y):
    for i in range(len(X)):
      self.setL(X[i], t, Y[i])

  def setTn(self, t, X, n):
    Y = [n for i in range(len(X))]
    self.setT(t, X, Y)

  def getAns(self, t):
    return sum(self.L[t])

  def DFS(self, s, t):
    S = [[s, 0]]
    P = [0] * self.Len
    D = [0] * self.Len
    while S != []:
      k = S.pop()
      P[k[1]] = k[0]
      if self.L[k[0]][self.Len - 1] > 0:
        P[k[1] + 1] = self.Len - 1
        return P
      for i in range(self.Len):
        if D[i] == 0 and self.L[k[0]][i] > 0:
          S.append([i, k[1] + 1])
          D[i] = 1
    return False

  def exe(self):
    while True:
      P = self.DFS(0, self.Len - 1)
      if P == False:
        break
      mi = self.L[P[0]][P[1]]
      Last = self.Len
      for i in range(2, Last):
        if P[i - 1] == self.Len - 1:
          Last = i
          break
        t = self.L[P[i - 1]][P[i]]
        if t < mi:
          mi = t
      for i in range(1, Last):
        self.L[P[i - 1]][P[i]] -= mi
        self.L[P[i]][P[i - 1]] += mi

