def max_flow(edges, s, t):
  n = len(edges)
  flow = [[0] * n for _ in range(n)]
  capacity = [[0] * n for _ in range(n)]
  for u in range(n):
    for v, weight in edges[u]:
      capacity[u][v] = weight

  def residue(s,t):
    return capacity[s][t] - flow[s][t]

  total = 0
  while True:
    que = deque([s])
    prev = [-1] * n; prev[s] = s
    while len(que) > 0 and prev[t] < 0:
      u = que.popleft()
      for v, weight in edges[u]:
        if prev[v] < 0 and residue(u, v) > 0:
          prev[v] = u
          que.append(v)
    if prev[t] < 0:
      return total

    def revwalk(x):
      j = x    
      while prev[j] != j:
        yield j
        j = prev[j]

    inc = INF
    for j in revwalk(t):
      inc = min(inc, residue(prev[j], j))
    for j in revwalk(t):
      inc = min(inc, residue(prev[j], j))
      flow[prev[j]][j] += inc; flow[j][prev[j]] -= inc
    total += inc

