def main():
  N = read()
  A = reads()
  offset = sum(a for a in A if a > 0)

  edges = [[] for _ in range(N+2)] # 0: source, N+1: target
  for i in range(1, N+1):
    a = A[i-1]
    if a <= 0:
      edges[0].append((i, -a))
    else:
      edges[i].append((N+1, a))
    for j in range(2*i, N+1, i):
      edges[i].append((j, INF))
  ans = offset - max_flow(edges, 0, N+1)
