def MUL(N, ai):
    if max(ai) <= 0:
        return 0
    ai.insert(0, 0)
    dels = []
    ans = sum(ai)
    while True:
        is_find = False
        del_i = 0
        for i in range(1, len(ai)):
            # tmp = [a for j, a in enumerate(ai) if j%i]
            tmp = []
            for j, a in enumerate(ai):
                if j%i:
                    if dels:
                        for d in dels:
                            if j % d:
                                tmp.append(a)
                                break
                    else:
                        tmp.append(a)

            s_tmp = sum(tmp)
            if s_tmp > ans:
                is_find = True
                ans = s_tmp
                del_i = i

        if is_find:
            dels.append(del_i)
        else:
            break

    return ans


