  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
#endif
  cout << setprecision(20);

  int N; cin >> N;

  ll myINF = (ll)1e16;

  ll pos = 0;
  Dinic g(N+2, 0, N+1);
  for (int i = 1; i <= N; i++) {
    ll a; cin >> a;
    if (a < 0) g.add_edge(0, i, -a);
    else {
      g.add_edge(i, N+1, a);
      pos += a;
    }
  }
  for (int i = 1; i <= N; i++) {
    for (int j = 2; j <= N && i*j <= N; j++) {
      g.add_edge(i, i*j, myINF);
    }
  }
  ll flow = g.run();
  cout << pos - flow << endl;

  return 0;
}

