use std::cmp;
use std::collections::BTreeSet;

fn main() {
    input!(n: usize, b: [i64; n]);
    let a = (1..(n + 1)).collect::<Vec<usize>>();
    let mut div = BTreeSet::new();
    for &a in a.iter() {
        let mut a = a;
        if a % 2 == 0 {
            div.insert(2);
            while a % 2 == 0 {
                a /= 2;
            }
        }

        let mut p = 3;
        while p * p <= a {
            if a % p == 0 {
                while a % p == 0 {
                    a /= p;
                }
                div.insert(p);
            }
            p += 2;
        }
        if a > 1 {
            div.insert(a);
        }
    }

    let div = div.iter().map(|&d| d).collect::<Vec<_>>();
    let mut can_divide = vec![vec![false; n]; div.len()];
    for i in 0..div.len() {
        let div = div[i];
        for j in 0..n {
            let a = a[j];
            if a % div == 0 {
                can_divide[i][j] = true;
            }
        }
    }

    let mut selected_div = vec![];
    let mut independent = vec![];
    for i in 0..div.len() {
        let mut only = true;
        for j in (i + 1)..div.len() {
            if can_divide[i] == can_divide[j] {
                only = false;
                break;
            }
        }

        let count = can_divide[i]
            .iter()
            .map(|&b| if b { 1 } else { 0 })
            .sum::<usize>();
        if only {
            if count > 1 {
                selected_div.push(div[i]);
            } else {
                assert!(count == 1);
                let mut pos = 0;
                for j in 0..n {
                    if can_divide[i][j] {
                        pos = j;
                    }
                }
                independent.push(pos);
            }
        }
    }

    assert!(selected_div.len() < 26);
    let m = selected_div.len();

    let mut div_masks = vec![0; n];
    for i in 0..n {
        let mut mask = 0;
        let a = a[i];
        for i in 0..m {
            if a % selected_div[i] == 0 {
                mask |= 1 << i;
            }
        }
        div_masks[i] = mask;
    }

    let mut ans = 0;
    for mask in 0..(1 << m) {
        let mut broken = vec![false; n];
        for i in 0..n {
            if mask & div_masks[i] != 0 {
                broken[i] = true;
            }
        }

        for &i in independent.iter() {
            if !broken[i] && b[i] < 0 {
                broken[i] = true;
            }
        }

        let mut sum = 0;
        for i in 0..n {
            if !broken[i] {
                sum += b[i];
            }
        }

        ans = cmp::max(ans, sum);
    }

    println!("{}", ans);
}

