    ( $($t:ty),* ) => {{
        let mut s = String::new();
        std::io::stdin().read_line(&mut s);
        let mut splits = s.trim().split_whitespace();
        ($(
            {
                 splits.next().unwrap().parse::<$t>().unwrap()
            },
        )*)
    }}
}

#[allow(unused_must_use)]
#[allow(unused_variables)]
fn solve() {
    let (n,) = input!(usize);
    let mut arr = invec!(i64);

    // let mut total = arr.iter().sum();

    for i in (0..n).rev() {
        if arr[i] < 0 {
            let mut diff = arr[i];
            let mut mul = 2;
            while (i + 1) * mul <= n {
                diff += arr[(i + 1) * mul - 1];
                mul += 1
            }
            mul = 1;
            if diff < 0 {
                while (i + 1) * mul <= n {
                    arr[(i + 1) * mul - 1] = 0;
                    mul += 1
                }
            }
        }
    }

    println!("{}", arr.iter().sum::<i64>());
}

