        for j in m+1..n+1 {
            if xs[j] < 0 {
                bs[j] = false;
            }
        }
        for j in 1..n+1 {
            if bs[j] { temp += xs[j]; }
        }
        /*
        if temp > ans {
            println!("{}", i);
            println!("{}", temp);
            for j in 1..n+1{
                print!("{} ", bs[j as usize]);
            }
            println!("\n");
        }
        */
        ans = max(temp, ans);
    }
    println!("{}", ans);
}

fn getbit(x: u64, i: usize) -> bool {
    return ((x << 1) >> i) % 2 > 0;
}

#[allow(dead_code)]
fn getline() -> String {
    let mut s = String::new();
    match stdin().read_line(&mut s){
        Ok(_) => {s.trim().to_string()}
        Err(_) => String::new()
    }
}

#[allow(dead_code)]
fn getvec<T: std::str::FromStr>() -> Vec<T>{
    let line = getline();
    line.split_whitespace().filter_map(|x| x.parse().ok()).collect()
}

#[allow(dead_code)]
fn getpair() -> (usize, usize){
    let nm = getvec();
    (nm[0], nm[1])
}
